# --------------------------------- Utilities ----------------------------------
def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def parse_float(value: Any, default: Optional[float] = None) -> Optional[float]:
    try:
        number = float(value)
        return number if math.isfinite(number) else default
    except (TypeError, ValueError, OverflowError):
        return default


def parse_price_text(value: Any, default: Optional[float] = None) -> Optional[float]:
    """Parse common Bitcoin/USD labels such as 67500.25 or 67,500.25."""
    raw = re.sub(r"[^0-9.,+\-]", "", str(value or "").strip())
    if not raw or not re.search(r"\d", raw):
        return default
    if "," in raw and "." in raw:
        # The separator occurring last is treated as the decimal separator.
        if raw.rfind(".") > raw.rfind(","):
            raw = raw.replace(",", "")
        else:
            raw = raw.replace(".", "").replace(",", ".")
    elif "," in raw:
        parts = raw.split(",")
        if len(parts) > 1 and len(parts[-1]) == 3 and all(part.isdigit() for part in parts):
            raw = "".join(parts)  # 67,500 -> 67500
        elif len(parts) == 2 and parts[-1].isdigit():
            raw = parts[0] + "." + parts[1]
        else:
            raw = "".join(parts)
    elif "." in raw:
        # A single dot followed by three digits is a thousands separator on many
        # localized broker UIs (67.500). Keep 0.875-style sub-unit values decimal.
        parts = raw.split(".")
        if (len(parts) == 2 and parts[0].isdigit() and parts[-1].isdigit()
                and 0 < int(parts[0]) <= 999 and len(parts[0]) <= 3 and len(parts[-1]) == 3):
            raw = "".join(parts)
    return parse_float(raw, default)


def format_market_price(value: Any) -> str:
    """Format BTC/USD magnitudes normally; preserve generic small test/proxy values."""
    number = parse_float(value, None)
    if number is None or number <= 0:
        return "—"
    if number >= 1000:
        return f"${number:,.2f}"
    if number >= 10:
        return f"${number:,.3f}".rstrip("0").rstrip(".")
    return f"{number:.5f}"


def parse_epoch(value: Any) -> Optional[float]:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        dt = parsedate_to_datetime(text)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.timestamp()
    except Exception:
        pass
    try:
        dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.timestamp()
    except Exception:
        return None


