def image_quality(image: np.ndarray) -> Dict[str, Any]:
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    brightness = float(np.mean(gray))
    contrast = float(np.std(gray))
    sharpness = float(cv2.Laplacian(gray, cv2.CV_64F).var())
    score = 100.0
    if brightness < 18 or brightness > 242:
        score -= 15
    if contrast < 10:
        score -= 20
    if sharpness < 5:
        score -= 20
    return {
        "score": int(clamp(score, 0, 100)),
        "width": int(image.shape[1]),
        "height": int(image.shape[0]),
        "brightness": round(brightness, 2),
        "contrast": round(contrast, 2),
        "sharpness": round(sharpness, 2),
    }



# ------------------------------- SQLite memory -------------------------------
def _base_db_connect() -> sqlite3.Connection:
    conn = sqlite3.connect(str(DB_PATH), timeout=5.0)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA secure_delete=ON")
    conn.execute(
        """CREATE TABLE IF NOT EXISTS cycle_items (
            cycle_id INTEGER NOT NULL,
            kind TEXT NOT NULL,
            item_key TEXT NOT NULL,
            observed_epoch REAL NOT NULL,
            payload_json TEXT NOT NULL,
            PRIMARY KEY (cycle_id, kind, item_key)
        )"""
    )
    conn.execute("CREATE INDEX IF NOT EXISTS idx_cycle_kind ON cycle_items(cycle_id, kind)")
    conn.commit()
    return conn


def db_store_many(cycle_id: int, kind: str, items: List[Tuple[str, Dict[str, Any], Optional[float]]]) -> None:
    if not items:
        return
    now = time.time()
    rows = []
    for key, value, observed_epoch in items:
        observed = now if observed_epoch is None else float(observed_epoch)
        encoded = json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)
        rows.append((int(cycle_id), str(kind), str(key), observed, encoded))
    with DB_LOCK:
        conn = db_connect()
        try:
            conn.executemany(
                "INSERT OR REPLACE INTO cycle_items(cycle_id,kind,item_key,observed_epoch,payload_json) VALUES(?,?,?,?,?)",
                rows,
            )
            conn.commit()
        finally:
            conn.close()


def db_store(cycle_id: int, kind: str, key: str, value: Dict[str, Any], observed_epoch: Optional[float] = None) -> None:
    db_store_many(cycle_id, kind, [(key, value, observed_epoch)])


def db_load(cycle_id: int, kind: str) -> List[Dict[str, Any]]:
    with DB_LOCK:
        conn = db_connect()
        try:
            rows = conn.execute(
                "SELECT payload_json FROM cycle_items WHERE cycle_id=? AND kind=? ORDER BY observed_epoch ASC",
                (int(cycle_id), str(kind)),
            ).fetchall()
        finally:
            conn.close()
    result: List[Dict[str, Any]] = []
    for row in rows:
        try:
            value = json.loads(row[0])
            if isinstance(value, dict):
                result.append(value)
        except Exception:
            continue
    return result


def db_reset_cycle(cycle_id: int) -> int:
    """Delete the cycle's collected context after its screenshot result is dispatched."""
    with DB_LOCK:
        conn = db_connect()
        try:
            cursor = conn.execute("DELETE FROM cycle_items WHERE cycle_id=?", (int(cycle_id),))
            removed = int(cursor.rowcount if cursor.rowcount >= 0 else 0)
            conn.commit()
            try:
                conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
            except sqlite3.DatabaseError:
                pass
            return removed
        finally:
            conn.close()


def db_clear_old_cycles(keep_cycle_id: int) -> None:
    with DB_LOCK:
        conn = db_connect()
        try:
            conn.execute("DELETE FROM cycle_items WHERE cycle_id<>?", (int(keep_cycle_id),))
            conn.commit()
        finally:
            conn.close()


