_BASE_DB_CONNECT = _base_db_connect
_BASE_BUILD_VISUAL_CANDLES = _base_build_visual_candles
_BASE_ANALYZE_CANDLES = _base_analyze_candles
_BASE_MAKE_ONLINE_ASSESSMENT = _base_make_online_assessment

OFFICIAL_CALENDAR_SOURCES: List[Tuple[str, str, str]] = []  # online calendar research disabled


# ---------------------- Persistent learning/audit database --------------------
def db_connect() -> sqlite3.Connection:
    conn = _BASE_DB_CONNECT()
    conn.execute("""CREATE TABLE IF NOT EXISTS forecast_history (
        prediction_id INTEGER PRIMARY KEY AUTOINCREMENT,
        created_epoch REAL NOT NULL,
        screenshot_id INTEGER NOT NULL,
        cycle_id INTEGER,
        horizon_minutes INTEGER NOT NULL,
        direction TEXT NOT NULL,
        evidence_score REAL NOT NULL,
        combined_bias REAL NOT NULL,
        features_json TEXT NOT NULL,
        actual_direction TEXT,
        outcome_source TEXT,
        resolved_epoch REAL
    )""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_forecast_horizon ON forecast_history(horizon_minutes, created_epoch)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_forecast_screenshot ON forecast_history(screenshot_id, horizon_minutes)")
    existing_columns = {str(row[1]) for row in conn.execute("PRAGMA table_info(forecast_history)").fetchall()}
    for column, declaration in (
        ("entry_price", "REAL"), ("expiry_price", "REAL"),
        ("entry_price_timestamp", "REAL"), ("expiry_price_timestamp", "REAL"), ("trade_result", "TEXT"),
        ("outcome_verification", "TEXT"), ("alert_started_epoch", "REAL"),
        ("target_expiry_epoch", "REAL"), ("prediction_epoch", "REAL"),
        ("outcome_training_eligible", "INTEGER"), ("broker_settlement_result", "TEXT")
    ):
        if column not in existing_columns:
            conn.execute(f"ALTER TABLE forecast_history ADD COLUMN {column} {declaration}")
    conn.execute("""CREATE TABLE IF NOT EXISTS candle_detection_audit (
        screenshot_id INTEGER PRIMARY KEY,
        created_epoch REAL NOT NULL,
        detected_total INTEGER NOT NULL,
        detected_red INTEGER NOT NULL,
        detected_green INTEGER NOT NULL,
        reading_confidence REAL,
        image_width INTEGER,
        image_height INTEGER,
        detected_candles_json TEXT NOT NULL,
        expected_candles_json TEXT,
        validated_epoch REAL,
        detector_version TEXT
    )""")
    existing_audit_columns = {str(row[1]) for row in conn.execute("PRAGMA table_info(candle_detection_audit)").fetchall()}
    if "detector_version" not in existing_audit_columns:
        conn.execute("ALTER TABLE candle_detection_audit ADD COLUMN detector_version TEXT")
    conn.execute("""CREATE TABLE IF NOT EXISTS source_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        cycle_id INTEGER NOT NULL,
        source TEXT NOT NULL,
        kind TEXT NOT NULL,
        observed_epoch REAL NOT NULL,
        succeeded INTEGER NOT NULL,
        age_seconds REAL,
        detail TEXT
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS live_price_snapshots (
        snapshot_id INTEGER PRIMARY KEY AUTOINCREMENT,
        observed_epoch REAL NOT NULL,
        price REAL NOT NULL,
        price_source TEXT NOT NULL,
        direct_quote_ocr INTEGER NOT NULL DEFAULT 0,
        price_scale_calibrated INTEGER NOT NULL DEFAULT 0,
        note TEXT
    )""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_live_price_snapshots_epoch ON live_price_snapshots(observed_epoch)")
    conn.execute("""CREATE TABLE IF NOT EXISTS live_forecast_index (
        bar_anchor_epoch INTEGER PRIMARY KEY,
        screenshot_id INTEGER NOT NULL UNIQUE,
        prediction_id INTEGER,
        prediction_epoch REAL NOT NULL,
        target_expiry_epoch REAL NOT NULL,
        direction TEXT NOT NULL,
        score_percent REAL NOT NULL,
        entry_price REAL NOT NULL,
        entry_price_timestamp REAL NOT NULL,
        entry_price_source TEXT NOT NULL,
        resolved INTEGER NOT NULL DEFAULT 0,
        resolution_status TEXT NOT NULL DEFAULT 'PENDING',
        expiry_price REAL,
        expiry_price_timestamp REAL,
        actual_direction TEXT
    )""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_live_forecast_target ON live_forecast_index(target_expiry_epoch,resolved)")
    conn.execute("""CREATE TABLE IF NOT EXISTS live_visual_candle_history (
        bar_open_epoch INTEGER PRIMARY KEY,
        observed_epoch REAL NOT NULL,
        timeframe TEXT NOT NULL,
        open_price_estimate REAL,
        high_price_estimate REAL,
        low_price_estimate REAL,
        close_price_estimate REAL,
        open_pixel_proxy REAL,
        high_pixel_proxy REAL,
        low_pixel_proxy REAL,
        close_pixel_proxy REAL,
        source TEXT NOT NULL,
        timestamp_basis TEXT NOT NULL,
        broker_ohlc_verified INTEGER NOT NULL DEFAULT 0,
        is_complete INTEGER NOT NULL DEFAULT 0,
        metadata_json TEXT NOT NULL DEFAULT '{}'
    )""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_live_visual_candles_time ON live_visual_candle_history(timeframe,bar_open_epoch)")
    conn.commit()
    return conn


def _audit_source(cycle_id: int, source: str, kind: str, succeeded: bool,
                  age_seconds: Optional[float] = None, detail: str = "") -> None:
    try:
        with DB_LOCK:
            conn = db_connect()
            try:
                conn.execute(
                    "INSERT INTO source_audit(cycle_id,source,kind,observed_epoch,succeeded,age_seconds,detail) VALUES(?,?,?,?,?,?,?)",
                    (int(cycle_id), str(source)[:240], str(kind)[:60], time.time(), int(bool(succeeded)),
                     float(age_seconds) if age_seconds is not None else None, str(detail)[:500]),
                )
                conn.commit()
            finally:
                conn.close()
    except Exception:
        pass


def _source_reliability(source: str, kind: str, age_seconds: Optional[float] = None) -> float:
    priors = {"market": 0.78, "reference": 0.70, "calendar": 0.94, "news": 0.62, "learning": 0.55}
    base = priors.get(kind, 0.60)
    try:
        with DB_LOCK:
            conn = db_connect()
            try:
                rows = conn.execute(
                    "SELECT succeeded FROM source_audit WHERE source=? ORDER BY observed_epoch DESC LIMIT 80",
                    (str(source)[:240],),
                ).fetchall()
            finally:
                conn.close()
        if len(rows) >= 5:
            success_ratio = sum(int(row[0]) for row in rows) / len(rows)
            base *= 0.65 + 0.35 * success_ratio
    except Exception:
        pass
    if age_seconds is not None:
        age = max(0.0, float(age_seconds))
        if kind == "market":
            freshness = math.exp(-age / 180.0)
        elif kind == "news":
            freshness = math.exp(-age / (8 * 3600.0))
        else:
            freshness = math.exp(-age / (7 * 86400.0))
        base *= 0.55 + 0.45 * freshness
    return round(float(clamp(base, 0.05, 0.99)), 3)


# ------------------------------ Chart auto ROI --------------------------------


def validate_candle_geometry(candle_result: Dict[str, Any]) -> Dict[str, Any]:
    """Check detected candle boxes and OHLC-like pixel geometry without inventing market prices."""
    candles = list(candle_result.get("candles") or [])
    shape = candle_result.get("plot_crop_shape") or {}
    width = int(parse_float(shape.get("width"), 0) or 0)
    height = int(parse_float(shape.get("height"), 0) or 0)
    if candles and (width <= 0 or height <= 0):
        width = max(int(row.get("x", 0)) + int(row.get("width", 0)) for row in candles)
        height = max(int(row.get("y", 0)) + int(row.get("height", 0)) for row in candles)
    issues_by_index: Dict[int, List[str]] = {}
    for pos, row in enumerate(candles, start=1):
        issues: List[str] = []
        try:
            x, y = float(row.get("x", -1)), float(row.get("y", -1))
            w, h = float(row.get("width", 0)), float(row.get("height", 0))
            body_top = float(row.get("body_top_pixel", y))
            body_bottom = float(row.get("body_bottom_pixel", y + h))
            wick_top = float(row.get("wick_top_pixel", y))
            wick_bottom = float(row.get("wick_bottom_pixel", y + h))
            open_y = float(row.get("estimated_open_pixel", body_bottom))
            close_y = float(row.get("estimated_close_pixel", body_top))
            upper = float(row.get("upper_wick_pixels", 0))
            lower = float(row.get("lower_wick_pixels", 0))
            color = str(row.get("color", "")).upper()
            if color not in ("RED", "GREEN"):
                issues.append("invalid_color")
            if w <= 0 or h <= 0:
                issues.append("nonpositive_box_size")
            if x < 0 or y < 0 or (width > 0 and x + w > width + 1) or (height > 0 and y + h > height + 1):
                issues.append("box_outside_chart_crop")
            if not (y - 1 <= wick_top <= body_top + 1 <= body_bottom + 1 <= wick_bottom + 1 <= y + h + 2):
                issues.append("body_or_wick_order_invalid")
            if not (body_top - 1 <= open_y <= body_bottom + 1 and body_top - 1 <= close_y <= body_bottom + 1):
                issues.append("open_close_outside_body")
            if upper < 0 or lower < 0:
                issues.append("negative_wick_length")
            if color == "GREEN" and close_y > open_y + 1:
                issues.append("green_open_close_orientation_mismatch")
            if color == "RED" and close_y < open_y - 1:
                issues.append("red_open_close_orientation_mismatch")
            if float(row.get("body_height_pixels", max(0, body_bottom - body_top))) > h + 2:
                issues.append("body_exceeds_total_range")
        except (TypeError, ValueError, OverflowError):
            issues.append("unparseable_geometry")
        index = int(parse_float(row.get("index"), pos) or pos)
        row["geometry_valid"] = not issues
        row["geometry_issues"] = issues
        row["geometry_quality_factor"] = 1.0 if not issues else 0.65
        issues_by_index[index] = issues

    red_count = sum(str(row.get("color", "")).upper() == "RED" for row in candles)
    green_count = sum(str(row.get("color", "")).upper() == "GREEN" for row in candles)
    reported_total = int(parse_float(candle_result.get("total"), len(candles)) or 0)
    colors_reconcile = red_count + green_count == len(candles) == reported_total
    invalid_count = sum(bool(issues) for issues in issues_by_index.values())
    invalid_fraction = invalid_count / max(1, len(candles))
    factor = float(clamp(1.0 - 0.45 * invalid_fraction - (0.18 if not colors_reconcile else 0.0), 0.55, 1.0)) if candles else 0.0
    report = {
        "available": bool(candles),
        "detected_count": len(candles),
        "reported_total": reported_total,
        "red_count": red_count,
        "green_count": green_count,
        "red_green_total_reconciles": colors_reconcile,
        "geometry_valid_count": len(candles) - invalid_count,
        "geometry_invalid_count": invalid_count,
        "geometry_valid_percent": round(100.0 * (len(candles) - invalid_count) / max(1, len(candles)), 2) if candles else 0.0,
        "invalid_candle_indices": [index for index, issues in issues_by_index.items() if issues],
        "issues_by_candle": {str(index): issues for index, issues in issues_by_index.items() if issues},
        "directional_score_factor": round(factor, 4),
        "basis": "pixel-coordinate consistency checks only; not verification against broker OHLC or manual ground truth",
    }
    candle_result["geometry_validation"] = report
    integrity = candle_result.get("count_integrity")
    if isinstance(integrity, dict):
        integrity["geometry_valid_count"] = report["geometry_valid_count"]
        integrity["geometry_invalid_count"] = report["geometry_invalid_count"]
        integrity["geometry_validation_factor"] = report["directional_score_factor"]
        integrity["red_plus_green_equals_total"] = bool(integrity.get("red_plus_green_equals_total")) and colors_reconcile
    return report




def _fit_price_scale_from_ticks(ticks: List[Dict[str, Any]], source: str = "visible_screenshot_price_axis_ocr") -> Dict[str, Any]:
    """Fit a conservative pixel-to-price scale from readable, monotonic price-axis labels."""
    usable: List[Dict[str, Any]] = []
    for tick in ticks or []:
        value = parse_float(tick.get("value"), None)
        y = parse_float(tick.get("y"), None)
        confidence = parse_float(tick.get("confidence"), 0.0) or 0.0
        if value is None or y is None or confidence < 30.0 or not (10.0 <= value <= 10_000_000.0):
            continue
        usable.append({"value": float(value), "y": float(y), "confidence": float(confidence),
                       "text": str(tick.get("text") or value)[:30]})
    usable.sort(key=lambda item: item["y"])
    # If OCR emits multiple fragments on one row, retain only the clearest reading.
    unique: List[Dict[str, Any]] = []
    for tick in usable:
        nearby = next((item for item in reversed(unique) if abs(item["y"] - tick["y"]) <= 7.0), None)
        if nearby is None:
            unique.append(tick)
        elif tick["confidence"] > nearby["confidence"]:
            unique[unique.index(nearby)] = tick
    unique.sort(key=lambda item: item["y"])
    base = {"available": False, "source": source, "mapped_candles": 0,
            "tick_count": len(unique), "tick_points": unique[:12],
            "reason": "At least three distinct, consistently ordered price-axis labels are required."}
    if len(unique) < 3 or (unique[-1]["y"] - unique[0]["y"]) < 30.0:
        return base
    values = np.asarray([item["value"] for item in unique], dtype=float)
    ys = np.asarray([item["y"] for item in unique], dtype=float)
    if not bool(np.all(np.diff(values) < 0.0)):
        base["reason"] = "OCR price labels were not strictly descending from top to bottom; scale rejected."
        return base
    slope, intercept = np.polyfit(ys, values, 1)
    predicted = slope * ys + intercept
    residual = values - predicted
    total_variance = float(np.sum((values - float(np.mean(values))) ** 2))
    r2 = 1.0 - float(np.sum(residual ** 2)) / max(total_variance, 1e-15)
    typical_tick_gap = float(np.median(np.abs(np.diff(values))))
    max_residual = float(np.max(np.abs(residual)))
    if slope >= 0 or not math.isfinite(float(slope)) or r2 < 0.94 or max_residual > max(typical_tick_gap * 0.30, 1e-7):
        base.update({"reason": "Price-axis labels did not fit a sufficiently linear, high-confidence scale.",
                     "fit_r_squared": round(float(r2), 5), "max_fit_residual": round(max_residual, 8)})
        return base
    return {
        "available": True, "source": source, "mapped_candles": 0,
        "tick_count": len(unique), "tick_points": unique[:12],
        "slope_price_per_pixel": float(slope), "intercept_price_at_image_y0": float(intercept),
        "fit_r_squared": round(float(r2), 5), "max_fit_residual": round(max_residual, 8),
        "mean_ocr_confidence": round(float(np.mean([item["confidence"] for item in unique])), 1),
        "reason": "Visible screenshot price-axis labels passed monotonicity and linear-fit checks; mapped OHLC remains an image-derived estimate, not a verified broker quote.",
    }


def read_price_axis_scale(image: np.ndarray) -> Dict[str, Any]:
    """Optional bounded OCR of visible price-axis numbers; never OCRs/checks the M1 label."""
    unavailable = {"available": False, "source": "visible_screenshot_price_axis_ocr", "mapped_candles": 0}
    try:
        import pytesseract
        from pytesseract import Output
    except Exception:
        return {**unavailable, "reason": "Optional pytesseract package is not installed."}
    configured_path = (os.environ.get("TESSERACT_CMD") or os.environ.get("TESSERACT_PATH") or "").strip()
    default_windows_path = r"C:\Program Files\Tesseract-OCR\tesseract.exe"
    executable = configured_path or (default_windows_path if os.name == "nt" and Path(default_windows_path).is_file() else shutil.which("tesseract"))
    if executable and (os.path.isfile(executable) or shutil.which(executable)):
        pytesseract.pytesseract.tesseract_cmd = executable
    elif shutil.which(str(getattr(pytesseract.pytesseract, "tesseract_cmd", "tesseract"))) is None:
        return {**unavailable, "reason": "Tesseract executable was not found; price-axis OCR skipped."}
    if image is None or image.size == 0 or image.ndim != 3 or image.shape[1] < 180 or image.shape[0] < 120:
        return {**unavailable, "reason": "Screenshot is too small or empty for reliable price-axis OCR."}
    height, width = image.shape[:2]
    x0, y0 = int(width * 0.62), int(height * 0.035)
    x1, y1 = width, int(height * 0.94)
    axis = image[y0:y1, x0:x1]
    if axis.size == 0:
        return {**unavailable, "reason": "No readable price-axis region in submitted screenshot."}
    scale = min(2.0, 1800.0 / max(axis.shape[:2]))
    scale = max(1.0, float(scale))
    prepared = cv2.resize(axis, None, fx=scale, fy=scale, interpolation=cv2.INTER_CUBIC) if scale != 1.0 else axis
    gray = cv2.cvtColor(prepared, cv2.COLOR_BGR2GRAY)
    gray = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(4, 4)).apply(gray)
    try:
        data = pytesseract.image_to_data(
            gray, output_type=Output.DICT,
            config="--psm 11 -c tessedit_char_whitelist=0123456789.,",
            timeout=TESSERACT_TIMEOUT_SECONDS,
        )
    except Exception as exc:
        return {**unavailable, "reason": f"Price-axis OCR skipped safely ({type(exc).__name__})."}
    ticks: List[Dict[str, Any]] = []
    for index, token in enumerate(data.get("text", [])):
        raw_text = str(token or "").strip()
        if not re.fullmatch(r"(?:(?:\d{1,3}(?:[,.]\d{3})+)|\d{2,8})(?:[,.]\d{1,5})?", raw_text):
            continue
        try:
            confidence = float(data.get("conf", [])[index])
            local_y = (float(data.get("top", [])[index]) + float(data.get("height", [])[index]) / 2.0) / scale
        except (ValueError, TypeError, IndexError):
            continue
        parsed_value = parse_price_text(raw_text, None)
        if parsed_value is None or not 10.0 <= parsed_value <= 10_000_000.0:
            continue
        ticks.append({"value": parsed_value, "y": float(y0) + local_y,
                      "confidence": confidence, "text": raw_text})
    if not ticks:
        return {**unavailable, "reason": "No parseable Bitcoin-like numeric price-axis labels were detected in the screenshot."}
    result = _fit_price_scale_from_ticks(ticks)
    result["ocr_elapsed_limit_seconds"] = TESSERACT_TIMEOUT_SECONDS
    result["axis_region"] = {"x": x0, "y": y0, "width": x1 - x0, "height": y1 - y0}
    return result


def apply_price_scale_to_candles(candle_result: Dict[str, Any], price_scale: Dict[str, Any]) -> int:
    """Map screen candle OHLC estimates onto the fitted visible price axis, if safely calibrated."""
    if not isinstance(price_scale, dict) or not price_scale.get("available"):
        return 0
    slope = parse_float(price_scale.get("slope_price_per_pixel"), None)
    intercept = parse_float(price_scale.get("intercept_price_at_image_y0"), None)
    if slope is None or intercept is None or slope >= 0:
        return 0
    roi_y = parse_float((candle_result.get("chart_region") or {}).get("y"), 0.0) or 0.0
    mapped = 0
    for candle in candle_result.get("candles") or []:
        def price_at(local_y: Any) -> Optional[float]:
            pixel_y = parse_float(local_y, None)
            if pixel_y is None:
                return None
            value = intercept + slope * (roi_y + float(pixel_y))
            return value if math.isfinite(value) and value > 0 else None
        open_price = price_at(candle.get("estimated_open_pixel"))
        close_price = price_at(candle.get("estimated_close_pixel"))
        high_price = price_at(candle.get("wick_top_pixel"))
        low_price = price_at(candle.get("wick_bottom_pixel"))
        if None in (open_price, close_price, high_price, low_price):
            continue
        candle.update({
            "estimated_open_price": round(float(open_price), 7),
            "estimated_close_price": round(float(close_price), 7),
            "estimated_high_price": round(max(float(high_price), float(open_price), float(close_price)), 7),
            "estimated_low_price": round(min(float(low_price), float(open_price), float(close_price)), 7),
            "price_estimate_basis": "VISIBLE_PRICE_AXIS_OCR_LINEAR_FIT; IMAGE-DERIVED ESTIMATE, NOT VERIFIED BROKER QUOTE",
            "ohlc_status": "PRICE-AXIS-CALIBRATED IMAGE ESTIMATE, NOT VERIFIED MARKET OHLC",
        })
        mapped += 1
    price_scale["mapped_candles"] = mapped
    return mapped

# ----------------------------- Candle structures ------------------------------
def _candle_proxy_ohlc(c: Dict[str, Any]) -> Tuple[float, float, float, float]:
    """Prefer a validated visible-axis price estimate; otherwise use relative screen geometry."""
    calibrated = [parse_float(c.get(key), None) for key in (
        "estimated_open_price", "estimated_high_price", "estimated_low_price", "estimated_close_price")]
    if all(value is not None and math.isfinite(float(value)) and float(value) > 0 for value in calibrated):
        o, high, low, close = (float(value) for value in calibrated)
        if high >= max(o, close) and low <= min(o, close) and high >= low:
            return o, high, low, close
    # Invert screen y so higher positions have higher numerical values. This is a pixel proxy,
    # not a verified broker quote, and normalized analysis remains available without axis OCR.
    o = -float(c.get("estimated_open_pixel", c.get("body_bottom_pixel", 0)))
    close = -float(c.get("estimated_close_pixel", c.get("body_top_pixel", 0)))
    high = -float(c.get("wick_top_pixel", c.get("y", 0)))
    low = -float(c.get("wick_bottom_pixel", float(c.get("y", 0)) + float(c.get("height", 1))))
    return o, max(high, o, close), min(low, o, close), close


def _extended_candle_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Scan every visible candle and every adjacent pair/triple, not only the last ones."""
    n = len(candles)
    if n < 1:
        return []
    ohlc = [_candle_proxy_ohlc(c) for c in candles]
    colors = [str(c.get("color", "")).upper() for c in candles]
    ranges = [max(1.0, h - l) for _, h, l, _ in ohlc]
    bodies = [max(0.0, abs(c - o)) for o, _, _, c in ohlc]
    upper_wicks = [max(0.0, h - max(o, c)) for o, h, _l, c in ohlc]
    lower_wicks = [max(0.0, min(o, c) - l) for o, _h, l, c in ohlc]
    median_range = max(1e-9, float(np.median(ranges)))
    tolerance = max(1e-9, median_range * 0.12)
    extras: List[Dict[str, Any]] = []

    def contiguous(start: int, end: int) -> bool:
        return all(not bool(candles[pos].get("sequence_break_before")) for pos in range(start + 1, end + 1))

    def prior_trend(index: int, lookback: int = 6) -> str:
        lo = max(0, index - lookback)
        # Never infer trend across a suspected missing candle interval.
        for boundary in range(max(lo + 1, 1), index + 1):
            if bool(candles[boundary].get("sequence_break_before")):
                lo = boundary
        if index - lo < 3:
            return "UNKNOWN"
        values = np.array([ohlc[k][3] for k in range(lo, index)], dtype=float)
        slope = float(np.polyfit(np.arange(len(values), dtype=float), values, 1)[0])
        delta = float(values[-1] - values[0])
        scale = max(1.0, float(np.median(ranges[lo:index])))
        if delta > scale * 0.22 and slope > 0:
            return "UP"
        if delta < -scale * 0.22 and slope < 0:
            return "DOWN"
        return "SIDEWAYS"

    def add(name: str, bias: float, start: int, end: int, strength: float = 0.5,
            context: Optional[str] = None) -> None:
        extras.append({
            "name": name, "bias": float(bias), "confirmed": False,
            "candle_indices": [int(start + 1), int(end + 1)],
            "strength": round(float(strength), 3), "raw_strength": round(float(strength), 3),
            "context": context or "sequence pattern; interpret with nearby trend and levels",
            "confirmation_status": "PENDING_OR_NO_FOLLOWING_CANDLE",
        })

    # Single-candle shapes, evaluated at every visible position.
    for i in range(n):
        o, h, l, c = ohlc[i]
        r = ranges[i]
        body = max(bodies[i], median_range * 1e-4, 1e-9)
        ur, lr = upper_wicks[i], lower_wicks[i]
        body_ratio = body / r
        top_body = max(o, c)
        bottom_body = min(o, c)
        trend = prior_trend(i)
        if body_ratio <= 0.10 and lr / r >= 0.62 and ur / r <= 0.14:
            bias = 0.50 if trend == "DOWN" else 0.0
            add("DRAGONFLY_DOJI", bias, i, i, 0.58, f"lower-wick rejection; bullish reversal evidence needs a prior downtrend and follow-through; prior trend={trend}")
        if body_ratio <= 0.10 and ur / r >= 0.62 and lr / r <= 0.14:
            bias = -0.50 if trend == "UP" else 0.0
            add("GRAVESTONE_DOJI", bias, i, i, 0.58, f"upper-wick rejection; bearish reversal evidence needs a prior uptrend and follow-through; prior trend={trend}")
        if body_ratio <= 0.30 and ur / r >= 0.20 and lr / r >= 0.20:
            add("SPINNING_TOP", 0.0, i, i, 0.38, "small body with two-sided wicks; indecision")
        if body_ratio >= 0.86 and (ur + lr) / r <= 0.14:
            marubozu_bias = 0.72 if colors[i] == "GREEN" else -0.72
            add("MARUBOZU", marubozu_bias, i, i, 0.66,
                "large body and small combined wicks; direction follows candle color")
            add("BULLISH_MARUBOZU" if colors[i] == "GREEN" else "BEARISH_MARUBOZU",
                marubozu_bias, i, i, 0.62,
                "Explicit directional Marubozu alias; still requires location and follow-through confirmation")
        if lr >= 2.0 * body and ur <= 0.18 * r and top_body >= l + 0.55 * r:
            if trend == "UP":
                add("HANGING_MAN", -0.58, i, i, 0.57, "long lower wick after an uptrend")
            elif trend == "DOWN":
                add("HAMMER", 0.58, i, i, 0.57, "long lower wick after a downtrend")
            else:
                add("LOWER_WICK_REJECTION", 0.0, i, i, 0.40, "long lower wick without a clear prior trend")
        if ur >= 2.0 * body and lr <= 0.18 * r and bottom_body <= l + 0.45 * r:
            if trend == "DOWN":
                add("INVERTED_HAMMER", 0.56, i, i, 0.55, "long upper wick after a downtrend")
            elif trend == "UP":
                add("SHOOTING_STAR", -0.58, i, i, 0.57, "long upper wick after an uptrend")
            else:
                add("UPPER_WICK_REJECTION", 0.0, i, i, 0.40, "long upper wick without a clear prior trend")
        # Explicit user-requested names: the shape is contextual, never a standalone signal.
        if (ur >= 1.65 * body and lr <= 0.25 * r and ur / r >= 0.48 and trend == "UP"):
            add("BEARISH_PIN_BAR", -0.50, i, i, 0.48,
                "upper-wick rejection after an uptrend; require a later bearish close and resistance context")
        if (lr >= 1.65 * body and ur <= 0.25 * r and lr / r >= 0.48 and trend == "DOWN"):
            add("BULLISH_PIN_BAR", 0.50, i, i, 0.48,
                "lower-wick rejection after a downtrend; require a later bullish close and support context")
        if trend == "UP" and lr >= 1.55 * body and ur <= 0.28 * r:
            add("BEARISH_HAMMER", -0.40, i, i, 0.40,
                "hammer-shaped candle after an uptrend is conventionally hanging-man-like; custom alias only")

    # Every consecutive 2-candle setup, not merely the last pair.
    for j in range(1, n):
        i = j - 1
        if not contiguous(i, j):
            continue
        o1, h1, l1, c1 = ohlc[i]
        o2, h2, l2, c2 = ohlc[j]
        b1lo, b1hi = min(o1, c1), max(o1, c1)
        b2lo, b2hi = min(o2, c2), max(o2, c2)
        prior_trend_name = prior_trend(i)
        if colors[i] != colors[j] and b2lo <= b1lo and b2hi >= b1hi and bodies[j] >= bodies[i] * 1.02:
            add("BULLISH_ENGULFING" if colors[j] == "GREEN" else "BEARISH_ENGULFING",
                0.78 if colors[j] == "GREEN" else -0.78, i, j, 0.65, "body engulfing; check trend and follow-through")
        elif colors[i] != colors[j] and b2lo >= b1lo and b2hi <= b1hi and bodies[j] <= bodies[i] * 0.65:
            add("BULLISH_HARAMI" if colors[j] == "GREEN" else "BEARISH_HARAMI",
                0.48 if colors[j] == "GREEN" else -0.48, i, j, 0.45, "small body inside previous body")
        midpoint = (o1 + c1) / 2.0
        if colors[i] == "RED" and colors[j] == "GREEN" and c2 > midpoint and c2 < o1:
            add("PIERCING_LINE", 0.58, i, j, 0.53, "bullish close recovers above previous body midpoint")
        if colors[i] == "GREEN" and colors[j] == "RED" and c2 < midpoint and c2 > o1:
            add("DARK_CLOUD_COVER", -0.58, i, j, 0.53, "bearish close falls below previous body midpoint")
        if h2 <= h1 + tolerance and l2 >= l1 - tolerance and (h1 - l1) > (h2 - l2) * 1.12:
            add("INSIDE_BAR", 0.0, i, j, 0.38, "range contraction; direction needs a break")
        if abs(h2 - h1) <= tolerance and colors[i] == "GREEN" and colors[j] == "RED":
            add("TWEEZER_TOP", -0.50, i, j, 0.45, "near-equal highs")
        if abs(l2 - l1) <= tolerance and colors[i] == "RED" and colors[j] == "GREEN":
            add("TWEEZER_BOTTOM", 0.50, i, j, 0.45, "near-equal lows")

        # These pair patterns are explicitly labelled as custom variants, not universal textbook signals.
        if prior_trend(i) == "UP" and all(bodies[z] / ranges[z] <= 0.12 for z in (i, j)):
            add("DOUBLE_DOJI_BEARISH", -0.34, i, j, 0.34,
                "two indecision candles after an uptrend; bearish only with subsequent downside follow-through")
        if prior_trend(i) == "UP" and all(
                lower_wicks[z] >= 1.45 * max(bodies[z], 1e-9)
                and upper_wicks[z] <= 0.30 * ranges[z] for z in (i, j)):
            add("DOUBLE_HAMMER_BEARISH", -0.36, i, j, 0.36,
                "two lower-wick rejection candles after an uptrend; nonstandard custom setup, require a bearish close")
        if prior_trend(i) == "UP" and all(
                upper_wicks[z] >= 1.45 * max(bodies[z], 1e-9)
                and lower_wicks[z] <= 0.30 * ranges[z] for z in (i, j)):
            add("DOUBLE_BEARISH_PIN_BAR", -0.42, i, j, 0.40,
                "two upper-wick rejections after an uptrend; require lower close / resistance confirmation")
        if prior_trend(i) == "DOWN" and all(
                lower_wicks[z] >= 1.45 * max(bodies[z], 1e-9)
                and upper_wicks[z] <= 0.30 * ranges[z] for z in (i, j)):
            add("DOUBLE_BULLISH_PIN_BAR", 0.42, i, j, 0.40,
                "two lower-wick rejections after a downtrend; require higher close / support confirmation")
        # For 24/7 crypto markets, a gap is only declared from a real OHLC open outside
        # the preceding high/low, not from missing chart slots or a drawing overlay.
        if o2 > h1 + 0.15 * median_range and c2 > o2 and bodies[j] / ranges[j] >= 0.30:
            add("GAP_UP_BULLISH_CONFIRMATION", 0.38, i, j, 0.38,
                "open above prior high with a bullish body; verify breakout hold and volume if available")
        if o2 < l1 - 0.15 * median_range and c2 < o2 and bodies[j] / ranges[j] >= 0.30:
            add("GAP_DOWN_BEARISH_CONFIRMATION", -0.38, i, j, 0.38,
                "open below prior low with a bearish body; verify breakdown hold and volume if available")

    # Every consecutive 3-candle setup, including the full visible history.
    for k in range(2, n):
        i, j = k - 2, k - 1
        if not contiguous(i, k):
            continue
        o1, h1, l1, c1 = ohlc[i]
        o2, h2, l2, c2 = ohlc[j]
        o3, h3, l3, c3 = ohlc[k]
        small_middle = bodies[j] <= max(bodies[i], bodies[k]) * 0.55
        star_trend = prior_trend(i)
        if colors[i] == "RED" and small_middle and colors[k] == "GREEN" and c3 >= (o1 + c1) / 2 and star_trend == "DOWN":
            add("MORNING_STAR", 0.66, i, k, 0.58, "three-candle bullish reversal after a detected downtrend; follow-through still required")
        if colors[i] == "GREEN" and small_middle and colors[k] == "RED" and c3 <= (o1 + c1) / 2 and star_trend == "UP":
            add("EVENING_STAR", -0.66, i, k, 0.58, "three-candle bearish reversal after a detected uptrend; follow-through still required")
        # Strong directional candles progressing in three successive bars.
        body_ok = all(bodies[x] / ranges[x] >= 0.52 for x in (i, j, k))
        progressively_up = c1 < c2 < c3 and h1 < h2 + tolerance and h2 < h3 + tolerance
        opens_rise = all(min(ohlc[x][0], ohlc[x][3]) - tolerance <= ohlc[x+1][0] <= max(ohlc[x][0], ohlc[x][3]) + tolerance
                         for x in (i, j))
        if colors[i] == colors[j] == colors[k] == "GREEN" and body_ok and progressively_up and opens_rise:
            add("THREE_WHITE_SOLDIERS", 0.76, i, k, 0.66, "three rising green bodies; check overhead resistance")
        progressively_down = c1 > c2 > c3 and l1 > l2 - tolerance and l2 > l3 - tolerance
        opens_fall = all(min(ohlc[x][0], ohlc[x][3]) - tolerance <= ohlc[x+1][0] <= max(ohlc[x][0], ohlc[x][3]) + tolerance
                         for x in (i, j))
        if colors[i] == colors[j] == colors[k] == "RED" and body_ok and progressively_down and opens_fall:
            add("THREE_BLACK_CROWS", -0.76, i, k, 0.66, "three falling red bodies; check nearby support")

    # Additional three-candle reversal confirmations.
    for k in range(2, n):
        i, j = k - 2, k - 1
        if not contiguous(i, k):
            continue
        o1, h1, l1, c1 = ohlc[i]
        o2, h2, l2, c2 = ohlc[j]
        o3, h3, l3, c3 = ohlc[k]
        first_lo, first_hi = min(o1, c1), max(o1, c1)
        middle_lo, middle_hi = min(o2, c2), max(o2, c2)
        prior = prior_trend(i)
        if (colors[i] == "RED" and colors[j] == "GREEN" and colors[k] == "GREEN"
                and middle_lo >= first_lo - tolerance and middle_hi <= first_hi + tolerance
                and c3 > max(o1, c1) and prior == "DOWN"):
            add("THREE_INSIDE_UP", 0.70, i, k, 0.61, "bullish harami followed by an upside close confirmation")
        if (colors[i] == "GREEN" and colors[j] == "RED" and colors[k] == "RED"
                and middle_lo >= first_lo - tolerance and middle_hi <= first_hi + tolerance
                and c3 < min(o1, c1) and prior == "UP"):
            add("THREE_INSIDE_DOWN", -0.70, i, k, 0.61, "bearish harami followed by a downside close confirmation")
        # Three-outside patterns require an engulfing second candle and a third-candle
        # close continuing in the engulfing direction.
        if (colors[i] == "RED" and colors[j] == "GREEN"
                and middle_lo <= first_lo and middle_hi >= first_hi and c3 > c2):
            add("THREE_OUTSIDE_UP", 0.72, i, k, 0.63, "bullish engulfing followed by upward follow-through")
        if (colors[i] == "GREEN" and colors[j] == "RED"
                and middle_lo <= first_lo and middle_hi >= first_hi and c3 < c2):
            add("THREE_OUTSIDE_DOWN", -0.72, i, k, 0.63, "bearish engulfing followed by downward follow-through")

    # Five-candle rising/falling three-method continuation structures. These are
    # only marked when the three countertrend candles stay within the first candle's range.
    for k in range(4, n):
        i = k - 4
        if not contiguous(i, k):
            continue
        first = ohlc[i]
        middle = ohlc[i + 1:k]
        last = ohlc[k]
        first_o, first_h, first_l, first_c = first
        first_body = abs(first_c - first_o)
        median_body_local = max(1.0, float(np.median([max(1.0, abs(row[3] - row[0])) for row in ohlc[max(0, i-6):k+1]])))
        middle_small = all(abs(row[3] - row[0]) <= max(first_body * 0.62, median_body_local * 0.9)
                           and row[1] <= first_h + tolerance and row[2] >= first_l - tolerance
                           for row in middle)
        if (colors[i] == "GREEN" and all(colors[z] == "RED" for z in range(i+1, k))
                and colors[k] == "GREEN" and first_body >= median_body_local * 1.15
                and middle_small and last[3] > first_c and prior_trend(i) in ("UP", "UNKNOWN")):
            add("RISING_THREE_METHODS", 0.66, i, k, 0.60, "bullish impulse, contained pullback, then continuation close")
        if (colors[i] == "RED" and all(colors[z] == "GREEN" for z in range(i+1, k))
                and colors[k] == "RED" and first_body >= median_body_local * 1.15
                and middle_small and last[3] < first_c and prior_trend(i) in ("DOWN", "UNKNOWN")):
            add("FALLING_THREE_METHODS", -0.66, i, k, 0.60, "bearish impulse, contained pullback, then continuation close")

    # Breakout rejection and false-breakout scan at every visible candle.
    for k in range(4, n):
        prior_start = max(0, k - 20)
        if not contiguous(prior_start, k):
            continue
        prior = ohlc[prior_start:k]
        if len(prior) < 4:
            continue
        prior_high = max(row[1] for row in prior)
        prior_low = min(row[2] for row in prior)
        _o, high, low, close = ohlc[k]
        if high > prior_high + tolerance and close < prior_high:
            add("FALSE_UPSIDE_BREAKOUT", -0.62, k, k, 0.57, "wick breached prior range but close returned inside")
        if low < prior_low - tolerance and close > prior_low:
            add("FALSE_DOWNSIDE_BREAKOUT", 0.62, k, k, 0.57, "wick breached prior range but close returned inside")

    # Avoid exact duplicates while retaining the same named pattern at separate points.
    unique: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for item in extras:
        key = (str(item["name"]), tuple(item["candle_indices"]))
        unique[key] = item
    return list(unique.values())


def _core_supplemental_candle_and_smc_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Additional transparent OHLC heuristics for less-common candlestick and SMC labels.

    All measurements come from axis-calibrated visible estimates when available; otherwise
    they use screen-relative OHLC proxies. The emitted entries are hypotheses, not trades.
    """
    rows = list(candles or [])
    n = len(rows)
    if n < 1:
        return []
    values = [_candle_proxy_ohlc(row) for row in rows]
    opens = np.asarray([v[0] for v in values], dtype=float)
    highs = np.asarray([v[1] for v in values], dtype=float)
    lows = np.asarray([v[2] for v in values], dtype=float)
    closes = np.asarray([v[3] for v in values], dtype=float)
    ranges = np.maximum(highs - lows, 1e-9)
    bodies = np.abs(closes - opens)
    upper = np.maximum(0.0, highs - np.maximum(opens, closes))
    lower = np.maximum(0.0, np.minimum(opens, closes) - lows)
    colors = np.asarray([1 if str(r.get("color", "")).upper() == "GREEN" else -1 for r in rows], dtype=int)
    median_range = max(1e-9, float(np.median(ranges[-min(60, n):])))
    median_body = max(1e-9, float(np.median(bodies[-min(60, n):])))
    tolerance = max(median_range * 0.14, 1e-9)
    found: List[Dict[str, Any]] = []

    def contiguous(start: int, end: int) -> bool:
        return all(not bool(rows[p].get("sequence_break_before")) for p in range(start + 1, end + 1))

    def trend_before(i: int, lookback: int = 6) -> str:
        a = max(0, i - lookback)
        for p in range(max(1, a + 1), i + 1):
            if bool(rows[p].get("sequence_break_before")):
                a = p
        if i - a < 3:
            return "UNKNOWN"
        sample = closes[a:i]
        delta = float(sample[-1] - sample[0])
        slope = float(np.polyfit(np.arange(len(sample), dtype=float), sample, 1)[0])
        scale = max(median_range, float(np.median(ranges[a:i])))
        if delta > 0.25 * scale and slope > 0:
            return "UP"
        if delta < -0.25 * scale and slope < 0:
            return "DOWN"
        return "SIDEWAYS"

    def add(name: str, bias: float, start: int, end: int, strength: float = 0.35,
            context: str = "Heuristic candidate; verify trend, level, follow-through and data quality.",
            confirmed: bool = False, family: str = "price_action") -> None:
        if not (0 <= start <= end < n):
            return
        found.append({
            "name": name, "bias": float(clamp(bias, -1.0, 1.0)),
            "confirmed": bool(confirmed), "candle_indices": list(range(start + 1, end + 2)),
            "strength": round(float(clamp(strength, 0.05, 0.95)), 3),
            "raw_strength": round(float(clamp(strength, 0.05, 0.95)), 3),
            "context": context, "pattern_family": family,
            "measurement_basis": "visible-axis OHLC estimate when validated; otherwise normalized screen-pixel proxy",
            "not_a_calibrated_probability": True,
        })

    # Single-candle families which were not separately named by the original detector.
    for i in range(n):
        if i and not contiguous(i - 1, i):
            continue
        o, h, l, c = values[i]
        r = max(1e-9, h - l)
        b = abs(c - o)
        ur, lr = upper[i], lower[i]
        body_ratio = b / r
        close_loc = (c - l) / r
        trend = trend_before(i)
        if body_ratio <= 0.08:
            add("STANDARD_DOJI", 0.0, i, i, 0.34, "Open and close are nearly equal relative to the full range; direction is neutral.")
            if ur / r >= 0.30 and lr / r >= 0.30:
                add("LONG_LEGGED_DOJI", 0.0, i, i, 0.38, "Doji with substantial upper and lower shadows; indecision, not directional confirmation.")
            if ur / r >= 0.32 and lr / r >= 0.32 and abs(close_loc - 0.5) <= 0.18:
                add("RICKSHAW_MAN", 0.0, i, i, 0.34, "Long, approximately balanced shadows and a near-centered doji body.")
        if r <= median_range * 0.18 and body_ratio <= 0.12:
            add("FOUR_PRICE_DOJI", 0.0, i, i, 0.32, "Extremely narrow OHLC range; only valid if candle geometry is genuinely readable.")
        if body_ratio <= 0.25 and ur / r >= 0.28 and lr / r >= 0.28:
            add("HIGH_WAVE_CANDLE", 0.0, i, i, 0.34, "Small body and long shadows on both sides indicate volatility/indecision.")
        if b <= median_body * 0.55 and r <= median_range * 0.72:
            add("SHORT_LINE_CANDLE", 0.0, i, i, 0.25, "Short real body/range versus recent candles; no direction by itself.")
        if b >= median_body * 1.45 and body_ratio >= 0.60:
            if c > o:
                add("LONG_WHITE_CANDLE", 0.42, i, i, 0.46, "Long bullish real body relative to recent bodies.")
            elif c < o:
                add("LONG_BLACK_CANDLE", -0.42, i, i, 0.46, "Long bearish real body relative to recent bodies.")
        if c > o and lower[i] <= 0.10 * r and body_ratio >= 0.55:
            add("OPENING_MARUBOZU", 0.42, i, i, 0.42, "Bullish candle opens at/near its low; require broader context.")
        if c > o and upper[i] <= 0.10 * r and body_ratio >= 0.55:
            add("CLOSING_MARUBOZU", 0.42, i, i, 0.42, "Bullish candle closes at/near its high; require broader context.")
        if c < o and upper[i] <= 0.10 * r and body_ratio >= 0.55:
            add("OPENING_MARUBOZU", -0.42, i, i, 0.42, "Bearish candle opens at/near its high; require broader context.")
        if c < o and lower[i] <= 0.10 * r and body_ratio >= 0.55:
            add("CLOSING_MARUBOZU", -0.42, i, i, 0.42, "Bearish candle closes at/near its low; require broader context.")
        if b >= median_body * 1.25 and c > o and lower[i] <= 0.08 * r:
            add("BULLISH_BELT_HOLD", 0.42, i, i, 0.42, "Long bullish candle with little/no lower shadow; standalone reliability is limited.")
        if b >= median_body * 1.25 and c < o and upper[i] <= 0.08 * r:
            add("BEARISH_BELT_HOLD", -0.42, i, i, 0.42, "Long bearish candle with little/no upper shadow; standalone reliability is limited.")

    # Less-common two-candle patterns. Gap-dependent rules intentionally require real OHLC gaps.
    for j in range(1, n):
        i = j - 1
        if not contiguous(i, j):
            continue
        o1, h1, l1, c1 = values[i]
        o2, h2, l2, c2 = values[j]
        r1, r2 = ranges[i], ranges[j]
        b1, b2 = bodies[i], bodies[j]
        lo1, hi1 = min(o1, c1), max(o1, c1)
        lo2, hi2 = min(o2, c2), max(o2, c2)
        gap_up = l2 > h1 + tolerance
        gap_down = h2 < l1 - tolerance
        # Harami cross: the second candle's body is doji-like and contained by the first real body.
        if b2 <= 0.10 * r2 and lo2 >= lo1 - tolerance and hi2 <= hi1 + tolerance:
            if trend_before(i) == "DOWN":
                add("BULLISH_HARAMI_CROSS", 0.38, i, j, 0.40, "Doji-like second body inside prior body after a downtrend; confirmation still required.")
            elif trend_before(i) == "UP":
                add("BEARISH_HARAMI_CROSS", -0.38, i, j, 0.40, "Doji-like second body inside prior body after an uptrend; confirmation still required.")
        # Counterattack lines: reversal candle closes near the prior close after a large opposite body.
        if colors[i] == -1 and colors[j] == 1 and b1 >= median_body and abs(c2 - c1) <= 0.18 * median_range:
            add("BULLISH_COUNTERATTACK_LINE", 0.34, i, j, 0.36, "Opposite-color candle closes near the previous close; needs trend/location confirmation.")
        if colors[i] == 1 and colors[j] == -1 and b1 >= median_body and abs(c2 - c1) <= 0.18 * median_range:
            add("BEARISH_COUNTERATTACK_LINE", -0.34, i, j, 0.36, "Opposite-color candle closes near the previous close; needs trend/location confirmation.")
        if colors[i] == -1 and colors[j] == 1 and (o2 > h1 + tolerance or o2 > o1 + 0.75 * median_range) and b2 >= median_body:
            add("BULLISH_KICKER", 0.55, i, j, 0.48, "Strong bullish reversal candle gaps/jumps above prior bearish structure; gap must be real.")
        if colors[i] == 1 and colors[j] == -1 and (o2 < l1 - tolerance or o2 < o1 - 0.75 * median_range) and b2 >= median_body:
            add("BEARISH_KICKER", -0.55, i, j, 0.48, "Strong bearish reversal candle gaps/jumps below prior bullish structure; gap must be real.")
        if colors[i] != colors[j] and abs(o2 - o1) <= 0.16 * median_range and b1 >= median_body and b2 >= median_body:
            add("BULLISH_SEPARATING_LINES" if colors[j] == 1 else "BEARISH_SEPARATING_LINES",
                0.30 if colors[j] == 1 else -0.30, i, j, 0.32,
                "Opposite-color candles open near the same level; use only with continuation confirmation.")
        # Tasuki gap continuation. Since crypto trades continuously, absence of a true gap means no detection.
        if i >= 1 and contiguous(i - 1, j):
            o0, h0, l0, c0 = values[i - 1]
            if colors[i - 1] == 1 and colors[i] == 1 and gap_up and colors[j] == -1 and min(o2, c2) > h0 and min(o2, c2) < max(o1, c1) and c2 > h1:
                add("UPSIDE_TASUKI_GAP", 0.40, i - 1, j, 0.42, "Bullish gap remains partially open after a bearish pullback candle.")
            if colors[i - 1] == -1 and colors[i] == -1 and gap_down and colors[j] == 1 and max(o2, c2) < l0 and max(o2, c2) > min(o1, c1) and c2 < l1:
                add("DOWNSIDE_TASUKI_GAP", -0.40, i - 1, j, 0.42, "Bearish gap remains partially open after a bullish pullback candle.")

    # Three-candle families with trend/context requirements where appropriate.
    for k in range(2, n):
        i, j = k - 2, k - 1
        if not contiguous(i, k):
            continue
        o1, h1, l1, c1 = values[i]
        o2, h2, l2, c2 = values[j]
        o3, h3, l3, c3 = values[k]
        if all(bodies[z] <= 0.10 * ranges[z] for z in (i, j, k)):
            add("TRI_STAR", 0.0, i, k, 0.38, "Three doji-like candles; reversal direction is unresolved until breakout.")
        if colors[i] == -1 and colors[j] == 1 and colors[k] == -1 and abs(c3 - c1) <= 0.18 * median_range and b2 >= 0.45 * median_body:
            add("STICK_SANDWICH", 0.0, i, k, 0.36, "Bearish candles with similar closes around a bullish middle candle; needs later confirmation.")
        if colors[i] == 1 and colors[j] == 1 and colors[k] == 1 and c1 < c2 < c3 and bodies[i] > bodies[j] > bodies[k] and upper[k] / ranges[k] > 0.22:
            add("ADVANCE_BLOCK", -0.30 if trend_before(i) == "UP" else 0.0, i, k, 0.36, "Three rising bullish candles with diminishing bodies/upper-wick pressure; possible weakening.")
        if colors[i] == 1 and colors[j] == 1 and colors[k] == 1 and c1 < c2 < c3 and bodies[k] <= 0.48 * min(bodies[i], bodies[j]):
            add("DELIBERATION_PATTERN", -0.28 if trend_before(i) == "UP" else 0.0, i, k, 0.34, "Third bullish candle contracts sharply after an advance; not a sell signal without confirmation.")
        if colors[i] == -1 and colors[j] == -1 and colors[k] == -1 and c1 > c2 > c3 and bodies[i] > bodies[j] > bodies[k] and lower[k] < lower[j]:
            add("THREE_STARS_IN_THE_SOUTH", 0.28 if trend_before(i) == "DOWN" else 0.0, i, k, 0.34, "Three bearish bodies weaken while lower-shadow/range behaviour changes; requires bullish follow-through.")
        if colors[i] == 1 and colors[j] == -1 and colors[k] == -1 and min(o2, c2) > max(o1, c1) and c3 < c2 and c3 > min(o1, c1):
            add("TWO_CROWS", -0.32, i, k, 0.34, "Two bearish candles after an upward gap; gap reliability depends on market/session conditions.")
        if colors[i] == 1 and colors[j] == -1 and colors[k] == -1 and l2 > h1 and c3 > c1 and c3 < c2:
            add("UPSIDE_GAP_TWO_CROWS", -0.36, i, k, 0.36, "Gap-up followed by two bearish candles; require the gap to be genuine and the breakdown to confirm.")
        # Abandoned baby needs genuine open gaps on both sides of a doji-like middle candle.
        if bodies[j] <= 0.10 * ranges[j] and i > 0:
            gap_middle_down = h2 < l1 - tolerance
            gap_middle_up = l2 > h1 + tolerance
            if colors[i] == -1 and colors[k] == 1 and gap_middle_down and l3 > h2 + tolerance and c3 > (o1 + c1) / 2:
                add("BULLISH_ABANDONED_BABY", 0.58, i, k, 0.48, "Doji isolated by downward/upward gaps after a downtrend; rare in continuous crypto charts.")
            if colors[i] == 1 and colors[k] == -1 and gap_middle_up and h3 < l2 - tolerance and c3 < (o1 + c1) / 2:
                add("BEARISH_ABANDONED_BABY", -0.58, i, k, 0.48, "Doji isolated by upward/downward gaps after an uptrend; rare in continuous crypto charts.")

    # Five-candle continuations/reversals.
    for k in range(4, n):
        i = k - 4
        if not contiguous(i, k):
            continue
        seq = list(range(i, k + 1))
        # Mat Hold / Rising Three Methods: strong bullish impulse, contained pullback, continuation breakout.
        if colors[i] == 1 and bodies[i] >= median_body * 1.25 and all(
                colors[z] == -1 and highs[z] <= highs[i] + tolerance and lows[z] >= lows[i] - tolerance
                for z in range(i + 1, k)) and colors[k] == 1 and closes[k] > highs[i]:
            add("MAT_HOLD", 0.56, i, k, 0.52, "Bullish impulse, contained three-candle pause, and close above the impulse high.", True)
        if colors[i] == 1 and bodies[i] >= median_body * 1.25 and all(
                highs[z] <= highs[i] + tolerance and lows[z] >= lows[i] - tolerance for z in range(i + 1, k)
                ) and colors[k] == 1 and closes[k] > highs[i]:
            add("RISING_THREE_METHODS_CONFIRMED", 0.56, i, k, 0.52, "Bullish continuation structure followed by a close above the first candle high.", True)
        if colors[i] == -1 and bodies[i] >= median_body * 1.25 and all(
                highs[z] <= highs[i] + tolerance and lows[z] >= lows[i] - tolerance for z in range(i + 1, k)
                ) and colors[k] == -1 and closes[k] < lows[i]:
            add("FALLING_THREE_METHODS_CONFIRMED", -0.56, i, k, 0.52, "Bearish continuation structure followed by a close below the first candle low.", True)
        # Five-day breakaway is approximate; only a completed reversal break contributes direction.
        if colors[i] == -1 and colors[k] == 1 and closes[k] > max(highs[i:k]) and trend_before(i) == "DOWN":
            add("BULLISH_BREAKAWAY", 0.38, i, k, 0.38, "Five-candle bearish-to-bullish reversal candidate; this is a simplified screen heuristic.", True)
        if colors[i] == 1 and colors[k] == -1 and closes[k] < min(lows[i:k]) and trend_before(i) == "UP":
            add("BEARISH_BREAKAWAY", -0.38, i, k, 0.38, "Five-candle bullish-to-bearish reversal candidate; this is a simplified screen heuristic.", True)

    # Smart-money/liquidity proxies. They are measured from the same OHLC sequence and
    # deliberately grouped: one liquidity event must not count as many independent votes.
    recent_start = max(0, n - 30)
    recent_highs = highs[recent_start:n - 1] if n > 1 else np.asarray([], dtype=float)
    recent_lows = lows[recent_start:n - 1] if n > 1 else np.asarray([], dtype=float)
    last_o, last_h, last_l, last_c = values[-1]
    last_range = max(1e-9, last_h - last_l)
    last_close_location = (last_c - last_l) / last_range
    level_tol = max(tolerance, median_range * 0.20)
    if n >= 6 and recent_highs.size >= 5:
        prior_hi = float(np.max(recent_highs))
        equal_highs = [idx for idx in range(recent_start, n - 1) if abs(highs[idx] - prior_hi) <= level_tol]
        swept_high = last_h > prior_hi + 0.10 * median_range and last_c < prior_hi
        if len(equal_highs) >= 2:
            add("EQUAL_HIGHS_BUY_SIDE_LIQUIDITY", 0.0, equal_highs[-2], equal_highs[-1], 0.30,
                "Two or more similar swing highs define a possible buy-side liquidity pool; this is a level, not direction.", False, "liquidity")
            add("BSL_EQH", 0.0, equal_highs[-2], equal_highs[-1], 0.22,
                "Buy-side liquidity / equal-high alias for the same price pool; not an independent directional vote.", False, "liquidity_alias")
        if swept_high:
            add("BUY_SIDE_LIQUIDITY_SWEEP_SELL_SIGNAL", -0.48, n - 1, n - 1, 0.50,
                "Latest wick swept prior highs and close returned below them (BSL sweep/stop-run proxy).", True, "liquidity")
            add("TURTLE_SOUP_SETUP", -0.40, n - 1, n - 1, 0.42,
                "Prior-range high was breached intrabar and reclaimed lower by close; bearish Turtle Soup proxy.", True, "liquidity")
            add("LIQUIDITY_GRAB_OR_STOP_HUNT", -0.38, n - 1, n - 1, 0.40,
                "Failed upside raid is inferred from OHLC only; actual order-book stops are not visible.", True, "liquidity")
            if len(equal_highs) >= 2:
                add("INDUCEMENT_BSL_RAID_PROXY", -0.24, equal_highs[-2], n - 1, 0.30,
                    "A visible equal-high pool preceded the upside sweep; inducement is a heuristic label, not intent detection.", True, "liquidity")
    if n >= 6 and recent_lows.size >= 5:
        prior_lo = float(np.min(recent_lows))
        equal_lows = [idx for idx in range(recent_start, n - 1) if abs(lows[idx] - prior_lo) <= level_tol]
        swept_low = last_l < prior_lo - 0.10 * median_range and last_c > prior_lo
        if len(equal_lows) >= 2:
            add("EQUAL_LOWS_SELL_SIDE_LIQUIDITY", 0.0, equal_lows[-2], equal_lows[-1], 0.30,
                "Two or more similar swing lows define a possible sell-side liquidity pool; this is a level, not direction.", False, "liquidity")
            add("SSL_EQL", 0.0, equal_lows[-2], equal_lows[-1], 0.22,
                "Sell-side liquidity / equal-low alias for the same price pool; not an independent directional vote.", False, "liquidity_alias")
        if swept_low:
            add("SELL_SIDE_LIQUIDITY_SWEEP_BUY_SIGNAL", 0.48, n - 1, n - 1, 0.50,
                "Latest wick swept prior lows and close returned above them (SSL sweep/stop-run proxy).", True, "liquidity")
            add("TURTLE_SOUP_SETUP", 0.40, n - 1, n - 1, 0.42,
                "Prior-range low was breached intrabar and reclaimed higher by close; bullish Turtle Soup proxy.", True, "liquidity")
            add("LIQUIDITY_GRAB_OR_STOP_HUNT", 0.38, n - 1, n - 1, 0.40,
                "Failed downside raid is inferred from OHLC only; actual order-book stops are not visible.", True, "liquidity")
            if len(equal_lows) >= 2:
                add("INDUCEMENT_SSL_RAID_PROXY", 0.24, equal_lows[-2], n - 1, 0.30,
                    "A visible equal-low pool preceded the downside sweep; inducement is a heuristic label, not intent detection.", True, "liquidity")

    # Three-candle fair-value gaps (FVG) and consequent encroachment (midpoint) zones.
    fvg_added = 0
    for k in range(max(2, n - 24), n):
        i = k - 2
        if not contiguous(i, k):
            continue
        bullish_gap = lows[k] > highs[i] + 0.04 * median_range
        bearish_gap = highs[k] < lows[i] - 0.04 * median_range
        if bullish_gap:
            zone_low, zone_high = float(highs[i]), float(lows[k])
            ce = (zone_low + zone_high) / 2.0
            reaction = last_c >= ce and last_l <= zone_high + tolerance
            add("BULLISH_FVG_IMBALANCE_LIQUIDITY_VOID", 0.22 if reaction else 0.0, i, k, 0.36,
                f"Three-candle bullish gap zone; CE midpoint={ce:.6g}; reaction={reaction}. Pixel proxies are not market prices.", bool(reaction), "imbalance")
            add("BULLISH_FVG", 0.0, i, k, 0.25,
                "Alias for the same measured bullish three-candle fair-value-gap zone; its direction is already represented by the parent imbalance feature.", bool(reaction), "imbalance_alias")
            if abs(last_c - ce) <= tolerance:
                add("CONSEQUENT_ENCROACHMENT_CE", 0.0, i, k, 0.24,
                    f"Price is near the 50% midpoint of the detected bullish FVG ({ce:.6g}); location-only confluence.", False, "imbalance_location")
            fvg_added += 1
        elif bearish_gap:
            zone_low, zone_high = float(highs[k]), float(lows[i])
            ce = (zone_low + zone_high) / 2.0
            reaction = last_c <= ce and last_h >= zone_low - tolerance
            add("BEARISH_FVG_IMBALANCE_LIQUIDITY_VOID", -0.22 if reaction else 0.0, i, k, 0.36,
                f"Three-candle bearish gap zone; CE midpoint={ce:.6g}; reaction={reaction}. Pixel proxies are not market prices.", bool(reaction), "imbalance")
            add("BEARISH_FVG", 0.0, i, k, 0.25,
                "Alias for the same measured bearish three-candle fair-value-gap zone; its direction is already represented by the parent imbalance feature.", bool(reaction), "imbalance_alias")
            if abs(last_c - ce) <= tolerance:
                add("CONSEQUENT_ENCROACHMENT_CE", 0.0, i, k, 0.24,
                    f"Price is near the 50% midpoint of the detected bearish FVG ({ce:.6g}); location-only confluence.", False, "imbalance_location")
            fvg_added += 1
        if fvg_added >= 3:
            break

    # Premium/discount and OTE are location context, not directional votes by themselves.
    if n >= 12:
        span_hi = float(np.max(highs[-min(30, n):]))
        span_lo = float(np.min(lows[-min(30, n):]))
        span = max(1e-9, span_hi - span_lo)
        eq = (span_hi + span_lo) / 2.0
        position = (last_c - span_lo) / span
        add("EQUILIBRIUM_50_PERCENT", 0.0, max(0, n - min(30, n)), n - 1, 0.22,
            f"Range midpoint={eq:.6g}; latest position in range={position:.3f}; location only, not a signal.", False, "location")
        if position >= 0.70:
            add("PREMIUM_ZONE", 0.0, max(0, n - min(30, n)), n - 1, 0.24,
                "Latest close is in the upper 30% of the recent range; premium alone does not mean SELL.", False, "location")
        elif position <= 0.30:
            add("DISCOUNT_ZONE", 0.0, max(0, n - min(30, n)), n - 1, 0.24,
                "Latest close is in the lower 30% of the recent range; discount alone does not mean BUY.", False, "location")
        # OTE-style pullback location after a clear swing is recorded only when the current candle reacts.
        recent_delta = float(closes[-1] - closes[-min(12, n)])
        if recent_delta > 0:
            fib618 = span_hi - 0.618 * span
            fib79 = span_hi - 0.79 * span
            in_ote = min(fib618, fib79) - tolerance <= last_c <= max(fib618, fib79) + tolerance
            reacted = last_c > last_o and last_close_location >= 0.55
            if in_ote and reacted:
                add("OPTIMAL_TRADE_ENTRY_OTE_BULLISH_REACTION", 0.22, n - 1, n - 1, 0.30,
                    "Bullish candle reaction inside a simplified 61.8–79% retracement area; Fibonacci is confluence only.", True, "location")
        elif recent_delta < 0:
            fib618 = span_lo + 0.618 * span
            fib79 = span_lo + 0.79 * span
            in_ote = min(fib618, fib79) - tolerance <= last_c <= max(fib618, fib79) + tolerance
            reacted = last_c < last_o and last_close_location <= 0.45
            if in_ote and reacted:
                add("OPTIMAL_TRADE_ENTRY_OTE_BEARISH_REACTION", -0.22, n - 1, n - 1, 0.30,
                    "Bearish candle reaction inside a simplified 61.8–79% retracement area; Fibonacci is confluence only.", True, "location")

    # Displacement and an order-block candidate: requires a large latest body plus a real break.
    if n >= 8:
        prior_high = float(np.max(highs[-9:-1]))
        prior_low = float(np.min(lows[-9:-1]))
        large_body = bodies[-1] >= 1.35 * median_body and ranges[-1] >= 1.15 * median_range
        bullish_disp = large_body and last_c > last_o and last_c > prior_high
        bearish_disp = large_body and last_c < last_o and last_c < prior_low
        if bullish_disp:
            add("BULLISH_DISPLACEMENT_BOS", 0.40, n - 1, n - 1, 0.44,
                "Large bullish body closed above the recent high; displacement/BOS proxy.", True, "structure")
            opposite = next((p for p in range(n - 2, max(-1, n - 7), -1) if colors[p] < 0), None)
            if opposite is not None:
                add("BULLISH_ORDER_BLOCK", 0.24, opposite, n - 1, 0.34,
                    "Last bearish candle before the detected bullish displacement; zone is a proxy, not order-flow data.", True, "order_block")
        if bearish_disp:
            add("BEARISH_DISPLACEMENT_BOS", -0.40, n - 1, n - 1, 0.44,
                "Large bearish body closed below the recent low; displacement/BOS proxy.", True, "structure")
            opposite = next((p for p in range(n - 2, max(-1, n - 7), -1) if colors[p] > 0), None)
            if opposite is not None:
                add("BEARISH_ORDER_BLOCK", -0.24, opposite, n - 1, 0.34,
                    "Last bullish candle before the detected bearish displacement; zone is a proxy, not order-flow data.", True, "order_block")

    # Additional objectively testable structure labels requested by the trading prompt.
    if n >= 20:
        win_start = n - 20
        width = 5
        rolling_widths = [float(np.max(highs[win_start+i:win_start+i+width]) - np.min(lows[win_start+i:win_start+i+width]))
                          for i in (0, 5, 10, 15)]
        expanding_then_contracting = (rolling_widths[1] > 1.12 * max(rolling_widths[0], 1e-9)
                                      and rolling_widths[3] < 0.88 * max(rolling_widths[1], 1e-9))
        if expanding_then_contracting:
            centre = win_start + 10
            if np.argmax(highs[win_start:n]) in range(5, 15):
                confirmed = bool(last_c < float(np.min(lows[-10:-1])) - 0.10 * median_range)
                add("DIAMOND_TOP", -0.38 if confirmed else 0.0, win_start, n-1, 0.36,
                    "Range first expands then contracts around a central high; bearish bias needs a completed downside break.", confirmed, "chart_pattern")
            if np.argmin(lows[win_start:n]) in range(5, 15):
                confirmed = bool(last_c > float(np.max(highs[-10:-1])) + 0.10 * median_range)
                add("DIAMOND_BOTTOM", 0.38 if confirmed else 0.0, win_start, n-1, 0.36,
                    "Range first expands then contracts around a central low; bullish bias needs a completed upside break.", confirmed, "chart_pattern")

    # Measured move projects the prior range height after a confirmed boundary close.
    if n >= 12:
        prior_hi = float(np.max(highs[-12:-1]))
        prior_lo = float(np.min(lows[-12:-1]))
        range_height = max(1e-9, prior_hi - prior_lo)
        if last_c > prior_hi + 0.10 * median_range:
            target = last_c + range_height
            add("MEASURED_MOVE_UP", 0.24, n-1, n-1, 0.28,
                f"Upside boundary closed; naive measured-move reference={target:.6g}, not a guaranteed target.", True, "projection")
        elif last_c < prior_lo - 0.10 * median_range:
            target = last_c - range_height
            add("MEASURED_MOVE_DOWN", -0.24, n-1, n-1, 0.28,
                f"Downside boundary closed; naive measured-move reference={target:.6g}, not a guaranteed target.", True, "projection")

        # Support/resistance role flips are only marked when a later candle retests a broken level.
        lookback = min(18, n - 1)
        previous_hi = float(np.max(highs[-lookback-1:-1]))
        previous_lo = float(np.min(lows[-lookback-1:-1]))
        if n >= 3 and closes[-2] > previous_hi + 0.10 * median_range:
            touched = lows[-1] <= previous_hi + tolerance and closes[-1] >= previous_hi - tolerance
            if touched:
                add("RESISTANCE_FLIP_TO_SUPPORT_ROLE_REVERSAL", 0.28, n-2, n-1, 0.34,
                    "Prior resistance was broken by a close, then the latest candle retested and held above it.", True, "structure")
        if n >= 3 and closes[-2] < previous_lo - 0.10 * median_range:
            touched = highs[-1] >= previous_lo - tolerance and closes[-1] <= previous_lo + tolerance
            if touched:
                add("SUPPORT_FLIP_TO_RESISTANCE_ROLE_REVERSAL", -0.28, n-2, n-1, 0.34,
                    "Prior support was broken by a close, then the latest candle retested and held below it.", True, "structure")

    # Order-block follow-up labels require a later retest of the displacement-origin candle.
    if n >= 10:
        scan_start = max(2, n - 12)
        block_added = 0
        for disp_idx in range(scan_start, n - 1):
            previous_idx = disp_idx - 1
            if bodies[disp_idx] < 1.35 * median_body or ranges[disp_idx] < 1.15 * median_range:
                continue
            local_hi = float(np.max(highs[max(0,disp_idx-8):disp_idx]))
            local_lo = float(np.min(lows[max(0,disp_idx-8):disp_idx]))
            bullish_disp = colors[disp_idx] > 0 and closes[disp_idx] > local_hi
            bearish_disp = colors[disp_idx] < 0 and closes[disp_idx] < local_lo
            zone_lo = float(min(opens[previous_idx], closes[previous_idx]))
            zone_hi = float(max(opens[previous_idx], closes[previous_idx]))
            for retest_idx in range(disp_idx + 1, n):
                intersects = lows[retest_idx] <= zone_hi + tolerance and highs[retest_idx] >= zone_lo - tolerance
                if not intersects:
                    continue
                if bullish_disp and colors[previous_idx] < 0:
                    if closes[retest_idx] >= zone_lo:
                        add("BULLISH_MITIGATION_BLOCK_RETEST", 0.20, previous_idx, retest_idx, 0.30,
                            "Later retest of a bearish candle before an upside displacement, with close holding the zone.", True, "order_block")
                    else:
                        add("BULLISH_ORDER_BLOCK_INVALIDATED_BEARISH_BREAKER", -0.20, previous_idx, retest_idx, 0.30,
                            "Prior bullish order-block hypothesis failed; the zone is treated as a potential bearish breaker only after close-through.", True, "order_block")
                if bearish_disp and colors[previous_idx] > 0:
                    if closes[retest_idx] <= zone_hi:
                        add("BEARISH_MITIGATION_BLOCK_RETEST", -0.20, previous_idx, retest_idx, 0.30,
                            "Later retest of a bullish candle before a downside displacement, with close holding the zone.", True, "order_block")
                    else:
                        add("BEARISH_ORDER_BLOCK_INVALIDATED_BULLISH_BREAKER", 0.20, previous_idx, retest_idx, 0.30,
                            "Prior bearish order-block hypothesis failed; the zone is treated as a potential bullish breaker only after close-through.", True, "order_block")
                block_added += 1
                break
            if block_added >= 2:
                break

    # Accumulation/manipulation/distribution is explicitly a range-sweep proxy, not proof of intent.
    if n >= 18:
        accumulation_start = max(0, n - 18)
        accumulation_end = n - 6
        acc_hi = float(np.max(highs[accumulation_start:accumulation_end]))
        acc_lo = float(np.min(lows[accumulation_start:accumulation_end]))
        acc_span = acc_hi - acc_lo
        acc_ranges = ranges[accumulation_start:accumulation_end]
        compressed_range = len(acc_ranges) >= 8 and acc_span <= 8.0 * max(median_range, 1e-9)
        manipulate_up = float(np.max(highs[accumulation_end:])) > acc_hi + 0.10*median_range
        manipulate_down = float(np.min(lows[accumulation_end:])) < acc_lo - 0.10*median_range
        distribution_down = last_c < acc_lo - 0.10*median_range
        distribution_up = last_c > acc_hi + 0.10*median_range
        if compressed_range and manipulate_up and distribution_down:
            add("ACCUMULATION_MANIPULATION_DISTRIBUTION_AMD_PO3_BEARISH_PROXY", -0.30, accumulation_start, n-1, 0.34,
                "Compressed range, upside sweep and downside distribution-like close; PO3/AMD is only a candle-sequence proxy.", True, "smc_sequence")
        elif compressed_range and manipulate_down and distribution_up:
            add("ACCUMULATION_MANIPULATION_DISTRIBUTION_AMD_PO3_BULLISH_PROXY", 0.30, accumulation_start, n-1, 0.34,
                "Compressed range, downside sweep and upside distribution-like close; PO3/AMD is only a candle-sequence proxy.", True, "smc_sequence")

    # A rejection-block proxy is emitted only when a wick sweeps a recent extreme and closes back inside.
    if n >= 6:
        local_hi = float(np.max(highs[-6:-1])); local_lo = float(np.min(lows[-6:-1]))
        if last_h > local_hi + tolerance and last_c < local_hi and upper[-1] >= 0.30*last_range:
            add("BEARISH_REJECTION_BLOCK", -0.28, n-1, n-1, 0.30,
                "Upper-wick rejection at a prior range high; wick/OHLC proxy, not order-book evidence.", True, "order_block")
        if last_l < local_lo - tolerance and last_c > local_lo and lower[-1] >= 0.30*last_range:
            add("BULLISH_REJECTION_BLOCK", 0.28, n-1, n-1, 0.30,
                "Lower-wick rejection at a prior range low; wick/OHLC proxy, not order-book evidence.", True, "order_block")

    # Gap-dependent island reversals: deliberately absent unless both gaps are visible in OHLC.
    for k in range(2, n):
        i, j = k - 2, k - 1
        if not contiguous(i, k):
            continue
        # Bullish island: middle candle is isolated below both neighbouring ranges.
        if highs[j] < lows[i] - tolerance and lows[k] > highs[j] + tolerance and closes[k] > opens[k]:
            add("BULLISH_ISLAND_REVERSAL", 0.38, i, k, 0.38,
                "Middle candle/cluster is isolated by genuine downside and upside gaps; rare on 24/7 crypto charts.", True, "chart_pattern")
        # Bearish island: middle candle is isolated above both neighbouring ranges.
        if lows[j] > highs[i] + tolerance and highs[k] < lows[j] - tolerance and closes[k] < opens[k]:
            add("BEARISH_ISLAND_REVERSAL", -0.38, i, k, 0.38,
                "Middle candle/cluster is isolated by genuine upside and downside gaps; rare on 24/7 crypto charts.", True, "chart_pattern")

    # Internal/external range liquidity are location tags; never count these tags as directional votes.
    if n >= 12:
        range_high = float(np.max(highs[-min(30,n):]))
        range_low = float(np.min(lows[-min(30,n):]))
        range_mid = (range_high + range_low) / 2.0
        if range_low < last_c < range_high:
            add("INTERNAL_RANGE_LIQUIDITY_IRL", 0.0, max(0,n-min(30,n)), n-1, 0.20,
                "Current close remains within the recent range; internal liquidity is a map label, not order-book data.", False, "liquidity")
        if last_h >= range_high - tolerance or last_l <= range_low + tolerance:
            add("EXTERNAL_RANGE_LIQUIDITY_ERL", 0.0, max(0,n-min(30,n)), n-1, 0.22,
                "Price is at/near the recent range extreme; external liquidity is inferred from visible highs/lows only.", False, "liquidity")

    # Explicit double-pattern checks requested for this version. They are treated as
    # lower-strength, non-standard variants and only gain direction after a later close
    # confirms the rejection; two shapes alone do not force a BUY/SELL.
    if n >= 4:
        first_candidate = max(0, n - 5)
        # Two upper-wick rejection bars followed by a lower close: bearish double-pin proxy.
        for confirm_idx in range(max(2, n - 3), n):
            a, b, z = confirm_idx - 2, confirm_idx - 1, confirm_idx
            if a < first_candidate or not contiguous(a, z):
                continue
            pin_a = upper[a] >= max(1e-9, 1.55 * bodies[a]) and upper[a] / ranges[a] >= 0.42 and lower[a] / ranges[a] <= 0.30
            pin_b = upper[b] >= max(1e-9, 1.55 * bodies[b]) and upper[b] / ranges[b] >= 0.42 and lower[b] / ranges[b] <= 0.30
            bearish_confirm = closes[z] < min(opens[b], closes[b]) and closes[z] < closes[b]
            if pin_a and pin_b and trend_before(a) == "UP":
                add("DOUBLE_PIN_BAR_BEARISH", -0.32 if bearish_confirm else 0.0, a, z, 0.32,
                    "Two upper-wick rejection candles after an up-move; bearish bias is admitted only after a later close confirms downward.",
                    bool(bearish_confirm), "double_rejection")
            # Two lower-wick rejection bars followed by a higher close: bullish counterpart.
            pin_a_bull = lower[a] >= max(1e-9, 1.55 * bodies[a]) and lower[a] / ranges[a] >= 0.42 and upper[a] / ranges[a] <= 0.30
            pin_b_bull = lower[b] >= max(1e-9, 1.55 * bodies[b]) and lower[b] / ranges[b] >= 0.42 and upper[b] / ranges[b] <= 0.30
            bullish_confirm = closes[z] > max(opens[b], closes[b]) and closes[z] > closes[b]
            if pin_a_bull and pin_b_bull and trend_before(a) == "DOWN":
                add("DOUBLE_PIN_BAR_BULLISH", 0.32 if bullish_confirm else 0.0, a, z, 0.32,
                    "Two lower-wick rejection candles after a down-move; bullish bias is admitted only after a later close confirms upward.",
                    bool(bullish_confirm), "double_rejection")

        # The phrase 'double hammer bearish' is not a standard single definition;
        # treat it as a custom two-rejection setup, never as a standalone textbook pattern.
        for confirm_idx in range(max(2, n - 3), n):
            a, b, z = confirm_idx - 2, confirm_idx - 1, confirm_idx
            if a < first_candidate or not contiguous(a, z) or trend_before(a) != "UP":
                continue
            hammer_a = lower[a] >= max(1e-9, 1.60 * bodies[a]) and upper[a] / ranges[a] <= 0.24
            hammer_b = lower[b] >= max(1e-9, 1.60 * bodies[b]) and upper[b] / ranges[b] <= 0.24
            bearish_confirm = closes[z] < min(lows[a], lows[b]) and colors[z] < 0
            if hammer_a and hammer_b:
                add("DOUBLE_HAMMER_BEARISH", -0.28 if bearish_confirm else 0.0, a, z, 0.28,
                    "Custom double lower-wick rejection after an uptrend; bearish direction requires a subsequent close below both lows.",
                    bool(bearish_confirm), "double_rejection")

        # Two doji-like candles at the upper end of an advance become bearish evidence
        # only when a following candle closes below both doji lows.
        doji_prior = [i for i in range(first_candidate, n - 1)
                      if bodies[i] / ranges[i] <= 0.10 and not any(bool(rows[p].get("sequence_break_before")) for p in range(i + 1, n))]
        if len(doji_prior) >= 2:
            a, b = doji_prior[-2:]
            bearish_confirm = (b < n - 1 and closes[-1] < min(lows[a], lows[b])
                               and colors[-1] < 0 and trend_before(a) == "UP")
            if trend_before(a) == "UP":
                add("DOUBLE_DOJI_BEARISH", -0.26 if bearish_confirm else 0.0, a, n - 1, 0.26,
                    "Two doji-like candles after an advance; directional bearish evidence requires a later close below both lows.",
                    bool(bearish_confirm), "double_indecision")

    # Trading-range and fakeout names are tied to measurable prior boundaries.
    # They remain neutral while price is inside the range; the wick-reclaim is the signal.
    if n >= 12:
        range_start = max(0, n - 19)
        prior_hi = float(np.max(highs[range_start:n - 1]))
        prior_lo = float(np.min(lows[range_start:n - 1]))
        prior_span = max(1e-9, prior_hi - prior_lo)
        recent_tolerance = max(tolerance, median_range * 0.20)
        hi_touches = sum(1 for value in highs[range_start:n - 1] if abs(float(value) - prior_hi) <= recent_tolerance)
        lo_touches = sum(1 for value in lows[range_start:n - 1] if abs(float(value) - prior_lo) <= recent_tolerance)
        compact = prior_span <= 9.0 * median_range
        if compact and hi_touches >= 2 and lo_touches >= 2:
            if closes[-1] > prior_hi + recent_tolerance:
                range_bias, range_confirmed = 0.24, True
                range_context = "Measured prior trading range broke upward on a close."
            elif closes[-1] < prior_lo - recent_tolerance:
                range_bias, range_confirmed = -0.24, True
                range_context = "Measured prior trading range broke downward on a close."
            else:
                range_bias, range_confirmed = 0.0, False
                range_context = "Repeated upper/lower tests form a possible range; no directional vote before a close outside it."
            add("TRADING_RANGE", range_bias, range_start, n - 1, 0.24, range_context,
                range_confirmed, "chart_structure")
        if highs[-1] > prior_hi + recent_tolerance and closes[-1] <= prior_hi:
            add("FAKEOUT_UPSIDE_SWEEP", -0.24, n - 1, n - 1, 0.28,
                "Latest high crossed the prior high but close returned underneath it; false-break proxy.", True, "breakout")
        elif lows[-1] < prior_lo - recent_tolerance and closes[-1] >= prior_lo:
            add("FAKEOUT_DOWNSIDE_SWEEP", 0.24, n - 1, n - 1, 0.28,
                "Latest low crossed the prior low but close reclaimed it; false-break proxy.", True, "breakout")

    # Compress repeated same-event labels so correlations cannot multiply the final score.
    unique: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for row in found:
        unique[(str(row.get("name")), tuple(row.get("candle_indices") or []))] = row
    return list(unique.values())


def _core_detect_classical_chart_patterns(candles: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Detect conservative, chart-derived formations; unbroken patterns are neutral, not trade calls."""
    all_rows = list(candles or [])
    segment_start = 0
    for idx in range(1, len(all_rows)):
        if bool(all_rows[idx].get("sequence_break_before")):
            segment_start = idx
    rows = all_rows[segment_start:]
    offset = segment_start
    if len(rows) > 80:
        offset += len(rows) - 80
        rows = rows[-80:]
    n = len(rows)
    if n < 12:
        return {"available": False, "patterns": [], "line_segments": [], "bias": 0.0,
                "reason": "At least 12 contiguous M1 candles are needed for conservative chart-pattern detection."}

    ohlc = [_candle_proxy_ohlc(row) for row in rows]
    opens = np.asarray([v[0] for v in ohlc], dtype=float)
    highs = np.asarray([v[1] for v in ohlc], dtype=float)
    lows = np.asarray([v[2] for v in ohlc], dtype=float)
    closes = np.asarray([v[3] for v in ohlc], dtype=float)
    ranges = np.maximum(highs - lows, 1e-9)
    typical_range = max(1e-9, float(np.median(ranges[-min(30, n):])))
    tolerance = max(0.55 * typical_range, 1e-9)
    pivot_highs: List[int] = []
    pivot_lows: List[int] = []
    for i in range(2, n - 2):
        if highs[i] >= max(float(np.max(highs[i-2:i])), float(np.max(highs[i+1:i+3]))):
            pivot_highs.append(i)
        if lows[i] <= min(float(np.min(lows[i-2:i])), float(np.min(lows[i+1:i+3]))):
            pivot_lows.append(i)

    found: List[Dict[str, Any]] = []
    lines: List[Dict[str, Any]] = []
    def add(name: str, bias: float, idxs: List[int], confirmed: bool, context: str,
            line_defs: Optional[List[Tuple[int, int, float, float, str]]] = None) -> None:
        item = {"name": name, "bias": float(bias), "confirmed": bool(confirmed),
                "state": "CONFIRMED_BREAKOUT" if confirmed else "FORMING_OR_UNCONFIRMED",
                "candle_indices": [int(offset + i + 1) for i in idxs], "context": context,
                "strength": round(min(1.0, 0.38 + 0.12 * len(idxs) + (0.16 if confirmed else 0.0)), 3)}
        found.append(item)
        for x1, x2, y1, y2, label in (line_defs or []):
            lines.append({"pattern": name, "label": label, "x1_index": int(offset + x1),
                          "x2_index": int(offset + x2), "y1_price": float(y1), "y2_price": float(y2),
                          "confirmed": bool(confirmed)})

    # Double tops/bottoms: equal-ish extrema plus a meaningful intervening swing; only a neck break gives direction.
    recent_highs = [i for i in pivot_highs if i >= max(0, n - 45)][-5:]
    recent_lows = [i for i in pivot_lows if i >= max(0, n - 45)][-5:]
    if len(recent_highs) >= 2:
        a, b = recent_highs[-2:]
        neckline = float(np.min(lows[a:b+1])) if b > a + 1 else min(lows[a], lows[b])
        equal = abs(float(highs[a] - highs[b])) <= max(0.75 * typical_range, tolerance)
        depth = float(min(highs[a], highs[b]) - neckline) >= 0.90 * typical_range
        confirmed = bool(equal and depth and closes[-1] < neckline - 0.10 * typical_range)
        if equal and depth:
            add("DOUBLE_TOP", -0.56 if confirmed else 0.0, [a, b], confirmed,
                "near-equal swing highs; directional bearish bias is enabled only after a confirmed neckline close below",
                [(a, b, float(highs[a]), float(highs[b]), "DOUBLE TOP") ,
                 (a, n-1, neckline, neckline, "NECKLINE")])
    if len(recent_lows) >= 2:
        a, b = recent_lows[-2:]
        neckline = float(np.max(highs[a:b+1])) if b > a + 1 else max(highs[a], highs[b])
        equal = abs(float(lows[a] - lows[b])) <= max(0.75 * typical_range, tolerance)
        depth = float(neckline - max(lows[a], lows[b])) >= 0.90 * typical_range
        confirmed = bool(equal and depth and closes[-1] > neckline + 0.10 * typical_range)
        if equal and depth:
            add("DOUBLE_BOTTOM", 0.56 if confirmed else 0.0, [a, b], confirmed,
                "near-equal swing lows; directional bullish bias is enabled only after a confirmed neckline close above",
                [(a, b, float(lows[a]), float(lows[b]), "DOUBLE BOTTOM"),
                 (a, n-1, neckline, neckline, "NECKLINE")])

    # Head-and-shoulders / inverse head-and-shoulders need three pivots, symmetric shoulders and neckline break.
    if len(recent_highs) >= 3:
        left, head, right = recent_highs[-3:]
        shoulder_match = abs(float(highs[left] - highs[right])) <= 1.25 * typical_range
        head_high = highs[head] > max(highs[left], highs[right]) + 0.45 * typical_range
        if left < head < right and shoulder_match and head_high:
            lneck = float(np.min(lows[left:head+1])); rneck = float(np.min(lows[head:right+1]))
            neckline_now = (lneck + rneck) / 2.0
            confirmed = bool(closes[-1] < neckline_now - 0.10 * typical_range)
            add("HEAD_AND_SHOULDERS", -0.62 if confirmed else 0.0, [left, head, right], confirmed,
                "three-peak reversal candidate; sell-side bias requires a close below the two-trough neckline",
                [(left, head, float(highs[left]), float(highs[head]), "H&S PEAKS"),
                 (head, right, float(highs[head]), float(highs[right]), "H&S PEAKS"),
                 (left, right, lneck, rneck, "H&S NECKLINE")])
    if len(recent_lows) >= 3:
        left, head, right = recent_lows[-3:]
        shoulder_match = abs(float(lows[left] - lows[right])) <= 1.25 * typical_range
        head_low = lows[head] < min(lows[left], lows[right]) - 0.45 * typical_range
        if left < head < right and shoulder_match and head_low:
            lneck = float(np.max(highs[left:head+1])); rneck = float(np.max(highs[head:right+1]))
            neckline_now = (lneck + rneck) / 2.0
            confirmed = bool(closes[-1] > neckline_now + 0.10 * typical_range)
            add("INVERSE_HEAD_AND_SHOULDERS", 0.62 if confirmed else 0.0, [left, head, right], confirmed,
                "three-trough reversal candidate; buy-side bias requires a close above the neckline",
                [(left, head, float(lows[left]), float(lows[head]), "INVERSE H&S TROUGHS"),
                 (head, right, float(lows[head]), float(lows[right]), "INVERSE H&S TROUGHS"),
                 (left, right, lneck, rneck, "INVERSE H&S NECKLINE")])

    # Regression on the latest 18 bars provides simple channel/triangle/rectangle candidates.
    window = min(18, n)
    start = n - window
    xs = np.arange(window, dtype=float)
    high_window = highs[start:]
    low_window = lows[start:]
    hi_slope, hi_intercept = np.polyfit(xs, high_window, 1)
    lo_slope, lo_intercept = np.polyfit(xs, low_window, 1)
    hs = float(hi_slope / typical_range)
    ls = float(lo_slope / typical_range)
    high_end = float(hi_slope * (window - 1) + hi_intercept)
    low_end = float(lo_slope * (window - 1) + lo_intercept)
    high_start = float(hi_intercept); low_start = float(lo_intercept)
    compressed = (float(np.std(high_window - (hi_slope*xs + hi_intercept))) < 0.75 * typical_range
                  and float(np.std(low_window - (lo_slope*xs + lo_intercept))) < 0.75 * typical_range)
    high_boundary = high_end; low_boundary = low_end
    close = float(closes[-1])
    breakout_up = close > high_boundary + 0.10 * typical_range
    breakout_down = close < low_boundary - 0.10 * typical_range
    def line_pair(name: str, bias: float, confirmed: bool, context: str) -> None:
        add(name, bias, [start, n-1], confirmed, context,
            [(start, n-1, high_start, high_end, name + " UPPER"),
             (start, n-1, low_start, low_end, name + " LOWER")])

    if compressed and hs < -0.10 and ls > 0.10 and high_end - low_end < (high_window[0] - low_window[0]) * 0.88:
        bias = 0.52 if breakout_up else (-0.52 if breakout_down else 0.0)
        line_pair("SYMMETRICAL_TRIANGLE", bias, bool(breakout_up or breakout_down),
                  "contracting lower highs and higher lows; direction only follows a confirmed boundary close")
    elif compressed and abs(hs) <= 0.075 and ls > 0.10:
        bias = 0.50 if breakout_up else 0.0
        line_pair("ASCENDING_TRIANGLE", bias, bool(breakout_up),
                  "near-horizontal highs and rising lows; bullish only after a close above resistance")
    elif compressed and abs(ls) <= 0.075 and hs < -0.10:
        bias = -0.50 if breakout_down else 0.0
        line_pair("DESCENDING_TRIANGLE", bias, bool(breakout_down),
                  "near-horizontal lows and falling highs; bearish only after a close below support")
    elif compressed and hs > 0.10 and ls > 0.10 and abs(hs-ls) <= max(0.10, 0.45 * abs(hs)):
        line_pair("ASCENDING_CHANNEL", 0.16 if not breakout_down else -0.38, bool(breakout_down),
                  "rising, roughly parallel boundaries; uptrend is context, not automatic BUY; lower-channel break is bearish")
    elif compressed and hs < -0.10 and ls < -0.10 and abs(hs-ls) <= max(0.10, 0.45 * abs(hs)):
        line_pair("DESCENDING_CHANNEL", -0.16 if not breakout_up else 0.38, bool(breakout_up),
                  "falling, roughly parallel boundaries; downtrend is context, not automatic SELL; upper-channel break is bullish")
    elif compressed and abs(hs) <= 0.065 and abs(ls) <= 0.065 and (max(high_window)-min(low_window)) >= 2.0*typical_range:
        bias = 0.45 if breakout_up else (-0.45 if breakout_down else 0.0)
        line_pair("RECTANGLE_RANGE", bias, bool(breakout_up or breakout_down),
                  "mostly horizontal consolidation; direction remains neutral until a confirmed range break")

    # Expanded formations: candidate labels are neutral until a boundary/neckline is broken.
    recent_highs = [i for i in pivot_highs if i >= max(0, n - 50)][-6:]
    recent_lows = [i for i in pivot_lows if i >= max(0, n - 50)][-6:]
    if len(recent_highs) >= 3:
        a, b, c = recent_highs[-3:]
        tops_close = max(highs[a], highs[b], highs[c]) - min(highs[a], highs[b], highs[c]) <= 1.1 * typical_range
        neck = float(min(np.min(lows[a:b+1]), np.min(lows[b:c+1])))
        confirmed = bool(tops_close and closes[-1] < neck - 0.10 * typical_range)
        if tops_close and a < b < c:
            add("TRIPLE_TOP", -0.58 if confirmed else 0.0, [a,b,c], confirmed,
                "Three similar swing highs; bearish bias only after a confirmed close below the intervening neckline.",
                [(a,c,float(highs[a]),float(highs[c]),"TRIPLE TOP"),(a,n-1,neck,neck,"TRIPLE TOP NECKLINE")])
    if len(recent_lows) >= 3:
        a, b, c = recent_lows[-3:]
        lows_close = max(lows[a], lows[b], lows[c]) - min(lows[a], lows[b], lows[c]) <= 1.1 * typical_range
        neck = float(max(np.max(highs[a:b+1]), np.max(highs[b:c+1])))
        confirmed = bool(lows_close and closes[-1] > neck + 0.10 * typical_range)
        if lows_close and a < b < c:
            add("TRIPLE_BOTTOM", 0.58 if confirmed else 0.0, [a,b,c], confirmed,
                "Three similar swing lows; bullish bias only after a confirmed close above the intervening neckline.",
                [(a,c,float(lows[a]),float(lows[c]),"TRIPLE BOTTOM"),(a,n-1,neck,neck,"TRIPLE BOTTOM NECKLINE")])

    # Wedge and broadening formations use upper/lower regression slopes and range evolution.
    first_half = max(4, window // 2)
    early_span = float(np.max(high_window[:first_half]) - np.min(low_window[:first_half]))
    late_span = float(np.max(high_window[-first_half:]) - np.min(low_window[-first_half:]))
    spread_start = max(1e-9, float(high_window[0] - low_window[0]))
    spread_end = max(1e-9, float(high_end - low_end))
    is_converging = spread_end < spread_start * 0.82
    if compressed and is_converging and hs > 0.06 and ls > 0.06 and hs < ls:
        confirmed = bool(close < low_boundary - 0.10 * typical_range)
        add("RISING_WEDGE", -0.48 if confirmed else 0.0, [start,n-1], confirmed,
            "Rising and converging boundaries; downside direction counts only after a close beneath support.",
            [(start,n-1,high_start,high_end,"RISING WEDGE UPPER"),(start,n-1,low_start,low_end,"RISING WEDGE LOWER")])
    if compressed and is_converging and hs < -0.06 and ls < -0.06 and hs > ls:
        confirmed = bool(close > high_boundary + 0.10 * typical_range)
        add("FALLING_WEDGE", 0.48 if confirmed else 0.0, [start,n-1], confirmed,
            "Falling and converging boundaries; upside direction counts only after a close above resistance.",
            [(start,n-1,high_start,high_end,"FALLING WEDGE UPPER"),(start,n-1,low_start,low_end,"FALLING WEDGE LOWER")])
    broadening = bool(late_span > early_span * 1.25 and late_span > 2.5 * typical_range)
    if broadening:
        if hs > 0.05 and ls < -0.05:
            name = "ASCENDING_BROADENING_WEDGE"
        elif hs < -0.05 and ls > 0.05:
            name = "DESCENDING_BROADENING_WEDGE"
        else:
            name = "BROADENING_FORMATION"
        bias = 0.0
        confirmed = bool(breakout_up or breakout_down)
        if confirmed:
            bias = 0.42 if breakout_up else -0.42
        add(name, bias, [start,n-1], confirmed,
            "Expanding swing range/volatility; breakout direction only follows the observed boundary close.",
            [(start,n-1,high_start,high_end,name+" UPPER"),(start,n-1,low_start,low_end,name+" LOWER")])
        add("MEGAPHONE_PATTERN", bias, [start,n-1], confirmed,
            "Megaphone/broadening-range alias for the same expanding boundaries; counted in the same pattern family.")

    # Flags/pennants need a measurable impulse pole followed by a compact countertrend pause.
    if n >= 16:
        pole_start = max(0, n - 16)
        pole_end = n - 8
        pole_move = float(closes[pole_end - 1] - closes[pole_start]) if pole_end - pole_start >= 3 else 0.0
        pole_size = abs(pole_move) / typical_range
        cons_hi = float(np.max(highs[pole_end:]))
        cons_lo = float(np.min(lows[pole_end:]))
        cons_range = cons_hi - cons_lo
        cxs = np.arange(8, dtype=float)
        chs = float(np.polyfit(cxs, highs[-8:], 1)[0] / typical_range)
        cls = float(np.polyfit(cxs, lows[-8:], 1)[0] / typical_range)
        compact = cons_range <= max(5.5 * typical_range, abs(pole_move) * 0.78)
        if pole_size >= 2.4 and compact and pole_move > 0 and chs < 0.08:
            confirmed = bool(close > cons_hi + 0.08 * typical_range)
            add("BULL_FLAG", 0.46 if confirmed else 0.0, [pole_start,n-1], confirmed,
                "Upward impulse followed by a compact pullback/consolidation; bullish only after upper-boundary acceptance.",
                [(pole_end,n-1,float(np.max(highs[pole_end:])),float(np.max(highs[pole_end:])),"BULL FLAG UPPER"),
                 (pole_end,n-1,float(np.min(lows[pole_end:])),float(np.min(lows[pole_end:])),"BULL FLAG LOWER")])
        if pole_size >= 2.4 and compact and pole_move < 0 and cls > -0.08:
            confirmed = bool(close < cons_lo - 0.08 * typical_range)
            add("BEAR_FLAG", -0.46 if confirmed else 0.0, [pole_start,n-1], confirmed,
                "Downward impulse followed by a compact rebound/consolidation; bearish only after lower-boundary acceptance.")
        if pole_size >= 2.4 and compact and chs < 0 and cls > 0 and spread_end < spread_start:
            confirmed = bool(breakout_up or breakout_down)
            bias = (0.44 if breakout_up else -0.44 if breakout_down else 0.0)
            add("BULL_PENNANT" if pole_move > 0 else "BEAR_PENNANT", bias, [pole_start,n-1], confirmed,
                "Impulse pole followed by a contracting triangle; direction remains unresolved before breakout.",
                [(start,n-1,high_start,high_end,"PENNANT UPPER"),(start,n-1,low_start,low_end,"PENNANT LOWER")])

    # Cup/handle and rounding structures are slow formations, so require enough visible candles.
    if n >= 28:
        m = min(40, n)
        base = n - m
        sub_close = closes[base:]
        q = max(5, m // 4)
        left_rim = float(np.max(highs[base:base+q]))
        right_rim = float(np.max(highs[-q:]))
        bowl_low = float(np.min(lows[base+q:n-q])) if n-q > base+q else float(np.min(lows[base:]))
        rim_match = abs(left_rim-right_rim) <= 1.6 * typical_range
        bowl_depth = min(left_rim,right_rim)-bowl_low
        handle_low = float(np.min(lows[-max(3,q//2):]))
        handle_valid = handle_low > bowl_low + 0.30 * max(bowl_depth,1e-9)
        cup_confirmed = bool(rim_match and bowl_depth >= 2.0*typical_range and handle_valid and close > max(left_rim,right_rim))
        if rim_match and bowl_depth >= 2.0*typical_range and handle_valid:
            add("CUP_AND_HANDLE", 0.46 if cup_confirmed else 0.0, [base,n-1], cup_confirmed,
                "Rounded bowl with similar rims and a shallow right-side handle; bullish only after a close above the rim.")
        left_floor = float(np.min(lows[base:base+q]))
        right_floor = float(np.min(lows[-q:]))
        inverted_top = float(np.max(highs[base+q:n-q])) if n-q > base+q else float(np.max(highs[base:]))
        top_height = inverted_top - max(left_floor,right_floor)
        inverted_handle_high = float(np.max(highs[-max(3,q//2):]))
        inv_handle_ok = inverted_handle_high < inverted_top - 0.30*max(top_height,1e-9)
        inv_confirmed = bool(abs(left_floor-right_floor) <= 1.6*typical_range and top_height >= 2*typical_range and inv_handle_ok and close < min(left_floor,right_floor))
        if top_height >= 2*typical_range and abs(left_floor-right_floor) <= 1.6*typical_range and inv_handle_ok:
            add("INVERTED_CUP_AND_HANDLE", -0.46 if inv_confirmed else 0.0, [base,n-1], inv_confirmed,
                "Rounded top with similar floors and a shallow rebound handle; bearish only after a close below the floor.")
        early_mean = float(np.mean(sub_close[:q]))
        middle_mean = float(np.mean(sub_close[m//2-q//2:m//2+q//2+1]))
        late_mean = float(np.mean(sub_close[-q:]))
        rounding_bottom = early_mean > middle_mean + 0.75*typical_range and late_mean > middle_mean + 0.75*typical_range
        rounding_top = early_mean < middle_mean - 0.75*typical_range and late_mean < middle_mean - 0.75*typical_range
        if rounding_bottom:
            confirmed = bool(close > max(early_mean,late_mean))
            add("ROUNDING_BOTTOM", 0.36 if confirmed else 0.0, [base,n-1], confirmed,
                "Smoothed U-shaped close sequence; directional bias needs a reclaim above the rim zone.")
        if rounding_top:
            confirmed = bool(close < min(early_mean,late_mean))
            add("ROUNDING_TOP", -0.36 if confirmed else 0.0, [base,n-1], confirmed,
                "Smoothed inverted-U close sequence; directional bias needs a break below the rim zone.")

    # V-top/V-bottom candidates require a central extreme and a substantial opposing move afterwards.
    if n >= 12:
        look = min(24,n)
        s = n-look
        local_hi_idx = s + int(np.argmax(highs[s:]))
        local_lo_idx = s + int(np.argmin(lows[s:]))
        if s+3 <= local_hi_idx <= n-4:
            after_drop = float(highs[local_hi_idx] - closes[-1])
            before_rise = float(closes[local_hi_idx] - closes[s])
            if after_drop >= 2.0*typical_range and before_rise >= 1.5*typical_range:
                confirmed = close < float(np.min(lows[local_hi_idx:n])) + 0.10*typical_range
                add("V_TOP_REVERSAL", -0.40 if confirmed else 0.0, [s,local_hi_idx,n-1], confirmed,
                    "Sharp rise into a local peak followed by a sharp decline; bearish bias requires lower-boundary confirmation.")
        if s+3 <= local_lo_idx <= n-4:
            after_rise = float(closes[-1] - lows[local_lo_idx])
            before_drop = float(closes[s] - closes[local_lo_idx])
            if after_rise >= 2.0*typical_range and before_drop >= 1.5*typical_range:
                confirmed = close > float(np.max(highs[local_lo_idx:n])) - 0.10*typical_range
                add("V_BOTTOM_REVERSAL", 0.40 if confirmed else 0.0, [s,local_lo_idx,n-1], confirmed,
                    "Sharp decline into a local trough followed by a sharp rebound; bullish bias requires upper-boundary confirmation.")

    # ABCD / three-drives shape ratios are neutral until the last swing reverses/breaks.
    if len(recent_highs) >= 3 and len(recent_lows) >= 2:
        p = sorted([(i,float(highs[i]),"H") for i in recent_highs[-4:]] + [(i,float(lows[i]),"L") for i in recent_lows[-4:]])
        p = p[-6:]
        if len(p) >= 4:
            p1,p2,p3,p4 = p[-4:]
            ab = abs(p2[1]-p1[1]); bc = abs(p3[1]-p2[1]); cd = abs(p4[1]-p3[1])
            alternating = len({p1[2],p2[2],p3[2],p4[2]}) == 2 and all(p[k][2] != p[k+1][2] for k in range(3))
            if alternating and ab > typical_range and bc > typical_range and 0.55 <= bc/ab <= 0.90 and 0.70 <= cd/ab <= 1.35:
                move_up = p4[1] > p3[1]
                bias = -0.25 if move_up else 0.25
                add("ABCD_PATTERN", bias, [p1[0],p2[0],p3[0],p4[0]], False,
                    "Alternating swing legs have approximate BC/AB and CD/AB ratios; ratio match is heuristic, not a trade probability.")
            if alternating and len(p) >= 6:
                q1,q2,q3,q4,q5,q6 = p[-6:]
                drives = [abs(q2[1]-q1[1]),abs(q4[1]-q3[1]),abs(q6[1]-q5[1])]
                if min(drives) > typical_range and max(drives)/max(min(drives),1e-9) <= 1.55:
                    last_dir_up = q6[1] > q5[1]
                    add("THREE_DRIVES_PATTERN", -0.28 if last_dir_up else 0.28, [q1[0],q2[0],q3[0],q4[0],q5[0],q6[0]], False,
                        "Three similarly sized impulse legs detected; reversal requires a separate structure/close confirmation.")

    # Simple range and breakout labels are structural context; they do not cast duplicate votes.
    if n >= 8:
        level_hi = float(np.max(highs[-21:-1] if n > 20 else highs[:-1]))
        level_lo = float(np.min(lows[-21:-1] if n > 20 else lows[:-1]))
        if close > level_hi + 0.10*typical_range:
            add("BREAKOUT_AND_RETEST" if any(low <= level_hi+tolerance and close >= level_hi-tolerance for low in lows[-3:]) else "COMPRESSION_BREAKOUT",
                0.30, [max(0,n-6),n-1], True, "Upside boundary close; retest is only confirmed by a later touch-and-hold candle.")
        elif close < level_lo - 0.10*typical_range:
            add("BREAKOUT_AND_RETEST" if any(high >= level_lo-tolerance and close <= level_lo+tolerance for high in highs[-3:]) else "COMPRESSION_BREAKOUT",
                -0.30, [max(0,n-6),n-1], True, "Downside boundary close; retest is only confirmed by a later touch-and-hold candle.")

    # Recent double/triple patterns can overlap; keep names unique and prefer confirmed entries in scoring.
    unique: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for item in found:
        unique[(item["name"], tuple(item["candle_indices"]))] = item
    found = list(unique.values())
    directional = [item for item in found if item.get("confirmed") and abs(float(item.get("bias") or 0.0)) > 0.0]
    # A trend-channel candidate is weak continuation context; all reversal/breakout names need a break.
    channel_context = [item for item in found if item.get("name") in ("ASCENDING_CHANNEL", "DESCENDING_CHANNEL") and not item.get("confirmed")]
    signed_values = [(float(item["bias"]), 1.0) for item in directional]
    signed_values.extend((float(item["bias"]), 0.30) for item in channel_context if abs(float(item["bias"] or 0)) > 0)
    bias = sum(value * weight for value, weight in signed_values) / max(1.0, sum(weight for _, weight in signed_values))
    return {
        "available": True,
        "candles_used": n,
        "pivot_high_count": len(pivot_highs),
        "pivot_low_count": len(pivot_lows),
        "patterns": found[-20:],
        "line_segments": lines[-36:],
        "bias": round(float(clamp(bias, -0.65, 0.65)), 4),
        "primary_pattern": (found[-1]["name"] if found else "NONE"),
        "confirmed_pattern_count": len(directional),
        "unconfirmed_patterns_are_direction_neutral": True,
        "basis": "visual OHLC proxy from the selected M1 chart; structures are candidates, not guaranteed forecasts",
    }


def _visual_divergence_patterns(candles: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Estimate RSI/MACD divergence from normalized screenshot-derived candle geometry.

    These are visual proxies, not real broker OHLC prices; no true price scale is inferred.
    Only pivots inside the last uninterrupted visible candle sequence are compared.
    """
    rows = list(candles or [])
    if len(rows) < 12:
        return {"available": False, "reason": "At least 12 visible candles are needed for stable visual divergence context.", "patterns": []}
    segment_start = 0
    for idx in range(1, len(rows)):
        if bool(rows[idx].get("sequence_break_before")):
            segment_start = idx
    rows = rows[segment_start:]
    n = len(rows)
    if n < 12:
        return {"available": False, "reason": "The latest uninterrupted visible sequence is too short for divergence context.", "patterns": []}
    ohlc = [_candle_proxy_ohlc(row) for row in rows]
    opens = np.asarray([v[0] for v in ohlc], dtype=float)
    highs = np.asarray([v[1] for v in ohlc], dtype=float)
    lows = np.asarray([v[2] for v in ohlc], dtype=float)
    closes = np.asarray([v[3] for v in ohlc], dtype=float)
    ranges = np.maximum(highs - lows, 1e-9)
    median_range = max(1e-9, float(np.median(ranges)))
    delta = np.diff(closes, prepend=closes[0])
    gain = np.maximum(delta, 0.0)
    loss = np.maximum(-delta, 0.0)
    rsi_values = np.full(n, 50.0, dtype=float)
    for i in range(2, n):
        start = max(1, i - 14 + 1)
        avg_gain = float(np.mean(gain[start:i+1])) if i >= start else 0.0
        avg_loss = float(np.mean(loss[start:i+1])) if i >= start else 0.0
        if avg_loss <= 1e-12:
            rsi_values[i] = 100.0 if avg_gain > 1e-12 else 50.0
        else:
            rs = avg_gain / avg_loss
            rsi_values[i] = 100.0 - 100.0 / (1.0 + rs)
    macd_line = _ema(closes, 12) - _ema(closes, 26)
    macd_signal = _ema(macd_line, 9)
    macd_hist = macd_line - macd_signal
    swing_highs: List[int] = []
    swing_lows: List[int] = []
    for i in range(2, n - 2):
        if highs[i] >= max(list(highs[i-2:i]) + list(highs[i+1:i+3])):
            swing_highs.append(i)
        if lows[i] <= min(list(lows[i-2:i]) + list(lows[i+1:i+3])):
            swing_lows.append(i)
    found: List[Dict[str, Any]] = []
    price_tolerance = max(0.12 * median_range, 0.5)

    # Compare consecutive confirmed swing pivots; their two right-hand neighbours
    # exist in the submitted image, so these pivots are not still-forming candidates.
    for pivots, side in ((swing_highs, "HIGH"), (swing_lows, "LOW")):
        for p1, p2 in zip(pivots, pivots[1:]):
            if p2 - p1 < 3:
                continue
            if side == "HIGH":
                higher_price = highs[p2] > highs[p1] + price_tolerance
                lower_price = highs[p2] < highs[p1] - price_tolerance
                rsi_div_bear = higher_price and rsi_values[p2] <= rsi_values[p1] - 4.0
                rsi_div_bull = lower_price and rsi_values[p2] >= rsi_values[p1] + 4.0
                macd_div_bear = higher_price and macd_hist[p2] < macd_hist[p1] - median_range * 0.05
                macd_div_bull = lower_price and macd_hist[p2] > macd_hist[p1] + median_range * 0.05
                if rsi_div_bear or macd_div_bear:
                    strength = 0.48 + 0.10 * int(rsi_div_bear) + 0.10 * int(macd_div_bear)
                    found.append({"name": "BEARISH_MOMENTUM_DIVERGENCE", "bias": -0.58, "confirmed": False,
                                  "candle_indices": [int(p1 + segment_start + 1), int(p2 + segment_start + 1)],
                                  "strength": round(strength, 3), "raw_strength": round(strength, 3),
                                  "context": "price made a higher swing high while visual RSI/MACD momentum weakened",
                                  "rsi_divergence": bool(rsi_div_bear), "macd_divergence": bool(macd_div_bear),
                                  "confirmation_status": "PIVOT_CONFIRMED; REVERSAL_FOLLOW_THROUGH_CHECKED_SEPARATELY"})
            else:
                lower_price = lows[p2] < lows[p1] - price_tolerance
                higher_price = lows[p2] > lows[p1] + price_tolerance
                rsi_div_bull = lower_price and rsi_values[p2] >= rsi_values[p1] + 4.0
                rsi_div_bear = higher_price and rsi_values[p2] <= rsi_values[p1] - 4.0
                macd_div_bull = lower_price and macd_hist[p2] > macd_hist[p1] + median_range * 0.05
                macd_div_bear = higher_price and macd_hist[p2] < macd_hist[p1] - median_range * 0.05
                if rsi_div_bull or macd_div_bull:
                    strength = 0.48 + 0.10 * int(rsi_div_bull) + 0.10 * int(macd_div_bull)
                    found.append({"name": "BULLISH_MOMENTUM_DIVERGENCE", "bias": 0.58, "confirmed": False,
                                  "candle_indices": [int(p1 + segment_start + 1), int(p2 + segment_start + 1)],
                                  "strength": round(strength, 3), "raw_strength": round(strength, 3),
                                  "context": "price made a lower swing low while visual RSI/MACD momentum strengthened",
                                  "rsi_divergence": bool(rsi_div_bull), "macd_divergence": bool(macd_div_bull),
                                  "confirmation_status": "PIVOT_CONFIRMED; REVERSAL_FOLLOW_THROUGH_CHECKED_SEPARATELY"})

    # Retain all detected historical divergences for recency-weighted pattern scoring.
    # Publish the latest proxy values for diagnosis; these are not actual quoted prices.
    summary = {
        "available": bool(n >= 12),
        "basis": "screen-pixel-derived synthetic OHLC; normalized visual momentum only, not broker prices",
        "latest_visual_rsi14_proxy": round(float(rsi_values[-1]), 2),
        "latest_visual_macd_histogram_proxy": round(float(macd_hist[-1] / median_range), 4),
        "swing_high_count": len(swing_highs), "swing_low_count": len(swing_lows),
        "bullish_divergence_count": sum(1 for row in found if row["bias"] > 0),
        "bearish_divergence_count": sum(1 for row in found if row["bias"] < 0),
        "patterns": found,
    }
    return summary


def _confirm_candle_patterns(candles: List[Dict[str, Any]], patterns: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Use the next visible candle as follow-through confirmation, when one exists."""
    result: List[Dict[str, Any]] = []
    n = len(candles)
    if not n:
        return result
    proxy = [_candle_proxy_ohlc(c) for c in candles]
    for original in patterns:
        row = dict(original)
        indices = row.get("candle_indices")
        if not isinstance(indices, list) or not indices:
            name = str(row.get("name") or "")
            width = 2 if ("ENGULFING" in name or "HARAMI" in name or "PIERCING" in name or "CLOUD" in name) else 1
            indices = [max(1, n - width + 1), n]
            row["candle_indices"] = indices
        end_index = max(1, min(n, max(int(v) for v in indices))) - 1
        bias = float(parse_float(row.get("bias"), 0.0) or 0.0)
        raw_strength = float(parse_float(row.get("raw_strength"), parse_float(row.get("strength"), 0.4)) or 0.4)
        if abs(bias) < 1e-9:
            row["confirmed"] = False
            row["confirmation_status"] = "DIRECTION_NEUTRAL_PATTERN"
            row["strength"] = round(raw_strength * 0.45, 3)
        elif end_index + 1 < n:
            next_index = end_index + 1
            if bool(candles[next_index].get("sequence_break_before")):
                row["confirmed"] = False
                row["confirmation_status"] = "NEXT_CANDLE_SEQUENCE_GAP"
                row["strength"] = round(raw_strength * 0.30, 3)
                result.append(row)
                continue
            next_color = str(candles[next_index].get("color") or "").upper()
            next_close = proxy[next_index][3]
            pattern_close = proxy[end_index][3]
            aligned = (bias > 0 and next_color == "GREEN" and next_close > pattern_close) or \
                      (bias < 0 and next_color == "RED" and next_close < pattern_close)
            pattern_hi = max(proxy[j][1] for j in range(min(int(v) for v in indices)-1, end_index + 1))
            pattern_lo = min(proxy[j][2] for j in range(min(int(v) for v in indices)-1, end_index + 1))
            breaks_pattern = (bias > 0 and next_close > pattern_hi) or (bias < 0 and next_close < pattern_lo)
            row["confirmed"] = bool(aligned)
            row["confirmation_status"] = "CONFIRMED_BY_FOLLOW_THROUGH" if aligned else "FOLLOW_THROUGH_NOT_CONFIRMED"
            row["confirmation_candle_index"] = next_index + 1
            row["breaks_pattern_range"] = bool(breaks_pattern)
            multiplier = 1.0 if aligned else 0.38
            row["strength"] = round(raw_strength * multiplier, 3)
        else:
            row["confirmed"] = False
            row["confirmation_status"] = "NO_FOLLOWING_CANDLE_IN_SCREENSHOT"
            row["strength"] = round(raw_strength * 0.58, 3)
        result.append(row)
    return result


def _structural_candle_context(candles: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Detect prior levels, breakout rejection, and a retest on a later candle."""
    if not candles:
        return {"available": False, "bias": 0.0, "basis": "no detected candles"}
    price_available = all(parse_float(row.get("estimated_close_price")) is not None and
                          parse_float(row.get("estimated_high_price")) is not None and
                          parse_float(row.get("estimated_low_price")) is not None for row in candles)
    if price_available:
        closes = np.array([float(row["estimated_close_price"]) for row in candles], dtype=float)
        highs = np.array([float(row["estimated_high_price"]) for row in candles], dtype=float)
        lows = np.array([float(row["estimated_low_price"]) for row in candles], dtype=float)
        basis = "estimated price-axis values"
    else:
        values = [_candle_proxy_ohlc(row) for row in candles]
        closes = np.array([v[3] for v in values], dtype=float)
        highs = np.array([v[1] for v in values], dtype=float)
        lows = np.array([v[2] for v in values], dtype=float)
        basis = "normalized screen-pixel relative levels; not executable prices"
    n = len(candles)
    ranges = np.maximum(highs - lows, 1e-9)
    typical_range = max(1e-9, float(np.median(ranges)))
    tolerance = max(typical_range * 0.12, 1e-9)
    slope_norm = 0.0
    if n >= 2:
        slope = float(np.polyfit(np.arange(n, dtype=float), closes, 1)[0])
        diff_scale = max(1e-9, float(np.median(np.abs(np.diff(closes)))))
        slope_norm = float(clamp(math.tanh((slope / diff_scale) * math.sqrt(n) * 0.22), -1.0, 1.0))
    window = min(20, max(0, n - 1))
    breakout_state, breakout_bias = "NONE", 0.0
    breakout_index, breakout_level = None, None
    retest_detected = False
    false_breakout = False
    # Find the latest breakout candle relative to bars strictly preceding it.
    for k in range(max(4, n - window - 1), n):
        seq_start = max(0, k - window)
        if any(bool(candles[pos].get("sequence_break_before")) for pos in range(seq_start + 1, k + 1)):
            continue
        if k - seq_start < 4:
            continue
        prior_high = float(np.max(highs[seq_start:k]))
        prior_low = float(np.min(lows[seq_start:k]))
        if closes[k] > prior_high + tolerance:
            breakout_state, breakout_bias = "UPSIDE_BREAKOUT", 0.62
            breakout_index, breakout_level = k, prior_high
        elif closes[k] < prior_low - tolerance:
            breakout_state, breakout_bias = "DOWNSIDE_BREAKOUT", -0.62
            breakout_index, breakout_level = k, prior_low
        elif highs[k] > prior_high + tolerance and closes[k] <= prior_high:
            breakout_state, breakout_bias = "UPSIDE_BREAKOUT_REJECTION", -0.28
            breakout_index, breakout_level, false_breakout = k, prior_high, True
        elif lows[k] < prior_low - tolerance and closes[k] >= prior_low:
            breakout_state, breakout_bias = "DOWNSIDE_BREAKOUT_REJECTION", 0.28
            breakout_index, breakout_level, false_breakout = k, prior_low, True
    # A valid retest is a different candle after the breakout candle, not its own wick.
    if breakout_index is not None and breakout_level is not None and not false_breakout and breakout_index < n - 1:
        for j in range(breakout_index + 1, n):
            if bool(candles[j].get("sequence_break_before")):
                break
            if breakout_state == "UPSIDE_BREAKOUT":
                touched = lows[j] <= breakout_level + tolerance and highs[j] >= breakout_level - tolerance
                held = closes[j] >= breakout_level - tolerance
                if touched and held:
                    retest_detected = True
                    breakout_state = "UPSIDE_BREAKOUT_THEN_LATER_RETEST"
                    breakout_bias = 0.72
            elif breakout_state == "DOWNSIDE_BREAKOUT":
                touched = highs[j] >= breakout_level - tolerance and lows[j] <= breakout_level + tolerance
                held = closes[j] <= breakout_level + tolerance
                if touched and held:
                    retest_detected = True
                    breakout_state = "DOWNSIDE_BREAKOUT_THEN_LATER_RETEST"
                    breakout_bias = -0.72
    prior_end = max(0, n - 1)
    prior_slice_start = max(0, prior_end - window)
    nearest_resistance = float(np.max(highs[prior_slice_start:prior_end])) if prior_end - prior_slice_start >= 1 else None
    nearest_support = float(np.min(lows[prior_slice_start:prior_end])) if prior_end - prior_slice_start >= 1 else None
    last_close = float(closes[-1])
    resistance_touches = sum(abs(float(v) - nearest_resistance) <= tolerance for v in highs[:-1]) if nearest_resistance is not None else 0
    support_touches = sum(abs(float(v) - nearest_support) <= tolerance for v in lows[:-1]) if nearest_support is not None else 0
    dist_res = abs(last_close - nearest_resistance) / typical_range if nearest_resistance is not None else None
    dist_sup = abs(last_close - nearest_support) / typical_range if nearest_support is not None else None
    return {
        "available": True, "basis": basis, "candle_count_used": n,
        "trendline_slope_normalized": round(slope_norm, 4),
        "breakout_state": breakout_state, "breakout_candle_index": breakout_index + 1 if breakout_index is not None else None,
        "breakout_level_relative": round(float(breakout_level), 7) if breakout_level is not None else None,
        "retest_detected": bool(retest_detected), "retest_requires_later_candle": True,
        "false_breakout_detected": bool(false_breakout), "breakout_bias": round(float(breakout_bias), 4),
        "nearest_prior_resistance": round(nearest_resistance, 7) if nearest_resistance is not None else None,
        "nearest_prior_support": round(nearest_support, 7) if nearest_support is not None else None,
        "distance_to_resistance_in_median_ranges": round(float(dist_res), 3) if dist_res is not None else None,
        "distance_to_support_in_median_ranges": round(float(dist_sup), 3) if dist_sup is not None else None,
        "prior_resistance_touches": int(resistance_touches), "prior_support_touches": int(support_touches),
        "level_tolerance": round(float(tolerance), 8),
        "interpretation_note": "Pixel-relative levels are not exact market prices; later retest must occur after breakout.",
    }
def _visual_fibonacci_context(candles: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Find a recent confirmed swing leg and report visual-only Fibonacci confluence.

    The levels are ratios on screen-derived price proxies, not pip/price levels.
    They are evidence only when the latest candle reacts at the level.
    """
    rows = list(candles or [])
    if len(rows) < 7:
        return {"available": False, "reason": "Not enough visible candles for a confirmed swing leg.", "bias": 0.0}
    ohlc = [_candle_proxy_ohlc(row) for row in rows]
    highs = np.asarray([r[1] for r in ohlc], dtype=float)
    lows = np.asarray([r[2] for r in ohlc], dtype=float)
    closes = np.asarray([r[3] for r in ohlc], dtype=float)
    bodies = np.asarray([r[3] - r[0] for r in ohlc], dtype=float)
    ranges = np.maximum(highs - lows, 1e-9)
    median_range = max(1e-9, float(np.median(ranges[-min(len(ranges), 30):])))
    swing_highs, swing_lows = [], []
    for i in range(2, len(rows) - 2):
        if highs[i] >= max(list(highs[i-2:i]) + list(highs[i+1:i+3])):
            swing_highs.append(i)
        if lows[i] <= min(list(lows[i-2:i]) + list(lows[i+1:i+3])):
            swing_lows.append(i)
    if not swing_highs or not swing_lows:
        return {"available": False, "reason": "No confirmed high/low swing pair found in the visible sequence.", "bias": 0.0}
    hi_i, lo_i = swing_highs[-1], swing_lows[-1]
    hi, lo = float(highs[hi_i]), float(lows[lo_i])
    span = hi - lo
    if span <= median_range * 1.2:
        return {"available": False, "reason": "Latest confirmed swing range is too small relative to visual candle range.", "bias": 0.0}
    latest_open, latest_high, latest_low, latest_close = ohlc[-1]
    latest_range = max(1e-9, latest_high - latest_low)
    close_location = clamp((latest_close - latest_low) / latest_range, 0.0, 1.0)
    signed_body = clamp((latest_close - latest_open) / latest_range, -1.0, 1.0)
    levels = (0.382, 0.500, 0.618)
    tolerance = max(0.16 * median_range, 1.0)
    bias, nearest = 0.0, None
    if lo_i < hi_i:
        leg = "UP_LEG_RETRACEMENT"
        level_map = {f"{ratio:.3f}": hi - ratio * span for ratio in levels}
        supports = [(abs(latest_close - value), ratio, value) for ratio, value in level_map.items()]
        distance, ratio, level = min(supports, key=lambda item: item[0])
        if distance <= tolerance:
            nearest = {"ratio": ratio, "pixel_proxy_level": round(float(level), 3), "distance_ranges": round(float(distance / median_range), 4)}
            if signed_body > 0.12 and close_location >= 0.58 and latest_low <= level + tolerance:
                bias = 0.40
            elif signed_body < -0.20 and latest_close < level - tolerance * 0.25:
                bias = -0.25
    else:
        leg = "DOWN_LEG_RETRACEMENT"
        level_map = {f"{ratio:.3f}": lo + ratio * span for ratio in levels}
        resistances = [(abs(latest_close - value), ratio, value) for ratio, value in level_map.items()]
        distance, ratio, level = min(resistances, key=lambda item: item[0])
        if distance <= tolerance:
            nearest = {"ratio": ratio, "pixel_proxy_level": round(float(level), 3), "distance_ranges": round(float(distance / median_range), 4)}
            if signed_body < -0.12 and close_location <= 0.42 and latest_high >= level - tolerance:
                bias = -0.40
            elif signed_body > 0.20 and latest_close > level + tolerance * 0.25:
                bias = 0.25
    return {
        "available": True, "leg_type": leg, "swing_high_candle_index": int(hi_i + 1),
        "swing_low_candle_index": int(lo_i + 1), "swing_range_pixels": round(float(span), 3),
        "retracement_ratios": {key: round(float(value), 3) for key, value in level_map.items()},
        "nearest_retracement": nearest, "near_key_level": bool(nearest),
        "reaction_bias": round(float(bias), 3), "bias": round(float(bias), 3),
        "basis": "visual pixel-coordinate proxy; not calibrated Bitcoin OTC price levels",
    }


def _enhanced_price_action_context(candles: List[Dict[str, Any]],
                                   patterns: Optional[List[Dict[str, Any]]] = None,
                                   structural_context: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Gap-aware M1 price-action model for a fixed 5-minute horizon; color count is only a 1% tie-break vote."""
    rows = list(candles or [])
    n = len(rows)
    if not n:
        return {
            "available": False, "bias": 0.0, "direction": "SELL", "tie_break_price_bias": -1.0,
            "analysis_model": "price_action_context_v8_m1_5m_horizon_setup_confidence", "components": {}, "component_weights": {},
            "position_context": {"available": False}, "reason": "No candle geometry was available.",
        }

    ohlc = [_candle_proxy_ohlc(row) for row in rows]
    opens = np.asarray([v[0] for v in ohlc], dtype=float)
    highs = np.asarray([v[1] for v in ohlc], dtype=float)
    lows = np.asarray([v[2] for v in ohlc], dtype=float)
    closes = np.asarray([v[3] for v in ohlc], dtype=float)
    ranges = np.maximum(highs - lows, 1e-9)
    bodies = np.abs(closes - opens)
    signed_bodies = np.clip((closes - opens) / ranges, -1.0, 1.0)
    colors = np.asarray([1.0 if str(row.get("color", "")).upper() == "GREEN" else -1.0 for row in rows], dtype=float)

    gap_starts = [i for i in range(1, n) if bool(rows[i].get("sequence_break_before"))]
    segment_start = gap_starts[-1] if gap_starts else 0
    segment_end = n
    short_trailing_segment_excluded = False
    minimum_context_segment = max(6, min(12, int(math.ceil(n * 0.05))))
    # An isolated last candidate can be a broker trade-marker/overlay at the crop edge.
    # Do not let a 1-7 candle tail erase a long valid sequence from trend/momentum/swing
    # context. We stop before that gap instead of connecting across it; pattern detectors
    # still use the original rows and respect every sequence_break_before flag.
    if gap_starts and (n - gap_starts[-1]) < minimum_context_segment:
        candidate_end = gap_starts[-1]
        prior_starts = [g for g in gap_starts[:-1] if candidate_end - g >= minimum_context_segment]
        if prior_starts:
            segment_start = prior_starts[-1]
            segment_end = candidate_end
            short_trailing_segment_excluded = True
        elif candidate_end >= minimum_context_segment:
            segment_start = 0
            segment_end = candidate_end
            short_trailing_segment_excluded = True
    segment_rows = rows[segment_start:segment_end]
    segment_closes = closes[segment_start:segment_end]
    segment_highs = highs[segment_start:segment_end]
    segment_lows = lows[segment_start:segment_end]
    segment_ranges = ranges[segment_start:segment_end]
    segment_colors = colors[segment_start:segment_end]
    local_n = len(segment_rows)
    typical_range = max(1e-9, float(np.median(segment_ranges[-min(20, local_n):])))

    def trend_bias(values: np.ndarray, period: int) -> float:
        if len(values) < 2:
            return 0.0
        sample = values[-min(len(values), period):]
        if len(sample) < 2:
            return 0.0
        x = np.arange(len(sample), dtype=float)
        slope = float(np.polyfit(x, sample, 1)[0])
        displacement = slope * (len(sample) - 1)
        return float(math.tanh(displacement / max(typical_range * 2.0, 1e-9)))

    def momentum_bias(values: np.ndarray) -> float:
        if len(values) < 2:
            return 0.0
        short_delta = float(values[-1] - values[-min(len(values), 4)]) if len(values) >= 2 else 0.0
        mid_delta = float(values[-1] - values[-min(len(values), 7)]) if len(values) >= 2 else 0.0
        short = math.tanh(short_delta / max(typical_range * 2.0, 1e-9))
        medium = math.tanh(mid_delta / max(typical_range * 3.2, 1e-9))
        return float(clamp(0.64 * short + 0.36 * medium, -1.0, 1.0))

    trend_all = 0.56 * trend_bias(segment_closes, 5) + 0.44 * trend_bias(segment_closes, 12)
    momentum_all = momentum_bias(segment_closes)
    latest_completion_unverified = bool(rows[-1].get("possibly_incomplete", False))
    # A single frame cannot prove the newest M1 candle has closed. Keep it in the
    # analysis, but let pre-latest trend/momentum dominate until a following candle exists.
    latest_mix = 0.20 if latest_completion_unverified else 0.32
    if len(segment_closes) >= 4:
        trend_before_latest = 0.56 * trend_bias(segment_closes[:-1], 5) + 0.44 * trend_bias(segment_closes[:-1], 12)
        momentum_before_latest = momentum_bias(segment_closes[:-1])
        trend_component = (1.0 - latest_mix) * trend_before_latest + latest_mix * trend_all
        momentum_component = (1.0 - latest_mix) * momentum_before_latest + latest_mix * momentum_all
    else:
        trend_component = trend_all
        momentum_component = momentum_all

    gap_aware_structure = _pivot_structure(segment_rows)
    structure_component = float(clamp(parse_float(gap_aware_structure.get("bias"), 0.0) or 0.0, -1.0, 1.0))
    structural_context = structural_context or {}

    latest_open, latest_high, latest_low, latest_close = (float(v) for v in ohlc[-1])
    latest_range = max(1e-9, latest_high - latest_low)
    latest_body = abs(latest_close - latest_open)
    body_ratio = float(clamp(latest_body / latest_range, 0.0, 1.0))
    close_location = float(clamp((latest_close - latest_low) / latest_range, 0.0, 1.0))
    upper_wick = max(0.0, latest_high - max(latest_open, latest_close))
    lower_wick = max(0.0, min(latest_open, latest_close) - latest_low)
    upper_wick_ratio = upper_wick / latest_range
    lower_wick_ratio = lower_wick / latest_range
    pressure = float(clamp(
        0.48 * signed_bodies[-1] +
        0.27 * (2.0 * close_location - 1.0) +
        0.25 * (lower_wick_ratio - upper_wick_ratio), -1.0, 1.0))
    if latest_completion_unverified:
        pressure *= 0.65
    latest_range_ratio = float(latest_range / typical_range)
    if latest_range_ratio >= 2.25 and body_ratio < 0.48:
        pressure *= 0.55

    prior_count = min(15, max(0, local_n - 1))
    prior_high = float(np.max(segment_highs[-prior_count-1:-1])) if prior_count >= 1 else None
    prior_low = float(np.min(segment_lows[-prior_count-1:-1])) if prior_count >= 1 else None
    tolerance = typical_range * 0.16
    distance_to_resistance = (prior_high - latest_close) / typical_range if prior_high is not None else None
    distance_to_support = (latest_close - prior_low) / typical_range if prior_low is not None else None
    near_support = bool(prior_low is not None and (latest_low <= prior_low + typical_range * 0.60 or (distance_to_support is not None and abs(distance_to_support) <= 0.75)))
    near_resistance = bool(prior_high is not None and (latest_high >= prior_high - typical_range * 0.60 or (distance_to_resistance is not None and abs(distance_to_resistance) <= 0.75)))
    support_rejection = near_support and lower_wick_ratio >= 0.18 and close_location >= 0.57
    resistance_rejection = near_resistance and upper_wick_ratio >= 0.18 and close_location <= 0.43

    location_component = 0.0
    if support_rejection and not resistance_rejection:
        location_component = float(clamp(0.42 + 0.34 * lower_wick_ratio + 0.24 * (close_location - 0.50), 0.0, 0.95))
    elif resistance_rejection and not support_rejection:
        location_component = -float(clamp(0.42 + 0.34 * upper_wick_ratio + 0.24 * (0.50 - close_location), 0.0, 0.95))
    elif near_support and signed_bodies[-1] < -0.35 and close_location < 0.35:
        location_component = -0.24
    elif near_resistance and signed_bodies[-1] > 0.35 and close_location > 0.65:
        location_component = 0.24

    fibonacci_context = _visual_fibonacci_context(segment_rows)
    fibonacci_bias = float(parse_float(fibonacci_context.get("reaction_bias"), 0.0) or 0.0)
    # Small adjustment only: Fibonacci is contextual confluence, never a stand-alone signal.
    if fibonacci_context.get("near_key_level"):
        location_component = float(clamp(location_component + 0.06 * fibonacci_bias, -1.0, 1.0))

    local_breakout = 0.0
    breakout_state = "NONE"
    if prior_high is not None and prior_low is not None and prior_count >= 4:
        if latest_close > prior_high + tolerance and close_location >= 0.62 and signed_bodies[-1] >= 0.20:
            local_breakout = 0.90
            breakout_state = "UPSIDE_CLOSE_CONFIRMED_RELATIVE_TO_VISIBLE_RANGE"
        elif latest_high > prior_high + tolerance and latest_close <= prior_high + tolerance:
            if close_location < 0.50 or upper_wick_ratio > lower_wick_ratio:
                local_breakout = -0.62
                breakout_state = "UPSIDE_WICK_REJECTED_BACK_INTO_RANGE"
        elif latest_close < prior_low - tolerance and close_location <= 0.38 and signed_bodies[-1] <= -0.20:
            local_breakout = -0.90
            breakout_state = "DOWNSIDE_CLOSE_CONFIRMED_RELATIVE_TO_VISIBLE_RANGE"
        elif latest_low < prior_low - tolerance and latest_close >= prior_low - tolerance:
            if close_location > 0.50 or lower_wick_ratio > upper_wick_ratio:
                local_breakout = 0.62
                breakout_state = "DOWNSIDE_WICK_REJECTED_BACK_INTO_RANGE"

    global_breakout = float(clamp(parse_float(structural_context.get("breakout_bias"), 0.0) or 0.0, -1.0, 1.0))
    global_break_index = parse_float(structural_context.get("breakout_candle_index"), None)
    if global_break_index is not None:
        age = max(0.0, float(n - global_break_index))
        global_breakout *= math.exp(-age / 5.0)
    if "THEN_LATER_RETEST" in str(structural_context.get("breakout_state") or "") and structural_context.get("retest_detected"):
        global_breakout *= 1.12
    classical_chart_patterns = _detect_classical_chart_patterns(rows)
    classical_chart_bias = float(clamp(parse_float(classical_chart_patterns.get("bias"), 0.0) or 0.0, -0.65, 0.65))
    breakout_component = float(clamp(0.72 * local_breakout + 0.20 * global_breakout + 0.08 * classical_chart_bias, -1.0, 1.0))
    if local_breakout > 0.05:
        structure_shift = "BULLISH_CHOCH_OR_BOS" if trend_component < -0.18 else "BULLISH_BOS_OR_BREAKOUT"
    elif local_breakout < -0.05:
        structure_shift = "BEARISH_CHOCH_OR_BOS" if trend_component > 0.18 else "BEARISH_BOS_OR_BREAKOUT"
    else:
        structure_shift = "NO_CONFIRMED_LOCAL_STRUCTURE_BREAK"
    if breakout_state == "NONE":
        breakout_state = str(structural_context.get("breakout_state") or "NONE")

    patterns = list(patterns or [])
    pattern_component = float(clamp(_weighted_recent_pattern_bias(rows, patterns), -1.0, 1.0)) if patterns else 0.0
    color_balance = float(np.mean(segment_colors[-min(6, local_n):])) if local_n else 0.0
    color_balance = float(clamp(color_balance, -1.0, 1.0))

    # Fixed-expiry context: the trade lasts 5 minutes, i.e. five M1 bars.
    # A persistent move remains continuation evidence, but its score must soften when
    # the last leg stretches and the sell/buy pressure begins to fade. A reversal is
    # considered confirmed only when at least two separate evidence groups agree and
    # at least one is an actual price/location/structure signal; a long streak alone
    # can never manufacture an opposite-direction alert.
    # Use the full available visible history (up to 110 bars) to judge trend age,
    # while also requiring the most recent 32-bar leg to agree with that trend.
    exhaustion_window = min(110, local_n)
    exhaustion_start = max(0, local_n - exhaustion_window)
    recent_trend_window = min(32, local_n)
    recent_trend_start = max(0, local_n - recent_trend_window)
    long_move_ranges = float((segment_closes[-1] - segment_closes[exhaustion_start]) / typical_range) if local_n >= 2 else 0.0
    recent_move_ranges = float((segment_closes[-1] - segment_closes[recent_trend_start]) / typical_range) if local_n >= 2 else 0.0
    long_trend_bias = float(trend_bias(segment_closes, exhaustion_window)) if local_n >= 2 else 0.0
    recent_trend_bias = float(trend_bias(segment_closes, recent_trend_window)) if local_n >= 2 else 0.0
    mature_downtrend = bool(local_n >= 12 and long_trend_bias <= -0.15 and recent_trend_bias <= -0.30
                            and long_move_ranges <= -4.0 and recent_move_ranges <= -2.3)
    mature_uptrend = bool(local_n >= 12 and long_trend_bias >= 0.15 and recent_trend_bias >= 0.30
                          and long_move_ranges >= 4.0 and recent_move_ranges >= 2.3)
    # Count the uninterrupted directional close streak across the visible chart, not
    # just the last few candles. A very long streak is maturity risk for a five-minute bet.
    close_changes = np.diff(segment_closes)
    directional_streak_bars = 0
    for change in close_changes[::-1]:
        if change < -0.04 * typical_range:
            directional_streak_bars += 1
        else:
            break
    bullish_streak_bars = 0
    for change in close_changes[::-1]:
        if change > 0.04 * typical_range:
            bullish_streak_bars += 1
        else:
            break
    # Keep the run length even after the first countertrend candle appears: a reversal
    # should not erase evidence that a long one-sided run happened only a few candles ago.
    # `*_streak_bars` still reports the literal run ending at the newest candle; the
    # prolonged flags also accept a >=24-bar run that ended within the last 8 candle steps.
    recent_end_start = max(0, len(close_changes) - 8)
    recent_max_bear_run = 0
    recent_max_bull_run = 0
    for end_idx in range(recent_end_start, len(close_changes)):
        bear_run = bull_run = 0
        pos = end_idx
        while pos >= 0 and close_changes[pos] < -0.04 * typical_range:
            bear_run += 1
            pos -= 1
        pos = end_idx
        while pos >= 0 and close_changes[pos] > 0.04 * typical_range:
            bull_run += 1
            pos -= 1
        recent_max_bear_run = max(recent_max_bear_run, bear_run)
        recent_max_bull_run = max(recent_max_bull_run, bull_run)
    prolonged_down_streak = directional_streak_bars >= 24 or recent_max_bear_run >= 24
    prolonged_up_streak = bullish_streak_bars >= 24 or recent_max_bull_run >= 24

    # Compare a fixed 16-bar context lookback with exactly the configured forecast horizon.
    # On M1, the context leg is 16 minutes and the current forecast leg is five minutes.
    # Use close-to-close intervals (N bars require N+1 close observations) so the
    # exhaustion calculation stays aligned when TIMEFRAME or expiry is changed later.
    comparison_lookback_bars = max(16, FORECAST_HORIZON_BARS * 3)
    horizon_bars = max(1, int(FORECAST_HORIZON_BARS))
    required_close_count = comparison_lookback_bars + horizon_bars + 1
    if local_n >= required_close_count:
        previous_end_offset = -(horizon_bars + 1)
        previous_start_offset = -(comparison_lookback_bars + horizon_bars + 1)
        previous_leg_delta = float(segment_closes[previous_end_offset] - segment_closes[previous_start_offset])
        latest_leg_delta = float(segment_closes[-1] - segment_closes[previous_end_offset])
        previous_leg_pace = previous_leg_delta / float(comparison_lookback_bars)
        latest_leg_pace = latest_leg_delta / float(horizon_bars)
        downward_momentum_slowing = bool(
            previous_leg_delta < -1.20 * typical_range and
            (latest_leg_pace >= 0.0 or abs(latest_leg_pace) < abs(previous_leg_pace) * 0.70
             or latest_leg_delta >= -0.30 * typical_range)
        )
        upward_momentum_slowing = bool(
            previous_leg_delta > 1.20 * typical_range and
            (latest_leg_pace <= 0.0 or abs(latest_leg_pace) < abs(previous_leg_pace) * 0.70
             or latest_leg_delta <= 0.30 * typical_range)
        )
    else:
        previous_leg_delta = latest_leg_delta = 0.0
        previous_leg_pace = latest_leg_pace = 0.0
        downward_momentum_slowing = upward_momentum_slowing = False

    rsi_proxy_window = segment_closes[-min(40, local_n):]
    rsi_proxy = _rsi(rsi_proxy_window, 14) if len(rsi_proxy_window) >= 3 else None
    oversold_proxy = bool(rsi_proxy is not None and rsi_proxy <= 34.0)
    overbought_proxy = bool(rsi_proxy is not None and rsi_proxy >= 66.0)
    long_support = float(np.min(segment_lows[-exhaustion_window:])) if exhaustion_window else None
    long_resistance = float(np.max(segment_highs[-exhaustion_window:])) if exhaustion_window else None
    near_long_support = bool(long_support is not None and (latest_low - long_support) / typical_range <= 0.75)
    near_long_resistance = bool(long_resistance is not None and (long_resistance - latest_high) / typical_range <= 0.75)

    # Range contraction near an extreme can warn that a directional move is losing
    # force, but this is only a warning—not a standalone countertrend entry.
    recent_range_median = float(np.median(segment_ranges[-min(4, local_n):])) if local_n else typical_range
    prior_range_sample = segment_ranges[-12:-4] if local_n >= 12 else np.asarray([], dtype=float)
    prior_range_median = float(np.median(prior_range_sample)) if prior_range_sample.size else typical_range
    recent_range_compression = bool(
        prior_range_sample.size >= 4 and prior_range_median > 1e-9
        and recent_range_median <= 0.78 * prior_range_median
    )
    previous_close = float(segment_closes[-2]) if local_n >= 2 else latest_close
    bullish_reclaim_of_prior_close = bool(
        local_n >= 2 and latest_close > previous_close + 0.06 * typical_range
        and close_location >= 0.52 and (body_ratio >= 0.12 or lower_wick_ratio >= 0.18)
    )
    bearish_reclaim_of_prior_close = bool(
        local_n >= 2 and latest_close < previous_close - 0.06 * typical_range
        and close_location <= 0.48 and (body_ratio >= 0.12 or upper_wick_ratio >= 0.18)
    )

    total_candles = len(rows)
    recent_bullish_pattern = False
    recent_bearish_pattern = False
    recent_bullish_divergence = False
    recent_bearish_divergence = False
    for pattern in patterns:
        if not isinstance(pattern, dict):
            continue
        name = str(pattern.get("name") or "").upper()
        indices = pattern.get("candle_indices") if isinstance(pattern.get("candle_indices"), list) else []
        indices = [int(value) for value in indices if parse_float(value, None) is not None and 1 <= int(value) <= total_candles]
        if not indices:
            continue
        pattern_end = max(indices)
        # Confirming bars must not be the currently forming far-right candle.
        recent = total_candles - pattern_end <= 16
        confirmation_index = parse_float(pattern.get("confirmation_candle_index"), None)
        completed_confirmation = bool(pattern.get("confirmed") and confirmation_index is not None
                                      and confirmation_index <= total_candles - 1 and pattern_end <= total_candles - 2)
        if recent and "BULLISH_MOMENTUM_DIVERGENCE" in name:
            recent_bullish_divergence = True
        if recent and "BEARISH_MOMENTUM_DIVERGENCE" in name:
            recent_bearish_divergence = True
        bullish_pattern_shape = any(token in name for token in (
            "BULLISH_ENGULFING", "MORNING_STAR", "HAMMER", "PIERCING_LINE",
            "TWEEZER_BOTTOM", "FALSE_DOWNSIDE_BREAKOUT", "DRAGONFLY_DOJI"))
        bearish_pattern_shape = any(token in name for token in (
            "BEARISH_ENGULFING", "EVENING_STAR", "SHOOTING_STAR", "DARK_CLOUD_COVER",
            "TWEEZER_TOP", "FALSE_UPSIDE_BREAKOUT", "GRAVESTONE_DOJI"))
        recent_bullish_pattern = recent_bullish_pattern or bool(recent and completed_confirmation and bullish_pattern_shape)
        recent_bearish_pattern = recent_bearish_pattern or bool(recent and completed_confirmation and bearish_pattern_shape)

    # An older, completed bar that closes beyond a short swing boundary is a stronger
    # price trigger than a wick or a still-forming rightmost candle.
    completed_bullish_break = completed_bearish_break = False
    if local_n >= 7:
        completed_index = local_n - 2
        recent_prior_highs = segment_highs[completed_index - 4:completed_index]
        recent_prior_lows = segment_lows[completed_index - 4:completed_index]
        completed_o, completed_h, completed_l, completed_c = _candle_proxy_ohlc(segment_rows[completed_index])
        completed_range = max(1e-9, completed_h - completed_l)
        completed_close_location = (completed_c - completed_l) / completed_range
        completed_body_ratio = (completed_c - completed_o) / completed_range
        completed_bullish_break = bool(
            len(recent_prior_highs) == 4 and completed_c > float(np.max(recent_prior_highs)) + tolerance
            and completed_close_location >= 0.60 and completed_body_ratio >= 0.12
        )
        completed_bearish_break = bool(
            len(recent_prior_lows) == 4 and completed_c < float(np.min(recent_prior_lows)) - tolerance
            and completed_close_location <= 0.40 and completed_body_ratio <= -0.12
        )

    # A genuine reversal reclaim requires several linked conditions: a mature/prolonged
    # trend, stretched RSI, slowing price pace, location near the extreme, and an actual
    # close reclaim. This lets the five-minute model detect exhaustion without flipping just
    # because 110 candles happen to be red or green.
    bullish_exhaustion_reclaim = bool(
        mature_downtrend and prolonged_down_streak and oversold_proxy and downward_momentum_slowing
        and near_long_support and bullish_reclaim_of_prior_close
    )
    bearish_exhaustion_reclaim = bool(
        mature_uptrend and prolonged_up_streak and overbought_proxy and upward_momentum_slowing
        and near_long_resistance and bearish_reclaim_of_prior_close
    )
    bullish_location_signal = bool(
        ((near_support or near_long_support) and
         (support_rejection or (lower_wick_ratio >= 0.26 and close_location >= 0.56)
          or breakout_state == "DOWNSIDE_WICK_REJECTED_BACK_INTO_RANGE"))
        or bullish_exhaustion_reclaim
    )
    bearish_location_signal = bool(
        ((near_resistance or near_long_resistance) and
         (resistance_rejection or (upper_wick_ratio >= 0.26 and close_location <= 0.44)
          or breakout_state == "UPSIDE_WICK_REJECTED_BACK_INTO_RANGE"))
        or bearish_exhaustion_reclaim
    )
    bullish_structure_signal = bool(completed_bullish_break or local_breakout >= 0.50
                                     or (structure_component >= 0.18 and downward_momentum_slowing))
    bearish_structure_signal = bool(completed_bearish_break or local_breakout <= -0.50
                                     or (structure_component <= -0.18 and upward_momentum_slowing))
    bullish_momentum_signal = bool(downward_momentum_slowing and (oversold_proxy or
                                   (local_n >= 4 and segment_closes[-2] > segment_closes[-4])))
    bearish_momentum_signal = bool(upward_momentum_slowing and (overbought_proxy or
                                   (local_n >= 4 and segment_closes[-2] < segment_closes[-4])))

    bullish_confirmation_count = sum((bullish_location_signal, recent_bullish_divergence,
                                      recent_bullish_pattern, bullish_structure_signal, bullish_momentum_signal))
    bearish_confirmation_count = sum((bearish_location_signal, recent_bearish_divergence,
                                      recent_bearish_pattern, bearish_structure_signal, bearish_momentum_signal))
    bullish_reversal_confirmed = bool(mature_downtrend and bullish_confirmation_count >= 2 and
                                      (bullish_location_signal or recent_bullish_pattern or bullish_structure_signal))
    bearish_reversal_confirmed = bool(mature_uptrend and bearish_confirmation_count >= 2 and
                                      (bearish_location_signal or recent_bearish_pattern or bearish_structure_signal))
    bullish_exhaustion_warning = bool(mature_downtrend and (downward_momentum_slowing or
                                        recent_bullish_divergence or bullish_location_signal or
                                        (prolonged_down_streak and oversold_proxy and recent_range_compression)))
    bearish_exhaustion_warning = bool(mature_uptrend and (upward_momentum_slowing or
                                        recent_bearish_divergence or bearish_location_signal or
                                        (prolonged_up_streak and overbought_proxy and recent_range_compression)))
    breakout_age = parse_float(structural_context.get("breakout_candle_index"), None)
    fresh_breakout_with_retest = bool(
        structural_context.get("retest_detected") and breakout_age is not None
        and total_candles - float(breakout_age) <= 8
    )
    # A red/green rightmost candle is not enough to confirm continuation over the next five minutes.
    # A long streak needs a recent completed breakout plus a later retest to override
    # the maturity penalty; otherwise continuation confidence is deliberately restrained.
    bearish_continuation_confirmed = bool(
        mature_downtrend and not downward_momentum_slowing and completed_bearish_break
        and signed_bodies[-1] <= -0.30 and close_location <= 0.38
        and not bullish_location_signal and not recent_bullish_divergence
        and (not prolonged_down_streak or fresh_breakout_with_retest)
    )
    bullish_continuation_confirmed = bool(
        mature_uptrend and not upward_momentum_slowing and completed_bullish_break
        and signed_bodies[-1] >= 0.30 and close_location >= 0.62
        and not bearish_location_signal and not recent_bearish_divergence
        and (not prolonged_up_streak or fresh_breakout_with_retest)
    )

    # Mildly temper a mature trend for a five-minute horizon. Stronger tempering is only
    # enabled by a multi-signal reversal setup; continuation candles retain their weight.
    trend_exhaustion_component = 0.0
    if mature_downtrend:
        if bullish_reversal_confirmed:
            damping = 0.34 if bullish_confirmation_count >= 3 else 0.52
            trend_component *= damping
            momentum_component *= damping
            if structure_component < 0 and bullish_structure_signal:
                structure_component *= 0.65
            trend_exhaustion_component = min(1.0, 0.56 + 0.12 * bullish_confirmation_count)
        elif bullish_exhaustion_warning:
            if prolonged_down_streak and oversold_proxy and (downward_momentum_slowing or recent_bullish_divergence or bullish_location_signal):
                trend_component *= 0.60
                momentum_component *= 0.46
                trend_exhaustion_component = 0.50
            else:
                trend_component *= 0.72 if prolonged_down_streak else 0.84
                momentum_component *= 0.60 if prolonged_down_streak else 0.72
                trend_exhaustion_component = 0.42 if prolonged_down_streak else (0.34 if bullish_confirmation_count >= 2 else 0.24)
        elif bearish_continuation_confirmed:
            trend_exhaustion_component = 0.08
        elif prolonged_down_streak:
            trend_component *= 0.68
            momentum_component *= 0.56
            trend_exhaustion_component = 0.36
        else:
            trend_component *= 0.84
            momentum_component *= 0.78
            trend_exhaustion_component = 0.20
    elif mature_uptrend:
        if bearish_reversal_confirmed:
            damping = 0.34 if bearish_confirmation_count >= 3 else 0.52
            trend_component *= damping
            momentum_component *= damping
            if structure_component > 0 and bearish_structure_signal:
                structure_component *= 0.65
            trend_exhaustion_component = -min(1.0, 0.56 + 0.12 * bearish_confirmation_count)
        elif bearish_exhaustion_warning:
            if prolonged_up_streak and overbought_proxy and (upward_momentum_slowing or recent_bearish_divergence or bearish_location_signal):
                trend_component *= 0.60
                momentum_component *= 0.46
                trend_exhaustion_component = -0.50
            else:
                trend_component *= 0.72 if prolonged_up_streak else 0.84
                momentum_component *= 0.60 if prolonged_up_streak else 0.72
                trend_exhaustion_component = -0.42 if prolonged_up_streak else (-0.34 if bearish_confirmation_count >= 2 else -0.24)
        elif bullish_continuation_confirmed:
            trend_exhaustion_component = -0.08
        elif prolonged_up_streak:
            trend_component *= 0.68
            momentum_component *= 0.56
            trend_exhaustion_component = -0.36
        else:
            trend_component *= 0.84
            momentum_component *= 0.78
            trend_exhaustion_component = -0.20

    # V8 continuation guard: a long, one-sided trend is NOT enough to justify a
    # high-confidence five-minute continuation forecast. Unless a fresh completed
    # break/retest and strong final-candle evidence confirm continuation, temper the
    # correlated trend/structure/pattern votes as a group. This lowers false confidence;
    # it does not automatically force a countertrend BUY/SELL without reversal evidence.
    downtrend_continuation_guard_applied = bool(
        mature_downtrend and prolonged_down_streak and not bearish_continuation_confirmed
    )
    uptrend_continuation_guard_applied = bool(
        mature_uptrend and prolonged_up_streak and not bullish_continuation_confirmed
    )
    if downtrend_continuation_guard_applied:
        trend_component *= 0.68
        momentum_component *= 0.52
        if structure_component < 0.0 and not completed_bearish_break:
            structure_component *= 0.58
        if breakout_component < 0.0 and not fresh_breakout_with_retest:
            breakout_component *= 0.55
        if pattern_component < 0.0 and not recent_bearish_pattern:
            pattern_component *= 0.70
        # Encode possible exhaustion as a modest positive offset, stronger only when
        # pressure is actually fading; the score still needs corroborating BUY evidence.
        trend_exhaustion_component = max(
            trend_exhaustion_component,
            0.46 if (downward_momentum_slowing or bullish_exhaustion_warning) else 0.28,
        )
    elif uptrend_continuation_guard_applied:
        trend_component *= 0.68
        momentum_component *= 0.52
        if structure_component > 0.0 and not completed_bullish_break:
            structure_component *= 0.58
        if breakout_component > 0.0 and not fresh_breakout_with_retest:
            breakout_component *= 0.55
        if pattern_component > 0.0 and not recent_bullish_pattern:
            pattern_component *= 0.70
        trend_exhaustion_component = min(
            trend_exhaustion_component,
            -0.46 if (upward_momentum_slowing or bearish_exhaustion_warning) else -0.28,
        )

    trend_exhaustion = {
        "available": bool(local_n >= 12),
        "forecast_horizon_minutes": FIXED_EXPIRY_MINUTES,
        "forecast_horizon_bars": FORECAST_HORIZON_BARS,
        "history_window_bars": exhaustion_window,
        "recent_trend_window_bars": recent_trend_window,
        "long_trend_bias": round(long_trend_bias, 5),
        "recent_trend_bias": round(recent_trend_bias, 5),
        "long_move_in_median_ranges": round(long_move_ranges, 3),
        "recent_move_in_median_ranges": round(recent_move_ranges, 3),
        "bearish_close_streak_bars": directional_streak_bars,
        "bullish_close_streak_bars": bullish_streak_bars,
        "max_recent_bearish_run_bars_ending_within_8_steps": int(recent_max_bear_run),
        "max_recent_bullish_run_bars_ending_within_8_steps": int(recent_max_bull_run),
        "prolonged_down_streak": prolonged_down_streak,
        "prolonged_up_streak": prolonged_up_streak,
        "mature_downtrend": mature_downtrend,
        "mature_uptrend": mature_uptrend,
        "downward_momentum_slowing": downward_momentum_slowing,
        "upward_momentum_slowing": upward_momentum_slowing,
        "previous_leg_delta_lookback_bars": round(previous_leg_delta, 6),
        "previous_leg_lookback_bars": int(comparison_lookback_bars),
        "latest_leg_delta_forecast_horizon": round(latest_leg_delta, 6),
        "latest_leg_delta_forecast_horizon_bars": int(horizon_bars),
        "previous_leg_pace_per_bar": round(previous_leg_pace, 6),
        "latest_leg_pace_per_bar": round(latest_leg_pace, 6),
        "recent_range_compression": recent_range_compression,
        "bullish_reclaim_of_prior_close": bullish_reclaim_of_prior_close,
        "bearish_reclaim_of_prior_close": bearish_reclaim_of_prior_close,
        "bullish_exhaustion_reclaim": bullish_exhaustion_reclaim,
        "bearish_exhaustion_reclaim": bearish_exhaustion_reclaim,
        "rsi_proxy": round(float(rsi_proxy), 2) if rsi_proxy is not None else None,
        "oversold_proxy": oversold_proxy,
        "overbought_proxy": overbought_proxy,
        "near_trailing_support": near_long_support,
        "near_trailing_resistance": near_long_resistance,
        "bullish_confirmation_count": int(bullish_confirmation_count),
        "bearish_confirmation_count": int(bearish_confirmation_count),
        "bullish_confirmation_groups": {
            "support_or_rejection": bullish_location_signal, "recent_bullish_divergence": recent_bullish_divergence,
            "confirmed_bullish_pattern": recent_bullish_pattern, "completed_structure_break": completed_bullish_break,
            "structure_or_failed_breakout": bullish_structure_signal, "momentum_slowing_with_context": bullish_momentum_signal,
        },
        "bearish_confirmation_groups": {
            "resistance_or_rejection": bearish_location_signal, "recent_bearish_divergence": recent_bearish_divergence,
            "confirmed_bearish_pattern": recent_bearish_pattern, "completed_structure_break": completed_bearish_break,
            "structure_or_failed_breakout": bearish_structure_signal, "momentum_slowing_with_context": bearish_momentum_signal,
        },
        "confirmed_bullish_reversal": bullish_reversal_confirmed,
        "confirmed_bearish_reversal": bearish_reversal_confirmed,
        "bullish_exhaustion_warning": bullish_exhaustion_warning,
        "bearish_exhaustion_warning": bearish_exhaustion_warning,
        "bearish_continuation_confirmed": bearish_continuation_confirmed,
        "bullish_continuation_confirmed": bullish_continuation_confirmed,
        "unconfirmed_downtrend_continuation_guard_applied": downtrend_continuation_guard_applied,
        "unconfirmed_uptrend_continuation_guard_applied": uptrend_continuation_guard_applied,
        "directional_score_adjustment": round(float(trend_exhaustion_component), 4),
        "interpretation": "A long trend alone does not trigger the opposite side; reversal score needs multiple recent confirmation groups. Mature moves and unconfirmed exhaustion lower confidence in the continuation call.",
    }

    reversal_weighting_active = bool(bullish_reversal_confirmed or bearish_reversal_confirmed)
    if reversal_weighting_active:
        # A confirmed reversal is a different 5-minute setup from simple trend continuation.
        # Reduce the correlated trend/momentum votes and increase the already-detected
        # exhaustion, confirmed-pattern, location and breakout groups. A long candle streak
        # alone never activates these weights; it must pass the independent confirmation
        # groups above. Weights still sum to 1.0 and the same nine components are retained.
        weights = {
            "trend": 0.08,
            "momentum": 0.05,
            "swing_structure": 0.10,
            "support_resistance_reaction": 0.18,
            "breakout_retest_false_breakout": 0.15,
            "context_confirmed_patterns": 0.17,
            "latest_candle_body_close_wicks": 0.06,
            "candle_color_balance": 0.01,
            "trend_exhaustion_5m": 0.20,
        }
        weighting_mode = "CONFIRMED_M1_REVERSAL_FOR_5M_HORIZON"
    else:
        weights = {
            "trend": 0.19,
            "momentum": 0.13,
            "swing_structure": 0.16,
            "support_resistance_reaction": 0.15,
            "breakout_retest_false_breakout": 0.11,
            "context_confirmed_patterns": 0.10,
            "latest_candle_body_close_wicks": 0.04,
            "candle_color_balance": 0.01,
            "trend_exhaustion_5m": 0.11,
        }
        weighting_mode = "BASE_M1_PRICE_ACTION_FOR_5M_HORIZON"
    trend_exhaustion["reversal_weighting_active"] = reversal_weighting_active
    trend_exhaustion["weighting_mode"] = weighting_mode
    trend_exhaustion["weight_sum"] = round(float(sum(weights.values())), 8)
    components = {
        "trend": float(clamp(trend_component, -1.0, 1.0)),
        "momentum": float(clamp(momentum_component, -1.0, 1.0)),
        "swing_structure": float(clamp(structure_component, -1.0, 1.0)),
        "support_resistance_reaction": float(clamp(location_component, -1.0, 1.0)),
        "breakout_retest_false_breakout": float(clamp(breakout_component, -1.0, 1.0)),
        "context_confirmed_patterns": pattern_component,
        "latest_candle_body_close_wicks": pressure,
        "candle_color_balance": color_balance,
        "trend_exhaustion_5m": float(clamp(trend_exhaustion_component, -1.0, 1.0)),
    }
    raw_bias = sum(components[key] * weights[key] for key in weights)
    sample_factor = 0.55 + 0.45 * (1.0 - math.exp(-min(local_n, 24) / 8.0))
    analysis_bias = float(clamp(raw_bias * sample_factor, -1.0, 1.0))

    # V8 setup-confidence guard: direction streaks describe the past, not by themselves
    # the next five M1 closes. The score therefore needs a distinct continuation setup
    # (completed break + strong close, with a later retest for a prolonged streak) or a
    # multi-group reversal setup before it can express high confidence in a mature move.
    # This symmetric guard only compresses confidence; it does not blindly reverse the
    # forecast. A BUY reversal still requires recent pattern/location/structure/momentum
    # evidence, and a SELL reversal after an uptrend follows the same rule.
    analysis_bias_before_v8_guard = float(analysis_bias)
    v8_streak_confidence_guard = {
        "applied": False,
        "side": None,
        "mode": "NONE",
        "bias_before": round(analysis_bias_before_v8_guard, 5),
        "bias_after": round(analysis_bias_before_v8_guard, 5),
        "score_ceiling_percent": None,
        "reason": "No mature or prolonged unconfirmed one-sided move detected.",
    }
    unconfirmed_down_extension = bool(
        (mature_downtrend or prolonged_down_streak)
        and not bearish_continuation_confirmed
        and not bullish_reversal_confirmed
    )
    unconfirmed_up_extension = bool(
        (mature_uptrend or prolonged_up_streak)
        and not bullish_continuation_confirmed
        and not bearish_reversal_confirmed
    )
    if unconfirmed_down_extension:
        cap = 0.22 if prolonged_down_streak else 0.28
        damping = 0.46 if prolonged_down_streak else 0.62
        analysis_bias = float(clamp(analysis_bias * damping, -cap, cap))
        v8_streak_confidence_guard = {
            "applied": True,
            "side": "DOWN",
            "mode": "PROLONGED_DOWN_MOVE_WITHOUT_CONFIRMED_CONTINUATION_OR_REVERSAL" if prolonged_down_streak else "MATURE_DOWNTREND_WITHOUT_CONFIRMATION",
            "bias_before": round(analysis_bias_before_v8_guard, 5),
            "bias_after": round(analysis_bias, 5),
            "score_ceiling_percent": round(50.0 + 49.0 * cap, 1),
            "reason": "Downward trend alone is not enough to claim a high-confidence five-minute SELL; require a fresh completed continuation setup or multiple bullish reversal groups.",
        }
    elif unconfirmed_up_extension:
        cap = 0.22 if prolonged_up_streak else 0.28
        damping = 0.46 if prolonged_up_streak else 0.62
        analysis_bias = float(clamp(analysis_bias * damping, -cap, cap))
        v8_streak_confidence_guard = {
            "applied": True,
            "side": "UP",
            "mode": "PROLONGED_UP_MOVE_WITHOUT_CONFIRMED_CONTINUATION_OR_REVERSAL" if prolonged_up_streak else "MATURE_UPTREND_WITHOUT_CONFIRMATION",
            "bias_before": round(analysis_bias_before_v8_guard, 5),
            "bias_after": round(analysis_bias, 5),
            "score_ceiling_percent": round(50.0 + 49.0 * cap, 1),
            "reason": "Upward trend alone is not enough to claim a high-confidence five-minute BUY; require a fresh completed continuation setup or multiple bearish reversal groups.",
        }
    v8_streak_confidence_guard["bias_after"] = round(analysis_bias, 5)
    weighted_contributions = {key: round(components[key] * weights[key] * sample_factor, 5) for key in weights}
    # Keep the feature-contribution audit numerically connected to the final bias:
    # the explicit guard adjustment bridges pre-guard weighted evidence to final bias.
    weighted_contributions["v8_streak_confidence_guard_adjustment"] = round(
        analysis_bias - analysis_bias_before_v8_guard, 5
    )
    score = round(50.0 + 49.0 * abs(analysis_bias), 1)
    if analysis_bias > 1e-8:
        direction = "BUY"
    elif analysis_bias < -1e-8:
        direction = "SELL"
    else:
        tie_break_price_bias = trend_component + momentum_component + structure_component
        if abs(tie_break_price_bias) < 1e-8:
            tie_break_price_bias = pressure
        direction = "BUY" if tie_break_price_bias > 0 else "SELL"

    recent_hi = float(np.max(segment_highs[-min(12, local_n):]))
    recent_lo = float(np.min(segment_lows[-min(12, local_n):]))
    local_span = max(1e-9, recent_hi - recent_lo)
    relative_position = float(clamp((latest_close - recent_lo) / local_span, 0.0, 1.0))
    trend_state = "UP" if trend_component > 0.18 else "DOWN" if trend_component < -0.18 else "SIDEWAYS_OR_TRANSITION"
    structure_state = "BULLISH_SWINGS" if structure_component > 0.15 else "BEARISH_SWINGS" if structure_component < -0.15 else "MIXED_SWINGS"
    if abs(trend_component) >= 0.42 and abs(structure_component) >= 0.20 and trend_component * structure_component > 0:
        regime = "TRENDING_WITH_STRUCTURE_CONFIRMATION"
    elif np.std(np.diff(segment_closes[-min(local_n, 10):])) <= typical_range * 0.10 if local_n >= 3 else False:
        regime = "COMPRESSION_OR_LOW_MOMENTUM"
    elif abs(structure_component) < 0.12:
        regime = "RANGE_OR_CHOP"
    else:
        regime = "TRANSITION_OR_BREAKOUT_TEST"

    return {
        "available": True,
        "analysis_model": "price_action_context_v8_m1_5m_horizon_setup_confidence",
        "bias": round(analysis_bias, 5),
        "direction": direction,
        "selected_direction_score_percent": score,
        "components": {key: round(value, 5) for key, value in components.items()},
        "component_weights": weights,
        "forecast_weighting_mode": weighting_mode,
        "confirmed_reversal_weighting_active": reversal_weighting_active,
        "trend_exhaustion_5m": trend_exhaustion,
        "v8_streak_confidence_guard": v8_streak_confidence_guard,
        "weighted_component_contributions": weighted_contributions,
        "color_count_weight_percent": 1.0,
        "color_count_used_as_primary_decision": False,
        "sample_factor": round(sample_factor, 4),
        "all_visible_candles_count": n,
        "last_contiguous_sequence_count": local_n,
        "sequence_segment_start_index": segment_start + 1,
        "sequence_segment_end_index": segment_end,
        "short_trailing_sequence_excluded_from_trend_context": short_trailing_segment_excluded,
        "trend_state": trend_state,
        "structure_state": structure_state,
        "regime": regime,
        "gap_aware_market_structure": gap_aware_structure,
        "position_context": {
            "available": prior_count >= 1,
            "latest_close_relative_position_in_recent_12_candle_range": round(relative_position, 4),
            "latest_candle_close_location_in_own_range": round(close_location, 4),
            "latest_body_to_range": round(body_ratio, 4),
            "latest_upper_wick_to_range": round(upper_wick_ratio, 4),
            "latest_lower_wick_to_range": round(lower_wick_ratio, 4),
            "latest_range_to_median_range": round(latest_range_ratio, 4),
            "latest_completion_status": str(rows[-1].get("completion_status") or ("UNKNOWN_STATIC_SCREENSHOT" if latest_completion_unverified else "NOT_MARKED")),
            "latest_completion_uncertainty_applied": latest_completion_unverified,
            "latest_trend_momentum_mix_weight": round(latest_mix, 3),
            "latest_pressure_reliability_factor": 0.65 if latest_completion_unverified else 1.0,
            "near_prior_support_zone": near_support,
            "near_prior_resistance_zone": near_resistance,
            "support_rejection_detected": bool(support_rejection),
            "resistance_rejection_detected": bool(resistance_rejection),
            "distance_to_prior_support_in_median_ranges": round(float(distance_to_support), 4) if distance_to_support is not None else None,
            "distance_to_prior_resistance_in_median_ranges": round(float(distance_to_resistance), 4) if distance_to_resistance is not None else None,
            "prior_support_proxy": round(prior_low, 4) if prior_low is not None else None,
            "prior_resistance_proxy": round(prior_high, 4) if prior_high is not None else None,
            "levels_are_pixel_relative_not_real_prices": True,
        },
        "fibonacci_retracement_context": fibonacci_context,
        "classical_chart_patterns": classical_chart_patterns,
        "classical_chart_pattern_bias": round(classical_chart_bias, 5),
        "market_structure_shift": structure_shift,
        "breakout_analysis": {
            "local_state": breakout_state,
            "market_structure_shift": structure_shift,
            "local_bias": round(local_breakout, 5),
            "structural_context_bias_age_adjusted": round(global_breakout, 5),
            "combined_breakout_bias": round(breakout_component, 5),
            "level_tolerance_in_median_ranges": 0.16,
        },
        "reason": "Weighted 5-minute price-action analysis of trend, momentum, swing structure, support/resistance, Fibonacci, candle confirmations, chart formations, breakout/retest and exhaustion; color count contributes only 1%.",
        "tie_break_price_bias": round(float(trend_component + momentum_component + structure_component + pressure + trend_exhaustion_component), 5),
    }


def _candle_fixed_expiry_forecast(candles: List[Dict[str, Any]],
                                  analysis_context: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Return the fixed five-M1-bar (5-minute) forecast, prioritizing context over color counts."""
    horizon = FIXED_EXPIRY_MINUTES
    context = analysis_context or _enhanced_price_action_context(candles, [], None)
    bias = float(clamp(parse_float(context.get("bias"), 0.0) or 0.0, -1.0, 1.0))
    if bias > 1e-8:
        direction = "BUY"
    elif bias < -1e-8:
        direction = "SELL"
    else:
        fallback = float(parse_float(context.get("tie_break_price_bias"), 0.0) or 0.0)
        direction = "BUY" if fallback > 0 else "SELL"
    context_score = parse_float(context.get("selected_direction_score_percent"), None)
    forecast_score = (float(context_score) if context_score is not None
                      else float(clamp(50.0 + 32.0 * math.tanh(1.6 * abs(bias)), 51.0, 82.0)))
    return {
        "horizon_minutes": horizon,
        "target_minutes": horizon,
        "bias": round(bias, 5),
        "direction": direction,
        "score_percent": round(float(clamp(forecast_score, 1.0, 99.0)), 1),
        "score_source": "same five-minute setup-confidence score from the connected price-action context" if context_score is not None else "fallback directional-evidence formula; context score unavailable",
        "analysis_model": "price_action_context_v8_m1_5m_horizon_setup_confidence",
        "color_count_weight_percent": 1.0,
        "components": context.get("components", {}),
        "component_weights": context.get("component_weights", {}),
        "position_context": context.get("position_context", {}),
    }

def _apply_pattern_context(candles: List[Dict[str, Any]], patterns: List[Dict[str, Any]],
                           structural: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Apply trend/location/context constraints without dropping the automatic signal."""
    if not candles:
        return []
    values = [_candle_proxy_ohlc(row) for row in candles]
    n = len(candles)
    median_range = max(1e-9, float(np.median([max(1e-9, h-l) for _o,h,l,_c in values])))
    reversal_bull = ("BULLISH_ENGULFING", "BULLISH_HARAMI", "PIERCING_LINE", "MORNING_STAR",
                     "HAMMER", "INVERTED_HAMMER", "DRAGONFLY_DOJI", "TWEEZER_BOTTOM", "FALSE_DOWNSIDE_BREAKOUT",
                     "BULLISH_MOMENTUM_DIVERGENCE")
    reversal_bear = ("BEARISH_ENGULFING", "BEARISH_HARAMI", "DARK_CLOUD_COVER", "EVENING_STAR",
                     "HANGING_MAN", "SHOOTING_STAR", "GRAVESTONE_DOJI", "TWEEZER_TOP", "FALSE_UPSIDE_BREAKOUT",
                     "BEARISH_MOMENTUM_DIVERGENCE")
    result = []
    for original in patterns:
        row = dict(original)
        idxs = row.get("candle_indices") if isinstance(row.get("candle_indices"), list) else []
        idxs = [int(v) for v in idxs if parse_float(v) is not None and 1 <= int(v) <= n]
        if not idxs:
            idxs = [n]
        start, end = min(idxs)-1, max(idxs)-1
        if any(bool(candles[pos].get("sequence_break_before")) for pos in range(start+1, end+1)):
            row["sequence_valid"] = False
            row["strength"] = round(float(parse_float(row.get("strength"), 0.3) or 0.3) * 0.2, 3)
            row["context_adjustment"] = "reduced: pattern crosses a suspected missing candle gap"
            result.append(row)
            continue
        name = str(row.get("name") or "").upper()
        bias = float(parse_float(row.get("bias"), 0.0) or 0.0)
        raw_strength = float(parse_float(row.get("raw_strength"), parse_float(row.get("strength"), 0.3)) or 0.3)
        prior_start = max(0, start-6)
        for pos in range(prior_start+1, start+1):
            if bool(candles[pos].get("sequence_break_before")):
                prior_start = pos
        prior_closes = np.array([values[j][3] for j in range(prior_start, start)], dtype=float)
        prior_trend = "UNKNOWN"
        if len(prior_closes) >= 3:
            slope = float(np.polyfit(np.arange(len(prior_closes), dtype=float), prior_closes, 1)[0])
            delta = float(prior_closes[-1] - prior_closes[0])
            if delta > median_range * 0.18 and slope > 0:
                prior_trend = "UP"
            elif delta < -median_range * 0.18 and slope < 0:
                prior_trend = "DOWN"
            else:
                prior_trend = "SIDEWAYS"
        multiplier = 1.0
        if any(token in name for token in reversal_bull) and bias > 0:
            multiplier = 1.0 if prior_trend == "DOWN" else 0.62 if prior_trend == "UNKNOWN" else 0.48
        elif any(token in name for token in reversal_bear) and bias < 0:
            multiplier = 1.0 if prior_trend == "UP" else 0.62 if prior_trend == "UNKNOWN" else 0.48
        # Keep sequential-continuation patterns context aware as well.
        elif name in ("THREE_WHITE_SOLDIERS", "THREE_BLACK_CROWS", "MARUBOZU"):
            multiplier = 1.0 if prior_trend in ("UP" if bias > 0 else "DOWN", "UNKNOWN") else 0.72
        # Context is calculated as-of the pattern endpoint; never use future candles to
        # decide whether an older pattern was near support/resistance when it formed.
        level_start = max(0, end - 20)
        prior_level_values = values[level_start:end]
        pattern_median_range = max(1e-9, float(np.median([max(1e-9, row[1]-row[2]) for row in prior_level_values]))) if prior_level_values else median_range
        local_support = float(min(row[2] for row in prior_level_values)) if prior_level_values else None
        local_resistance = float(max(row[1] for row in prior_level_values)) if prior_level_values else None
        level_tolerance = pattern_median_range * 0.12
        end_close = values[end][3]
        near_support = local_support is not None and abs(end_close - local_support) <= pattern_median_range * 1.5
        near_resistance = local_resistance is not None and abs(end_close - local_resistance) <= pattern_median_range * 1.5
        support_touches = sum(1 for row in prior_level_values if abs(row[2] - local_support) <= level_tolerance) if local_support is not None else 0
        resistance_touches = sum(1 for row in prior_level_values if abs(row[1] - local_resistance) <= level_tolerance) if local_resistance is not None else 0
        support_rejections = sum(1 for row in prior_level_values if local_support is not None and abs(row[2]-local_support) <= level_tolerance and row[3] > row[2] + level_tolerance)
        resistance_rejections = sum(1 for row in prior_level_values if local_resistance is not None and abs(row[1]-local_resistance) <= level_tolerance and row[3] < row[1] - level_tolerance)
        distance_support = abs(end_close-local_support)/pattern_median_range if local_support is not None else None
        distance_resistance = abs(end_close-local_resistance)/pattern_median_range if local_resistance is not None else None
        if bias > 0 and near_support and any(token in name for token in reversal_bull):
            multiplier *= 1.12
        if bias < 0 and near_resistance and any(token in name for token in reversal_bear):
            multiplier *= 1.12
        multiplier = float(clamp(multiplier, 0.15, 1.15))
        row["prior_trend_context"] = prior_trend
        row["near_support"] = bool(near_support)
        row["near_resistance"] = bool(near_resistance)
        row["pattern_support_level_asof"] = round(local_support, 7) if local_support is not None else None
        row["pattern_resistance_level_asof"] = round(local_resistance, 7) if local_resistance is not None else None
        row["support_touches_before_pattern"] = int(support_touches)
        row["resistance_touches_before_pattern"] = int(resistance_touches)
        row["support_rejections_before_pattern"] = int(support_rejections)
        row["resistance_rejections_before_pattern"] = int(resistance_rejections)
        row["distance_to_support_in_ranges_at_pattern"] = round(float(distance_support), 3) if distance_support is not None else None
        row["distance_to_resistance_in_ranges_at_pattern"] = round(float(distance_resistance), 3) if distance_resistance is not None else None
        row["context_uses_only_information_available_by_pattern_end"] = True
        row["context_multiplier"] = round(multiplier, 3)
        row["contextual_strength"] = round(float(clamp(raw_strength * multiplier, 0.0, 1.0)), 4)
        row["strength"] = row["contextual_strength"]
        row["sequence_valid"] = True
        row["context_adjustment"] = "trend, level proximity, sequence continuity applied"
        result.append(row)
    return result


def _weighted_recent_pattern_bias(candles: List[Dict[str, Any]], patterns: List[Dict[str, Any]]) -> float:
    """Deduplicate overlapping pattern votes at each candle endpoint and decay older patterns."""
    n = len(candles)
    grouped: Dict[Tuple[int, int], List[Tuple[float, float]]] = defaultdict(list)
    for row in patterns:
        if row.get("sequence_valid") is False:
            continue
        bias = float(parse_float(row.get("bias"), 0.0) or 0.0)
        if abs(bias) <= 1e-8:
            continue
        indices = row.get("candle_indices") if isinstance(row.get("candle_indices"), list) else []
        end = max([int(v) for v in indices if parse_float(v) is not None] or [n])
        end = int(clamp(end, 1, max(1, n)))
        age = max(0, n-end)
        recency = math.exp(-age / 7.0)
        strength = float(parse_float(row.get("contextual_strength"), parse_float(row.get("strength"), 0.2)) or 0.2)
        if row.get("confirmed"):
            strength *= 1.08
        else:
            strength *= 0.62
        weight = max(1e-5, strength * recency)
        grouped.setdefault((end, 1 if bias > 0 else -1), []).append((bias, weight))
    if not grouped:
        return 0.0
    by_endpoint: Dict[int, List[Tuple[float, float]]] = defaultdict(list)
    for (end, sign), items in grouped.items():
        sum_w = sum(w for _b,w in items)
        group_bias = sum(b*w for b,w in items) / max(sum_w, 1e-9)
        # Multiple names on the same candle sequence are a single evidence cluster.
        cluster_weight = max(w for _b,w in items) * (1.0 + min(0.25, 0.05*(len(items)-1)))
        by_endpoint[end].append((group_bias, cluster_weight))
    endpoint_votes = []
    for end, items in by_endpoint.items():
        total = sum(w for _b,w in items)
        b = sum(v*w for v,w in items) / max(total, 1e-9)
        endpoint_votes.append((b, total * math.exp(-max(0,n-end)/7.0)))
    total = sum(w for _b,w in endpoint_votes)
    return float(clamp(sum(b*w for b,w in endpoint_votes)/max(total, 1e-9), -1.0, 1.0))


def _latest_candle_state(candles: List[Dict[str, Any]], image_width: int, prior_bias: Optional[float], current_bias: float) -> Dict[str, Any]:
    """A static screenshot cannot prove a bar is closed; report possibility and score sensitivity."""
    if not candles:
        return {"state": "UNKNOWN_STATIC_SCREENSHOT", "possibly_incomplete": True,
                "basis": "no candle geometry available"}
    last = candles[-1]
    x_end = float(last.get("x", 0)) + float(last.get("width", 0))
    near_right_edge = bool(image_width > 0 and (image_width - x_end) <= max(2.0, image_width * 0.025))
    return {
        "state": "UNKNOWN_STATIC_SCREENSHOT",
        "possibly_incomplete": True,
        "right_edge_proximity_cue": near_right_edge,
        "basis": "screenshot contains no reliable candle-close timestamp; right-edge position is only a visual cue",
        "direction_without_latest_candle": ("BUY" if prior_bias > 0 else "SELL" if prior_bias < 0 else None) if prior_bias is not None else None,
        "direction_with_latest_candle": "BUY" if current_bias >= 0 else "SELL",
        "latest_candle_bias_delta": round(float(current_bias - prior_bias), 5) if prior_bias is not None else None,
        "direction_changed_when_latest_included": bool(prior_bias is not None and ((prior_bias >= 0) != (current_bias >= 0))),
    }


def _candle_scale_features(candles: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not candles:
        return {"available": False, "features": []}
    ranges = np.array([max(1e-9, float(row.get("height", 1))) for row in candles], dtype=float)
    median_range = max(1e-9, float(np.median(ranges)))
    features = []
    for row, candle_range in zip(candles, ranges):
        body = max(0.0, float(row.get("body_height_pixels", 0)))
        upper = max(0.0, float(row.get("upper_wick_pixels", 0)))
        lower = max(0.0, float(row.get("lower_wick_pixels", 0)))
        features.append({
            "index": int(row.get("index", len(features)+1)), "color": str(row.get("color") or "UNKNOWN"),
            "body_to_range": round(float(clamp(body/candle_range, 0, 1)), 5),
            "upper_wick_to_range": round(float(clamp(upper/candle_range, 0, 1)), 5),
            "lower_wick_to_range": round(float(clamp(lower/candle_range, 0, 1)), 5),
            "range_to_median_range": round(float(candle_range/median_range), 5),
            "upper_wick_to_body": round(float(upper/max(body, 1e-9)), 5),
            "lower_wick_to_body": round(float(lower/max(body, 1e-9)), 5),
            "gap_ratio_to_typical": parse_float(row.get("gap_ratio_to_typical"), 1.0),
            "sequence_id": int(row.get("sequence_id", 0) or 0),
        })
    return {"available": True, "median_range_pixels": round(median_range, 4), "features": features,
            "ratios_are_scale_normalized": True}


def _scale_invariance_check(image: np.ndarray) -> Dict[str, Any]:
    """Self-test helper: compare normalized geometry/direction over resized copies."""
    outcomes = []
    for scale in (0.75, 1.0, 1.25):
        resized = image if scale == 1.0 else cv2.resize(image, None, fx=scale, fy=scale, interpolation=cv2.INTER_AREA if scale < 1 else cv2.INTER_LINEAR)
        detected = build_visual_candles(resized)
        analysis = analyze_candles(detected, int((detected.get("chart_region") or {}).get("height") or resized.shape[0]))
        norm = _candle_scale_features(detected.get("candles") or {})
        features = [x["body_to_range"] for x in (norm.get("features") or [])]
        outcomes.append({"scale": scale, "detected_count": detected.get("total", 0), "direction": analysis.get("direction"),
                         "median_body_to_range": round(float(np.median(features)), 4) if features else None})
    comparable = [x for x in outcomes if x.get("detected_count", 0) > 0]
    directions_stable = bool(comparable and len({x.get("direction") for x in comparable}) == 1)
    base = next((x for x in outcomes if x.get("scale") == 1.0), {})
    base_count = int(base.get("detected_count", 0) or 0)
    count_drift = max((abs(int(x.get("detected_count", 0) or 0) - base_count) / max(1, base_count)
                       for x in outcomes), default=1.0)
    base_body = parse_float(base.get("median_body_to_range"), None)
    body_drift = max((abs(float(x["median_body_to_range"]) - float(base_body))
                      for x in outcomes if base_body is not None and x.get("median_body_to_range") is not None), default=1.0)
    count_stable = bool(base_count > 0 and count_drift <= 0.10)
    geometry_stable = bool(base_body is not None and body_drift <= 0.10)
    consistency_stable = bool(directions_stable and count_stable and geometry_stable)
    return {"available": True, "outcomes": outcomes,
            "direction_stable_across_scales": directions_stable,
            "candle_count_stable_within_10_percent": count_stable,
            "normalized_geometry_stable_within_0_10": geometry_stable,
            "maximum_relative_candle_count_drift": round(float(count_drift), 4),
            "maximum_median_body_ratio_drift": round(float(body_drift), 4),
            "scale_consistency_stable": consistency_stable,
            "normalized_geometry_used": True,
            "interpretation": "diagnostic only; resizing can alter thin strokes and component detection"}


def _attach_requested_analysis_coverage(result: Dict[str, Any]) -> Dict[str, Any]:
    """Attach the requested 169-feature audit without wrapping/redefining the main analyzer."""
    try:
        report = _v10_catalog_runtime_report(result)
        result["requested_analysis_coverage"] = {key: value for key, value in report.items() if key != "all_requested_features"}
        audit = result.setdefault("connected_feature_audit", {})
        audit["requested_analysis_coverage"] = {
            "catalog_version": report["catalog_version"],
            "requested_item_count": report["requested_item_count"],
            "evaluated_items": report["evaluated_items"],
            "matched_items_on_this_chart": report["matched_items_on_this_chart"],
            "conditional_data_items_unavailable": report["conditional_data_items_unavailable"],
            "score_link": report["score_integration"],
        }
    except Exception as exc:
        # Audit reporting is ancillary and must never interrupt the live analysis flow.
        result["requested_analysis_coverage"] = {"available": False, "error_type": type(exc).__name__}
    return result


def analyze_candles(candles_result: Dict[str, Any], image_height: int,
                    use_historical_pattern_weights: bool = False) -> Dict[str, Any]:
    candles = list(candles_result.get("candles") or [])
    n = len(candles)
    for index, candle in enumerate(candles):
        is_latest = index == len(candles) - 1
        candle["completion_status"] = "UNKNOWN_STATIC_SCREENSHOT" if is_latest else "HAS_LATER_VISIBLE_CANDLE"
        candle["possibly_incomplete"] = bool(is_latest)
        candle["completion_status_basis"] = "A single image has no verified bar-close timestamp; latest candle is treated as potentially open."
    candles_result["candles"] = candles
    geometry_validation = candles_result.get("geometry_validation") or validate_candle_geometry(candles_result)
    result = _BASE_ANALYZE_CANDLES(candles_result, image_height)
    price_scale = candles_result.get("price_scale") or {"available": False}
    normalization = _candle_scale_features(candles)
    if not candles:
        result.update({"available": False, "candle_count": 0, "bias": 0.0,
            "direction": "SELL", "selected_direction_score_percent": 50.1,
            "buy_direction_score_percent": 50.0, "sell_direction_score_percent": 50.1,
            "patterns": [], "fixed_expiry_forecast": _candle_fixed_expiry_forecast([]),
            "reading_confidence_percent": 0.0, "normalization": normalization,
            "price_scale_calibration": price_scale,
            "geometry_validation": geometry_validation,
            "reading_confidence_semantics": "HEURISTIC_ONLY; actual detection precision/recall requires manually labeled screenshots",
            "latest_candle_state": _latest_candle_state([], 0, None, 0.0),
            "analysis_model": "price_action_context_v8_m1_5m_horizon_setup_confidence"})
        return _attach_requested_analysis_coverage(result)

    patterns = list(result.get("patterns") or [])
    advanced_patterns = _extended_candle_patterns(candles)
    advanced_patterns.extend(_supplemental_candle_and_smc_patterns(candles))
    visual_divergence = _visual_divergence_patterns(candles)
    advanced_patterns.extend(visual_divergence.get("patterns") or [])
    # Merge core + supplemental findings on the exact same named event/span. A second
    # scanner is allowed to improve confirmation/strength, but not to cast another vote.
    merged_patterns: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for row in patterns + advanced_patterns:
        key = (str(row.get("name") or ""), tuple(row.get("candle_indices") or []))
        old_row = merged_patterns.get(key)
        if old_row is None or (bool(row.get("confirmed")) and not bool(old_row.get("confirmed"))) or (bool(row.get("confirmed")) == bool(old_row.get("confirmed")) and float(parse_float(row.get("strength"), 0.0) or 0.0) > float(parse_float(old_row.get("strength"), 0.0) or 0.0)):
            merged_patterns[key] = row
    patterns = list(merged_patterns.values())
    if len(candles) >= 2 and bool(candles[-1].get("sequence_break_before")):
        patterns = [p for p in patterns if isinstance(p.get("candle_indices"), list)
                    and (len(p.get("candle_indices") or []) <= 1 or min(p["candle_indices"]) == max(p["candle_indices"]))]
    patterns = _confirm_candle_patterns(candles, patterns)
    if candles:
        latest_index = len(candles)
        for pattern in patterns:
            indices = pattern.get("candle_indices") if isinstance(pattern.get("candle_indices"), list) else []
            uses_latest = latest_index in [int(v) for v in indices if parse_float(v, None) is not None]
            if uses_latest and not pattern.get("confirmed"):
                prior_strength = float(parse_float(pattern.get("strength"), 0.0) or 0.0)
                pattern["strength_before_latest_uncertainty_adjustment"] = round(prior_strength, 4)
                pattern["strength"] = round(prior_strength * 0.80, 4)
                pattern["latest_candle_completion_uncertainty_applied"] = True
                pattern["latest_candle_completion_status"] = "UNKNOWN_STATIC_SCREENSHOT"
    historical_pattern_metrics: Dict[str, Any] = {}
    if use_historical_pattern_weights and patterns:
        historical_pattern_metrics = _pattern_historical_metrics(
            [str(row.get("name") or "") for row in patterns], FIXED_EXPIRY_MINUTES)
        patterns = _apply_historical_pattern_reliability(patterns, historical_pattern_metrics)
    structural_context = _structural_candle_context(candles)
    patterns = _apply_pattern_context(candles, patterns, structural_context)
    pattern_bias = _weighted_recent_pattern_bias(candles, patterns)
    original_bias = float(clamp(parse_float(result.get("bias"), 0.0) or 0.0, -1.0, 1.0))
    price_action = _enhanced_price_action_context(candles, patterns, structural_context)
    combined_bias = float(clamp(parse_float(price_action.get("bias"), original_bias) or 0.0, -1.0, 1.0))

    normalized_features = normalization.get("features") or []
    body_ratios = [float(row.get("body_to_range", 0.0)) for row in normalized_features]
    upper_ratios = [float(row.get("upper_wick_to_range", 0.0)) for row in normalized_features]
    lower_ratios = [float(row.get("lower_wick_to_range", 0.0)) for row in normalized_features]
    range_ratios = [float(row.get("range_to_median_range", 1.0)) for row in normalized_features]
    ranges = np.array([max(1.0, float(row.get("height", 1))) for row in candles], dtype=float)
    px_closes = np.array([_candle_proxy_ohlc(row)[3] for row in candles], dtype=float)
    changes = np.diff(px_closes)
    vol = float(np.std(changes[-min(20, len(changes)):])) if len(changes) else 0.0
    confidence = float(candles_result.get("candle_reading_confidence_percent", 0.0) or 0.0)
    quality_factor = confidence / 100.0
    shape_heuristic_factor = 0.72 + 0.28 * quality_factor
    geometry_factor = float(clamp(parse_float(geometry_validation.get("directional_score_factor"), 1.0) or 1.0, 0.0, 1.0))
    quality_adjustment_factor = shape_heuristic_factor * geometry_factor
    price_action["raw_context_bias"] = round(float(price_action.get("bias", 0.0) or 0.0), 5)
    price_action["shape_reading_heuristic_factor"] = round(shape_heuristic_factor, 5)
    price_action["geometry_validation_factor"] = round(geometry_factor, 5)
    price_action["reading_quality_adjustment_factor"] = round(quality_adjustment_factor, 5)
    price_action["score_adjustment_semantics"] = "Heuristic shape score and pixel-geometry consistency temper directional evidence; neither is win probability."
    combined_bias *= quality_adjustment_factor
    price_action["bias"] = round(float(combined_bias), 5)
    buy_pct = float(clamp(50 + 49 * combined_bias, 1.0, 99.0))
    sell_pct = 100.0 - buy_pct
    direction = "BUY" if combined_bias > 1e-8 else "SELL" if combined_bias < -1e-8 else str(price_action.get("direction") or "SELL")
    price_action["direction"] = direction
    price_action["selected_direction_score_percent"] = round(float(clamp(50.0 + 49.0 * abs(combined_bias), 1.0, 99.0)), 1)

    prior_bias = None
    base_direction_with_latest_bias = parse_float(result.get("bias"), None)
    if len(candles) >= 3:
        prior_base = _BASE_ANALYZE_CANDLES({"candles": candles[:-1]}, image_height)
        prior_bias = parse_float(prior_base.get("bias"), None)
    latest_state = _latest_candle_state(
        candles, int((candles_result.get("plot_crop_shape") or {}).get("width") or 0),
        prior_bias, float(base_direction_with_latest_bias or 0.0))
    latest_state["enhanced_direction_with_latest_candle"] = direction
    latest_state["enhanced_bias_with_latest_candle"] = round(float(combined_bias), 5)
    latest_state["comparison_method"] = "same base analyzer with and without latest candle; enhanced position-aware analysis reported separately"

    raw_components = price_action.get("components") or {}
    prior_weighted = price_action.get("weighted_component_contributions") or {}
    result.update({
        "bias": round(combined_bias, 5), "direction": direction,
        "buy_direction_score_percent": round(buy_pct, 1), "sell_direction_score_percent": round(sell_pct, 1),
        "selected_direction_score_percent": round(buy_pct if direction == "BUY" else sell_pct, 1),
        "patterns": patterns, "pattern_bias": round(pattern_bias, 5),
        "pattern_weighting_method": "recency-decayed and clustered by endpoint; trend/location/confirmation weighted; previous-screenshot outcome weighting disabled for live predictions",
        "pattern_historical_performance": historical_pattern_metrics,
        "pattern_historical_weighting_enabled_for_this_screenshot": bool(use_historical_pattern_weights),
        "pattern_confirmation_summary": {
            "total_patterns": len(patterns),
            "confirmed_patterns": sum(1 for row in patterns if row.get("confirmed")),
            "unconfirmed_patterns": sum(1 for row in patterns if not row.get("confirmed")),
            "context_adjusted_patterns": sum(1 for row in patterns if row.get("context_multiplier") is not None),
            "invalid_sequence_patterns_downweighted": sum(1 for row in patterns if row.get("sequence_valid") is False),
            "unconfirmed_pattern_strength_reduced": True,
        },
        "structural_context": structural_context,
        "classical_chart_patterns": price_action.get("classical_chart_patterns", {}),
        "advanced_patterns_detected": len(advanced_patterns),
        "visual_momentum_divergence": {key: value for key, value in visual_divergence.items() if key != "patterns"},
        "reading_confidence_percent": round(confidence, 1),
        "shape_reading_heuristic_score_percent": round(confidence, 1),
        "reading_confidence_semantics": "HEURISTIC_ONLY; measured detector precision/recall is reported separately from manually labeled screenshots",
        "geometry_validation": geometry_validation,
        "latest_candle_completion_status": latest_state.get("state"),
        "latest_candle_completion_uncertainty_applied": bool(candles[-1].get("possibly_incomplete", False)),
        "chart_detection": candles_result.get("chart_region"),
        "possible_missing_spacing_gaps": candles_result.get("possible_missing_spacing_gaps", 0),
        "sequence_gap_indices": [int(row.get("index", i+1)) for i,row in enumerate(candles) if row.get("sequence_break_before")],
        "latest_candle_state": latest_state,
        "analysis_model": CANDLE_ANALYSIS_MODEL_VERSION,
        "legacy_color_weighted_bias_diagnostic_only": round(original_bias, 5),
        "legacy_weighted_color_momentum_diagnostic_only": round(float(result.get("weighted_color_momentum", 0.0) or 0.0), 5),
        "trend_component": round(float(raw_components.get("trend", 0.0) or 0.0), 5),
        "weighted_color_momentum": round(float(raw_components.get("momentum", 0.0) or 0.0), 5),
        "market_structure": price_action.get("gap_aware_market_structure", result.get("market_structure", {})),
        "trend": price_action.get("trend_state", result.get("trend", "SIDEWAYS_OR_MIXED")),
        "momentum": "BULLISH" if float(raw_components.get("momentum", 0.0) or 0.0) > 0.10 else "BEARISH" if float(raw_components.get("momentum", 0.0) or 0.0) < -0.10 else "MIXED",
        "price_action_context": price_action,
        "feature_contributions": {key: value for key, value in prior_weighted.items()},
        "normalization": {
            "body_to_range_median": round(float(np.median(body_ratios)), 5) if body_ratios else None,
            "upper_wick_to_range_median": round(float(np.median(upper_ratios)), 5) if upper_ratios else None,
            "lower_wick_to_range_median": round(float(np.median(lower_ratios)), 5) if lower_ratios else None,
            "range_to_median_range_median": round(float(np.median(range_ratios)), 5) if range_ratios else None,
            "median_range_pixels": round(float(np.median(ranges)), 3) if len(ranges) else 0.0,
            "recent_range_mean_pixels": round(float(np.mean(ranges[-min(10, len(ranges)):])) , 3) if len(ranges) else 0.0,
            "per_candle_scale_normalized_features": normalized_features,
            "ratios_are_scale_normalized": True,
        },
        "market_regime": price_action.get("regime", "TRANSITION_OR_BREAKOUT_TEST"),
        "visual_return_volatility": round(vol, 4),
        "price_scale_calibration": price_scale, "price_scale_calibrated": bool(price_scale.get("available")),
        "fixed_expiry_forecast": _candle_fixed_expiry_forecast(candles, price_action),
        "connected_feature_audit": {
            "instrument": "Bitcoin OTC chart; actual settlement remains broker-specific",
            "forecast_horizon_minutes": FIXED_EXPIRY_MINUTES,
            "timeframe": TIMEFRAME_LABEL,
            "visible_candles_used_by_main_analysis": n,
            "visible_candle_count_capped": False,
            "candlestick_patterns": {
                "detected_count": len(patterns),
                "confirmed_count": sum(1 for row in patterns if row.get("confirmed")),
                "unconfirmed_count": sum(1 for row in patterns if not row.get("confirmed")),
                "score_link": "context-adjusted pattern features feed price_action_context; same-event clusters are grouped to limit correlated votes",
                "active": bool(patterns),
            },
            "chart_patterns": {
                "detected_count": len((price_action.get("classical_chart_patterns") or {}).get("patterns") or []),
                "line_segments": len((price_action.get("classical_chart_patterns") or {}).get("line_segments") or []),
                "score_link": "confirmed formations and boundary-break context feed the five-minute price-action score",
                "active": bool((price_action.get("classical_chart_patterns") or {}).get("available")),
            },
            "market_structure": {
                "active": bool(structural_context.get("available")),
                "breakout_state": structural_context.get("breakout_state"),
                "retest_detected": bool(structural_context.get("retest_detected")),
                "false_breakout_detected": bool(structural_context.get("false_breakout_detected")),
                "score_link": "swing structure, displacement, breakout/retest and exhaustion are included in price_action_context",
            },
            "support_resistance_and_fibonacci": {
                "support_zone_count": len(result.get("support_pixel_zones") or []),
                "resistance_zone_count": len(result.get("resistance_pixel_zones") or []),
                "fibonacci_available": bool((price_action.get("fibonacci_retracement_context") or {}).get("available")),
                "fibonacci_reaction_bias": (price_action.get("fibonacci_retracement_context") or {}).get("reaction_bias"),
                "score_link": "level proximity and observed reaction are score inputs; drawn lines alone do not create votes",
            },
            "smart_money_and_liquidity": {
                "detected_count": sum(1 for row in patterns if str(row.get("pattern_family") or "") in {"liquidity", "liquidity_alias", "order_block", "imbalance", "imbalance_alias", "imbalance_location", "location", "smc_sequence"}),
                "score_link": "measured liquidity sweeps, displacement, order-block candidates, FVGs and location/retest evidence share the pattern/structure pipeline",
                "real_order_book_available": False,
            },
            "technical_indicators": {
                "available_from_candles": True,
                "score_link": "EMA/RSI/MACD/ADX/ATR/ROC/Bollinger are grouped into one confirmation layer to avoid duplicate votes",
            },
            "volume": {
                "real_or_declared_volume_in_visual_candles": False,
                "synthetic_volume_created": False,
                "score_link": "volume is used only when an actual declared volume source is available in the broker OHLC export",
            },
            "time_based_ict_setups": {
                "available": False,
                "reason": "ICT kill zones, Silver Bullet and Judas Swing require trustworthy per-candle timestamps and a defined timezone/session. Static candle pixels alone do not prove session time; these are not guessed or added as directional votes.",
            },
            "price_provenance": {
                "latest_quote": "direct visible broker price badge OCR when readable; otherwise unavailable or labelled estimate",
                "historical_candle_ohlc": "axis-calibrated image estimate when validated, otherwise screen-pixel proxy; verified broker OHLC requires timestamped broker export",
                "public_BTC_USD_context_is_broker_otc_price": False,
            },
            "score_semantics": "directional five-minute evidence estimate; it becomes a calibrated empirical success probability only when sufficient correctly timestamped broker outcome labels exist",
        },
    })
    return _attach_requested_analysis_coverage(result)

def validate_m1_bars(bars: List[Dict[str, Any]], now_epoch: Optional[float] = None) -> Dict[str, Any]:
    """Validate OHLC geometry, timestamps, duplicates, minute gaps, freshness and jumps.

    Valid, non-duplicate bars are retained in chronological order. Extreme but internally
    valid price moves are flagged rather than silently deleted; consumers can reduce their
    weight. A public quote is fresh only when the newest timestamp is near current time.
    """
    now = time.time() if now_epoch is None else float(now_epoch)
    by_stamp: Dict[int, Dict[str, Any]] = {}
    invalid_ohlc = invalid_timestamp = duplicate_timestamps = 0
    for original in bars or []:
        if not isinstance(original, dict):
            continue
        stamp_value = parse_float(original.get("timestamp"), None)
        if stamp_value is None:
            stamp_value = parse_epoch(original.get("timestamp_utc") or original.get("time") or original.get("datetime"))
        if stamp_value is None or stamp_value <= 0:
            invalid_timestamp += 1
            continue
        stamp = int(stamp_value)
        values = {key: parse_float(original.get(key), None) for key in ("open", "high", "low", "close")}
        if any(value is None or value <= 0 for value in values.values()):
            invalid_ohlc += 1
            continue
        o, h, l, c = (float(values[k]) for k in ("open", "high", "low", "close"))
        tolerance = max(abs(o), abs(h), abs(l), abs(c), 1.0) * 1e-10
        if h + tolerance < max(o, c) or l - tolerance > min(o, c) or h + tolerance < l:
            invalid_ohlc += 1
            continue
        row = dict(original)
        row.update({"timestamp": stamp, "open": o, "high": h, "low": l, "close": c})
        if stamp in by_stamp:
            duplicate_timestamps += 1
            # Prefer the later record; providers sometimes repeat a bar during refresh.
        by_stamp[stamp] = row
    clean = [by_stamp[k] for k in sorted(by_stamp)]
    missing_intervals = 0
    max_gap_intervals = 0
    for prior, current in zip(clean, clean[1:]):
        elapsed_seconds = max(0.0, float(current["timestamp"] - prior["timestamp"]))
        intervals = max(0, int(round(elapsed_seconds / TIMEFRAME_INTERVAL_SECONDS)))
        if intervals > 1:
            missing_intervals += intervals - 1
            max_gap_intervals = max(max_gap_intervals, intervals - 1)
    jumps = []
    returns = []
    for i in range(1, len(clean)):
        previous, current = clean[i-1]["close"], clean[i]["close"]
        ret = abs(math.log(current / previous)) if previous > 0 and current > 0 else 0.0
        returns.append(ret)
    if returns:
        med = float(np.median(returns))
        mad = float(np.median(np.abs(np.asarray(returns, dtype=float) - med)))
        jump_threshold = max(0.005, med + 12.0 * max(mad, 1e-7))
        for i, ret in enumerate(returns, start=1):
            if ret > jump_threshold:
                jumps.append({"timestamp": clean[i]["timestamp"], "absolute_log_return": round(ret, 7),
                              "threshold": round(jump_threshold, 7), "index": i})
    age = now - float(clean[-1]["timestamp"]) if clean else None
    fresh = bool(age is not None and -120.0 <= age <= MAX_M1_BAR_AGE_SECONDS)
    return {
        "bars": clean, "input_count": len(bars or []), "valid_count": len(clean),
        "invalid_ohlc_count": invalid_ohlc, "invalid_timestamp_count": invalid_timestamp,
        "duplicate_timestamp_count": duplicate_timestamps, "missing_interval_count": missing_intervals,
        "maximum_missing_gap_intervals": max_gap_intervals, "price_jump_count": len(jumps),
        "price_jump_details": jumps[:20], "latest_bar_age_seconds": round(age, 2) if age is not None else None,
        "fresh": fresh, "usable_for_live_context": bool(fresh and len(clean) >= 5),
        "all_timestamps_unique": duplicate_timestamps == 0,
        "ohlc_geometry_validated": True,
        "timestamp_interval_seconds": TIMEFRAME_INTERVAL_SECONDS,
        "timeframe": TIMEFRAME_LABEL,
    }


def _wilson_interval(successes: int, total: int, z: float = 1.96) -> Optional[Dict[str, float]]:
    """Wilson score interval for a measured proportion; returns percentages."""
    if total <= 0:
        return None
    p = float(successes) / float(total)
    den = 1.0 + z*z/total
    center = (p + z*z/(2*total)) / den
    margin = z * math.sqrt((p*(1-p) + z*z/(4*total))/total) / den
    return {"lower_percent": round(max(0.0, center-margin)*100, 2),
            "upper_percent": round(min(1.0, center+margin)*100, 2), "confidence_level_percent": 95.0}


# ----------------------- M1 market indicators / context ----------------------
def _technical_indicators(bars: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Calculate validated M1 indicators using Wilder ATR/DI/ADX and regime context.

    Indicators are a single price-derived evidence group. They are not treated as
    independent market feeds or as guaranteed forecasts for the broker's OTC feed.
    """
    validation = validate_m1_bars(bars)
    rows = validation["bars"]
    if len(rows) < 5:
        return {"available": False, "sample_count": len(rows), "bias": 0.0,
                "fresh": bool(validation.get("fresh")),
                "market_data_validation": {k: v for k, v in validation.items() if k != "bars"}}

    o = np.array([float(r["open"]) for r in rows], dtype=float)
    h = np.array([float(r["high"]) for r in rows], dtype=float)
    l = np.array([float(r["low"]) for r in rows], dtype=float)
    c = np.array([float(r["close"]) for r in rows], dtype=float)
    ema9, ema12, ema21, ema26 = (_ema(c, n) for n in (9, 12, 21, 26))
    macd_line = ema12 - ema26
    macd_signal = _ema(macd_line, 9)
    macd_histogram = macd_line - macd_signal

    prior_close = np.r_[c[0], c[:-1]]
    true_range = np.maximum(h - l, np.maximum(np.abs(h - prior_close), np.abs(l - prior_close)))
    period = min(14, len(true_range))
    atr_series = _wilder_average(true_range, period)
    atr = max(1e-12, float(atr_series[-1]))

    up_move = np.diff(h, prepend=h[0])
    down_move = -np.diff(l, prepend=l[0])
    plus_dm = np.where((up_move > down_move) & (up_move > 0), up_move, 0.0)
    minus_dm = np.where((down_move > up_move) & (down_move > 0), down_move, 0.0)
    plus_series = _wilder_average(plus_dm, period)
    minus_series = _wilder_average(minus_dm, period)
    plus_di_series = 100.0 * plus_series / np.maximum(atr_series, 1e-12)
    minus_di_series = 100.0 * minus_series / np.maximum(atr_series, 1e-12)
    dx_series = 100.0 * np.abs(plus_di_series - minus_di_series) / np.maximum(plus_di_series + minus_di_series, 1e-12)
    adx_series = _wilder_average(dx_series, period)
    plus_di, minus_di, adx = float(plus_di_series[-1]), float(minus_di_series[-1]), float(adx_series[-1])

    bb_period = min(20, len(c))
    bb_window = c[-bb_period:]
    bb_mid = float(np.mean(bb_window))
    bb_std = float(np.std(bb_window))
    bb_up, bb_down = bb_mid + 2.0 * bb_std, bb_mid - 2.0 * bb_std
    bb_width = max(0.0, bb_up - bb_down)
    bb_width_pct = bb_width / max(1e-12, abs(bb_mid)) * 100.0
    bb_percent_b = (float(c[-1]) - bb_down) / bb_width if bb_width > 1e-12 else 0.5
    bb_z_score = (float(c[-1]) - bb_mid) / max(bb_std, 1e-12)

    stoch_n = min(14, len(c))
    stoch_low, stoch_high = float(np.min(l[-stoch_n:])), float(np.max(h[-stoch_n:]))
    stoch_k = 50.0 if stoch_high <= stoch_low else 100.0 * (float(c[-1]) - stoch_low) / (stoch_high - stoch_low)
    rsi_value = _rsi(c, 14)
    roc = {str(n): round((float(c[-1]) / max(1e-12, float(c[-1 - n])) - 1.0) * 100.0, 6)
           for n in (1, 3, 5) if len(c) > n}

    if adx >= 25.0:
        regime = "TRENDING"
    elif bb_width_pct < 0.06 and atr / max(1e-12, abs(float(c[-1]))) < 0.00025:
        regime = "LOW_VOLATILITY_RANGE"
    elif adx < 16.0:
        regime = "RANGING_OR_CHOPPY"
    else:
        regime = "TRANSITION_OR_BREAKOUT"

    atr_scale = max(atr, 1e-12)
    trend_scale = 1.0 if regime == "TRENDING" else 0.55 if regime in ("RANGING_OR_CHOPPY", "LOW_VOLATILITY_RANGE") else 0.80
    macd_norm = math.tanh(float(macd_line[-1]) / atr_scale * 5.0) * trend_scale
    macd_hist_norm = math.tanh(float(macd_histogram[-1]) / atr_scale * 8.0) * trend_scale
    ema_norm = math.tanh((float(ema9[-1]) - float(ema21[-1])) / atr_scale * 4.0) * trend_scale
    rsi_momentum = clamp(((float(rsi_value) - 50.0) / 30.0) if rsi_value is not None else 0.0, -1.0, 1.0)
    stoch_momentum = clamp((stoch_k - 50.0) / 45.0, -1.0, 1.0)
    # Oscillators are interpreted differently in a choppy range versus a strong trend.
    if regime in ("RANGING_OR_CHOPPY", "LOW_VOLATILITY_RANGE"):
        rsi_norm = -0.65 * rsi_momentum
        stoch_norm = -0.75 * stoch_momentum
        oscillator_mode = "mean_reversion_damped"
    elif regime == "TRENDING":
        rsi_norm = rsi_momentum
        stoch_norm = stoch_momentum
        oscillator_mode = "trend_momentum"
    else:
        rsi_norm = 0.50 * rsi_momentum
        stoch_norm = 0.35 * stoch_momentum
        oscillator_mode = "mixed_transition"
    di_norm = clamp((plus_di - minus_di) / 40.0, -1.0, 1.0) * clamp(adx / 35.0, 0.0, 1.0)
    roc1 = parse_float(roc.get("1"), 0.0) or 0.0
    roc_norm = math.tanh(roc1 / 0.025)
    # The MACD line and histogram share information; their weights are partitioned.
    # Weights sum to 1.00 so no feature group is accidentally counted twice.
    bias = float(clamp(
        0.18 * macd_norm + 0.12 * macd_hist_norm + 0.20 * ema_norm
        + 0.14 * rsi_norm + 0.18 * di_norm + 0.08 * stoch_norm + 0.10 * roc_norm,
        -1.0, 1.0))

    volume_values = np.array([max(0.0, float(parse_float(row.get("volume"), 0.0) or 0.0)) for row in rows], dtype=float)
    positive_volume = volume_values[volume_values > 0]
    declared_types = {str(row.get("volume_type") or "").strip().lower()
                      for row in rows if float(parse_float(row.get("volume"), 0.0) or 0.0) > 0}
    volume_type_valid = len(declared_types) == 1 and next(iter(declared_types), "") in VOLUME_TYPES_ALLOWED
    volume_source_valid = all(bool(str(row.get("volume_source") or row.get("source") or "").strip())
                              for row in rows if float(parse_float(row.get("volume"), 0.0) or 0.0) > 0)
    volume_available = (volume_type_valid and volume_source_valid
                        and len(positive_volume) >= min(5, len(volume_values))
                        and float(np.std(positive_volume)) > 1e-12 and volume_values[-1] > 0)
    volume_ratio = volume_bias = None
    if volume_available:
        volume_ratio = float(volume_values[-1] / max(1e-12, float(np.median(positive_volume))))
        latest_direction = 1.0 if c[-1] > o[-1] else -1.0 if c[-1] < o[-1] else 0.0
        volume_strength = float(clamp((volume_ratio - 1.0) / 1.5, 0.0, 1.0))
        volume_bias = float(clamp(latest_direction * volume_strength, -1.0, 1.0))
        bias = float(clamp(0.96 * bias + 0.04 * volume_bias, -1.0, 1.0))

    latest_range = max(1e-12, float(h[-1] - l[-1]))
    return {
        "available": True, "sample_count": len(rows), "latest_close": float(c[-1]),
        "ema9": round(float(ema9[-1]), 7), "ema21": round(float(ema21[-1]), 7),
        "macd": round(float(macd_line[-1]), 8), "macd_signal": round(float(macd_signal[-1]), 8),
        "macd_histogram": round(float(macd_histogram[-1]), 8),
        "macd_histogram_bias": round(float(macd_hist_norm), 5),
        "atr14": round(atr, 8), "atr_smoothing": "Wilder_RMA",
        "adx_estimate": round(adx, 2), "adx_smoothing": "Wilder_RMA",
        "plus_di_estimate": round(plus_di, 2), "minus_di_estimate": round(minus_di, 2),
        "bollinger_upper": round(bb_up, 7), "bollinger_middle": round(bb_mid, 7),
        "bollinger_lower": round(bb_down, 7), "bollinger_width_percent": round(bb_width_pct, 5),
        "bollinger_percent_b": round(float(bb_percent_b), 5),
        "bollinger_z_score": round(float(bb_z_score), 4),
        "stochastic_k": round(float(stoch_k), 2), "rsi14": round(float(rsi_value), 2) if rsi_value is not None else None,
        "rsi_smoothing": "Wilder_RMA", "rsi_signal_bias": round(float(rsi_norm), 5),
        "stochastic_signal_bias": round(float(stoch_norm), 5), "oscillator_mode": oscillator_mode,
        "roc_percent": roc, "latest_range_vs_atr": round(latest_range / atr_scale, 3),
        "volume_available": bool(volume_available),
        "latest_volume": round(float(volume_values[-1]), 4) if volume_available else None,
        "volume_to_median_ratio": round(float(volume_ratio), 4) if volume_ratio is not None else None,
        "volume_bias": round(float(volume_bias), 4) if volume_bias is not None else None,
        "volume_interpretation": ("Documented source-supplied " + str(next(iter(declared_types), "volume")) + "; not consolidated exchange-wide Bitcoin market volume") if volume_available else "Volume omitted: source did not document tick_volume or real_volume semantics",
        "volume_type": next(iter(declared_types), None) if volume_available else None,
        "volume_source": next((str(row.get("volume_source") or row.get("source")) for row in reversed(rows)
                                if float(parse_float(row.get("volume"), 0.0) or 0.0) > 0), None) if volume_available else None,
        "fresh": bool(validation.get("fresh")),
        "usable_for_live_context": bool(validation.get("usable_for_live_context")),
        "market_data_validation": {k: v for k, v in validation.items() if k != "bars"},
        "regime": regime, "trend_scale": round(float(trend_scale), 3), "bias": round(bias, 5),
        "indicator_method": "Wilder-smoothed RSI/ATR/DI/ADX; MACD histogram; regime-aware oscillator interpretation",
        "weight_sum": 1.0,
    }


def _m1_market_context(bars: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Summarize validated M1 returns; lookbacks are counted in 1-minute bars."""
    validation = validate_m1_bars(bars)
    clean = validation["bars"]
    closes = np.array([float(row["close"]) for row in clean], dtype=float)
    if len(closes) < 2:
        return {"available": False, "fresh": bool(validation.get("fresh")), "timeframe": "M1",
                "bar_count": len(closes), "bias": 0.0,
                "market_data_validation": {k: v for k, v in validation.items() if k != "bars"},
                "basis": "validated public 1-minute reference bars only"}
    recent_log_returns = np.diff(np.log(closes))[-15:]
    return_volatility = float(np.std(recent_log_returns)) if len(recent_log_returns) else 0.0
    components, returns = {}, {}
    for lookback in (3, 5, 15):
        period = min(lookback, len(closes) - 1)
        prior, current = float(closes[-period - 1]), float(closes[-1])
        pct = (current / max(1e-12, prior) - 1.0) * 100.0
        returns[str(lookback)] = round(pct, 6)
        normalized = (math.log(current / max(1e-12, prior)) /
                      max(1e-12, return_volatility * math.sqrt(max(1, period)))) if return_volatility > 1e-12 else 0.0
        components[str(lookback)] = math.tanh(normalized * 0.75)
    bias = float(clamp(0.50 * components["3"] + 0.30 * components["5"] + 0.20 * components["15"], -1.0, 1.0))
    return {
        "available": True, "fresh": bool(validation.get("fresh")),
        "usable_for_live_context": bool(validation.get("usable_for_live_context")),
        "timeframe": "M1", "bar_count": len(clean), "bias": round(bias, 5),
        "recent_return_3_m1_bars_percent": returns["3"], "recent_return_5_m1_bars_percent": returns["5"],
        "recent_return_15_m1_bars_percent": returns["15"],
        "recent_log_return_volatility": round(return_volatility, 8),
        "market_data_validation": {k: v for k, v in validation.items() if k != "bars"},
        "basis": "validated public M1 bars; lookbacks are 3/5/15 1-minute bars",
        "is_public_reference_not_broker_otc": True,
    }


def _online_fixed_expiry_forecast(bars: List[Dict[str, Any]], indicator_bias: float = 0.0,
                                  m1_context: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Forecast the next 5 minutes using only validated public M1 reference data."""
    horizon_minutes = FIXED_EXPIRY_MINUTES
    horizon_bars = FORECAST_HORIZON_BARS
    validation = validate_m1_bars(bars)
    clean = validation["bars"]
    closes = np.array([float(row["close"]) for row in clean], dtype=float)
    returns = np.diff(np.log(closes)) if len(closes) > 1 else np.array([], dtype=float)
    m1_context = m1_context or {}
    fresh = bool(validation.get("fresh")) and bool(validation.get("usable_for_live_context", validation.get("fresh")))
    m1_bias = float(parse_float(m1_context.get("bias"), 0.0) or 0.0) if fresh else 0.0
    ind_bias = float(indicator_bias) if fresh else 0.0
    sample_size = min(len(returns), max(5, horizon_bars * 3))
    sample = returns[-sample_size:] if sample_size else np.array([], dtype=float)
    if fresh and len(sample) >= 2:
        target_sample = sample[-min(len(sample), max(1, horizon_bars * 2)):]
        mean_ret = float(np.mean(target_sample))
        sigma = max(1e-8, float(np.std(sample)))
        impulse = math.tanh((mean_ret / sigma) * math.sqrt(horizon_bars) * 0.70)
    else:
        impulse = 0.0
    bias = float(clamp(0.60 * impulse + 0.28 * ind_bias + 0.12 * m1_bias, -1.0, 1.0))
    direction = "BUY" if bias >= 0 else "SELL"
    return {"horizon_minutes": horizon_minutes, "target_minutes": horizon_minutes,
            "horizon_bars": horizon_bars, "bias": round(bias, 5),
            "direction": direction, "score_percent": round(50 + 49 * abs(bias), 1),
            "reference_sample_bars": sample_size, "reference_timeframe": "M1",
            "reference_data_fresh": fresh,
            "market_data_validation": {k: v for k, v in validation.items() if k != "bars"}}


def _walk_forward_backtest(bars: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Chronological baseline backtest: five M1 bars ahead for a 5-minute target."""
    horizon_minutes = FIXED_EXPIRY_MINUTES
    horizon_bars = FORECAST_HORIZON_BARS
    validation = validate_m1_bars(bars)
    clean = validation["bars"]
    closes = np.array([float(row["close"]) for row in clean], dtype=float)
    n = len(closes)
    purge_gap = max(FORECAST_PURGE_GAP_RECORDS, horizon_bars)
    if n < max(100, horizon_bars + 40):
        return {"available": False, "fixed_expiry_minutes": horizon_minutes, "horizon_bars": horizon_bars,
                "sample_count": n, "reason": "Not enough sequential public M1 bars for holdout validation"}
    train_end = int(n * 0.70)
    test_start = train_end + purge_gap
    if test_start >= n - horizon_bars - 10:
        return {"available": False, "fixed_expiry_minutes": horizon_minutes, "horizon_bars": horizon_bars,
                "sample_count": n, "reason": "Insufficient data after purging overlapping five-minute target windows"}
    predictions, actuals = [], []
    for index in range(test_start, n - horizon_bars):
        history = closes[:index]
        if len(history) < 20:
            continue
        short = history[-min(3, len(history)):]
        medium = history[-min(12, len(history)):]
        score = (short[-1] / max(1e-12, short[0]) - 1) * 0.65 + (medium[-1] / max(1e-12, medium[0]) - 1) * 0.35
        predictions.append(1 if score >= 0 else -1)
        actuals.append(1 if closes[index + horizon_bars] > closes[index] else -1 if closes[index + horizon_bars] < closes[index] else 0)
    valid = [(pred, actual) for pred, actual in zip(predictions, actuals) if actual != 0]
    if not valid:
        return {"available": False, "fixed_expiry_minutes": horizon_minutes, "horizon_bars": horizon_bars,
                "sample_count": n, "reason": "No non-flat five-minute target outcomes in the chronological holdout"}
    hits = sum(pred == actual for pred, actual in valid)
    return {"available": True, "fixed_expiry_minutes": horizon_minutes, "horizon_bars": horizon_bars,
            "sample_count": n, "chronological_train_fraction": 0.70, "test_fraction": 0.30,
            "purge_gap_bars": purge_gap, "lookahead_used_for_prediction": False,
            "holdout_samples": len(valid), "directional_hit_rate_percent": round(hits / len(valid) * 100, 2),
            "hit_rate_ci_95_percent": _wilson_interval(hits, len(valid)),
            "scope": "Validated public Bitcoin M1 spot proxy only; five-bar (5-minute) horizon; not broker OTC or visual-model replay",
            "market_data_validation": {k: v for k, v in validation.items() if k != "bars"}}

def _session_context() -> Dict[str, Any]:
    """Bitcoin trades continuously; regional trading hours are only an intraday activity proxy."""
    now_utc = datetime.now(timezone.utc)
    try:
        london = now_utc.astimezone(ZoneInfo("Europe/London"))
        new_york = now_utc.astimezone(ZoneInfo("America/New_York"))
        london_active = 8 <= london.hour < 17 and london.weekday() < 5
        ny_active = 8 <= new_york.hour < 17 and new_york.weekday() < 5
        if london_active and ny_active:
            activity_window = "LONDON_NEW_YORK_OVERLAP_PROXY"
        elif london_active:
            activity_window = "LONDON_DAYTIME_PROXY"
        elif ny_active:
            activity_window = "NEW_YORK_DAYTIME_PROXY"
        elif now_utc.hour >= 0 and now_utc.hour < 8:
            activity_window = "ASIA_UTC_HOURS_PROXY"
        else:
            activity_window = "OFF_PEAK_OR_TRANSITION_PROXY"
        return {
            "market_status": "CRYPTO_24_7; NOT A SESSION-OPEN SIGNAL",
            "session": "CRYPTO_24_7",
            "activity_window_proxy": activity_window,
            "utc_time": now_utc.isoformat(timespec="minutes"),
            "london_time": london.isoformat(timespec="minutes"),
            "new_york_time": new_york.isoformat(timespec="minutes"),
            "liquidity_status": "TIME-OF-DAY PROXY ONLY; live exchange volume is not available from this clock calculation",
        }
    except Exception:
        return {"market_status": "CRYPTO_24_7", "session": "CRYPTO_24_7",
                "activity_window_proxy": "UNKNOWN", "liquidity_status": "TIME-OF-DAY PROXY UNAVAILABLE"}


