def _clean_html_fragments(html_text: str) -> List[str]:
    text = re.sub(r"(?is)<script.*?</script>|<style.*?</style>|<!--.*?-->", " ", html_text)
    fragments = re.split(r"(?i)</(?:p|li|tr|article|h[1-6]|td|section|div|time)>|<br\s*/?>", text)
    output = []
    for frag in fragments:
        value = re.sub(r"(?s)<[^>]+>", " ", frag)
        value = re.sub(r"\s+", " ", value).strip()
        value = value.replace("&nbsp;", " ").replace("&amp;", "&").replace("&#39;", "'")
        if 18 <= len(value) <= 1200:
            output.append(value)
    return output


