def _extract_release_surprise(text: str) -> Optional[Dict[str, Any]]:
    text = re.sub(r"\s+", " ", str(text or ""))
    # Only report a surprise when the headline explicitly labels both actual and forecast/expected values.
    pattern = re.compile(r"(?i)(?:actual|actual(?:ly)?|reported|came in at)\D{0,28}(-?\d+(?:\.\d+)?%?)\D{0,60}(?:forecast|expected|consensus)\D{0,24}(-?\d+(?:\.\d+)?%?)")
    match = pattern.search(text)
    reverse = False
    if not match:
        pattern = re.compile(r"(?i)(?:forecast|expected|consensus)\D{0,24}(-?\d+(?:\.\d+)?%?)\D{0,60}(?:actual|reported|came in at)\D{0,24}(-?\d+(?:\.\d+)?%?)")
        match = pattern.search(text)
        reverse = True
    if not match:
        return None
    a_text = match.group(2 if reverse else 1).replace("%", "")
    b_text = match.group(1 if reverse else 2).replace("%", "")
    a, b = parse_float(a_text), parse_float(b_text)
    if a is None or b is None:
        return None
    result = {"actual": a, "forecast": b, "surprise": round(a - b, 6), "explicitly_labeled": True}
    previous_match = re.search(
        r"(?i)(?:previous(?:ly)?|prior(?:\s+period)?|previous\s+(?:reading|value)|prior\s+(?:reading|value)|revised\s+from)"
        r"\D{0,24}(-?\d+(?:\.\d+)?%?)",
        text,
    )
    if not previous_match:
        previous_match = re.search(
            r"(?i)(-?\d+(?:\.\d+)?%?)\D{0,20}(?:previous|prior\s+value)", text
        )
    if previous_match:
        previous_value = parse_float(previous_match.group(1).replace("%", ""), None)
        if previous_value is not None:
            result["previous"] = previous_value
            result["change_from_previous"] = round(a - previous_value, 6)
    return result


def _term_negated(text: str, term: str) -> bool:
    escaped = re.escape(term.lower())
    pattern = re.compile(r"\b(?:not|no|never|fails? to|failed to|denies|denied|unlikely to)\b(?:\W+\w+){0,3}\W+" + escaped + r"\b", re.I)
    return bool(pattern.search(text))


def _release_surprise_directional_bias(items: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Do not impose a fixed up/down mapping from macro surprises onto Bitcoin."""
    records = []
    for item in items or []:
        text = (str(item.get("title") or "") + " " + str(item.get("description") or "")).lower()
        surprise = _extract_release_surprise(text)
        if surprise:
            records.append({
                "title": item.get("title"),
                "source": item.get("source"),
                "surprise": surprise,
                "directional_mapping": "CONTEXT_ONLY_NO_FIXED_BITCOIN_DIRECTION",
                "reason": "Macro surprise impact on BTC depends on expectations, liquidity, yields, positioning and contemporaneous price response.",
            })
    return {
        "available": False,
        "bias": None,
        "records": records,
        "note": "Official U.S. macro/regulatory events are risk context only; no fixed directional bias is inferred from an economic surprise.",
    }


def headline_bias(articles: List[Dict[str, Any]]) -> Tuple[Optional[float], int, int]:
    """Score fresh headline direction while limiting repeated publisher/syndication votes."""
    bull = bear = neutral = 0
    weighted = []
    # Only the freshest article from a publisher contributes a directional vote.
    # If publisher attribution is missing, the RSS search/feed is the conservative fallback.
    unique_publishers: Dict[str, Dict[str, Any]] = {}
    for article in articles or []:
        publisher_key = re.sub(r"[^a-z0-9]", "", str(article.get("publisher") or article.get("source") or "unknown").lower())
        previous = unique_publishers.get(publisher_key)
        published = parse_float(article.get("published_epoch"), 0.0) or 0.0
        previous_published = parse_float((previous or {}).get("published_epoch"), 0.0) or 0.0
        if previous is None or published > previous_published:
            unique_publishers[publisher_key] = article
    for article in unique_publishers.values():
        title = str(article.get("title") or "").lower()
        description = str(article.get("description") or "").lower()
        text = re.sub(r"\s+", " ", title + " " + description).strip()
        up_terms = [term for term in BULLISH_TERMS if term in text]
        down_terms = [term for term in BEARISH_TERMS if term in text]
        up = bool(up_terms) and not any(_term_negated(text, term) for term in up_terms)
        down = bool(down_terms) and not any(_term_negated(text, term) for term in down_terms)
        if up and down:
            neutral += 1
            continue
        sign = 1 if up and not down else -1 if down and not up else 0
        if not sign:
            neutral += 1
            continue
        published = parse_float(article.get("published_epoch"), time.time()) or time.time()
        age = max(0.0, time.time() - published)
        source = str(article.get("source") or "")
        reliability = _source_reliability(source, "news", age)
        weight = reliability * math.exp(-age / (12 * 3600.0))
        weighted.append(sign * weight)
        if sign > 0: bull += 1
        else: bear += 1
    if not weighted:
        return None, bull, bear
    return float(clamp(sum(weighted) / max(1e-9, sum(abs(v) for v in weighted)), -1.0, 1.0)), bull, bear
def _store_calendar_items(cycle_id: int, events: List[Dict[str, Any]]) -> None:
    batch = [(str(row.get("key") or hashlib.sha256(str(row).encode()).hexdigest()), row,
              parse_float(row.get("event_epoch"), None)) for row in events]
    db_store_many(cycle_id, "calendar_event", batch)


