def self_test() -> int:
    checks: List[Tuple[str, bool]] = []

    def check(label: str, condition: Any) -> None:
        checks.append((label, bool(condition)))

    # Synthetic chart deliberately has no fixed image-size assumptions.
    test_image = np.full((480, 960, 3), 245, dtype=np.uint8)
    centers = list(range(40, 920, 14))
    for idx, x in enumerate(centers):
        base = 300 - int(90 * idx / max(1, len(centers) - 1))
        color = (0, 190, 0) if idx % 3 else (0, 0, 205)  # BGR green / red
        top = max(30, base - (12 + idx % 7))
        bottom = min(440, base + (13 + idx % 5))
        cv2.line(test_image, (x + 2, top - 8), (x + 2, bottom + 8), color, 1)
        cv2.rectangle(test_image, (x, top), (x + 4, bottom), color, -1)
    extracted = build_visual_candles(test_image)
    analysis = analyze_candles(extracted, test_image.shape[0])
    check("synthetic red/green chart detects more than zero candles", extracted["total"] > 0)
    check("geometry validation is attached to every screenshot candle extraction", isinstance(extracted.get("geometry_validation"), dict) and "directional_score_factor" in extracted["geometry_validation"])
    check("per-candle shape score is labeled heuristic rather than measured accuracy", "HEURISTIC_ONLY" in str(extracted.get("reading_confidence_semantics", "")))
    check("live-frame analysis marks latest candle potentially incomplete", bool((analysis.get("latest_candle_state") or {}).get("possibly_incomplete")) and bool(analysis.get("latest_candle_completion_uncertainty_applied")))
    check("latest-candle uncertainty is reflected in price-action output", bool((analysis.get("price_action_context") or {}).get("position_context", {}).get("latest_completion_uncertainty_applied")))
    check("every detected candle is classified red or green", extracted["red_count"] + extracted["green_count"] == extracted["total"])
    check("no fixed cap is placed on screenshot candle count", extracted["candle_count_cap"] is None)
    many_count = 120
    many_spacing = 8
    many_width = (many_count - 1) * many_spacing + 40
    many_image = np.full((480, many_width, 3), 245, dtype=np.uint8)
    for idx in range(many_count):
        x = 20 + idx * many_spacing
        base = 300 - int(100 * idx / max(1, many_count - 1))
        color = (0, 190, 0) if idx % 3 else (0, 0, 205)
        top = max(30, base - (12 + idx % 7))
        bottom = min(440, base + (13 + idx % 5))
        cv2.line(many_image, (x + 2, top - 8), (x + 2, bottom + 8), color, 1)
        cv2.rectangle(many_image, (x, top), (x + 4, bottom), color, -1)
    many_detected = build_visual_candles(many_image)
    check("120-candle synthetic chart is counted without a count cap", many_detected.get("total") == many_count)
    check("120-candle color counts reconcile with total", many_detected.get("red_count", 0) + many_detected.get("green_count", 0) == many_count)
    check("candidate-level count integrity diagnostics are present", bool(many_detected.get("count_integrity", {}).get("red_plus_green_equals_total")))
    remote_glyph_image = many_image.copy()
    aligned_x = 20 + 40 * many_spacing + 2
    cv2.line(remote_glyph_image, (aligned_x, 18), (aligned_x, 24), (0, 0, 205), 1)
    glyph_detected = build_visual_candles(remote_glyph_image)
    check("small distant toolbar-like pixels do not cause a real candle slot to be discarded", glyph_detected.get("total") == many_count and glyph_detected.get("count_integrity", {}).get("skipped_slots_scattered_artifact_pixels", 0) == 0)
    axis_test = np.full((480, 960, 3), (35, 35, 35), dtype=np.uint8)
    for axis_line_x in range(0, 810, 80):
        cv2.line(axis_test, (axis_line_x, 0), (axis_line_x, 479), (55, 55, 55), 1)
    cv2.line(axis_test, (820, 0), (820, 479), (180, 120, 70), 2)
    cv2.putText(axis_test, "0.9000", (840, 150), cv2.FONT_HERSHEY_SIMPLEX, 0.5, (210, 210, 210), 1)
    axis_crop, axis_info = _crop_right_price_axis_for_candle_count(axis_test)
    check("clear right-side price-axis divider is excluded from candle-count ROI", bool(axis_info.get("crop_right_axis_labels")) and axis_crop.shape[1] < axis_test.shape[1] and axis_crop.shape[1] >= 800)
    wide_count, wide_pitch, wide_width = 200, 5, 2
    wide_image = np.full((480, (wide_count - 1) * wide_pitch + 40, 3), 245, dtype=np.uint8)
    for idx in range(wide_count):
        x = 20 + idx * wide_pitch
        base = 300 - int(100 * idx / max(1, wide_count - 1))
        color = (0, 190, 0) if idx % 3 else (0, 0, 205)
        top = max(30, base - (8 + idx % 5))
        bottom = min(440, base + (9 + idx % 5))
        cv2.line(wide_image, (x + wide_width // 2, top - 5), (x + wide_width // 2, bottom + 5), color, 1)
        cv2.rectangle(wide_image, (x, top), (x + wide_width - 1, bottom), color, -1)
    wide_detected = build_visual_candles(wide_image)
    check("200 narrow candles are counted without a fixed total cap", wide_detected.get("total") == wide_count)
    check("count audit exposes slot-grid, final and fallback component counts", all(k in wide_detected.get("count_integrity", {}) for k in ("primary_component_estimate", "final_detected_count", "slot_grid_candidate_count")))
    overlay_count = 100
    overlay_pitch, overlay_candle_width = 8, 4
    overlay_image = np.full((480, (overlay_count - 1) * overlay_pitch + 40, 3), 245, dtype=np.uint8)
    for idx in range(overlay_count):
        x = 20 + idx * overlay_pitch
        base = 300 - int(100 * idx / max(1, overlay_count - 1))
        color = (0, 190, 0) if idx % 3 else (0, 0, 205)
        top = max(30, base - (12 + idx % 7))
        bottom = min(440, base + (13 + idx % 5))
        cv2.line(overlay_image, (x + 2, top - 8), (x + 2, bottom + 8), color, 1)
        cv2.rectangle(overlay_image, (x, top), (x + overlay_candle_width - 1, bottom), color, -1)
    for idx in range(overlay_count - 1):
        left = 20 + idx * overlay_pitch + overlay_candle_width
        right = 20 + (idx + 1) * overlay_pitch
        if right > left:
            line_color = (0, 190, 0) if idx % 2 else (0, 0, 205)
            cv2.line(overlay_image, (left, 190 + (idx % 5) * 2), (right, 190 + (idx % 5) * 2), line_color, 2)
    overlay_detected = build_visual_candles(overlay_image)
    check("thin connected-color overlay does not explode candle count", abs(int(overlay_detected.get("total", 0)) - overlay_count) <= 3)
    check("slot-grid detector is the authoritative candle counter", many_detected.get("count_integrity", {}).get("slot_grid_detector_enabled") is True)
    spectral_120 = _estimate_spectral_candle_pitch(cv2.bitwise_or(*create_color_masks(many_image)[::-1]))
    check("spectral pitch estimator finds the repeated spacing on dense candles", spectral_120.get("confident") is True and abs(float(spectral_120.get("pitch_pixels", 0)) - many_spacing) <= 0.2)
    alias_guard = _apply_pitch_geometry_guard(33, {6: 0.71, 12: 0.57, 18: 0.58, 33: 0.82}, 5.0)
    check("pitch geometry guard corrects an implausible 33px alias to the 6px candle pitch", alias_guard.get("selected_pitch_after_guard") == 6 and alias_guard.get("geometry_guard_applied") is True)
    regular_guard = _apply_pitch_geometry_guard(6, {6: 0.71, 12: 0.57, 18: 0.58}, 5.0)
    check("pitch geometry guard preserves a plausible 6px candle pitch", regular_guard.get("selected_pitch_after_guard") == 6 and regular_guard.get("geometry_guard_applied") is False)
    check("final candle count is not inflated by a projection fallback", many_detected.get("projection_added_candidates", 0) == 0 and many_detected.get("total") == many_count)
    scaled_075 = build_visual_candles(cv2.resize(many_image, None, fx=0.75, fy=0.75, interpolation=cv2.INTER_NEAREST))
    scaled_125 = build_visual_candles(cv2.resize(many_image, None, fx=1.25, fy=1.25, interpolation=cv2.INTER_NEAREST))
    check("120-candle count survives 0.75x resize", scaled_075.get("total") == many_count)
    check("120-candle count survives 1.25x resize", scaled_125.get("total") == many_count)
    check("red means bearish/Sell candle evidence", any(row["color"] == "RED" for row in extracted["candles"]))
    check("green means bullish/Buy candle evidence", any(row["color"] == "GREEN" for row in extracted["candles"]))
    check("candle assessment returns a direction for readable candle input", analysis.get("direction") in ("BUY", "SELL"))
    online = {"available": False, "bias": 0.0, "direction": "UNAVAILABLE"}
    combined = combine_assessments(analysis, online, None)
    check("combined signal selects BUY or SELL without a no-signal label", combined.get("direction") in ("BUY", "SELL"))
    proxy_test = combine_assessments(analysis, {
        "available": True, "market_data_fresh_for_live_context": True,
        "fixed_expiry_forecast": {"reference_data_fresh": True, "bias": -1.0},
        "news_bias": -0.8, "headline_count": 5,
        "technical_indicators": {"available": True, "bias": -0.9, "volume_available": False},
        "source_reliability_scores": {"synthetic-test-source": 1.0},
    }, {"available": True, "bias": 0.2, "direction": "BUY", "confidence": 60})
    check("public Bitcoin proxy cannot exceed the configured pre-adaptive 12 percent cap", proxy_test.get("weights", {}).get("online", 1.0) <= 0.120001)
    check("each combined screenshot forecast reports a component-use audit", isinstance(proxy_test.get("analysis_execution_audit"), dict) and "five_minute_outcome_calibration" in proxy_test["analysis_execution_audit"] and "latest_candle_completion" in proxy_test["analysis_execution_audit"])
    local_rate_test = _current_screenshot_walk_forward_rates(many_detected, query_strength=0.15, image_height=480)
    check("five-minute probability estimator uses only rolling prefixes from the current screenshot", local_rate_test.get("available") and local_rate_test.get("uses_previous_screenshot_outcomes") is False and local_rate_test.get("walk_forward_samples", 0) >= 20)
    check("M1 screenshot walk-forward measures close-to-close direction five candles ahead", local_rate_test.get("forecast_horizon_bars") == 5 and "five contiguous M1 candles" in local_rate_test.get("target_definition", ""))
    check("current screenshot probability estimator reports direction-specific rates and confidence intervals", all((local_rate_test.get("direction_rates") or {}).get(d, {}).get("sample_count", 0) >= 0 for d in ("BUY", "SELL")) and "selected_strength_bin" in local_rate_test)
    check("five-minute walk-forward outcomes use non-overlapping five-bar targets", local_rate_test.get("non_overlapping_target_windows") is True and local_rate_test.get("walk_forward_origin_step_bars") == 5)
    conflict_combined = combine_assessments(analysis, online, None, None, 480, visual_indicators={"available": True, "sample_count": 80, "directional_bias": -0.95})
    check("strong opposing visual-indicator evidence is recorded as risk rather than an indefinite alert block", conflict_combined.get("signal_ready") is True and any("oppose" in str(note).lower() or "disagreement" in str(note).lower() for note in conflict_combined.get("analysis_risk_notes", [])))
    check("V10 keeps the score visible when visual indicators oppose the screenshot structure", conflict_combined.get("signal_ready") is True and float(conflict_combined.get("selected_direction_score_percent", 0.0)) >= ALERT_SIGNAL_THRESHOLD_PERCENT and not any("strong candle-structure vs indicator disagreement" in str(reason) for reason in conflict_combined.get("trigger_block_reasons", [])))
    check("alert threshold is configured at 65 percent", ALERT_SIGNAL_THRESHOLD_PERCENT == 65.0)
    check("V14 score is not artificially floored at 65 and remains a non-calibrated evidence score", 50 <= combined["selected_direction_score_percent"] <= 95 and combined.get("forecast_probability_estimate_is_five_minute_direction_probability_estimate") is False and combined.get("forecast_probability_estimate_is_heuristic_model_estimate") is True and combined.get("v10_raw_heuristic_probability_estimate_percent") is not None and "not a calibrated" in combined.get("score_semantics", ""))
    check("BUY and SELL five-minute direction estimates are complementary and total 100 percent", combined.get("buy_outcome_probability_percent") is not None and combined.get("sell_outcome_probability_percent") is not None and abs(float(combined.get("buy_outcome_probability_percent", 0.0)) + float(combined.get("sell_outcome_probability_percent", 0.0)) - 100.0) < 0.11 and combined.get("formal_broker_payout_probability_calibrated") is False)
    check("V10 raw heuristic estimate uses only the current screenshot and cycle context, without prior screenshot outcomes", "No empirical win-probability claim is made" in combined.get("forecast_probability_estimate_basis", "") and combined.get("forecast_probability_estimate_is_five_minute_success_estimate") is False and combined.get("production_pipeline_holdout", {}).get("used_for_live_score") is False and combined.get("v10_raw_heuristic_probability_estimate_percent") is not None)
    check("forecast expiry is always fixed at 5 minutes", combined["forecast_horizon_minutes"] == FIXED_EXPIRY_MINUTES and combined.get("fixed_expiry_minutes") == FIXED_EXPIRY_MINUTES)
    check("one five-minute forecast object is retained", isinstance(combined.get("fixed_expiry_forecast"), dict) and combined["fixed_expiry_forecast"].get("horizon_minutes") == FIXED_EXPIRY_MINUTES and "horizon_forecasts" not in combined)
    check("fixed-expiry model and history are present", combined.get("fixed_expiry_model", {}).get("horizon_minutes") == FIXED_EXPIRY_MINUTES and "historical_performance" in combined)
    check("analysis ablation report is included without changing fixed live weights", "analysis_ablation_backtest" in combined and (combined.get("analysis_ablation_backtest") or {}).get("live_weights_changed") is False)
    check("pattern validation is for the single fixed expiry", list(combined.get("pattern_historical_performance_by_fixed_expiry", {}).keys()) == ["5"])
