def _correlation_at_lag(values: np.ndarray, lag: int) -> float:
    signal = np.asarray(values, dtype=np.float64).reshape(-1)
    if lag < 1 or len(signal) <= lag + 2:
        return -1.0
    left = signal[:-lag]
    right = signal[lag:]
    left = left - float(np.mean(left))
    right = right - float(np.mean(right))
    denominator = float(np.linalg.norm(left) * np.linalg.norm(right))
    if denominator <= 1e-12:
        return -1.0
    value = float(np.dot(left, right) / denominator)
    return value if math.isfinite(value) else -1.0


def _apply_pitch_geometry_guard(
    selected_pitch: int,
    scores: Dict[int, float],
    median_colored_run_width: float,
) -> Dict[str, Any]:
    """Reject a grossly oversized pitch when raw colored runs show finer candle strokes."""
    pitch = int(selected_pitch)
    median_width = float(median_colored_run_width or 0.0)
    report: Dict[str, Any] = {
        "selected_pitch_before_guard": pitch,
        "selected_pitch_after_guard": pitch,
        "median_colored_run_width_pixels": round(median_width, 3),
        "geometry_guard_applied": False,
        "geometry_guard_candidate_pitch_pixels": None,
        "geometry_guard_candidate_correlation": None,
    }
    if median_width <= 0.0 or pitch <= median_width * 4.0:
        return report

    low = max(3, int(math.floor(median_width * 0.65)))
    high = min(40, int(math.ceil(median_width * 4.0)))
    plausible = {
        int(lag): float(score) for lag, score in scores.items()
        if low <= int(lag) <= high and math.isfinite(float(score))
    }
    if not plausible:
        return report
    best_score = max(plausible.values())
    if best_score < 0.08:
        return report
    tolerance = max(0.025, abs(best_score) * 0.025)
    near_best = [lag for lag, score in plausible.items() if score >= best_score - tolerance]
    candidate = min(near_best) if near_best else max(plausible, key=plausible.get)
    report["geometry_guard_candidate_pitch_pixels"] = int(candidate)
    report["geometry_guard_candidate_correlation"] = round(float(plausible[candidate]), 4)
    if candidate < pitch:
        report["selected_pitch_after_guard"] = int(candidate)
        report["geometry_guard_applied"] = True
    return report


def _median_colored_run_width(mask: np.ndarray) -> float:
    """Estimate typical occupied horizontal stroke width while ignoring long overlays."""
    if not isinstance(mask, np.ndarray) or mask.size == 0:
        return 0.0
    active = np.any(mask > 0, axis=0)
    positions = np.flatnonzero(active)
    if positions.size == 0:
        return 0.0
    starts = [int(positions[0])]
    ends: List[int] = []
    previous = int(positions[0])
    for value in positions[1:]:
        value = int(value)
        if value > previous + 1:
            ends.append(previous + 1)
            starts.append(value)
        previous = value
    ends.append(previous + 1)
    max_useful_width = max(3, int(round(mask.shape[1] * 0.08)))
    widths = [end - start for start, end in zip(starts, ends)
              if 1 <= end - start <= max_useful_width]
    return float(np.median(widths)) if widths else 0.0


def _estimate_spectral_candle_pitch(combined_mask: np.ndarray) -> Dict[str, Any]:
    """Estimate candle spacing from the dominant spatial frequency of column pixel energy."""
    if not isinstance(combined_mask, np.ndarray) or combined_mask.ndim != 2 or combined_mask.size == 0:
        return {"available": False, "reason": "invalid color mask"}
    energy = np.count_nonzero(combined_mask, axis=0).astype(np.float64)
    width = int(energy.size)
    if width < 64 or float(np.std(energy)) < 1e-6:
        return {"available": False, "reason": "not enough varying column-energy data"}
    signal = (energy - float(np.mean(energy))) * np.hanning(width)
    power = np.abs(np.fft.rfft(signal)) ** 2
    frequencies = np.fft.rfftfreq(width)
    periods = np.full(frequencies.shape, np.inf, dtype=np.float64)
    periods[1:] = 1.0 / frequencies[1:]
    max_period = min(40.0, float(width) / 3.0)
    eligible = [i for i in range(1, len(power) - 1)
                if 3.0 <= periods[i] <= max_period
                and power[i] >= power[i - 1] and power[i] >= power[i + 1]]
    if not eligible:
        return {"available": False, "reason": "no spectral peak inside the supported spacing range"}
    peaks = sorted(eligible, key=lambda i: float(power[i]), reverse=True)
    best_i = int(peaks[0])
    best_power = float(power[best_i])
    second_power = float(power[peaks[1]]) if len(peaks) > 1 else 0.0
    ratio = best_power / max(second_power, 1e-12)

    # Parabolic interpolation in log power gives sub-pixel spacing for scaled crops
    # whose candle pitch is fractional (for example, 4.5 pixels after a 0.75x resize).
    left_power = math.log(max(1e-12, float(power[best_i - 1])))
    center_power = math.log(max(1e-12, best_power))
    right_power = math.log(max(1e-12, float(power[best_i + 1])))
    denominator = left_power - 2.0 * center_power + right_power
    delta = 0.0 if abs(denominator) < 1e-12 else 0.5 * (left_power - right_power) / denominator
    delta = float(clamp(delta, -0.5, 0.5))
    refined_frequency = (float(best_i) + delta) / float(width)
    pitch = 1.0 / refined_frequency if refined_frequency > 0 else float(periods[best_i])
    # Snap values that are essentially integer to avoid needless drift on native images.
    nearest_integer = round(pitch)
    if abs(pitch - nearest_integer) <= 0.12:
        pitch = float(nearest_integer)
    return {
        "available": True,
        "pitch_pixels": round(float(pitch), 3),
        "peak_period_pixels": round(float(periods[best_i]), 3),
        "peak_power": round(best_power, 3),
        "second_peak_power": round(second_power, 3),
        "peak_to_second_ratio": round(float(ratio), 4),
        "confident": bool(ratio >= 1.35),
        "peak_count": int(len(peaks)),
        "method": "hann_windowed_column_energy_fft_with_log_parabolic_interpolation",
    }


def _select_candle_pitch(red_mask: np.ndarray, green_mask: np.ndarray) -> Dict[str, Any]:
    """Estimate the repeated horizontal candle pitch using independent pixel signals."""
    combined = cv2.bitwise_or(red_mask, green_mask)
    occupied = np.any(combined > 0, axis=0).astype(np.float64)
    energy = np.count_nonzero(combined, axis=0).astype(np.float64)
    width = int(occupied.size)
    max_lag = min(40, max(12, width // 8))
    max_lag = min(max_lag, max(3, width // 4))
    lags = list(range(3, max_lag + 1))
    binary_scores = {lag: _correlation_at_lag(occupied, lag) for lag in lags}
    energy_scores = {lag: _correlation_at_lag(energy, lag) for lag in lags}
    binary_lag = max(lags, key=lambda lag: binary_scores[lag]) if lags else 0
    energy_lag = max(lags, key=lambda lag: energy_scores[lag]) if lags else 0
    binary_best = binary_scores.get(binary_lag, -1.0)
    energy_best = energy_scores.get(energy_lag, -1.0)

    # Binary occupancy is the more reliable signal when there is a visible gap between
    # adjacent candle bodies. Filled/connected overlays can erase those gaps; in that case
    # the per-column pixel-energy signal usually preserves the actual candle pitch.
    if energy_best > binary_best + 0.05:
        source, scores, best_lag, best_score = "column_energy_autocorrelation", energy_scores, energy_lag, energy_best
    else:
        source, scores, best_lag, best_score = "column_occupancy_autocorrelation", binary_scores, binary_lag, binary_best
    if best_lag and best_score > 0.08:
        near_best = [lag for lag, score in scores.items()
                     if score >= best_score - max(0.025, abs(best_score) * 0.025)]
        pitch = int(min(near_best)) if near_best else int(best_lag)
    else:
        components = _merge_candle_parts(_components(red_mask, "RED") + _components(green_mask, "GREEN"))
        centers = sorted({round(float(row.get("center_x", 0.0)), 2) for row in components})
        gaps = np.diff(centers) if len(centers) > 1 else np.asarray([], dtype=np.float64)
        gaps = gaps[(gaps >= 3.0) & (gaps <= 40.0)] if gaps.size else gaps
        pitch = int(round(float(np.median(gaps)))) if gaps.size else max(3, int(round(width / 150.0)))
        source = "component_spacing_fallback"
        best_score = max(0.0, float(best_score))
    pitch_before_geometry_guard = int(pitch)
    median_run_width = _median_colored_run_width(combined)
    geometry_guard = _apply_pitch_geometry_guard(pitch, scores, median_run_width)
    pitch = float(geometry_guard["selected_pitch_after_guard"])
    if geometry_guard["geometry_guard_applied"]:
        source = str(source) + "_colored_run_geometry_guard"
        best_score = float(scores.get(int(round(pitch)), best_score))

    spectral_report = _estimate_spectral_candle_pitch(combined)
    # A clearly dominant FFT period is especially helpful when resized strokes nearly
    # touch: short-lag autocorrelation then mistakes body width for candle-to-candle pitch.
    # The spectral path only selects spacing; all per-slot body/wick and color reading
    # remains the same downstream routine.
    if spectral_report.get("available") and spectral_report.get("confident"):
        spectral_pitch = parse_float(spectral_report.get("pitch_pixels"), None)
        if spectral_pitch is not None and 3.0 <= spectral_pitch <= 40.0:
            pitch = float(spectral_pitch)
            source = str(source) + "_fft_spectral_pitch"
            nearby = [float(scores[k]) for k in (int(math.floor(pitch)), int(math.ceil(pitch))) if k in scores]
            if nearby:
                best_score = max(nearby)
    pitch = float(max(3.0, min(40.0, pitch)))
    return {
        "pitch_pixels": round(float(pitch), 3),
        "confidence_correlation": round(float(max(0.0, best_score)), 4),
        "source": source,
        "pitch_before_geometry_guard_pixels": int(pitch_before_geometry_guard),
        "median_colored_run_width_pixels": round(float(median_run_width), 3),
        "pitch_geometry_guard_applied": bool(geometry_guard["geometry_guard_applied"]),
        "pitch_geometry_guard_candidate_pixels": geometry_guard["geometry_guard_candidate_pitch_pixels"],
        "spectral_pitch_estimation": spectral_report,
        "binary_best_lag": int(binary_lag),
        "binary_best_correlation": round(float(binary_best), 4),
        "energy_best_lag": int(energy_lag),
        "energy_best_correlation": round(float(energy_best), 4),
        "all_lag_correlations": {str(lag): round(float(scores[lag]), 4) for lag in sorted(scores)},
    }


def _estimate_candle_grid_phase(red_mask: np.ndarray, green_mask: np.ndarray,
                                pitch_pixels: int) -> Dict[str, Any]:
    """Estimate candle-center phase from run centers; fall back to center-energy scoring."""
    combined = cv2.bitwise_or(red_mask, green_mask)
    active = np.any(combined > 0, axis=0)
    width = int(active.size)
    starts = np.flatnonzero(active & ~np.r_[False, active[:-1]])
    ends = np.flatnonzero(active & ~np.r_[active[1:], False]) + 1
    run_residues: List[int] = []
    run_centers: List[float] = []
    for start, end in zip(starts, ends):
        run_width = int(end - start)
        if run_width < 1 or run_width > int(math.ceil(pitch_pixels * 1.45)):
            continue
        center = float(start) + (min(run_width, pitch_pixels) - 1.0) / 2.0
        run_centers.append(center)
        run_residues.append(int(round(center)) % pitch_pixels)
    residue_counts = Counter(run_residues)
    phase = None
    method = "centered_occupied_column_runs"
    dominance = 0.0
    if residue_counts:
        residue, occurrences = residue_counts.most_common(1)[0]
        dominance = occurrences / max(1.0, float(len(run_residues)))
        if len(run_residues) >= 3 and occurrences >= max(3, int(math.ceil(len(run_residues) * 0.20))):
            phase = float(residue)
    if phase is None:
        energy = np.count_nonzero(combined, axis=0).astype(np.float64)
        smoothed = np.convolve(energy, np.asarray([0.25, 0.5, 0.25]), mode="same") if width > 2 else energy
        candidates = []
        for candidate_phase in np.arange(0.0, float(pitch_pixels), 0.25):
            centers = np.arange(candidate_phase, float(width), float(pitch_pixels))
            score = 0.0
            for center in centers:
                center_x = int(round(center))
                if 0 <= center_x < width:
                    score += float(smoothed[center_x])
                    if center_x > 0:
                        score += 0.35 * float(smoothed[center_x - 1])
                    if center_x + 1 < width:
                        score += 0.35 * float(smoothed[center_x + 1])
                    midpoint = int(round(center + pitch_pixels / 2.0))
                    if 0 <= midpoint < width:
                        score -= 0.25 * float(smoothed[midpoint])
            candidates.append((score, float(candidate_phase)))
        phase = max(candidates, key=lambda item: item[0])[1] if candidates else 0.0
        method = "center_energy_phase_fallback"
    return {
        "phase_pixels_mod_pitch": round(float(phase), 3),
        "phase_method": method,
        "run_centers_used": int(len(run_centers)),
        "most_common_phase_support_percent": round(100.0 * float(dominance), 2),
        "run_phase_distribution": {str(key): int(value) for key, value in residue_counts.most_common(12)},
    }


def _crop_obvious_full_broker_ui(image: np.ndarray) -> Tuple[np.ndarray, Dict[str, Any]]:
    """Crop surrounding broker controls only when wide colored order buttons prove it is a full UI."""
    height, width = image.shape[:2]
    full_meta = {
        "x": 0, "y": 0, "width": int(width), "height": int(height),
        "source": "USER_DRAG_CROP_USED_AS_RECEIVED", "confidence": 0.95,
        "reason": "No separate wide broker control buttons were detected outside the chart; no extra crop applied.",
    }
    if width < 500 or height < 250:
        return image, full_meta
    red_mask, green_mask = create_color_masks(image)
    control_left_edges: List[int] = []
    min_button_width = max(80, int(round(width * 0.075)))
    min_button_height = max(20, int(round(height * 0.035)))
    for mask in (red_mask, green_mask):
        count, _labels, stats, _centers = cv2.connectedComponentsWithStats(mask, connectivity=8)
        for component_id in range(1, count):
            x, y, w, h, area = [int(value) for value in stats[component_id]]
            if (x >= int(width * 0.66) and y >= int(height * 0.22)
                    and y <= int(height * 0.72) and w >= min_button_width
                    and h >= min_button_height and area >= int(w * h * 0.18)):
                control_left_edges.append(x)
    if not control_left_edges:
        return image, full_meta

    # The rightmost order panel starts after the chart. Ratios are used only after the
    # actual broad BUY/SELL-style controls were found, not on a user-selected chart crop.
    controls_left = min(control_left_edges)
    x2 = int(round(controls_left - width * 0.048))
    x1 = int(round(width * 0.066))
    x1 = max(0, min(x1, width - 2))
    x2 = max(x1 + int(width * 0.30), min(width, x2))
    if x2 - x1 < int(width * 0.35):
        return image, full_meta

    region_mask = cv2.bitwise_or(red_mask[:, x1:x2], green_mask[:, x1:x2])
    # The top of a full broker screenshot contains colored toolbar text and icons that
    # share candle colors. Restrict row-bound discovery to the central/lower plot band,
    # then use dense rows rather than isolated colored text to find the chart's vertical
    # candle envelope. These ratios are only used after broad order buttons proved this
    # is a full broker screen; a user-dragged crop bypasses this auto-crop entirely.
    y_search_start = int(round(height * 0.15))
    y_search_end = max(y_search_start + 1, int(round(height * 0.95)))
    row_counts = np.count_nonzero(region_mask[y_search_start:y_search_end], axis=1)
    row_threshold = max(10, int(round((x2 - x1) * 0.01)))
    dense_rows = np.flatnonzero(row_counts >= row_threshold)
    if dense_rows.size >= 3:
        y_pad = max(5, int(round(height * 0.02)))
        y1 = max(y_search_start, y_search_start + int(dense_rows[0]) - y_pad)
        y2 = min(y_search_end, y_search_start + int(dense_rows[-1]) + 1 + y_pad)
    else:
        y1, y2 = int(round(height * 0.20)), int(round(height * 0.93))
    if y2 - y1 < int(height * 0.30):
        return image, full_meta
    roi = image[y1:y2, x1:x2].copy()
    meta = {
        "x": int(x1), "y": int(y1), "width": int(roi.shape[1]), "height": int(roi.shape[0]),
        "source": "AUTO_CROP_MAIN_CHART_PANE_FROM_FULL_BROKER_SCREEN",
        "confidence": 0.91,
        "wide_order_controls_detected_at_x": sorted(set(control_left_edges)),
        "control_panel_left_x": int(controls_left),
        "all_horizontal_candle_slots_inside_chart_pane_retained": True,
    }
    return roi, meta


def _detect_order_badge_regions(image: Optional[np.ndarray]) -> List[Dict[str, int]]:
    """Detect the small saturated orange trade/price badge without confusing it with candles."""
    if not isinstance(image, np.ndarray) or image.size == 0 or image.ndim < 2:
        return []
    height, width = image.shape[:2]
    if width < 300 or height < 160:
        return []
    hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
    orange = cv2.inRange(
        hsv, np.array([2, 145, 100], dtype=np.uint8),
        np.array([10, 255, 255], dtype=np.uint8),
    )
    # In a chart screenshot, a broker badge is usually in the upper-right. Restrict
    # the search so orange/brown candles elsewhere are not labelled as an overlay.
    x_min = int(round(width * 0.72))
    y_max = int(round(height * 0.36))
    search = np.zeros_like(orange)
    search[:y_max, x_min:] = orange[:y_max, x_min:]
    count, _labels, stats, _centers = cv2.connectedComponentsWithStats(search, connectivity=8)
    pieces: List[Dict[str, int]] = []
    for component_id in range(1, count):
        x, y, w, h, area = [int(value) for value in stats[component_id]]
        if (x < x_min or y >= y_max or w < max(18, int(round(width * 0.022)))
                or h < max(8, int(round(height * 0.014))) or area < 100):
            continue
        pieces.append({"x1": x, "y1": y, "x2": x + w, "y2": y + h})
    if not pieces:
        return []

    # Join the badge's top and bottom orange strips and its little arrow/edge when
    # they are adjacent. Do not expand the mask across the whole connected candle group.
    pieces.sort(key=lambda row: (row["y1"], row["x1"]))
    groups: List[Dict[str, int]] = []
    for piece in pieces:
        merged = False
        for group in groups:
            x_gap = max(0, max(group["x1"], piece["x1"]) - min(group["x2"], piece["x2"]))
            vertical_gap = max(0, max(group["y1"], piece["y1"]) - min(group["y2"], piece["y2"]))
            horizontal_overlap = max(0, min(group["x2"], piece["x2"]) - max(group["x1"], piece["x1"]))
            min_width = max(1, min(group["x2"] - group["x1"], piece["x2"] - piece["x1"]))
            joins = (vertical_gap <= 3 and (horizontal_overlap >= 0.40 * min_width or x_gap <= 3))
            if joins:
                group["x1"] = min(group["x1"], piece["x1"])
                group["y1"] = min(group["y1"], piece["y1"])
                group["x2"] = max(group["x2"], piece["x2"])
                group["y2"] = max(group["y2"], piece["y2"])
                merged = True
                break
        if not merged:
            groups.append(dict(piece))

    regions: List[Dict[str, int]] = []
    for group in groups:
        w = group["x2"] - group["x1"]
        h = group["y2"] - group["y1"]
        if w >= max(22, int(round(width * 0.025))) and h >= max(15, int(round(height * 0.025))):
            pad = 1
            x1 = max(0, group["x1"] - pad)
            y1 = max(0, group["y1"] - pad)
            x2 = min(width, group["x2"] + pad)
            y2 = min(height, group["y2"] + pad)
            regions.append({"x": int(x1), "y": int(y1), "width": int(x2 - x1), "height": int(y2 - y1)})
    return regions


def _remove_overlay_and_non_candle_artifacts(red_mask: np.ndarray, green_mask: np.ndarray,
                                              pitch_pixels: int,
                                              image: Optional[np.ndarray] = None) -> Dict[str, Any]:
    """Mask detected broker badges precisely and preserve candle pixels around them."""
    height, width = red_mask.shape[:2]
    badge_regions = _detect_order_badge_regions(image)
    removed_overlay_components = 0
    removed_thin_streak_components = 0
    broad_fallback_components = 0

    for mask in (red_mask, green_mask):
        count, labels, stats, _centers = cv2.connectedComponentsWithStats(mask, connectivity=8)
        to_remove: List[int] = []
        for component_id in range(1, count):
            x, y, w, h, area = [int(value) for value in stats[component_id]]
            overlay_like = (
                x >= int(width * 0.80) and y <= int(height * 0.24)
                and w >= max(24, int(round(width * 0.045)))
                and h >= max(16, int(round(height * 0.035)))
                and area >= int(w * h * 0.18)
            )
            overlaps_precise_badge = any(
                x < region["x"] + region["width"] and x + w > region["x"]
                and y < region["y"] + region["height"] and y + h > region["y"]
                for region in badge_regions
            )
            # The former bounding-box removal could erase many real candle wicks/body
            # pixels when an orange badge touched a red candle. Use it only as fallback.
            if overlay_like and not (badge_regions and overlaps_precise_badge):
                to_remove.append(component_id)
        for component_id in to_remove:
            mask[labels == component_id] = 0
            removed_overlay_components += 1
            broad_fallback_components += 1

    before_badge_pixels = int(cv2.countNonZero(red_mask)) + int(cv2.countNonZero(green_mask))
    for region in badge_regions:
        x1 = max(0, int(region["x"]))
        y1 = max(0, int(region["y"]))
        x2 = min(width, x1 + int(region["width"]))
        y2 = min(height, y1 + int(region["height"]))
        red_mask[y1:y2, x1:x2] = 0
        green_mask[y1:y2, x1:x2] = 0
    after_badge_pixels = int(cv2.countNonZero(red_mask)) + int(cv2.countNonZero(green_mask))

    # Reject only isolated 1–2 pixel streaks spanning much of the chart height.
    for mask in (red_mask, green_mask):
        count, labels, stats, _centers = cv2.connectedComponentsWithStats(mask, connectivity=8)
        to_remove = []
        for component_id in range(1, count):
            x, y, w, h, area = [int(value) for value in stats[component_id]]
            if (h > height * 0.48 and w <= 2 and h / max(1.0, float(w)) > 40.0
                    and area >= int(h * 0.45)):
                to_remove.append(component_id)
        for component_id in to_remove:
            mask[labels == component_id] = 0
            removed_thin_streak_components += 1

    return {
        "removed_wide_overlay_components": int(removed_overlay_components),
        "fallback_broad_overlay_components_removed": int(broad_fallback_components),
        "removed_isolated_thin_streak_components": int(removed_thin_streak_components),
        "order_badge_regions_masked": badge_regions,
        "pixels_removed_by_precise_badge_mask": max(0, before_badge_pixels - after_badge_pixels),
        "method": "precise orange badge rectangle masking where detected; connected-component bbox fallback otherwise; candle pixels outside the actual badge are retained",
    }


def _crop_right_price_axis_for_candle_count(image: np.ndarray) -> Tuple[np.ndarray, Dict[str, Any]]:
    """Exclude a clearly detected vertical price-axis divider from the candle-count ROI."""
    height, width = image.shape[:2]
    metadata: Dict[str, Any] = {
        "detected": False, "source": "NO_CONFIDENT_RIGHT_AXIS_DIVIDER",
        "original_width": int(width), "plot_width": int(width),
        "crop_right_axis_labels": False,
    }
    if width < 500 or height < 250:
        return image, metadata
    start_x = max(1, int(round(width * 0.78)))
    stop_x = min(width - 2, int(round(width * 0.985)))
    best: Optional[Tuple[float, int, float, float]] = None
    for x in range(start_x, stop_x):
        column = image[:, x, :]
        _unique, counts = np.unique(column, axis=0, return_counts=True)
        dominant = float(counts.max()) / max(1.0, float(height))
        # Anti-aliased/resized screenshots can dilute the divider's single-pixel
        # uniformity. The strong neighboring-color contrast and right-edge location
        # below provide the second check, so a softer divider can still be retained.
        if dominant < 0.25:
            continue
        line_color = np.median(column.astype(np.float64), axis=0)
        left_start, left_end = max(0, x - 7), max(0, x - 2)
        right_start, right_end = min(width, x + 2), min(width, x + 7)
        if left_end <= left_start or right_end <= right_start:
            continue
        left_color = np.median(image[:, left_start:left_end, :].reshape(-1, 3).astype(np.float64), axis=0)
        right_color = np.median(image[:, right_start:right_end, :].reshape(-1, 3).astype(np.float64), axis=0)
        contrast_left = float(np.linalg.norm(line_color - left_color))
        contrast_right = float(np.linalg.norm(line_color - right_color))
        contrast = min(contrast_left, contrast_right)
        if contrast < 24.0:
            continue
        score = dominant * contrast
        if best is None or score > best[0]:
            best = (score, int(x), dominant, contrast)
    if best is None:
        return image, metadata
    _score, boundary_x, dominant, contrast = best
    if boundary_x < int(round(width * 0.80)) or width - boundary_x < max(8, int(round(width * 0.015))):
        return image, metadata
    # Keep a small inside-the-plot safety margin so a candle slot centered directly
    # against the divider is not fabricated from the divider/badge edge itself.
    edge_buffer = max(2, int(round(width * 0.003)))
    plot_end = max(2, boundary_x - edge_buffer)
    plot = image[:, :plot_end].copy()
    metadata = {
        "detected": True,
        "source": "HIGH_UNIFORMITY_VERTICAL_RIGHT_PRICE_AXIS_DIVIDER",
        "boundary_x_exclusive": int(boundary_x),
        "axis_edge_buffer_pixels": int(edge_buffer),
        "boundary_dominant_pixel_fraction": round(float(dominant), 4),
        "boundary_neighbor_color_contrast": round(float(contrast), 2),
        "original_width": int(width), "plot_width": int(plot.shape[1]),
        "crop_right_axis_labels": True,
    }
    return plot, metadata

def detect_chart_region(image: np.ndarray) -> Tuple[np.ndarray, Dict[str, Any]]:
    """Keep user drag crops intact and isolate the plot when a full broker UI is detected."""
    if not isinstance(image, np.ndarray) or image.ndim < 2 or image.size == 0:
        raise ValueError("Invalid image passed to chart-region detection.")
    crop, meta = _crop_obvious_full_broker_ui(image)
    if meta.get("source") == "AUTO_CROP_MAIN_CHART_PANE_FROM_FULL_BROKER_SCREEN":
        crop = crop.copy()
        height, width = crop.shape[:2]
        red_mask, green_mask = create_color_masks(crop)
        # The chart's small top-left drawing-tool icon can overlap two candle slots
        # horizontally but is not price data. Remove only its colored pixels; genuine
        # candlestick pixels start much lower in this leftmost part of the displayed chart.
        zone_h = min(height, max(32, int(round(height * 0.075))))
        zone_w = min(width, max(48, int(round(width * 0.07))))
        artifact_pixels = cv2.bitwise_or(red_mask[:zone_h, :zone_w], green_mask[:zone_h, :zone_w])
        removed_toolbar_pixels = int(cv2.countNonZero(artifact_pixels))
        crop[:zone_h, :zone_w][artifact_pixels > 0] = (45, 45, 45)
        meta["removed_top_left_non_candle_toolbar_pixels"] = removed_toolbar_pixels
    return crop, meta


def _build_candles_from_slot_grid(image: np.ndarray) -> Dict[str, Any]:
    """Read one candle per repeated chart slot rather than merging touching color components."""
    red_mask, green_mask = create_color_masks(image)
    pitch_report = _select_candle_pitch(red_mask, green_mask)
    pitch = float(pitch_report.get("pitch_pixels") or 0.0)
    artifact_report = _remove_overlay_and_non_candle_artifacts(red_mask, green_mask, pitch, image=image)

    # Removing an overlay may improve the column signal; keep the strongest stable pitch
    # from before removal unless the cleaned image clearly supports a better one.
    cleaned_pitch_report = _select_candle_pitch(red_mask, green_mask)
    if (cleaned_pitch_report.get("confidence_correlation", 0.0) >=
            float(pitch_report.get("confidence_correlation", 0.0)) + 0.04):
        pitch_report = cleaned_pitch_report
        pitch = float(pitch_report.get("pitch_pixels") or pitch)
    phase_report = _estimate_candle_grid_phase(red_mask, green_mask, pitch)
    phase = float(phase_report.get("phase_pixels_mod_pitch") or 0.0) % max(1, pitch)
    height, width = image.shape[:2]
    centers = np.arange(phase, float(width), float(pitch))
    radius = max(1, min(4, int(round(pitch * 0.30))))
    max_scatter_span = max(10, int(round(height * 0.34)))
    min_pixel_evidence = max(3, int(round(pitch * 0.55)))
    candles: List[Dict[str, Any]] = []
    skipped_low_evidence: List[int] = []
    skipped_scattered_artifacts: List[int] = []
    candlestick_evidence: List[Dict[str, Any]] = []

    for candidate_index, center in enumerate(centers, start=1):
        center_x = int(round(float(center)))
        left = max(0, center_x - radius)
        right = min(width, center_x + radius + 1)
        if right <= left:
            skipped_low_evidence.append(int(candidate_index))
            continue
        red_profile = np.count_nonzero(red_mask[:, left:right], axis=1).astype(np.float64)
        green_profile = np.count_nonzero(green_mask[:, left:right], axis=1).astype(np.float64)
        combined_profile = red_profile + green_profile
        active_rows = np.flatnonzero(combined_profile > 0)
        if active_rows.size == 0:
            skipped_low_evidence.append(int(candidate_index))
            continue

        # Choose the strongest vertically coherent pixel group. This prevents a small
        # toolbar glyph or quote label high above a real candle from making its full
        # vertical span look like a scattered artifact (the source of skipped candles).
        max_row_gap = max(2, min(5, int(round(pitch * 0.70))))
        row_groups: List[List[int]] = []
        group: List[int] = [int(active_rows[0])]
        for row_y in active_rows[1:]:
            row_y = int(row_y)
            if row_y - group[-1] <= max_row_gap:
                group.append(row_y)
            else:
                row_groups.append(group)
                group = [row_y]
        row_groups.append(group)
        def _row_group_strength(rows_in_group: List[int]) -> Tuple[float, int, int]:
            indices = np.asarray(rows_in_group, dtype=np.int32)
            pixel_energy = float(np.sum(red_profile[indices] + green_profile[indices]))
            vertical_span = int(rows_in_group[-1] - rows_in_group[0] + 1)
            return pixel_energy, vertical_span, len(rows_in_group)
        selected_group = max(row_groups, key=_row_group_strength)
        selected_top = int(selected_group[0])
        selected_bottom = int(selected_group[-1]) + 1
        keep_rows = np.zeros(height, dtype=bool)
        keep_rows[selected_top:selected_bottom] = True
        red_profile[~keep_rows] = 0.0
        green_profile[~keep_rows] = 0.0

        red_energy = float(np.sum(red_profile ** 2))
        green_energy = float(np.sum(green_profile ** 2))
        total_pixels = float(np.sum(red_profile) + np.sum(green_profile))
        if total_pixels < min_pixel_evidence:
            skipped_low_evidence.append(int(candidate_index))
            continue
        color = "GREEN" if green_energy > red_energy else "RED"
        chosen_mask = green_mask if color == "GREEN" else red_mask
        chosen_profile = green_profile if color == "GREEN" else red_profile
        y_positions = np.flatnonzero(chosen_profile > 0)
        if y_positions.size == 0:
            skipped_low_evidence.append(int(candidate_index))
            continue
        y_top, y_bottom_exclusive = int(y_positions[0]), int(y_positions[-1]) + 1
        y_span = y_bottom_exclusive - y_top
        total_active_rows = int(np.count_nonzero((red_profile + green_profile) > 0))
        active_row_fraction = total_active_rows / max(1.0, float(y_span))
        # After remote icon pixels are excluded, keep tall, mostly contiguous genuine candles.
        if y_span > max_scatter_span and active_row_fraction < 0.42:
            skipped_scattered_artifacts.append(int(candidate_index))
            continue
        if y_span < 3:
            skipped_low_evidence.append(int(candidate_index))
            continue

        shape = _estimate_body(chosen_mask, left, y_top, right - left, y_span)
        body_top = int(clamp(shape.get("body_top", y_top), y_top, y_bottom_exclusive))
        body_bottom = int(clamp(shape.get("body_bottom", y_bottom_exclusive), body_top, y_bottom_exclusive))
        if body_bottom <= body_top:
            body_top, body_bottom = y_top, y_bottom_exclusive
        if color == "GREEN":
            open_pixel, close_pixel = body_bottom, body_top
        else:
            open_pixel, close_pixel = body_top, body_bottom
        dominance = max(red_energy, green_energy) / max(1e-9, red_energy + green_energy)
        shape_score = 0.42
        if shape.get("separated"):
            shape_score += 0.24
        if y_span >= 5:
            shape_score += 0.08
        shape_score += 0.18 * float(clamp((dominance - 0.5) / 0.5, 0.0, 1.0))
        shape_score += 0.08 * float(clamp(pitch_report.get("confidence_correlation", 0.0), 0.0, 1.0))
        box_width = int(right - left)
        candles.append({
            "index": 0,
            "x": int(left), "y": int(y_top), "width": int(box_width), "height": int(y_span),
            "center_x": float(center_x), "slot_center_x": float(center),
            "slot_pitch_pixels": round(float(pitch), 3), "color": color,
            "body_top_pixel": int(body_top), "body_bottom_pixel": int(body_bottom),
            "body_height_pixels": max(1, int(body_bottom - body_top)),
            "upper_wick_pixels": max(0, int(shape.get("upper_wick", 0))),
            "lower_wick_pixels": max(0, int(shape.get("lower_wick", 0))),
            "wick_top_pixel": int(y_top), "wick_bottom_pixel": int(y_bottom_exclusive),
            "estimated_open_pixel": int(open_pixel), "estimated_close_pixel": int(close_pixel),
            "estimated_high_pixel": int(y_top), "estimated_low_pixel": int(y_bottom_exclusive),
            "body_wick_separation_estimated": bool(shape.get("separated", False)),
            "ohlc_status": "IMAGE PIXEL ESTIMATE, NOT VERIFIED MARKET PRICE",
            "detector": "HORIZONTAL_CANDLE_PITCH_GRID",
            "color_evidence_dominance_percent": round(100.0 * dominance, 2),
            "pixel_evidence_count": int(total_pixels),
            "visible_row_coverage_percent": round(100.0 * active_row_fraction, 2),
            "reading_confidence_percent": round(100.0 * clamp(shape_score, 0.05, 0.98), 1),
        })
        candlestick_evidence.append({
            "slot_center_x": int(center_x), "color": color,
            "evidence_pixels": int(total_pixels), "vertical_span_pixels": int(y_span),
            "color_dominance_percent": round(100.0 * dominance, 2),
        })

    candles.sort(key=lambda row: (float(row.get("slot_center_x", row.get("x", 0))), row["color"]))
    for index, candle in enumerate(candles, start=1):
        candle["index"] = index
    reds = sum(1 for row in candles if row["color"] == "RED")
    greens = sum(1 for row in candles if row["color"] == "GREEN")
    all_color_pixels_red = int(cv2.countNonZero(red_mask))
    all_color_pixels_green = int(cv2.countNonZero(green_mask))
    confidences = [float(row.get("reading_confidence_percent", 0.0)) for row in candles]

    # Raw connected components are kept only as a diagnostic; they are not the final count.
    legacy_components = _merge_candle_parts(_components(red_mask, "RED") + _components(green_mask, "GREEN"))
    legacy_component_estimate = len(legacy_components)
    slot_total = int(len(centers))
    accepted_total = int(len(candles))
    integrity = {
        "slot_grid_detector_enabled": True,
        "slot_grid_candidate_count": slot_total,
        "final_detected_count": accepted_total,
        "detected_red_count": int(reds),
        "detected_green_count": int(greens),
        "red_plus_green_equals_total": int(reds + greens) == accepted_total,
        "slot_pitch_pixels": round(float(pitch), 3),
        "slot_pitch_confidence_correlation": float(pitch_report.get("confidence_correlation", 0.0)),
        "slot_pitch_estimation_source": str(pitch_report.get("source") or "unknown"),
        "slot_phase_pixels_mod_pitch": float(phase),
        "slot_phase_method": str(phase_report.get("phase_method") or "unknown"),
        "skipped_slots_low_or_occluded_pixel_evidence": len(skipped_low_evidence),
        "skipped_slots_scattered_artifact_pixels": len(skipped_scattered_artifacts),
        "skipped_low_evidence_candidate_indices": skipped_low_evidence[:250],
        "skipped_scattered_artifact_candidate_indices": skipped_scattered_artifacts[:250],
        "legacy_connected_component_count_diagnostic_only": int(legacy_component_estimate),
        "slot_grid_minus_legacy_component_estimate": int(accepted_total - legacy_component_estimate),
        "all_detected_candles_included": True,
        "arbitrary_candle_count_limit": None,
        "overlay_artifact_removal": artifact_report,
        "caveat": "The slot grid separates touching candles; count/color accuracy still depends on visible pixels and should be validated on labeled chart crops.",
    }
    result = {
        "candles": candles,
        "total": accepted_total,
        "red_count": int(reds),
        "green_count": int(greens),
        "red_mask_pixels": all_color_pixels_red,
        "green_mask_pixels": all_color_pixels_green,
        "red_components": int(len(_components(red_mask, "RED"))),
        "green_components": int(len(_components(green_mask, "GREEN"))),
        "primary_component_candle_estimate": int(legacy_component_estimate),
        "projection_detector_enabled": False,
        "projection_red_candidates": 0,
        "projection_green_candidates": 0,
        "projection_added_candidates": 0,
        "all_detected_candles_included": True,
        "candle_count_cap": None,
        "slot_grid": {
            "pitch_pixels": round(float(pitch), 3), "phase_pixels_mod_pitch": round(float(phase), 3),
            "candidate_slots": slot_total, "accepted_candles": accepted_total,
            "pitch_estimation": pitch_report, "phase_estimation": phase_report,
        },
        "candle_reading_confidence_percent": round(float(np.mean(confidences)), 1) if confidences else 0.0,
        "count_integrity": integrity,
        "plot_crop_shape": {"width": int(width), "height": int(height)},
        "reading_confidence_semantics": "HEURISTIC_ONLY; not measured precision/recall or a calibrated probability",
        "candle_reading_method": "one slot per inferred horizontal candle pitch; body/wick read from each slot's red/green pixel profiles",
        "slot_level_evidence": candlestick_evidence[:600],
    }
    validate_candle_geometry(result)
    return result


def build_visual_candles(image: np.ndarray) -> Dict[str, Any]:
    """Extract readable M1 candles and report the chart-slot count separately from occluded bars."""
    crop, roi = detect_chart_region(image)
    plot_crop, axis_report = _crop_right_price_axis_for_candle_count(crop)
    result = _build_candles_from_slot_grid(plot_crop)
    candles = result.get("candles") or []
    centers = [float(c.get("slot_center_x", float(c.get("x", 0)) + float(c.get("width", 1)) / 2.0)) for c in candles]
    gaps = np.diff(centers) if len(centers) > 1 else np.asarray([], dtype=np.float64)
    positive = gaps[gaps > 0] if len(gaps) else np.asarray([], dtype=np.float64)
    typical = float(np.median(positive)) if positive.size else float(result.get("slot_grid", {}).get("pitch_pixels", 0) or 0)
    possible_gaps = int(sum(g > typical * 1.65 for g in positive)) if typical > 0 else 0
    sequence_id = 0
    for i, candle in enumerate(candles):
        gap = centers[i] - centers[i - 1] if i > 0 else 0.0
        gap_ratio = gap / typical if typical > 0 and i > 0 else 1.0
        break_before = bool(i > 0 and typical > 0 and gap_ratio > 1.65)
        if break_before:
            sequence_id += 1
        candle["gap_from_previous_pixels"] = round(float(gap), 3)
        candle["gap_ratio_to_typical"] = round(float(gap_ratio), 3)
        candle["sequence_break_before"] = break_before
        candle["sequence_id"] = sequence_id

    # Estimate the consecutive visible-bar span using regular M1 slot spacing. If a
    # detected broker badge completely hides a bar, count its slot but do not invent a
    # RED/GREEN colour or feed a made-up candle into price-action analysis.
    pitch = float((result.get("slot_grid") or {}).get("pitch_pixels") or 0.0)
    phase = float((result.get("slot_grid") or {}).get("phase_pixels_mod_pitch") or 0.0)
    candidate_centers = np.arange(phase, float(plot_crop.shape[1]), float(max(1, pitch))) if pitch > 0 else np.asarray([], dtype=float)
    slot_index_by_center = {int(round(float(center))): int(index) for index, center in enumerate(candidate_centers, start=1)}
    readable_slot_indices = sorted({
        slot_index_by_center[int(round(float(c.get("slot_center_x", -999))))]
        for c in candles if int(round(float(c.get("slot_center_x", -999)))) in slot_index_by_center
    })
    badge_regions = (result.get("count_integrity") or {}).get("overlay_artifact_removal", {}).get("order_badge_regions_masked", [])
    occluded_slot_indices: List[int] = []
    if readable_slot_indices and pitch > 0:
        first_index = min(readable_slot_indices)
        last_index = max(readable_slot_indices)
        for center in candidate_centers:
            cx = int(round(float(center)))
            slot_idx = slot_index_by_center[cx]
            if slot_idx < first_index or slot_idx > last_index or slot_idx in readable_slot_indices:
                continue
            inside_badge = any(
                int(region.get("x", 0)) <= cx < int(region.get("x", 0)) + int(region.get("width", 0))
                for region in badge_regions if isinstance(region, dict)
            )
            if inside_badge:
                occluded_slot_indices.append(slot_idx)
    estimated_visible_bar_count = len(readable_slot_indices) + len(occluded_slot_indices)
    # Fill only the known badge-occluded slots in the continuous span. Do not claim blank
    # chart margins or right-axis labels are candles.
    plot_region = dict(roi)
    plot_region["candle_count_plot_roi"] = axis_report
    result["chart_region"] = plot_region
    result["right_price_axis_detection"] = axis_report
    result["readable_candle_count"] = len(candles)
    result["estimated_visible_bar_count"] = int(estimated_visible_bar_count)
    result["estimated_occluded_bar_slots"] = int(len(occluded_slot_indices))
    result["occluded_bar_slot_indices"] = occluded_slot_indices
    result["slot_grid"]["candidate_slots_inside_price_plot"] = int(len(candidate_centers))
    result["slot_grid"]["readable_bar_slots_between_first_and_last"] = int(len(readable_slot_indices))
    result["slot_grid"]["estimated_visible_bar_count_including_badge_occlusion"] = int(estimated_visible_bar_count)
    result["slot_grid"]["occluded_bar_slot_indices"] = occluded_slot_indices
    result["plot_crop_shape"] = {"width": int(plot_crop.shape[1]), "height": int(plot_crop.shape[0])}
    result["candle_reading_confidence_percent"] = round(float(np.mean([
        float(c.get("reading_confidence_percent", 0.0)) for c in candles
    ])), 1) if candles else 0.0
    result["all_detected_readable_candles_used_for_reading"] = True
    skipped_noncandle_edge_slots = int((result.get("count_integrity") or {}).get("skipped_slots_low_or_occluded_pixel_evidence", 0) or 0)
    skipped_scattered = int((result.get("count_integrity") or {}).get("skipped_slots_scattered_artifact_pixels", 0) or 0)
    result["all_visible_candles_used_for_reading"] = bool(
        len(occluded_slot_indices) == 0 and skipped_noncandle_edge_slots == 0 and skipped_scattered == 0
    )
    result["fixed_candle_count_limit"] = None
    result["possible_missing_spacing_gaps"] = possible_gaps
    result["count_integrity"].update({
        "readable_candles_all_used_for_analysis": True,
        "all_candidate_slots_have_confirmed_candles": int(result.get("total", 0) or 0) == int(result.get("slot_grid", {}).get("candidate_slots", 0) or 0),
        "primary_component_estimate": int(result.get("primary_component_candle_estimate", 0) or 0),
        "final_detected_count": int(result.get("total", 0) or 0),
        "estimated_visible_bar_count": int(estimated_visible_bar_count),
        "readable_candle_count": int(len(candles)),
        "estimated_occluded_bar_slots": int(len(occluded_slot_indices)),
        "occluded_bar_slot_indices": occluded_slot_indices,
        "right_price_axis_cropped_for_counting": bool(axis_report.get("crop_right_axis_labels")),
        "right_price_axis_boundary": axis_report.get("boundary_x_exclusive"),
        "projection_candidates_red": 0,
        "projection_candidates_green": 0,
        "projection_candidates_added": 0,
        "geometry_validation_pending": True,
        "all_horizontal_candle_slots_inside_chart_pane_retained": True,
    })
    result["shape_reading_heuristic_score_percent"] = result.get("candle_reading_confidence_percent", 0.0)
    validate_candle_geometry(result)
    result["count_integrity"]["geometry_valid_count"] = result["geometry_validation"]["geometry_valid_count"]
    result["count_integrity"]["geometry_invalid_count"] = result["geometry_validation"]["geometry_invalid_count"]
    result["count_integrity"]["geometry_validation_factor"] = result["geometry_validation"]["directional_score_factor"]
    result["count_integrity"]["geometry_validation_pending"] = False
    result["count_integrity"]["red_plus_green_equals_total"] = (
        int(result.get("red_count", 0) or 0) + int(result.get("green_count", 0) or 0) == int(result.get("total", 0) or 0)
    )
    return result

# Final entry point: silent research collection; only the final screenshot result is printed.



# -------------------------- Live chart indicators -----------------------------
def visual_technical_indicators(candle_result: Dict[str, Any]) -> Dict[str, Any]:
    """Calculate a compact, regime-aware indicator group from the currently visible candles.

    Price values may be OCR-calibrated broker-axis estimates or negative pixel-relative
    proxies. Directional calculations are normalized by ATR so both representations work;
    ROC is explicitly marked as percent or ATR units to avoid treating negative pixels as prices.
    """
    rows = list(candle_result.get("candles") or [])
    if not rows:
        return {"available": False, "sample_count": 0, "basis": "NO_READABLE_CANDLES",
                "directional_bias": 0.0, "indicator_components": {}}

    ohlc = [_candle_proxy_ohlc(row) for row in rows]
    opens = np.asarray([item[0] for item in ohlc], dtype=float)
    highs = np.asarray([item[1] for item in ohlc], dtype=float)
    lows = np.asarray([item[2] for item in ohlc], dtype=float)
    closes = np.asarray([item[3] for item in ohlc], dtype=float)
    n = len(closes)

    ema9 = _ema(closes, min(9, n))
    ema21 = _ema(closes, min(21, n))
    ema12 = _ema(closes, min(12, n))
    ema26 = _ema(closes, min(26, n))
    macd_line = ema12 - ema26
    signal_line = _ema(macd_line, min(9, n)) if n else np.asarray([], dtype=float)
    macd_hist = macd_line - signal_line if n else np.asarray([], dtype=float)

    previous_close = np.r_[closes[0], closes[:-1]]
    true_range = np.maximum(highs - lows,
                            np.maximum(np.abs(highs - previous_close), np.abs(lows - previous_close)))
    atr_series = _wilder_average(true_range, 14)
    atr = float(atr_series[-1]) if len(atr_series) else None
    atr_safe = np.maximum(atr_series, 1e-9)

    plus_dm = np.zeros(n, dtype=float)
    minus_dm = np.zeros(n, dtype=float)
    if n > 1:
        up_move = highs[1:] - highs[:-1]
        down_move = lows[:-1] - lows[1:]
        plus_dm[1:] = np.where((up_move > down_move) & (up_move > 0), up_move, 0.0)
        minus_dm[1:] = np.where((down_move > up_move) & (down_move > 0), down_move, 0.0)
    plus_di_series = 100.0 * _wilder_average(plus_dm, 14) / atr_safe
    minus_di_series = 100.0 * _wilder_average(minus_dm, 14) / atr_safe
    dx = 100.0 * np.abs(plus_di_series - minus_di_series) / np.maximum(plus_di_series + minus_di_series, 1e-9)
    adx_series = _wilder_average(dx, 14)
    plus_di = float(plus_di_series[-1]) if len(plus_di_series) else 0.0
    minus_di = float(minus_di_series[-1]) if len(minus_di_series) else 0.0
    adx = float(adx_series[-1]) if len(adx_series) else None

    lookback = min(14, n)
    lowest = float(np.min(lows[-lookback:]))
    highest = float(np.max(highs[-lookback:]))
    stoch = 50.0 if highest <= lowest else float(clamp((closes[-1] - lowest) / (highest - lowest) * 100.0, 0.0, 100.0))
    rsi = _rsi(closes, 14)

    band_n = min(20, n)
    band_closes = closes[-band_n:]
    band_mean = float(np.mean(band_closes))
    band_std = float(np.std(band_closes))
    bb_upper = band_mean + 2.0 * band_std
    bb_lower = band_mean - 2.0 * band_std
    bb_width = max(0.0, bb_upper - bb_lower)
    bb_width_pct = (bb_width / max(1e-9, abs(band_mean)) * 100.0) if abs(band_mean) > 1e-9 else 0.0
    bb_percent_b = (float(closes[-1]) - bb_lower) / bb_width if bb_width > 1e-9 else 0.5
    bb_z_score = (float(closes[-1]) - band_mean) / max(band_std, 1e-9)

    if adx is not None and adx >= 25.0:
        regime = "TRENDING"
        trend_scale = 1.0
        rsi_norm = clamp(((float(rsi) - 50.0) / 30.0) if rsi is not None else 0.0, -1.0, 1.0)
        stoch_norm = clamp((stoch - 50.0) / 45.0, -1.0, 1.0)
        bb_norm = 0.25 * clamp((bb_percent_b - 0.5) * 2.0, -1.0, 1.0)
        oscillator_mode = "trend_momentum"
    elif adx is not None and adx < 16.0:
        regime = "RANGING_OR_CHOPPY"
        trend_scale = 0.55
        rsi_norm = -0.55 * clamp(((float(rsi) - 50.0) / 35.0) if rsi is not None else 0.0, -1.0, 1.0)
        stoch_norm = -0.60 * clamp((stoch - 50.0) / 45.0, -1.0, 1.0)
        bb_norm = -0.45 * clamp((bb_percent_b - 0.5) * 2.0, -1.0, 1.0)
        oscillator_mode = "mean_reversion_damped"
    else:
        regime = "TRANSITION_OR_BREAKOUT"
        trend_scale = 0.80
        rsi_norm = 0.40 * clamp(((float(rsi) - 50.0) / 35.0) if rsi is not None else 0.0, -1.0, 1.0)
        stoch_norm = 0.30 * clamp((stoch - 50.0) / 45.0, -1.0, 1.0)
        bb_norm = 0.10 * clamp((bb_percent_b - 0.5) * 2.0, -1.0, 1.0)
        oscillator_mode = "mixed_transition"

    atr_den = max(1e-9, float(atr or 0.0))
    ema_norm = math.tanh((float(ema9[-1]) - float(ema21[-1])) / atr_den * 3.0) * trend_scale
    macd_hist_norm = math.tanh(float(macd_hist[-1]) / atr_den * 6.0) * trend_scale
    di_norm = clamp((plus_di - minus_di) / 35.0, -1.0, 1.0) * clamp(float(adx or 0.0) / 35.0, 0.0, 1.0)

    roc = {}
    for lookback_bars in (1, 3, 5):
        if n <= lookback_bars:
            continue
        prior = float(closes[-1 - lookback_bars])
        current = float(closes[-1])
        if current > 0 and prior > 0:
            roc[str(lookback_bars)] = round((current / prior - 1.0) * 100.0, 6)
        else:
            # On screen-relative negative pixel proxies, a price change is not a percent return.
            roc[str(lookback_bars)] = round((current - prior) / atr_den, 5)
    roc_unit = "PERCENT" if np.all(closes > 0) else "ATR_UNITS_PIXEL_PROXY"
    roc5_delta = float(closes[-1] - closes[max(0, n - 6)])
    roc_norm = math.tanh((roc5_delta / atr_den) * 0.70)

    indicator_components = {
        "ema9_21": float(clamp(ema_norm, -1.0, 1.0)),
        "macd_histogram": float(clamp(macd_hist_norm, -1.0, 1.0)),
        "directional_movement_di_adx": float(clamp(di_norm, -1.0, 1.0)),
        "rsi_regime_adjusted": float(clamp(rsi_norm, -1.0, 1.0)),
        "stochastic_regime_adjusted": float(clamp(stoch_norm, -1.0, 1.0)),
        "roc_5_atr_normalized": float(clamp(roc_norm, -1.0, 1.0)),
        "bollinger_position_regime_adjusted": float(clamp(bb_norm, -1.0, 1.0)),
    }
    indicator_weights = {
        "ema9_21": 0.24,
        "macd_histogram": 0.18,
        "directional_movement_di_adx": 0.18,
        "rsi_regime_adjusted": 0.13,
        "stochastic_regime_adjusted": 0.09,
        "roc_5_atr_normalized": 0.10,
        "bollinger_position_regime_adjusted": 0.08,
    }
    directional_bias = float(clamp(sum(indicator_components[k] * indicator_weights[k] for k in indicator_weights), -1.0, 1.0))
    fast_slow = float(ema9[-1] - ema21[-1]) if len(ema9) and len(ema21) else 0.0

    return {
        "available": True,
        "sample_count": n,
        "basis": "Visible candle-derived OHLC; pixel-relative proxy unless validated price-axis OCR succeeds.",
        "ema9": float(ema9[-1]) if len(ema9) else None,
        "ema21": float(ema21[-1]) if len(ema21) else None,
        "ema9_series": ema9.tolist(),
        "ema21_series": ema21.tolist(),
        "macd": float(macd_line[-1]) if len(macd_line) else None,
        "macd_signal": float(signal_line[-1]) if len(signal_line) else None,
        "macd_histogram": float(macd_hist[-1]) if len(macd_hist) else None,
        "rsi14": float(rsi) if rsi is not None else None,
        "atr14": atr,
        "adx14_estimate": adx,
        "plus_di14_estimate": plus_di,
        "minus_di14_estimate": minus_di,
        "stochastic_k14": stoch,
        "bollinger_upper": bb_upper,
        "bollinger_middle": band_mean,
        "bollinger_lower": bb_lower,
        "bollinger_percent_b": float(bb_percent_b),
        "bollinger_z_score": float(bb_z_score),
        "bollinger_width_percent": bb_width_pct,
        "ema_bias": "BULLISH" if fast_slow > 1e-9 else "BEARISH" if fast_slow < -1e-9 else "FLAT",
        "ema_spread_atr_normalized": round(float((ema9[-1] - ema21[-1]) / atr_den), 5),
        "macd_histogram_atr_normalized": round(float(macd_hist[-1] / atr_den), 5),
        "roc_percent_or_proxy": roc,
        "roc_unit": roc_unit,
        "roc_5_atr_normalized": round(float(roc_norm), 5),
        "indicator_regime": regime,
        "oscillator_mode": oscillator_mode,
        "indicator_components": {k: round(v, 5) for k, v in indicator_components.items()},
        "indicator_component_weights": indicator_weights,
        "directional_bias": round(directional_bias, 5),
        "directional_bias_method": "One weighted technical-indicator group; correlated price-derived measures are grouped to limit double counting.",
        "trend_strength": "STRONG" if adx is not None and adx >= 25 else "WEAK/MIXED",
    }

def _draw_dashed_horizontal(image: np.ndarray, y: int, color: Tuple[int, int, int], thickness: int = 1) -> None:
    height, width = image.shape[:2]
    if not 0 <= y < height:
        return
    for x in range(0, width, 18):
        cv2.line(image, (x, y), (min(width - 1, x + 9), y), color, thickness, cv2.LINE_AA)


def _five_minute_candidate_label(forecast_display: Dict[str, Any]) -> str:
    """Return the visible candidate/qualified label without conflating it with an alarm."""
    direction = str((forecast_display or {}).get("direction") or "ANALYZING").upper()
    if direction not in ("BUY", "SELL"):
        direction = "ANALYZING"
    return f"{direction} READY" if bool((forecast_display or {}).get("signal_ready")) else f"{direction} CANDIDATE"


def _append_five_minute_projection_panel(
    image: np.ndarray,
    candles: List[Dict[str, Any]],
    forecast_display: Dict[str, Any],
    candle_analysis: Dict[str, Any],
    score_hidden: bool = False,
) -> np.ndarray:
    """Append a five-future-M1-candle scenario panel to the monitor preview.

    This is a visual scenario based on the current model bias and recent candle range,
    not fabricated broker-price OHLC. The actual broker chart is never modified.
    """
    if not isinstance(image, np.ndarray) or image.size == 0 or not candles:
        return image
    h, original_w = image.shape[:2]
    horizon_bars = int(FORECAST_HORIZON_BARS)
    if horizon_bars != 5 or FIXED_EXPIRY_MINUTES != 5:
        # This file intentionally targets the configured, fixed five-minute expiry.
        horizon_bars = 5
    pad_w = int(clamp(round(original_w * 0.34), 190, 360))

    # Sample the chart's corners for a neutral extension background; avoid smearing a
    # final candle/trade marker across the forecast region.
    patch_w = min(24, original_w)
    patch_h = min(18, h)
    patches = [
        image[:patch_h, :patch_w],
        image[:patch_h, max(0, original_w-patch_w):original_w],
        image[max(0, h-patch_h):h, :patch_w],
        image[max(0, h-patch_h):h, max(0, original_w-patch_w):original_w],
    ]
    samples = [patch.reshape(-1, 3) for patch in patches if patch.size]
    background = np.median(np.concatenate(samples, axis=0), axis=0).astype(np.uint8) if samples else np.array([30,30,30], dtype=np.uint8)
    canvas = np.empty((h, original_w + pad_w, 3), dtype=np.uint8)
    canvas[:, :original_w] = image
    canvas[:, original_w:] = background

    direction = str(forecast_display.get("direction") or candle_analysis.get("direction") or "SELL").upper()
    direction = "BUY" if direction == "BUY" else "SELL"
    bias = parse_float(forecast_display.get("bias"), None)
    if bias is None:
        bias = parse_float(candle_analysis.get("bias"), 0.0) or 0.0
    # Respect selected direction when rounded/near-zero components tie.
    if abs(float(bias)) < 1e-6:
        bias = 0.12 if direction == "BUY" else -0.12
    if (direction == "BUY" and bias < 0) or (direction == "SELL" and bias > 0):
        bias = abs(float(bias)) * (1.0 if direction == "BUY" else -1.0)
    bias = float(clamp(bias, -1.0, 1.0))

    range_samples = []
    body_samples = []
    for row in candles[-min(30, len(candles)):]:
        top = parse_float(row.get("wick_top_pixel", row.get("y")), None)
        bottom = parse_float(row.get("wick_bottom_pixel"), None)
        if top is not None and bottom is not None and bottom > top:
            range_samples.append(bottom - top)
        body = parse_float(row.get("body_height_pixels"), None)
        if body is not None and body > 0:
            body_samples.append(body)
    median_range = max(3.0, float(np.median(range_samples)) if range_samples else h * 0.025)
    median_body = max(2.0, float(np.median(body_samples)) if body_samples else median_range * 0.45)
    last = candles[-1]
    base_y = int(round(float(last.get("estimated_close_pixel", last.get("body_top_pixel", h/2)))))
    base_y = int(clamp(base_y, 8, max(8, h-8)))
    trend_sign = -1.0 if direction == "BUY" else 1.0  # image coordinates invert price direction
    endpoint_distance = min(h * 0.20, max(4.0, median_range * (0.65 + 3.8 * abs(bias))))
    target_y = int(clamp(base_y + trend_sign * endpoint_distance, 8, max(8, h-8)))

    panel_left = original_w
    cv2.line(canvas, (panel_left, 0), (panel_left, h-1), (210, 210, 210), 1, cv2.LINE_AA)
    header = f"NEXT {FIXED_EXPIRY_MINUTES} MIN | {direction}"
    confidence = parse_float(forecast_display.get("confidence"), None)
    if not score_hidden and confidence is not None:
        header += f" EST {confidence:.0f}%"
    cv2.rectangle(canvas, (panel_left+4, 5), (original_w+pad_w-5, 28), (7, 18, 38), -1)
    cv2.putText(canvas, header[:48], (panel_left+10, 21), cv2.FONT_HERSHEY_SIMPLEX, 0.40,
                (50, 230, 255), 1, cv2.LINE_AA)
    note = "CANDIDATE / ALERT GATES NOT PASSED" if not bool(forecast_display.get("signal_ready")) else "QUALIFIED FORECAST"
    if score_hidden:
        note = "FORECAST DETAIL HIDDEN DURING COOLDOWN"
    cv2.putText(canvas, note, (panel_left+9, 43), cv2.FONT_HERSHEY_SIMPLEX, 0.31,
                (210, 210, 210), 1, cv2.LINE_AA)

    step_w = max(18, int(pad_w / (horizon_bars + 1)))
    xs = [original_w + int(round(step_w * i)) for i in range(1, horizon_bars+1)]
    xs = [min(original_w+pad_w-12, max(original_w+8, x)) for x in xs]
    points = [(max(0, original_w-2), base_y)]
    for i in range(1, horizon_bars+1):
        linear_y = base_y + (target_y-base_y) * (i / horizon_bars)
        wiggle = 0.0 if i == horizon_bars else (median_range * 0.23 * (1 if i % 2 else -1))
        y = int(clamp(round(linear_y + wiggle), 8, max(8, h-8)))
        points.append((xs[i-1], y))

    # Uncertainty envelope widens into the future; its pixels are explicitly relative.
    upper = []
    lower = []
    for i, (px, py) in enumerate(points[1:], start=1):
        half = min(h * 0.10, max(3.0, median_range * (0.32 + i * 0.15)))
        upper.append((px, int(clamp(py-half, 6, max(6, h-6)))))
        lower.append((px, int(clamp(py+half, 6, max(6, h-6)))))
    if upper and lower:
        poly = np.asarray(upper + list(reversed(lower)), dtype=np.int32)
        overlay = canvas.copy()
        cv2.fillPoly(overlay, [poly], (35, 90, 60) if direction == "BUY" else (70, 45, 100))
        canvas[:, panel_left:] = cv2.addWeighted(overlay[:, panel_left:], 0.22, canvas[:, panel_left:], 0.78, 0)

    for i in range(1, horizon_bars+1):
        x, y = points[i]
        prev_y = points[i-1][1]
        up_step = y < prev_y
        bar_color = (45, 220, 110) if up_step else (40, 70, 255)
        if y == prev_y:
            bar_color = (200, 200, 200)
        # Draw a short path connecting the projected candle closes; future candles
        # remain inside their separate right-side panel and cannot be mistaken for history.
        cv2.line(canvas, points[i-1], points[i], bar_color, 1, cv2.LINE_AA)
        wick = max(2, int(round(median_range * 0.18)))
        open_y = prev_y
        top = max(4, min(open_y, y)-wick)
        bottom = min(h-5, max(open_y, y)+wick)
        cv2.line(canvas, (x, top), (x, bottom), bar_color, 1, cv2.LINE_AA)
        body_top = min(open_y, y)
        body_bottom = max(open_y, y)
        if body_bottom-body_top < 2:
            body_top = max(4, body_top-1)
            body_bottom = min(h-5, body_bottom+1)
        half_body_w = max(3, int(round(step_w*0.16)))
        cv2.rectangle(canvas, (x-half_body_w, body_top), (x+half_body_w, body_bottom), bar_color, -1)
        cv2.putText(canvas, f"+{i}m", (max(panel_left+2, x-12), min(h-4, 60)),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.28, (225,225,225), 1, cv2.LINE_AA)

    cv2.line(canvas, (panel_left+4, base_y), (original_w+pad_w-5, base_y), (150,150,150), 1, cv2.LINE_AA)
    target_label = "SCENARIO TARGET" if not score_hidden else "5-MIN PATH"
    cv2.putText(canvas, target_label, (panel_left+8, max(55, min(h-8, target_y-7))),
                cv2.FONT_HERSHEY_SIMPLEX, 0.30, (50,230,255), 1, cv2.LINE_AA)
    cv2.putText(canvas, "PIXEL-RELATIVE | NOT GUARANTEED", (panel_left+7, h-8),
                cv2.FONT_HERSHEY_SIMPLEX, 0.24, (190,190,190), 1, cv2.LINE_AA)
    return canvas


def draw_chart_analysis(chart_image: np.ndarray, candle_result: Dict[str, Any],
                        candle_analysis: Dict[str, Any], indicators: Dict[str, Any]) -> np.ndarray:
    """Render analysis drawings on the monitor's chart preview without controlling the broker UI."""
    if not isinstance(chart_image, np.ndarray) or chart_image.size == 0:
        return np.zeros((240, 420, 3), dtype=np.uint8)
    image = chart_image.copy()
    h, w = image.shape[:2]
    candles = list(candle_result.get("candles") or [])
    if not candles:
        cv2.putText(image, "WAITING FOR READABLE CANDLES", (16, 34), cv2.FONT_HERSHEY_SIMPLEX,
                    0.65, (0, 210, 255), 2, cv2.LINE_AA)
        return image

    # Draw EMA curves on close pixel positions. The numerical indicators above use the same candles.
    xs = np.asarray([float(row.get("slot_center_x", float(row.get("x", 0)) + float(row.get("width", 1)) / 2)) for row in candles], dtype=float)
    close_y = np.asarray([float(row.get("estimated_close_pixel", row.get("body_top_pixel", 0))) for row in candles], dtype=float)
    if len(xs) >= 2:
        for period, color, thickness in ((9, (255, 190, 30), 2), (21, (0, 205, 255), 2), (50, (130, 220, 95), 1)):
            if len(close_y) < period:
                continue
            curve = _ema(close_y, min(period, len(close_y)))
            pts = np.asarray([[int(round(x)), int(round(y))] for x, y in zip(xs, curve)
                              if 0 <= x < w and 0 <= y < h], dtype=np.int32)
            if len(pts) >= 2:
                cv2.polylines(image, [pts.reshape((-1, 1, 2))], False, color, thickness, cv2.LINE_AA)

        # Rolling Bollinger-style envelopes are drawn in screen-pixel space. These are
        # visual range overlays, not claims about calibrated broker prices.
        if len(close_y) >= 10:
            upper_pts, lower_pts = [], []
            window = min(20, len(close_y))
            for i in range(len(close_y)):
                local = close_y[max(0, i - window + 1):i + 1]
                mid = float(np.mean(local))
                std = float(np.std(local))
                upper_y = int(round(mid - 2.0 * std))
                lower_y = int(round(mid + 2.0 * std))
                x_i = int(round(xs[i]))
                if 0 <= x_i < w:
                    if 0 <= upper_y < h:
                        upper_pts.append((x_i, upper_y))
                    if 0 <= lower_y < h:
                        lower_pts.append((x_i, lower_y))
            if len(upper_pts) >= 2:
                cv2.polylines(image, [np.asarray(upper_pts, dtype=np.int32).reshape((-1, 1, 2))], False, (190, 115, 255), 1, cv2.LINE_AA)
            if len(lower_pts) >= 2:
                cv2.polylines(image, [np.asarray(lower_pts, dtype=np.int32).reshape((-1, 1, 2))], False, (190, 115, 255), 1, cv2.LINE_AA)
            cv2.putText(image, "BB 20/2", (5, min(h - 5, 45)), cv2.FONT_HERSHEY_SIMPLEX, 0.34, (190, 115, 255), 1, cv2.LINE_AA)

        # Mark locally confirmed swing highs and lows (two bars on each side).
        pivot_highs, pivot_lows = [], []
        for i in range(2, len(candles) - 2):
            hi = float(candles[i].get("wick_top_pixel", candles[i].get("y", 0)))
            lo = float(candles[i].get("wick_bottom_pixel", float(candles[i].get("y", 0)) + float(candles[i].get("height", 1))))
            other_hi = [float(row.get("wick_top_pixel", row.get("y", 0))) for row in candles[i-2:i] + candles[i+1:i+3]]
            other_lo = [float(row.get("wick_bottom_pixel", float(row.get("y", 0)) + float(row.get("height", 1)))) for row in candles[i-2:i] + candles[i+1:i+3]]
            if hi <= min(other_hi):
                pivot_highs.append((int(round(xs[i])), int(round(hi))))
            if lo >= max(other_lo):
                pivot_lows.append((int(round(xs[i])), int(round(lo))))
        structure_drawings = candle_analysis.get("structure_drawings") or {}
        swing_label_lookup = {(int(row.get("x", -1)), int(row.get("y", -1))): str(row.get("label") or "")
                              for row in (structure_drawings.get("swing_labels") or [])}
        for x_p, y_p in pivot_highs[-6:]:
            if 0 <= x_p < w and 0 <= y_p < h:
                cv2.circle(image, (x_p, y_p), 3, (255, 120, 80), -1, cv2.LINE_AA)
                label = swing_label_lookup.get((x_p,y_p), "SH")
                cv2.putText(image, label, (max(0, x_p - 10), max(12, y_p - 5)), cv2.FONT_HERSHEY_SIMPLEX, 0.30, (255, 150, 100), 1, cv2.LINE_AA)
        for x_p, y_p in pivot_lows[-6:]:
            if 0 <= x_p < w and 0 <= y_p < h:
                cv2.circle(image, (x_p, y_p), 3, (100, 230, 150), -1, cv2.LINE_AA)
                label = swing_label_lookup.get((x_p,y_p), "SL")
                cv2.putText(image, label, (max(0, x_p - 10), min(h - 3, y_p + 12)), cv2.FONT_HERSHEY_SIMPLEX, 0.30, (100, 230, 150), 1, cv2.LINE_AA)

        # Five-minute range uses the empirical distribution of non-overlapping completed five-M1 outcomes.
        band = candle_analysis.get("five_minute_projection_band") or {}
        if band.get("available"):
            latest_x = int(round(xs[-1])); latest_y = int(round(close_y[-1]))
            mapping = _fit_visual_price_map(candles)
            if band.get("price_based_levels_available") and mapping.get("available") and all(
                    parse_float(band.get(k), None) is not None for k in ("upper_projected_level", "lower_projected_level", "median_projected_level")):
                slope = float(mapping["price_per_pixel"]); intercept = float(mapping["intercept"])
                upper_range_y = int(round((float(band["upper_projected_level"])-intercept)/slope))
                lower_range_y = int(round((float(band["lower_projected_level"])-intercept)/slope))
                median_range_y = int(round((float(band["median_projected_level"])-intercept)/slope))
                label = f"5M EST. BAND ~{format_market_price(band['lower_projected_level'])}–{format_market_price(band['upper_projected_level'])}"
            elif all(parse_float(band.get(k), None) is not None for k in ("upper_projected_pixel_proxy", "lower_projected_pixel_proxy", "median_projected_pixel_proxy")):
                # Proxy values are negated y coordinates, never broker prices.
                upper_range_y = int(round(-float(band["upper_projected_pixel_proxy"])))
                lower_range_y = int(round(-float(band["lower_projected_pixel_proxy"])))
                median_range_y = int(round(-float(band["median_projected_pixel_proxy"])))
                label = "5M HIST BAND — PIXEL PROXY"
            else:
                upper_range_y = lower_range_y = median_range_y = latest_y
                label = "5M BAND — NO PRICE SCALE"
            if 0 <= latest_x < w:
                _draw_dashed_horizontal(image, upper_range_y, (255, 170, 80), 1)
                _draw_dashed_horizontal(image, lower_range_y, (255, 170, 80), 1)
                _draw_dashed_horizontal(image, median_range_y, (210, 190, 120), 1)
                cv2.putText(image, label[:88], (6, max(42, min(h-8, upper_range_y-4))), cv2.FONT_HERSHEY_SIMPLEX, 0.34, (255, 190, 100), 1, cv2.LINE_AA)
        else:
            cv2.putText(image, "5M BAND: NEED MORE COMPLETED BARS", (6, 45), cv2.FONT_HERSHEY_SIMPLEX, 0.34, (120, 190, 255), 1, cv2.LINE_AA)

        # Mark BOS/CHOCH, later retest, and the corresponding invalidation level.
        sd = candle_analysis.get("structure_drawings") or {}
        if sd.get("event") not in (None, "NONE", "INSUFFICIENT_HISTORY") and sd.get("break_y") is not None:
            by = int(sd["break_y"])
            _draw_dashed_horizontal(image, by, (255, 215, 70), 2)
            event_label = str(sd.get("event")) + (" RETEST" if sd.get("retest_confirmed") else "")
            cv2.putText(image, event_label[:50], (6, max(14, by-5)), cv2.FONT_HERSHEY_SIMPLEX, 0.38, (255, 215, 70), 1, cv2.LINE_AA)
        if sd.get("invalidation_y") is not None:
            iy = int(sd["invalidation_y"])
            _draw_dashed_horizontal(image, iy, (90, 90, 255), 1)
            cv2.putText(image, "INVALIDATION", (max(4,w-118), max(14,iy-4)), cv2.FONT_HERSHEY_SIMPLEX, 0.31, (100,100,255), 1, cv2.LINE_AA)

        # Draw the exact 5-minute exhaustion/reversal status consumed by the score.
        # This is an annotation on the analyzer preview only; it never edits the broker chart.
        price_action = candle_analysis.get("price_action_context") or {}
        exhaustion = price_action.get("trend_exhaustion_5m") or {}
        if exhaustion.get("confirmed_bullish_reversal") or exhaustion.get("confirmed_bearish_reversal"):
            reversal_side = "BUY" if exhaustion.get("confirmed_bullish_reversal") else "SELL"
            marker_color = (40, 235, 110) if reversal_side == "BUY" else (40, 60, 255)
            label = f"5M REVERSAL CONFIRMED: {reversal_side}"
            cv2.rectangle(image, (6, 54), (min(w-8, 350), 75), (7, 18, 38), -1)
            cv2.putText(image, label, (12, 69), cv2.FONT_HERSHEY_SIMPLEX, 0.39, marker_color, 1, cv2.LINE_AA)
            if candles:
                marker_x = int(round(float(candles[-1].get("slot_center_x", candles[-1].get("x", 0)))))
                marker_y = int(round(float(candles[-1].get("estimated_close_pixel", candles[-1].get("body_top_pixel", 0)))))
                end_y = max(5, marker_y-30) if reversal_side == "BUY" else min(h-5, marker_y+30)
                if 0 <= marker_x < w and 0 <= marker_y < h:
                    cv2.arrowedLine(image, (marker_x, marker_y), (marker_x, end_y), marker_color, 2, cv2.LINE_AA, tipLength=0.35)
        elif exhaustion.get("prolonged_down_streak") or exhaustion.get("prolonged_up_streak"):
            stretched_side = "DOWN" if exhaustion.get("prolonged_down_streak") else "UP"
            warning = exhaustion.get("bullish_exhaustion_warning") if stretched_side == "DOWN" else exhaustion.get("bearish_exhaustion_warning")
            label = f"5M {stretched_side}TREND EXTENDED | EXHAUSTION {'CONFIRMING' if warning else 'NOT CONFIRMED'}"
            cv2.rectangle(image, (6, 54), (min(w-8, 485), 75), (7, 18, 38), -1)
            cv2.putText(image, label[:75], (12, 69), cv2.FONT_HERSHEY_SIMPLEX, 0.35, (0, 205, 255), 1, cv2.LINE_AA)

        # M30/H1 direction is visible on the same live chart overlay.
        mtf = candle_analysis.get("multi_timeframe_confirmation") or {}
        mtf_m30 = (mtf.get("M30") or {}).get("trend", "—")
        mtf_h1 = (mtf.get("H1") or {}).get("trend", "—")
        cv2.putText(image, f"M30 {mtf_m30} | H1 {mtf_h1}", (max(5,w-260), 45), cv2.FONT_HERSHEY_SIMPLEX, 0.35, (100,220,255), 1, cv2.LINE_AA)

        # Classical chart formations share the same price-action context used by the final score.
        chart_patterns = candle_analysis.get("classical_chart_patterns") or (candle_analysis.get("price_action_context") or {}).get("classical_chart_patterns") or {}
        price_map_for_patterns = _fit_visual_price_map(candles)
        for segment in (chart_patterns.get("line_segments") or [])[-12:]:
            try:
                i1 = int(segment.get("x1_index", -1)); i2 = int(segment.get("x2_index", -1))
                if not (0 <= i1 < len(candles) and 0 <= i2 < len(candles)):
                    continue
                x1 = int(round(float(candles[i1].get("slot_center_x", candles[i1].get("x", 0)))))
                x2 = int(round(float(candles[i2].get("slot_center_x", candles[i2].get("x", 0)))))
                p1 = float(segment.get("y1_price")); p2 = float(segment.get("y2_price"))
                if price_map_for_patterns.get("available"):
                    scale = float(price_map_for_patterns["price_per_pixel"])
                    intercept = float(price_map_for_patterns["intercept"])
                    y1 = int(round((p1-intercept)/scale)); y2 = int(round((p2-intercept)/scale))
                else:
                    # Without a calibrated axis the detector uses inverted screen-pixel OHLC proxies.
                    y1 = int(round(-p1)); y2 = int(round(-p2))
                if 0 <= x1 < w and 0 <= x2 < w and -h <= y1 < 2*h and -h <= y2 < 2*h:
                    confirmed = bool(segment.get("confirmed"))
                    color = (0, 220, 120) if confirmed and float((chart_patterns.get("bias") or 0.0)) > 0 else (20, 130, 255) if confirmed else (180, 120, 230)
                    cv2.line(image, (x1, max(0,min(h-1,y1))), (x2, max(0,min(h-1,y2))), color, 1, cv2.LINE_AA)
                    if segment.get("label") and 0 <= x1 < w:
                        cv2.putText(image, str(segment.get("label"))[:32], (max(3,min(w-100,x1+2)), max(12,min(h-5,y1-3))), cv2.FONT_HERSHEY_SIMPLEX, 0.27, color, 1, cv2.LINE_AA)
            except (TypeError, ValueError, IndexError, KeyError):
                continue

        # Draw readable labels and rectangles for the most recent detected candle patterns.
        visible_patterns = list(candle_analysis.get("patterns") or [])
        recent_pattern_labels = []
        seen_pattern_names = set()
        for pattern in reversed(visible_patterns):
            name = str(pattern.get("name") or "").replace("_", " ").strip()
            if not name or name in seen_pattern_names:
                continue
            indices = pattern.get("candle_indices") or []
            try:
                idxs = [int(v)-1 for v in indices if 1 <= int(v) <= len(candles)]
            except (TypeError, ValueError):
                idxs = []
            if not idxs or max(idxs) < max(0, len(candles)-14):
                continue
            seen_pattern_names.add(name)
            recent_pattern_labels.append((pattern, name, idxs))
            if len(recent_pattern_labels) >= 14:
                break
        for row_i, (pattern, name, idxs) in enumerate(recent_pattern_labels):
            pattern_x_left = [float(candles[idx].get("x", 0)) for idx in idxs]
            pattern_x_right = [float(candles[idx].get("x", 0)) + float(candles[idx].get("width", 1)) for idx in idxs]
            pattern_y_top = [float(candles[idx].get("wick_top_pixel", candles[idx].get("y", 0))) for idx in idxs]
            pattern_y_bottom = [float(candles[idx].get("wick_bottom_pixel", float(candles[idx].get("y", 0)) + float(candles[idx].get("height", 1)))) for idx in idxs]
            x_left = max(0, int(round(min(pattern_x_left) - 3)))
            x_right = min(w - 1, int(round(max(pattern_x_right) + 3)))
            y_top = max(0, int(round(min(pattern_y_top) - 3)))
            y_bottom = min(h - 1, int(round(max(pattern_y_bottom) + 3)))
            color = (0, 220, 120) if float(parse_float(pattern.get("bias"), 0.0) or 0.0) > 0 else (50, 130, 255) if float(parse_float(pattern.get("bias"), 0.0) or 0.0) < 0 else (190, 190, 190)
            if x_right > x_left and y_bottom > y_top:
                cv2.rectangle(image, (x_left,y_top), (x_right,y_bottom), color, 1, cv2.LINE_AA)
            suffix = " CONFIRMED" if pattern.get("confirmed") else " PENDING"
            label = (name + suffix)[:58]
            yy = min(h-6, 91 + row_i*17)
            cv2.rectangle(image, (5, yy-12), (min(w-4, 14 + len(label)*6), yy+3), (7,18,38), -1)
            cv2.putText(image, label, (8,yy), cv2.FONT_HERSHEY_SIMPLEX, 0.31, color, 1, cv2.LINE_AA)

        # Price-level labels appear only when visible-axis calibration is consistent.
        local_map = _fit_visual_price_map(candles)
        if local_map.get("available"):
            sl = float(local_map["price_per_pixel"]); itc = float(local_map["intercept"])
            # Support/resistance price labels are rendered once in the shared zone block below.
            # The existing FIB lines are still visual references; this adds approximate prices only when scale fit succeeds.
            high_y = min(float(row.get("wick_top_pixel", row.get("y", 0))) for row in candles)
            low_y = max(float(row.get("wick_bottom_pixel", float(row.get("y", 0)) + float(row.get("height", 1)))) for row in candles)
            if low_y > high_y + 8:
                for level, label in ((0.382,"F38"),(0.5,"F50"),(0.618,"F62")):
                    yy = high_y + (low_y-high_y)*level
                    price_val = itc + sl*yy
                    if price_val > 0:
                        cv2.putText(image, f"{label} ~{format_market_price(price_val)}", (6,max(14,int(yy)-3)), cv2.FONT_HERSHEY_SIMPLEX, 0.30, (190,125,255), 1, cv2.LINE_AA)

        # Broker volume-profile levels are drawn only if documented volume and a compatible price map exist.
        vp = candle_analysis.get("volume_profile") or {}
        if vp.get("available") and local_map.get("available"):
            sl = float(local_map["price_per_pixel"]); itc = float(local_map["intercept"])
            for key,label,color in (("poc","POC",(255,255,255)),("vah","VAH",(255,180,70)),("val","VAL",(70,180,255))):
                value = parse_float(vp.get(key),None)
                if value is None: continue
                yy = int(round((value-itc)/sl))
                _draw_dashed_horizontal(image, yy, color, 1)
                if 0 <= yy < h:
                    cv2.putText(image, f"{label} {format_market_price(value)}", (max(4,w-118),max(14,yy-3)), cv2.FONT_HERSHEY_SIMPLEX,0.31,color,1,cv2.LINE_AA)

        # Overall trendline over all available visible candle closes.
        try:
            slope, intercept = np.polyfit(xs, close_y, 1)
            y1, y2 = int(round(slope * xs[0] + intercept)), int(round(slope * xs[-1] + intercept))
            cv2.line(image, (int(xs[0]), max(0, min(h - 1, y1))),
                     (int(xs[-1]), max(0, min(h - 1, y2))), (255, 255, 0), 1, cv2.LINE_AA)
        except Exception:
            pass

    # Support/resistance zones are derived from repeated detected wick highs/lows.
    for row in (candle_analysis.get("resistance_pixel_zones") or [])[:3]:
        yy = int(round(float(row.get("pixel_y", -1))))
        _draw_dashed_horizontal(image, yy, (40, 40, 255), 1)
        if 0 <= yy < h:
            price_map_for_label = _fit_visual_price_map(candles)
            if price_map_for_label.get("available"):
                approx_price = float(price_map_for_label["intercept"]) + float(price_map_for_label["price_per_pixel"])*yy
                label = f"RES ~{format_market_price(approx_price)}" if approx_price > 0 else "RES"
            else:
                label = "RES (PX)"
            cv2.putText(image, label, (max(4, w - 132), max(14, yy - 3)), cv2.FONT_HERSHEY_SIMPLEX,
                        0.32, (40, 40, 255), 1, cv2.LINE_AA)
    for row in (candle_analysis.get("support_pixel_zones") or [])[:3]:
        yy = int(round(float(row.get("pixel_y", -1))))
        _draw_dashed_horizontal(image, yy, (0, 220, 120), 1)
        if 0 <= yy < h:
            price_map_for_label = _fit_visual_price_map(candles)
            if price_map_for_label.get("available"):
                approx_price = float(price_map_for_label["intercept"]) + float(price_map_for_label["price_per_pixel"])*yy
                label = f"SUP ~{format_market_price(approx_price)}" if approx_price > 0 else "SUP"
            else:
                label = "SUP (PX)"
            cv2.putText(image, label, (max(4, w - 132), max(14, yy - 3)), cv2.FONT_HERSHEY_SIMPLEX,
                        0.32, (0, 220, 120), 1, cv2.LINE_AA)

    # Fibonacci reference lines from the visible high/low range (not claimed as exact market prices).
    high_y = min(float(row.get("wick_top_pixel", row.get("y", 0))) for row in candles)
    low_y = max(float(row.get("wick_bottom_pixel", float(row.get("y", 0)) + float(row.get("height", 1)))) for row in candles)
    if low_y > high_y + 8:
        for level, label in ((0.382, "F38"), (0.5, "F50"), (0.618, "F62")):
            yy = int(round(high_y + (low_y - high_y) * level))
            _draw_dashed_horizontal(image, yy, (160, 90, 230), 1)
            cv2.putText(image, label, (5, max(14, yy - 3)), cv2.FONT_HERSHEY_SIMPLEX,
                        0.34, (190, 125, 255), 1, cv2.LINE_AA)

    last = candles[-1]
    last_x = int(round(float(last.get("slot_center_x", 0))))
    last_y = int(round(float(last.get("estimated_close_pixel", last.get("body_top_pixel", 0)))) )
    if 0 <= last_x < w and 0 <= last_y < h:
        cv2.circle(image, (last_x, last_y), 4, (255, 255, 255), 1, cv2.LINE_AA)
        cv2.line(image, (last_x, 0), (last_x, h - 1), (170, 170, 170), 1, cv2.LINE_AA)

    trend = str(candle_analysis.get("trend") or "MIXED").replace("SIDEWAYS_OR_MIXED", "MIXED")
    forecast_display = candle_analysis.get("five_minute_forecast_display") or {}
    signal = str(forecast_display.get("direction") or candle_analysis.get("direction") or "ANALYZING")
    score = parse_float(forecast_display.get("confidence"), None)
    trigger_ready = bool(forecast_display.get("signal_ready"))
    signal_label = _five_minute_candidate_label(forecast_display)
    try:
        with APP_STATE_LOCK:
            _hidden_until = float(APP_STATE.get("score_hidden_until_epoch") or 0.0)
    except Exception:
        _hidden_until = 0.0
    _score_hidden = time.time() < _hidden_until
    score_label = "" if _score_hidden else (f" {score:.0f}%" if score is not None else "")
    mtf = candle_analysis.get("multi_timeframe_confirmation") or {}
    mtf_tag = f"M30:{(mtf.get('M30') or {}).get('trend','—')} H1:{(mtf.get('H1') or {}).get('trend','—')}"
    caption = ("5M FORECAST HIDDEN | M1 | EMA 9/21/50 | BB | S/R | FIB" if _score_hidden else f"5M {signal_label}{score_label} | M1 | EMA 9/21/50 | BB | S/R | FIB | {mtf_tag} | {trend}")
    cv2.rectangle(image, (6, 6), (min(w - 8, 760), 31), (7, 18, 38), -1)
    cv2.putText(image, caption[:105], (12, 24), cv2.FONT_HERSHEY_SIMPLEX, 0.43,
                (50, 230, 255), 1, cv2.LINE_AA)
    # Add five explicit future M1 slots to the right of current candles. This drawing is
    # a candidate scenario on the analyzer monitor only; it never overlays broker controls.
    return _append_five_minute_projection_panel(image, candles, forecast_display, candle_analysis, _score_hidden)


def read_current_price_tag(frame: np.ndarray, candle_result: Dict[str, Any]) -> Tuple[Optional[float], str]:
    """Read the broker's visible current-price badge near the latest candle; never invent a quote."""
    try:
        import pytesseract
        from pytesseract import Output
    except Exception:
        return None, "TESSERACT MISSING"
    configured_path = (os.environ.get("TESSERACT_CMD") or os.environ.get("TESSERACT_PATH") or "").strip()
    default_windows_path = r"C:\Program Files\Tesseract-OCR\tesseract.exe"
    executable = configured_path or (default_windows_path if os.name == "nt" and Path(default_windows_path).is_file() else shutil.which("tesseract"))
    if executable and (os.path.isfile(executable) or shutil.which(executable)):
        pytesseract.pytesseract.tesseract_cmd = executable
    elif shutil.which(str(getattr(pytesseract.pytesseract, "tesseract_cmd", "tesseract"))) is None:
        return None, "TESSERACT MISSING"
    candles = list(candle_result.get("candles") or [])
    region = candle_result.get("chart_region") or {}
    if not candles or frame is None or frame.size == 0:
        return None, "NO PRICE REGION"
    frame_h, frame_w = frame.shape[:2]
    x = int(parse_float(region.get("x"), 0) or 0)
    y = int(parse_float(region.get("y"), 0) or 0)
    width = int(parse_float(region.get("width"), frame_w) or frame_w)
    latest = candles[-1]
    close_pixel = parse_float(latest.get("estimated_close_pixel"), latest.get("body_top_pixel"))
    if close_pixel is None:
        return None, "NO PRICE LOCATION"
    target_y = int(round(y + close_pixel))
    # Current-price badge sits immediately to the right of the plot pane. The crop is
    # anchored to the latest candle's height to distinguish it from other axis labels.
    x0 = max(0, min(frame_w - 1, int(x + width * 0.975)))
    x1 = max(x0 + 1, min(frame_w, int(x + width * 1.075)))
    y0 = max(0, target_y - 26)
    y1 = min(frame_h, target_y + 14)
    if x1 - x0 < 28 or y1 - y0 < 12:
        return None, "PRICE BADGE OUTSIDE SCREEN"
    crop = frame[y0:y1, x0:x1]
    if crop.size == 0:
        return None, "PRICE BADGE NOT VISIBLE"
    try:
        up = cv2.resize(crop, None, fx=3.0, fy=3.0, interpolation=cv2.INTER_CUBIC)
        gray = cv2.cvtColor(up, cv2.COLOR_BGR2GRAY)
        # The colored quote badge can be more legible after local contrast enhancement.
        gray = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(4, 4)).apply(gray)
        data = pytesseract.image_to_data(
            gray, output_type=Output.DICT,
            config="--psm 11 -c tessedit_char_whitelist=0123456789.,",
            timeout=TESSERACT_TIMEOUT_SECONDS,
        )
    except Exception as exc:
        return None, "PRICE OCR " + type(exc).__name__.upper()
    candidates = []
    texts = data.get("text", [])
    for index, token in enumerate(texts):
        text_value = re.sub(r"[^0-9.,]", "", str(token or ""))
        if not re.fullmatch(r"(?:(?:\d{1,3}(?:[,.]\d{3})+)|\d{2,8})(?:[,.]\d{1,5})?", text_value):
            continue
        try:
            confidence = float(data.get("conf", [])[index])
            center_y = y0 + (float(data.get("top", [])[index]) + float(data.get("height", [])[index]) / 2.0) / 3.0
        except (ValueError, TypeError, IndexError):
            continue
        parsed = parse_price_text(text_value, None)
        if parsed is None or not (10.0 <= parsed <= 10_000_000.0) or confidence < 35:
            continue
        distance = abs(center_y - target_y)
        if distance <= 30:
            candidates.append((distance, -confidence, float(parsed)))
    if not candidates:
        return None, "PRICE BADGE NOT READ"
    candidates.sort()
    return candidates[0][2], "SCREEN OCR"


def extract_screen_price(price_scale: Dict[str, Any], candle_result: Dict[str, Any],
                         screen_quote: Optional[float] = None) -> Tuple[Optional[float], str]:
    """Prefer the on-screen quote badge; axis-calibrated candle closes are only estimates."""
    if screen_quote is not None and math.isfinite(float(screen_quote)) and float(screen_quote) > 0:
        return float(screen_quote), "SCREEN OCR"
    candles = list(candle_result.get("candles") or [])
    if not candles:
        return None, "NO CANDLES"
    if price_scale.get("available"):
        current = parse_float(candles[-1].get("estimated_close_price"), None)
        if current is not None and current > 0:
            return float(current), "AXIS EST"
    chart_region = candle_result.get("chart_region") or {}
    roi_y = float(parse_float(chart_region.get("y"), 0.0) or 0.0)
    target_y = roi_y + float(parse_float(candles[-1].get("estimated_close_pixel"), candles[-1].get("body_top_pixel", 0)) or 0.0)
    ticks = price_scale.get("tick_points") or []
    usable = []
    for tick in ticks:
        value = parse_float(tick.get("value"), None)
        y = parse_float(tick.get("y"), None)
        confidence = parse_float(tick.get("confidence"), 0.0) or 0.0
        if value is not None and y is not None and confidence >= 30 and 10.0 <= value <= 10_000_000.0:
            usable.append((abs(float(y) - target_y), float(value), float(y)))
    if usable:
        distance, value, _y = min(usable, key=lambda item: item[0])
        if distance <= 32.0:
            return value, "AXIS TICK"
    return None, "NOT READ"


# ------------------------------ Dashboard state -------------------------------
# The chart is continuously sampled in memory. Expensive quote-badge OCR is throttled
# separately so a slow Tesseract call cannot stall every live candle-analysis frame.
_LIVE_PRICE_TAG_CACHE_LOCK = threading.RLock()
_LIVE_PRICE_TAG_CACHE: Dict[str, Any] = {
    "epoch": 0.0, "price": None, "status": "NOT READ", "frame_shape": None,
    "in_flight": False, "generation": 0,
}
_LIVE_PRICE_SCALE_CACHE_LOCK = threading.RLock()
_LIVE_PRICE_SCALE_CACHE: Dict[str, Any] = {
    "epoch": 0.0,
    "result": {"available": False, "reason": "Price-axis OCR pending", "tick_points": []},
    "frame_shape": None, "in_flight": False, "generation": 0,
}


def _reset_live_price_tag_cache() -> None:
    """Forget old price reads and invalidate all OCR workers when the selected region changes."""
    with _LIVE_PRICE_TAG_CACHE_LOCK:
        generation = int(_LIVE_PRICE_TAG_CACHE.get("generation") or 0) + 1
        _LIVE_PRICE_TAG_CACHE.update({
            "epoch": 0.0, "price": None, "status": "NOT READ", "frame_shape": None,
            "in_flight": False, "generation": generation,
        })
    with _LIVE_PRICE_SCALE_CACHE_LOCK:
        generation = int(_LIVE_PRICE_SCALE_CACHE.get("generation") or 0) + 1
        _LIVE_PRICE_SCALE_CACHE.update({
            "epoch": 0.0,
            "result": {"available": False, "reason": "Price-axis OCR pending", "tick_points": []},
            "frame_shape": None, "in_flight": False, "generation": generation,
        })


def _live_price_tag_ocr_worker(
    frame: np.ndarray, candle_result: Dict[str, Any], generation: int,
    frame_shape: Optional[Tuple[int, int]],
) -> None:
    """Read the tiny price badge off-thread so OCR never blocks live candle analysis."""
    try:
        price, status = read_current_price_tag(frame, candle_result)
    except Exception as exc:
        price, status = None, "PRICE OCR " + type(exc).__name__.upper()
    with _LIVE_PRICE_TAG_CACHE_LOCK:
        # Selecting a new screen region invalidates any quote worker from the old crop.
        if int(_LIVE_PRICE_TAG_CACHE.get("generation") or 0) == generation:
            _LIVE_PRICE_TAG_CACHE.update({
                "epoch": time.time(), "price": price, "status": str(status),
                "frame_shape": frame_shape, "in_flight": False,
            })


def _read_current_price_tag_cached(
    frame: np.ndarray, candle_result: Dict[str, Any],
) -> Tuple[Optional[float], str]:
    """Schedule price-badge OCR every few seconds and return cached data immediately."""
    now = time.time()
    shape = tuple(int(v) for v in frame.shape[:2]) if isinstance(frame, np.ndarray) and frame.ndim >= 2 else None
    with _LIVE_PRICE_TAG_CACHE_LOCK:
        cached_shape = _LIVE_PRICE_TAG_CACHE.get("frame_shape")
        if cached_shape is not None and cached_shape != shape:
            generation = int(_LIVE_PRICE_TAG_CACHE.get("generation") or 0) + 1
            _LIVE_PRICE_TAG_CACHE.update({
                "epoch": 0.0, "price": None, "status": "NOT READ", "frame_shape": shape,
                "in_flight": False, "generation": generation,
            })
        last_epoch = float(_LIVE_PRICE_TAG_CACHE.get("epoch") or 0.0)
        current_generation = int(_LIVE_PRICE_TAG_CACHE.get("generation") or 0)
        age = now - last_epoch
        if (last_epoch > 0.0 and _LIVE_PRICE_TAG_CACHE.get("frame_shape") == shape
                and 0.0 <= age < LIVE_PRICE_TAG_OCR_INTERVAL_SECONDS):
            return _LIVE_PRICE_TAG_CACHE.get("price"), str(_LIVE_PRICE_TAG_CACHE.get("status") or "NOT READ")
        if bool(_LIVE_PRICE_TAG_CACHE.get("in_flight")):
            return _LIVE_PRICE_TAG_CACHE.get("price"), str(_LIVE_PRICE_TAG_CACHE.get("status") or "OCR PENDING")
        _LIVE_PRICE_TAG_CACHE.update({"in_flight": True, "frame_shape": shape})

    # The OCR worker needs only the current frame and last-candle coordinates; copies make
    # those inputs stable while the main thread immediately processes the next live frame.
    try:
        frame_snapshot = frame.copy()
        candles = list(candle_result.get("candles") or [])
        ocr_candle_result = {
            "candles": [dict(candles[-1])] if candles else [],
            "chart_region": dict(candle_result.get("chart_region") or {}),
        }
        worker = threading.Thread(
            target=_live_price_tag_ocr_worker,
            args=(frame_snapshot, ocr_candle_result, current_generation, shape),
            daemon=True, name="putra-price-badge-ocr",
        )
        worker.start()
    except Exception as exc:
        with _LIVE_PRICE_TAG_CACHE_LOCK:
            if int(_LIVE_PRICE_TAG_CACHE.get("generation") or 0) == current_generation:
                _LIVE_PRICE_TAG_CACHE.update({"in_flight": False, "status": "OCR WORKER " + type(exc).__name__.upper()})
    with _LIVE_PRICE_TAG_CACHE_LOCK:
        return _LIVE_PRICE_TAG_CACHE.get("price"), str(_LIVE_PRICE_TAG_CACHE.get("status") or "OCR PENDING")


def _live_price_scale_ocr_worker(frame: np.ndarray, generation: int,
                                 frame_shape: Optional[Tuple[int, int]]) -> None:
    """Calibrate price-axis labels in the background; never block the live analysis thread."""
    try:
        result = read_price_axis_scale(frame)
        if not isinstance(result, dict):
            result = {"available": False, "reason": "Price-axis OCR returned no result", "tick_points": []}
    except Exception as exc:
        result = {"available": False, "reason": type(exc).__name__, "tick_points": []}
    with _LIVE_PRICE_SCALE_CACHE_LOCK:
        if int(_LIVE_PRICE_SCALE_CACHE.get("generation") or 0) == generation:
            _LIVE_PRICE_SCALE_CACHE.update({
                "epoch": time.time(), "result": result, "frame_shape": frame_shape, "in_flight": False,
            })


def _get_live_price_scale_cached(frame: np.ndarray) -> Dict[str, Any]:
    """Schedule price-axis OCR periodically and return the latest known calibration immediately."""
    now = time.time()
    shape = tuple(int(v) for v in frame.shape[:2]) if isinstance(frame, np.ndarray) and frame.ndim >= 2 else None
    with _LIVE_PRICE_SCALE_CACHE_LOCK:
        cached_shape = _LIVE_PRICE_SCALE_CACHE.get("frame_shape")
        if cached_shape is not None and cached_shape != shape:
            generation = int(_LIVE_PRICE_SCALE_CACHE.get("generation") or 0) + 1
            _LIVE_PRICE_SCALE_CACHE.update({
                "epoch": 0.0,
                "result": {"available": False, "reason": "Price-axis OCR pending", "tick_points": []},
                "frame_shape": shape, "in_flight": False, "generation": generation,
            })
        last_epoch = float(_LIVE_PRICE_SCALE_CACHE.get("epoch") or 0.0)
        current_generation = int(_LIVE_PRICE_SCALE_CACHE.get("generation") or 0)
        result = dict(_LIVE_PRICE_SCALE_CACHE.get("result") or {})
        fresh = last_epoch > 0.0 and 0.0 <= now - last_epoch < LIVE_OCR_INTERVAL_SECONDS
        if fresh or bool(_LIVE_PRICE_SCALE_CACHE.get("in_flight")):
            return result
        _LIVE_PRICE_SCALE_CACHE.update({"in_flight": True, "frame_shape": shape})

    try:
        worker = threading.Thread(
            target=_live_price_scale_ocr_worker,
            args=(frame.copy(), current_generation, shape),
            daemon=True, name="putra-price-axis-ocr",
        )
        worker.start()
    except Exception as exc:
        with _LIVE_PRICE_SCALE_CACHE_LOCK:
            if int(_LIVE_PRICE_SCALE_CACHE.get("generation") or 0) == current_generation:
                _LIVE_PRICE_SCALE_CACHE.update({
                    "in_flight": False,
                    "result": {"available": False, "reason": "Price-axis OCR worker " + type(exc).__name__, "tick_points": []},
                })
    with _LIVE_PRICE_SCALE_CACHE_LOCK:
        return dict(_LIVE_PRICE_SCALE_CACHE.get("result") or {})


