    _ocr_mock_calls: List[str] = []
    _ocr_mock_lock = threading.Lock()
    _ocr_mock_event = threading.Event()
    def _mock_quote_reader(_frame: np.ndarray, _candle_result: Dict[str, Any]) -> Tuple[Optional[float], str]:
        with _ocr_mock_lock:
            _ocr_mock_calls.append("quote")
            _ocr_mock_event.set()
        return 67500.25, "SCREEN OCR"
    def _mock_scale_reader(_frame: np.ndarray) -> Dict[str, Any]:
        with _ocr_mock_lock:
            _ocr_mock_calls.append("scale")
            _ocr_mock_event.set()
        return {"available": True, "tick_points": [{"value": 67000.0, "y": 12}], "reason": "self-test"}
    def _wait_for_ocr_cache(cache: Dict[str, Any], lock: Any, wanted_key: str, wanted_value: Any) -> bool:
        deadline = time.monotonic() + 2.0
        while time.monotonic() < deadline:
            with lock:
                if cache.get(wanted_key) == wanted_value and not cache.get("in_flight"):
                    return True
            time.sleep(0.01)
        return False
