def _v10_feature_group(name: str) -> str:
    if name in _V10_METHODOLOGY_NAMES or name in _V10_MTF_NAMES or name in _V10_VOLUME_NAMES or name in _V10_TIME_DEPENDENT_NAMES:
        return "methodology_or_data_dependent"
    names = _V10_CATALOG_NAMES
    i = names.index(name)
    candle_end = names.index(_V10_CANDLE_CATALOG_LAST)
    chart_end = names.index(_V10_CHART_CATALOG_LAST)
    if i <= candle_end:
        return "candlestick_pattern"
    if i <= chart_end:
        return "classical_chart_pattern"
    return "price_action_structure_smc"


def _v10_feature_algorithm(name: str, group: str) -> Tuple[str, str, str]:
    """Return implementation status, rule summary, and extra input requirement."""
    if name == "Market Maker Model":
        return ("HEURISTIC_SEQUENCE_PROXY", "Looks for a measurable accumulation/range phase, a liquidity sweep/manipulation candidate, displacement and a distribution-like close. This is a price-sequence proxy, not evidence of actual institutional intent.", "Visible OHLC sequence; trusted timestamps improve session interpretation, and actual order flow is not inferred from candle pixels.")
    if name in _V10_TIME_DEPENDENT_NAMES:
        return ("CONDITIONAL_TIMESTAMPED_DATA", "Checks the named session/setup only from trusted per-candle timestamps, a configured timezone/session, and the associated price-action sequence; the label never becomes a directional vote just because the clock matches.", "Broker-aligned candle timestamps and an explicitly configured session timezone; otherwise status remains unavailable." )
    if name in _V10_MTF_NAMES:
        return ("CONDITIONAL_MULTITIMEFRAME_DATA", "Compares lower-timeframe price action with completed higher-timeframe structure and momentum; higher-timeframe bars must end before the forecast time to avoid look-ahead.", "Sufficient contiguous OHLC bars for M15/M30/H1 or a validated broker export; a single image is not itself multiple timeframes." )
    if name in _V10_VOLUME_NAMES:
        return ("CONDITIONAL_VERIFIED_VOLUME", "Volume is compared with its recent baseline and price response only when a valid provider-declared volume series exists; screenshot color/brightness is never treated as trading volume.", "Valid timestamped OHLCV with declared tick_volume or real_volume semantics. Pixel-only screenshots cannot reveal actual volume." )
    if name in _V10_METHODOLOGY_NAMES:
        return ("METHODOLOGY_APPLIED_TO_FEATURES", "Uses the combined naked-chart/price-action or SMC pipeline: candle pattern, swing structure, support/resistance, displacement, liquidity sweep, order-block/FVG proxies, and confirmation are linked to one composite score rather than treating the method name as a signal.", "No standalone signal is emitted from a methodology name; its measurable components must be present." )
    if group == "candlestick_pattern":
        return ("OHLC_HEURISTIC_DETECTOR", "Evaluates body-to-range and upper/lower-wick ratios, candle direction, multi-candle order, relative body/range size, prior trend/location, genuine gaps where required, and follow-through. Reversal shapes are contextual rather than standalone entries.", "Readable visible candle bodies/wicks; calibrated price-axis OHLC is preferred, otherwise screen-pixel OHLC proxy is marked heuristic." )
    if group == "classical_chart_pattern":
        return ("SWING_GEOMETRY_HEURISTIC_DETECTOR", "Searches rolling swing pivots and relative highs/lows for symmetry, necklines, compression/expansion, flags/wedges/triangles, rounded formations, and breakout confirmation; incomplete formations remain direction-neutral.", "Enough uninterrupted visible candles to form pivots; the pattern is not considered confirmed until the relevant boundary/neckline is closed through." )
    return ("STRUCTURE_OR_SMC_HEURISTIC", "Evaluates pivots, HH/HL/LH/LL, trend/regime, range boundaries, support/resistance touches, close-through breaks, later retests, liquidity sweeps, displacement, FVG/imbalance, order-block/retest and location confluence. Related aliases are grouped to avoid double-counting one event.", "Visible OHLC sequence; actual order-book liquidity, institutional intent and exact broker prices are not inferred from colored pixels alone." )


_V10_REQUESTED_ANALYSIS_CATALOG = []
for _v10_name in _V10_CATALOG_NAMES:
    _v10_group = _v10_feature_group(_v10_name)
    _v10_status, _v10_rule, _v10_req = _v10_feature_algorithm(_v10_name, _v10_group)
    _V10_REQUESTED_ANALYSIS_CATALOG.append({
        "name": _v10_name,
        "key": _v10_feature_key(_v10_name),
        "group": _v10_group,
        "implementation_status": _v10_status,
        "algorithm": _v10_rule,
        "data_requirement": _v10_req,
        "match_aliases": list(dict.fromkeys(_V10_CATALOG_ALIASES.get(_v10_name, [_v10_feature_key(_v10_name)]))),
    })


def _core_requested_context_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Add missing named, rule-based structure events into the existing scored pattern pipe."""
    rows = list(candles or [])
    n = len(rows)
    if n < 6:
        return []
    ohlc = [_candle_proxy_ohlc(row) for row in rows]
    opens = np.asarray([v[0] for v in ohlc], dtype=float)
    highs = np.asarray([v[1] for v in ohlc], dtype=float)
    lows = np.asarray([v[2] for v in ohlc], dtype=float)
    closes = np.asarray([v[3] for v in ohlc], dtype=float)
    ranges = np.maximum(highs - lows, 1e-9)
    typical_range = max(1e-9, float(np.median(ranges[-min(30, n):])))
    tol = max(0.12 * typical_range, 1e-9)
    out: List[Dict[str, Any]] = []

    def add(name: str, bias: float, start: int, end: int, strength: float, context: str,
            confirmed: bool = False, family: str = "structure") -> None:
        out.append({
            "name": name, "bias": float(clamp(bias, -1.0, 1.0)), "confirmed": bool(confirmed),
            "candle_indices": list(range(max(0, start) + 1, min(n - 1, end) + 2)),
            "strength": round(float(clamp(strength, 0.05, 0.90)), 3),
            "raw_strength": round(float(clamp(strength, 0.05, 0.90)), 3),
            "context": context,
            "pattern_family": family,
            "measurement_basis": "visual OHLC estimate; normalized pixel proxy unless validated price-axis calibration is available",
            "not_a_calibrated_probability": True,
        })

    def has_break(start: int, end: int) -> bool:
        return not any(bool(rows[p].get("sequence_break_before")) for p in range(start + 1, end + 1))

    # Regime / rectangle: detect a compressed, repeatedly-tested channel rather than
    # naming every small range a rectangle. These are neutral context, not trade votes.
    w = min(20, n)
    s = n - w
    window_hi, window_lo = float(np.max(highs[s:])), float(np.min(lows[s:]))
    span = max(typical_range, window_hi - window_lo)
    high_touch_count = int(np.sum(highs[s:] >= window_hi - 0.22 * typical_range))
    low_touch_count = int(np.sum(lows[s:] <= window_lo + 0.22 * typical_range))
    close_slope = float(np.polyfit(np.arange(w, dtype=float), closes[s:], 1)[0]) if w >= 3 else 0.0
    path = float(np.sum(np.abs(np.diff(closes[s:])))) if w >= 2 else 0.0
    efficiency = abs(float(closes[-1] - closes[s])) / max(typical_range, path, 1e-9)
    compressed_sideways = abs(close_slope) <= 0.14 * typical_range and efficiency <= 0.38
    if has_break(s, n - 1) and compressed_sideways:
        add("SIDEWAYS_MARKET", 0.0, s, n - 1, 0.20,
            "Low directional efficiency and a small normalized slope over the recent window; range context only.", False, "regime")
        add("CONSOLIDATION", 0.0, s, n - 1, 0.20,
            "Recent closes are compressed/sideways; a later boundary close is needed for direction.", False, "regime")
        add("TRADING_RANGE", 0.0, s, n - 1, 0.24,
            "Recent range with limited net progress relative to traveled distance; use its high/low as boundaries.", False, "chart_pattern")
        if high_touch_count >= 2 and low_touch_count >= 2 and span <= 10.0 * typical_range:
            add("RECTANGLE_PATTERN", 0.0, s, n - 1, 0.28,
                "Approximately horizontal range boundaries have repeated upper/lower tests; neutral until breakout and hold.", False, "chart_pattern")

    # Horizontal support/resistance proxy: repeated tests of extrema; zones are neutral
    # unless the latest candle confirms a rejection or a close-through breakout.
    prior_end = n - 1
    recent_start = max(0, prior_end - min(30, n - 1))
    if prior_end - recent_start >= 4:
        prior_highs, prior_lows = highs[recent_start:prior_end], lows[recent_start:prior_end]
        r_level = float(np.max(prior_highs))
        s_level = float(np.min(prior_lows))
        r_touches = int(np.sum(np.abs(prior_highs - r_level) <= max(tol, 0.18 * typical_range)))
        s_touches = int(np.sum(np.abs(prior_lows - s_level) <= max(tol, 0.18 * typical_range)))
        if r_touches >= 2 or s_touches >= 2:
            add("SUPPORT_AND_RESISTANCE", 0.0, recent_start, n - 1, 0.24,
                f"Range-edge clusters from visible highs/lows; prior resistance touches={r_touches}, support touches={s_touches}.", False, "location")
            add("HORIZONTAL_SUPPORT_AND_RESISTANCE", 0.0, recent_start, n - 1, 0.25,
                "Horizontal levels are estimated by repeated extreme tests; pixel levels are not exact broker prices.", False, "location")
            add("SUPPLY_AND_DEMAND_ZONES", 0.0, recent_start, n - 1, 0.24,
                "Repeated range-edge reactions serve as supply/demand candidates; not true resting-order data.", False, "location")
        ema9 = float(_ema(closes, min(9, n))[-1])
        ema21 = float(_ema(closes, min(21, n))[-1])
        if abs(closes[-1] - ema9) <= 0.65 * typical_range or abs(closes[-1] - ema21) <= 0.65 * typical_range:
            add("DYNAMIC_SUPPORT_AND_RESISTANCE", 0.0, max(0, n - 21), n - 1, 0.20,
                "Price is near a visually estimated EMA 9/21 dynamic reference; the average is context, not a guaranteed floor/ceiling.", False, "location")

    # Confirmed swing pivots and BOS / CHoCH / MSS. A break is tested on the last close
    # against pivots strictly before the latest candle to prevent look-ahead leakage.
    swing_highs: List[int] = []
    swing_lows: List[int] = []
    scan_start = max(2, n - 60)
    for i in range(scan_start, n - 2):
        if highs[i] >= max(np.max(highs[i - 2:i]), np.max(highs[i + 1:i + 3])):
            swing_highs.append(i)
        if lows[i] <= min(np.min(lows[i - 2:i]), np.min(lows[i + 1:i + 3])):
            swing_lows.append(i)
    trend_sample = closes[max(0, n - 9):n - 1]
    prior_trend = "SIDEWAYS"
    if len(trend_sample) >= 4:
        slope = float(np.polyfit(np.arange(len(trend_sample), dtype=float), trend_sample, 1)[0])
        delta = float(trend_sample[-1] - trend_sample[0])
        if slope > 0 and delta > 0.45 * typical_range:
            prior_trend = "UP"
        elif slope < 0 and delta < -0.45 * typical_range:
            prior_trend = "DOWN"
    break_direction = None
    broken_level = None
    pivot_hi = max((float(highs[i]) for i in swing_highs if i < n - 1), default=None)
    pivot_lo = min((float(lows[i]) for i in swing_lows if i < n - 1), default=None)
    if pivot_hi is not None and closes[-1] > pivot_hi + tol:
        break_direction, broken_level = "UP", pivot_hi
    elif pivot_lo is not None and closes[-1] < pivot_lo - tol:
        break_direction, broken_level = "DOWN", pivot_lo
    if break_direction:
        bias = 0.38 if break_direction == "UP" else -0.38
        start_idx = max(0, n - 6)
        add("BREAK_OF_STRUCTURE_BOS", bias, start_idx, n - 1, 0.43,
            f"Latest close broke a previously confirmed swing {'high' if break_direction == 'UP' else 'low'}; level proxy={broken_level:.5g}.", True, "structure")
        add("MARKET_STRUCTURE_SHIFT_MSS", bias, start_idx, n - 1, 0.38,
            "Market-structure shift candidate from close-through of a confirmed swing; follow-through remains important.", True, "structure_alias")
        reversal = (prior_trend == "DOWN" and break_direction == "UP") or (prior_trend == "UP" and break_direction == "DOWN")
        if reversal:
            add("CHANGE_OF_CHARACTER_CHOCH", bias, start_idx, n - 1, 0.42,
                f"Close-through break points against the prior {prior_trend.lower()} slope; CHoCH remains a visual OHLC proxy.", True, "structure_alias")
        if break_direction == "UP":
            add("TRENDLINE_BREAK_UP", 0.28, start_idx, n - 1, 0.30,
                "Upside swing break accompanies a close above a recent structural ceiling.", True, "trendline")
        else:
            add("TRENDLINE_BREAK_DOWN", -0.28, start_idx, n - 1, 0.30,
                "Downside swing break accompanies a close below a recent structural floor.", True, "trendline")
        # Retest is only valid if a later candle touches the old level and closes on the
        # breakout side; the breakout candle itself cannot serve as its own retest.
        if n >= 2 and broken_level is not None:
            prev_close = float(closes[-2])
            latest_touch = lows[-1] <= broken_level + tol if break_direction == "UP" else highs[-1] >= broken_level - tol
            held_side = closes[-1] >= broken_level - tol if break_direction == "UP" else closes[-1] <= broken_level + tol
            previous_break_seen = prev_close > broken_level + tol if break_direction == "UP" else prev_close < broken_level - tol
            if latest_touch and held_side and previous_break_seen:
                add("TRENDLINE_RETEST", bias * 0.7, n - 2, n - 1, 0.32,
                    "A later candle touched the broken level and closed on the breakout side.", True, "trendline")
                add("BREAKOUT_AND_RETEST", bias * 0.75, n - 2, n - 1, 0.34,
                    "Breakout is followed by a separate touch-and-hold candle.", True, "breakout")
    # Rejection / impulse / pullback descriptors are contextual, not standalone trades.
    body = abs(closes[-1] - opens[-1])
    upper = max(0.0, highs[-1] - max(opens[-1], closes[-1]))
    lower = max(0.0, min(opens[-1], closes[-1]) - lows[-1])
    if upper >= 1.4 * max(body, 1e-9) or lower >= 1.4 * max(body, 1e-9):
        add("REJECTION_CANDLE", 0.0, n - 1, n - 1, 0.24,
            "A long wick relative to the body indicates rejection/failed auction at one side; location sets direction.", False, "price_action")
    if body >= 1.45 * typical_range and body / max(ranges[-1], 1e-9) >= 0.58:
        add("IMPULSE", 0.18 if closes[-1] > opens[-1] else -0.18, n - 1, n - 1, 0.28,
            "Body expansion versus recent typical range; verify breakout context and next-candle acceptance.", False, "price_action")
    if n >= 4:
        last_move = closes[-1] - closes[-4]
        prior_move = closes[-4] - closes[-min(n, 8)] if n >= 8 else closes[-4] - closes[0]
        if abs(prior_move) > typical_range and last_move * prior_move < 0 and abs(last_move) < abs(prior_move):
            add("PULLBACK", 0.0, max(0, n - 4), n - 1, 0.22,
                "Short counter-move within a larger recent move; continuation requires the trend structure to hold.", False, "price_action")
    # Range and structural labels are direction-neutral in the scoring layer unless their
    # actual break/rejection event has a signed bias above.
    if n >= 8:
        add("RANGE_HIGH", 0.0, s, n - 1, 0.18, "Highest visible range boundary for the recent window.", False, "location")
        add("RANGE_LOW", 0.0, s, n - 1, 0.18, "Lowest visible range boundary for the recent window.", False, "location")
        if swing_highs:
            add("SWING_HIGH", 0.0, swing_highs[-1], swing_highs[-1], 0.18, "Last confirmed local swing-high pivot.", False, "location")
        if swing_lows:
            add("SWING_LOW", 0.0, swing_lows[-1], swing_lows[-1], 0.18, "Last confirmed local swing-low pivot.", False, "location")
    return out



def _supplemental_candle_and_smc_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """V10 extended scanner plus requested rectangle/BOS/CHoCH/trendline/context labels."""
    base = list(_core_supplemental_candle_and_smc_patterns(candles) or [])
    # This is the single integration point: base rules are reused, never reimplemented.
    base.extend(_v10_2_missing_candle_events(candles))
    extra = _v10_requested_context_patterns(candles)
    # Friendly canonical names for existing SMC detector events. These are aliases of
    # the same event and are grouped in scoring to prevent artificial multi-votes.
    names = {str(row.get("name") or "") for row in base + extra}
    if "BULLISH_ORDER_BLOCK_INVALIDATED_BEARISH_BREAKER" in names:
        n = len(candles)
        if n:
            extra.append({"name": "BEARISH_BREAKER_BLOCK", "bias": 0.0, "confirmed": True,
                "candle_indices": [max(1, n - 2), n], "strength": 0.22, "raw_strength": 0.22,
                "context": "Alias of an invalidated bullish order-block / bearish breaker event; not an independent vote.",
                "pattern_family": "order_block_alias", "not_a_calibrated_probability": True})
    if "BEARISH_ORDER_BLOCK_INVALIDATED_BULLISH_BREAKER" in names:
        n = len(candles)
        if n:
            extra.append({"name": "BULLISH_BREAKER_BLOCK", "bias": 0.0, "confirmed": True,
                "candle_indices": [max(1, n - 2), n], "strength": 0.22, "raw_strength": 0.22,
                "context": "Alias of an invalidated bearish order-block / bullish breaker event; not an independent vote.",
                "pattern_family": "order_block_alias", "not_a_calibrated_probability": True})
    if any("ACCUMULATION_MANIPULATION_DISTRIBUTION_AMD_PO3_" in name for name in names):
        n = len(candles)
        if n:
            extra.append({"name": "POWER_OF_THREE_PO3", "bias": 0.0, "confirmed": True,
                "candle_indices": [max(1, n - 17), n], "strength": 0.20, "raw_strength": 0.20,
                "context": "Alias of the detected AMD/range-sweep proxy; PO3 phase labels remain heuristic and are not an independent vote.",
                "pattern_family": "smc_sequence_alias", "not_a_calibrated_probability": True})
            extra.append({"name": "MARKET_MAKER_MODEL_SEQUENCE_PROXY", "bias": 0.0, "confirmed": True,
                "candle_indices": [max(1, n - 17), n], "strength": 0.20, "raw_strength": 0.20,
                "context": "A range/sweep/distribution-like sequence was measured; this is a heuristic proxy, not proof of a real market maker or institutional intent.",
                "pattern_family": "smc_sequence_alias", "measurement_basis": "visible OHLC sequence proxy", "not_a_calibrated_probability": True})
    unique: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for row in base + extra:
        key = (str(row.get("name") or ""), tuple(row.get("candle_indices") or []))
        old_row = unique.get(key)
        if old_row is None or (bool(row.get("confirmed")) and not bool(old_row.get("confirmed"))) or (bool(row.get("confirmed")) == bool(old_row.get("confirmed")) and float(row.get("strength") or 0.0) > float(old_row.get("strength") or 0.0)):
            unique[key] = row
    return list(unique.values())


def _core_v10_catalog_runtime_report(analysis: Dict[str, Any]) -> Dict[str, Any]:
    """Build a compact per-chart report showing detections versus required-source gaps."""
    patterns = list(analysis.get("patterns") or [])
    classical = (analysis.get("classical_chart_patterns") or {}).get("patterns") or []
    all_names = { _v10_feature_key(row.get("name")) for row in patterns + list(classical) if isinstance(row, dict) }
    all_raw_names = {str(row.get("name") or "").upper() for row in patterns + list(classical) if isinstance(row, dict)}
    n = int(parse_float(analysis.get("candle_count"), len(analysis.get("candles") or [])) or 0)
    structural = analysis.get("structural_context") or {}
    price_action = analysis.get("price_action_context") or {}
    online = analysis.get("online_context") or {}
    audit_rows = []
    matched = []
    conditional = []
    for feature in _V10_REQUESTED_ANALYSIS_CATALOG:
        name = feature["name"]
        aliases = feature["match_aliases"]
        hit_aliases = [alias for alias in aliases if any(
            _v10_feature_key(alias) == detected
            or (len(_v10_feature_key(alias)) >= 8 and _v10_feature_key(alias) in detected)
            for detected in all_names
        )]
        group = feature["group"]
        active = bool(hit_aliases)
        if name in _V10_METHODOLOGY_NAMES:
            active = n > 0
            hit_aliases = ["connected candle/structure/SMC feature pipeline"] if active else []
        elif name in _V10_MTF_NAMES:
            mtf = analysis.get("multi_timeframe_confirmation") or {}
            active = bool(mtf.get("available"))
            if active:
                hit_aliases = ["multi_timeframe_confirmation"]
            else:
                conditional.append(name)
        elif name in _V10_VOLUME_NAMES:
            volume_audit = ((analysis.get("connected_feature_audit") or {}).get("volume") or {})
            volume_profile = analysis.get("volume_profile") or {}
            active = bool(volume_audit.get("available") or volume_profile.get("available"))
            if not active:
                conditional.append(name)
        elif name in _V10_TIME_DEPENDENT_NAMES:
            ict = (analysis.get("connected_feature_audit") or {}).get("time_based_ict_setups") or {}
            active = bool(ict.get("available"))
            if not active:
                conditional.append(name)
        elif name == "Support and Resistance" or name == "Horizontal Support and Resistance" or name == "Supply and Demand Zones":
            active = bool(n >= 6 and (structural.get("available") or price_action.get("position_context")))
            if active and not hit_aliases:
                hit_aliases = ["measured support/resistance context"]
        elif name == "Dynamic Support and Resistance":
            active = bool(n >= 9 and (analysis.get("visual_indicators") or analysis.get("technical_indicators") or price_action.get("components")))
            if active and not hit_aliases:
                hit_aliases = ["EMA / rolling structure context"]
        elif name == "Market Structure":
            active = bool(n >= 5 and (analysis.get("market_structure") or structural.get("available") or price_action.get("components")))
            if active and not hit_aliases:
                hit_aliases = ["swing structure and trend context"]
        elif name in {"Uptrend", "Downtrend", "Sideways Market"}:
            trend = str(analysis.get("trend") or price_action.get("trend") or "").upper()
            if name == "Uptrend": active = trend in {"UP", "UPTREND", "BULLISH"}
            elif name == "Downtrend": active = trend in {"DOWN", "DOWNTREND", "BEARISH"}
            else: active = trend in {"SIDEWAYS", "RANGE", "CHOPPY", "CONSOLIDATION"} or "SIDEWAYS_MARKET" in all_raw_names
            if active and not hit_aliases:
                hit_aliases = [f"trend/regime={trend}"]
        status = feature["implementation_status"]
        audit_rows.append({
            "name": name,
            "group": group,
            "implementation_status": status,
            "evaluated_for_this_chart": bool(n > 0 and status not in {"CONDITIONAL_TIMESTAMPED_DATA", "CONDITIONAL_MULTITIMEFRAME_DATA", "CONDITIONAL_VERIFIED_VOLUME"} or active),
            "matched_this_chart": bool(active),
            "matched_detector_aliases": hit_aliases,
            "algorithm": feature["algorithm"],
            "data_requirement": feature["data_requirement"],
        })
        if active:
            matched.append(name)
    count_by_status = Counter(row["implementation_status"] for row in audit_rows)
    return {
        "catalog_version": "10.1-requested-pattern-and-strategy-coverage",
        "requested_item_count": len(audit_rows),
        "evaluated_items": sum(bool(row["evaluated_for_this_chart"]) for row in audit_rows),
        "matched_items_on_this_chart": len(matched),
        "conditional_data_items_unavailable": sorted(set(conditional)),
        "implementation_status_counts": dict(count_by_status),
        "matched_features": matched,
        "all_requested_features": audit_rows,
        "score_integration": "Detected directional candle/structure events enter the existing pattern confirmation/context-weighting/composite-score pipeline. Neutral structure tags provide context only. ICT session, MTF, and volume concepts remain unavailable until their required source data exists.",
        "measurement_limit": "Visual OHLC estimates support heuristic pattern screening; screenshot colors alone do not provide true exchange volume, order-book liquidity, institutional intent, guaranteed future direction, or calibrated win probability.",
    }



def _v10_catalog_regression_tests() -> int:
    """Offline tests for catalog completeness and the newly connected structure events."""
    checks: List[Tuple[str, bool]] = []
    def check(label: str, condition: Any) -> None:
        checks.append((label, bool(condition)))

    check("V10.1 catalog includes all 169 supplied names without duplicates",
          len(_V10_CATALOG_NAMES) == 169 and len(set(_V10_CATALOG_NAMES)) == 169)
    check("V10.1 catalog records an algorithm and evidence requirement for every entry",
          len(_V10_REQUESTED_ANALYSIS_CATALOG) == 169 and all(
              row.get("algorithm") and row.get("data_requirement") and row.get("implementation_status")
              for row in _V10_REQUESTED_ANALYSIS_CATALOG))
    check("session-specific ICT concepts explicitly require timestamped session data",
          all(next(row for row in _V10_REQUESTED_ANALYSIS_CATALOG if row["name"] == name)["implementation_status"] == "CONDITIONAL_TIMESTAMPED_DATA"
              for name in _V10_TIME_DEPENDENT_NAMES))
    check("volume explicitly requires valid declared OHLCV rather than candle color",
          next(row for row in _V10_REQUESTED_ANALYSIS_CATALOG if row["name"] == "Volume")["implementation_status"] == "CONDITIONAL_VERIFIED_VOLUME")

    # Synthetic price sequence with confirmed earlier swing pivots and a close through the
    # latest pivot-high; all predictions use the current/past sequence, no future candle.
    closes = [120, 121, 116, 118, 113, 115, 110, 112, 107, 109,
              104, 106, 101, 103, 98, 100, 95, 97, 132]
    candles: List[Dict[str, Any]] = []
    previous = closes[0] + 0.25
    for i, close in enumerate(closes, start=1):
        open_ = previous
        high = max(open_, close) + 0.18
        low = min(open_, close) - 0.18
        candles.append({
            "index": i, "estimated_open_price": open_, "estimated_high_price": high,
            "estimated_low_price": low, "estimated_close_price": close,
            "estimated_open_pixel": -open_, "estimated_close_pixel": -close,
            "wick_top_pixel": -high, "wick_bottom_pixel": -low,
            "body_top_pixel": -max(open_, close), "body_bottom_pixel": -min(open_, close),
            "body_height_pixels": max(1.0, abs(close-open_)), "upper_wick_pixels": 0.18,
            "lower_wick_pixels": 0.18, "width": 5, "height": max(2, int(high-low)),
            "x": i*8, "y": int(-high), "color": "GREEN" if close >= open_ else "RED",
            "sequence_break_before": False,
        })
        previous = close
    detected = _v10_requested_context_patterns(candles)
    detected_names = {row.get("name") for row in detected}
    check("new structure scanner detects a close-through Break of Structure and MSS alias",
          "BREAK_OF_STRUCTURE_BOS" in detected_names and "MARKET_STRUCTURE_SHIFT_MSS" in detected_names)
    check("new structure scanner labels countertrend break as CHoCH when applicable",
          "CHANGE_OF_CHARACTER_CHOCH" in detected_names)
    merged = _supplemental_candle_and_smc_patterns(candles)
    check("new structure events are connected to the pattern scanner used by the forecast",
          any(row.get("name") == "BREAK_OF_STRUCTURE_BOS" for row in merged))
    report = _v10_catalog_runtime_report({"candle_count": len(candles), "patterns": merged,
        "structural_context": {"available": True}, "price_action_context": {"components": {}}})
    check("per-chart coverage report identifies matches and retains the full 169-item registry",
          report.get("requested_item_count") == 169 and len(report.get("all_requested_features") or []) == 169
          and report.get("matched_items_on_this_chart", 0) > 0)
    check("new structural tags keep a directional sign only on actual measured break events",
          all(float(row.get("bias") or 0.0) == 0.0 for row in detected
              if row.get("name") in {"SIDEWAYS_MARKET", "CONSOLIDATION", "TRADING_RANGE", "RECTANGLE_PATTERN", "SUPPORT_AND_RESISTANCE", "HORIZONTAL_SUPPORT_AND_RESISTANCE", "SUPPLY_AND_DEMAND_ZONES", "DYNAMIC_SUPPORT_AND_RESISTANCE", "RANGE_HIGH", "RANGE_LOW", "SWING_HIGH", "SWING_LOW"}))

    for label, ok in checks:
        print(("PASS" if ok else "FAIL") + " | " + label, flush=True)
    passed = sum(ok for _, ok in checks)
    print(f"BOT 10.1 CATALOG/STRUCTURE REGRESSION: {passed}/{len(checks)} passed", flush=True)
    return 0 if passed == len(checks) else 1


# ---------------- V11.0 FUNCTIONAL PATTERN-TO-SCORE WIRING ----------------
# This layer closes gaps between the requested 169-item registry and the events
# actually emitted by the candle/structure scanners. Pattern aliases point to the
# same measured event; they are not added as separate directional votes.
V11_MODEL_VERSION = "putra_trading_bot_11_0_consolidated_pattern_engine"


def _v10_requested_context_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Supplement the existing context scanner with named HH/HL/LH/LL and regime labels."""
    rows = list(candles or [])
    n = len(rows)
    out = list(_core_requested_context_patterns(rows) or [])
    if n < 6:
        return out
    vals = [_candle_proxy_ohlc(row) for row in rows]
    opens = np.asarray([v[0] for v in vals], dtype=float)
    highs = np.asarray([v[1] for v in vals], dtype=float)
    lows = np.asarray([v[2] for v in vals], dtype=float)
    closes = np.asarray([v[3] for v in vals], dtype=float)
    scale = max(1e-9, float(np.median((highs - lows)[-min(30, n):])))
    tol = max(0.16 * scale, 1e-9)

    def add_context(name: str, start: int, end: int, message: str, family: str = "market_structure") -> None:
        out.append({
            "name": name, "bias": 0.0, "confirmed": True,
            "candle_indices": list(range(max(0, start) + 1, min(n - 1, end) + 2)),
            "strength": 0.22, "raw_strength": 0.22, "context": message,
            "pattern_family": family,
            "measurement_basis": "visible OHLC swing comparison; pixel-derived values are proxies unless axis calibration is validated",
            "not_a_calibrated_probability": True,
            "direction_neutral_context": True,
        })

    # Local swing pivots are confirmed only after two right-side bars exist. This avoids
    # treating a still-forming high/low as a completed HH/HL/LH/LL pivot.
    pivot_highs: List[int] = []
    pivot_lows: List[int] = []
    for i in range(2, n - 2):
        if highs[i] >= max(float(np.max(highs[i-2:i])), float(np.max(highs[i+1:i+3]))):
            pivot_highs.append(i)
        if lows[i] <= min(float(np.min(lows[i-2:i])), float(np.min(lows[i+1:i+3]))):
            pivot_lows.append(i)
    # Collapse adjacent/nearby equal pivot candidates into one swing. A wide or plateaued
    # candle can otherwise register as two neighbouring pivots and hide the real HH/HL
    # progression from the latest two swing points.
    def collapse_pivot_plateaus(indices: List[int], series: np.ndarray, find_high: bool) -> List[int]:
        compact: List[int] = []
        for idx in indices:
            if compact and idx - compact[-1] <= 2 and abs(float(series[idx]) - float(series[compact[-1]])) <= tol:
                old_idx = compact[-1]
                if (find_high and series[idx] >= series[old_idx]) or (not find_high and series[idx] <= series[old_idx]):
                    compact[-1] = idx
            else:
                compact.append(idx)
        return compact
    pivot_highs = collapse_pivot_plateaus(pivot_highs, highs, True)
    pivot_lows = collapse_pivot_plateaus(pivot_lows, lows, False)
    high_state = low_state = "UNKNOWN"
    if len(pivot_highs) >= 2:
        p1, p2 = pivot_highs[-2:]
        d = float(highs[p2] - highs[p1])
        if d > tol:
            high_state = "HH"
            add_context("HIGHER_HIGH", p1, p2, f"Latest confirmed swing high exceeded the previous pivot by {d:.5g} normalized price units.")
        elif d < -tol:
            high_state = "LH"
            add_context("LOWER_HIGH", p1, p2, f"Latest confirmed swing high was below the previous pivot by {abs(d):.5g} normalized price units.")
    if len(pivot_lows) >= 2:
        p1, p2 = pivot_lows[-2:]
        d = float(lows[p2] - lows[p1])
        if d > tol:
            low_state = "LL"
            add_context("LOWER_LOW", p1, p2, f"Latest confirmed swing low fell below the previous pivot by {d:.5g} normalized price units.")
        elif d < -tol:
            low_state = "HL"
            add_context("HIGHER_LOW", p1, p2, f"Latest confirmed swing low held above the previous pivot by {abs(d):.5g} normalized price units.")
    add_context("MARKET_STRUCTURE", max(0, n - 20), n - 1,
                f"Swing-structure summary: highs={high_state}, lows={low_state}; pivots need two later bars to confirm.")
    if high_state == "HH" and low_state == "HL":
        add_context("UPTREND", max(0, n - 20), n - 1, "Both recent confirmed swing highs and lows are rising; trend label is context, not an automatic BUY.")
    elif high_state == "LH" and low_state == "LL":
        add_context("DOWNTREND", max(0, n - 20), n - 1, "Both recent confirmed swing highs and lows are falling; trend label is context, not an automatic SELL.")

    # Detect a genuine expanding wedge/formation as a shape, not merely a large candle.
    if n >= 18:
        w = min(24, n)
        start = n - w
        x = np.arange(w, dtype=float)
        hi_slope, hi_intercept = np.polyfit(x, highs[start:], 1)
        lo_slope, lo_intercept = np.polyfit(x, lows[start:], 1)
        start_span = max(scale, float(highs[start] - lows[start]))
        end_span = max(scale, float(highs[-1] - lows[-1]))
        expanding = end_span >= 1.18 * start_span and end_span >= 1.4 * scale
        boundary_tol = 0.10 * scale
        up_break = closes[-1] > float(hi_slope * (w - 1) + hi_intercept) + boundary_tol
        down_break = closes[-1] < float(lo_slope * (w - 1) + lo_intercept) - boundary_tol
        if expanding and hi_slope > 0 and lo_slope > 0 and hi_slope > lo_slope:
            bias = 0.35 if up_break else (-0.35 if down_break else 0.0)
            out.append({"name": "ASCENDING_BROADENING_WEDGE", "bias": bias, "confirmed": bool(up_break or down_break),
                "candle_indices": list(range(start + 1, n + 1)), "strength": 0.34, "raw_strength": 0.34,
                "context": "Rising, expanding upper/lower boundaries; direction is only assigned after a measured close beyond a boundary.",
                "pattern_family": "chart_pattern", "measurement_basis": "visible OHLC regression proxy", "not_a_calibrated_probability": True})
            out.append({"name": "BROADENING_FORMATION", "bias": bias, "confirmed": bool(up_break or down_break),
                "candle_indices": list(range(start + 1, n + 1)), "strength": 0.30, "raw_strength": 0.30,
                "context": "Alias of the rising broadening wedge; counted as the same event, not an independent vote.",
                "pattern_family": "chart_pattern_alias", "measurement_basis": "visible OHLC regression proxy", "not_a_calibrated_probability": True})
        elif expanding and hi_slope < 0 and lo_slope < 0 and lo_slope < hi_slope:
            bias = 0.35 if up_break else (-0.35 if down_break else 0.0)
            out.append({"name": "DESCENDING_BROADENING_WEDGE", "bias": bias, "confirmed": bool(up_break or down_break),
                "candle_indices": list(range(start + 1, n + 1)), "strength": 0.34, "raw_strength": 0.34,
                "context": "Falling, expanding upper/lower boundaries; direction is only assigned after a measured close beyond a boundary.",
                "pattern_family": "chart_pattern", "measurement_basis": "visible OHLC regression proxy", "not_a_calibrated_probability": True})
            out.append({"name": "BROADENING_FORMATION", "bias": bias, "confirmed": bool(up_break or down_break),
                "candle_indices": list(range(start + 1, n + 1)), "strength": 0.30, "raw_strength": 0.30,
                "context": "Alias of the falling broadening wedge; counted as the same event, not an independent vote.",
                "pattern_family": "chart_pattern_alias", "measurement_basis": "visible OHLC regression proxy", "not_a_calibrated_probability": True})
        elif expanding and (hi_slope >= 0 >= lo_slope or hi_slope <= 0 <= lo_slope):
            out.append({"name": "BROADENING_FORMATION", "bias": 0.0, "confirmed": False,
                "candle_indices": list(range(start + 1, n + 1)), "strength": 0.27, "raw_strength": 0.27,
                "context": "Upper/lower range is expanding, but the directions do not define an ascending/descending wedge; neutral until confirmed.",
                "pattern_family": "chart_pattern", "measurement_basis": "visible OHLC regression proxy", "not_a_calibrated_probability": True})

    # Remove only exact duplicate names at the same candle indices; related event names
    # remain available for the report/visual annotation, while score grouping de-correlates them.
    unique: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for row in out:
        key = (str(row.get("name") or ""), tuple(row.get("candle_indices") or []))
        if key not in unique or float(row.get("strength") or 0.0) > float(unique[key].get("strength") or 0.0):
            unique[key] = row
    return list(unique.values())



def _v10_2_missing_candle_events(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Explicit directional marubozu variants missing from older generic marubozu labels."""
    rows = list(candles or [])
    n = len(rows)
    if not n:
        return []
    values = [_candle_proxy_ohlc(row) for row in rows]
    ranges = np.asarray([max(1e-9, h - l) for _o, h, l, _c in values], dtype=float)
    bodies = np.asarray([abs(c - o) for o, _h, _l, c in values], dtype=float)
    typical_body = max(1e-9, float(np.median(bodies[-min(30, n):])))
    found: List[Dict[str, Any]] = []
    for i, (o, h, l, c) in enumerate(values):
        if i and bool(rows[i].get("sequence_break_before")):
            continue
        r = ranges[i]
        body = bodies[i]
        upper = max(0.0, h - max(o, c))
        lower = max(0.0, min(o, c) - l)
        # A true directional marubozu needs a large body and very small combined shadows.
        # Keep this stricter than the broader belt-hold/opening/closing-marubozu tests.
        if body / r >= 0.78 and (upper + lower) / r <= 0.22 and body >= 0.90 * typical_body:
            if c > o:
                name, bias = "BULLISH_MARUBOZU", 0.43
            elif c < o:
                name, bias = "BEARISH_MARUBOZU", -0.43
            else:
                continue
            found.append({"name": name, "bias": bias, "confirmed": False,
                "candle_indices": [i + 1], "strength": 0.43, "raw_strength": 0.43,
                "context": "Large directional real body with small combined shadows; still requires trend/location and follow-through confirmation.",
                "pattern_family": "single_candle", "measurement_basis": "visible OHLC estimate; screen-pixel proxy where uncalibrated", "not_a_calibrated_probability": True})
    return found



def _detect_classical_chart_patterns(candles: List[Dict[str, Any]]) -> Dict[str, Any]:
    """V11.0: add explicit broadening-wedge aliases to the existing chart-pattern output."""
    result = dict(_core_detect_classical_chart_patterns(candles) or {})
    rows = list(candles or [])
    n = len(rows)
    patterns = list(result.get("patterns") or [])
    lines = list(result.get("line_segments") or [])
    names = {str(item.get("name") or "") for item in patterns if isinstance(item, dict)}
    if n >= 18:
        vals = [_candle_proxy_ohlc(row) for row in rows[-min(24, n):]]
        m = len(vals)
        highs = np.asarray([v[1] for v in vals], dtype=float)
        lows = np.asarray([v[2] for v in vals], dtype=float)
        closes = np.asarray([v[3] for v in vals], dtype=float)
        x = np.arange(m, dtype=float)
        h_slope, h_intercept = np.polyfit(x, highs, 1)
        l_slope, l_intercept = np.polyfit(x, lows, 1)
        typical = max(1e-9, float(np.median(highs - lows)))
        start_span = max(typical, float(highs[0] - lows[0]))
        end_span = max(typical, float(highs[-1] - lows[-1]))
        expanding = end_span >= 1.18 * start_span and end_span >= 1.4 * typical
        top_now = float(h_slope * (m - 1) + h_intercept)
        bottom_now = float(l_slope * (m - 1) + l_intercept)
        close = float(closes[-1])
        up_break = close > top_now + 0.10 * typical
        down_break = close < bottom_now - 0.10 * typical
        if expanding:
            candidates: List[Tuple[str, str]] = []
            if h_slope > 0 and l_slope > 0 and h_slope > l_slope:
                candidates.append(("ASCENDING_BROADENING_WEDGE", "Rising upper and lower boundaries are diverging."))
            elif h_slope < 0 and l_slope < 0 and l_slope < h_slope:
                candidates.append(("DESCENDING_BROADENING_WEDGE", "Falling upper and lower boundaries are diverging."))
            candidates.append(("BROADENING_FORMATION", "The recent high-low envelope is expanding."))
            for name, description in candidates:
                if name in names:
                    continue
                bias = (0.36 if up_break else -0.36 if down_break else 0.0)
                item = {"name": name, "bias": bias, "confirmed": bool(up_break or down_break),
                    "state": "CONFIRMED_BREAKOUT" if up_break or down_break else "FORMING_OR_UNCONFIRMED",
                    "candle_indices": list(range(n - m + 1, n + 1)),
                    "context": description + " Direction is assigned only when the last close exceeds a measured boundary.",
                    "strength": 0.36 if up_break or down_break else 0.27,
                    "measurement_basis": "visible OHLC regression proxy", "not_a_calibrated_probability": True}
                patterns.append(item)
                names.add(name)
                lines.extend([
                    {"pattern": name, "label": name + " UPPER", "x1_index": n - m, "x2_index": n - 1,
                     "y1_price": float(h_intercept), "y2_price": top_now, "confirmed": bool(up_break or down_break)},
                    {"pattern": name, "label": name + " LOWER", "x1_index": n - m, "x2_index": n - 1,
                     "y1_price": float(l_intercept), "y2_price": bottom_now, "confirmed": bool(up_break or down_break)},
                ])
    # Keep every unique named pattern from the base detector plus the missing formations;
    # no fixed last-20 truncation here, because the GUI/report should be able to audit all.
    dedup: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for item in patterns:
        key = (str(item.get("name") or ""), tuple(item.get("candle_indices") or []))
        if key not in dedup or (bool(item.get("confirmed")) and not bool(dedup[key].get("confirmed"))):
            dedup[key] = item
    result["patterns"] = list(dedup.values())
    result["line_segments"] = lines[-72:]
    result["requested_formation_count"] = len(result["patterns"])
    return result


def _v10_catalog_runtime_report(analysis: Dict[str, Any]) -> Dict[str, Any]:
    """V11.0 coverage audit: distinguish actually evaluated features from unavailable inputs."""
    report = _core_v10_catalog_runtime_report(analysis)
    n = int(parse_float(analysis.get("candle_count"), len(analysis.get("candles") or [])) or 0)
    source_conditional = {"CONDITIONAL_TIMESTAMPED_DATA", "CONDITIONAL_MULTITIMEFRAME_DATA", "CONDITIONAL_VERIFIED_VOLUME"}
    for row in report.get("all_requested_features") or []:
        group = str(row.get("group") or "")
        status = str(row.get("implementation_status") or "")
        active = bool(row.get("matched_this_chart"))
        if status == "CONDITIONAL_TIMESTAMPED_DATA":
            evaluated = active
            if not active and row.get("name") not in report.get("conditional_data_items_unavailable", []):
                report.setdefault("conditional_data_items_unavailable", []).append(row["name"])
        elif status == "CONDITIONAL_MULTITIMEFRAME_DATA":
            mtf = analysis.get("multi_timeframe_confirmation") or {}
            evaluated = bool(mtf.get("available"))
        elif status == "CONDITIONAL_VERIFIED_VOLUME":
            vol = ((analysis.get("connected_feature_audit") or {}).get("volume") or {})
            vol_profile = analysis.get("volume_profile") or {}
            evaluated = bool(vol.get("available") or vol_profile.get("available"))
        elif group == "candlestick_pattern":
            evaluated = n >= 1
        elif group == "classical_chart_pattern":
            evaluated = n >= 12
        elif status == "METHODOLOGY_APPLIED_TO_FEATURES":
            evaluated = n >= 1
        else:
            evaluated = n >= 6
        row["evaluated_for_this_chart"] = bool(evaluated)
        row["evaluation_note"] = ("Matched measured evidence" if active else
            "Algorithm ran; no qualifying evidence matched this chart" if evaluated else
            "Not evaluated: the visible sample or required source data is insufficient")
    report["evaluated_items"] = sum(bool(row.get("evaluated_for_this_chart")) for row in report.get("all_requested_features") or [])
    report["catalog_version"] = "11.0-consolidated-pattern-engine"
    report["score_integration"] = "Direction-bearing detector events feed the existing five-minute pattern/context composite; neutral structure, range, liquidity-location and methodology tags contribute context only. Aliases are audited but correlated labels do not become independent votes. Timestamped ICT sessions, higher timeframes and verified volume are conditional on real source data."
    report["detector_wiring"] = {
        "candlestick_events": "_extended_candle_patterns + _supplemental_candle_and_smc_patterns -> confirmation/context adjustment -> recency/grouped pattern bias -> 5-minute forecast score",
        "chart_formations": "_detect_classical_chart_patterns -> pattern names/line segments + classical-pattern bias -> 5-minute forecast score",
        "market_structure_smc": "swing pivots, BOS/CHoCH/MSS, liquidity sweeps, order-block/FVG proxies, premium/discount and retest features -> unified pattern/context score",
        "duplicate_control": "same-name same-index duplicates removed; same-event aliases explicitly grouped; neutral labels carry zero directional bias",
    }
    return report



def _v11_regression_tests() -> int:
    """Focused tests for detector-to-catalog aliases and newly added feature wiring."""
    checks: List[Tuple[str, bool]] = []
    def check(label: str, condition: Any) -> None:
        checks.append((label, bool(condition)))

    check("V11.0 keeps every requested feature name exactly once with algorithm and data requirements",
          len(_V10_CATALOG_NAMES) == 169 and len(set(_V10_CATALOG_NAMES)) == 169
          and len(_V10_REQUESTED_ANALYSIS_CATALOG) == 169
          and all(row.get("algorithm") and row.get("data_requirement") and row.get("match_aliases")
                  for row in _V10_REQUESTED_ANALYSIS_CATALOG))
    check("V11.0 maps all requested marubozu variants to direction-specific detector events",
          _V10_CATALOG_ALIASES.get("Bullish Marubozu") == ["BULLISH_MARUBOZU"]
          and "BEARISH_MARUBOZU" in _V10_CATALOG_ALIASES.get("Bearish Marubozu", []))
    check("V11.0 links the classic reversal, chart and SMC categories to measurable names",
          all(_V10_CATALOG_ALIASES.get(name) for name in (
              "Bullish Engulfing", "Head and Shoulders", "Ascending Broadening Wedge",
              "Failed Breakout", "Higher High (HH)", "Liquidity Sweep", "Bullish Order Block",
              "Fair Value Gap (FVG)", "Market Maker Model")))
    check("V11.0 keeps every feature alias unique instead of stacking repeated votes",
          all(len(row.get("match_aliases") or []) == len(set(row.get("match_aliases") or []))
              for row in _V10_REQUESTED_ANALYSIS_CATALOG))
    check("V11.0 treats Price Action Trading, Naked Chart Trading and SMC as applied methods, not fake standalone signals",
          all(next(row for row in _V10_REQUESTED_ANALYSIS_CATALOG if row["name"] == name)["implementation_status"] == "METHODOLOGY_APPLIED_TO_FEATURES"
              for name in ("Price Action Trading", "Naked Chart Trading", "Smart Money Concepts (SMC)")))
    # Guard against the earlier patch-on-patch structure: each public pipeline entry point
    # must be defined once. Core helpers are separate functions and do not redefine the API.
    try:
        tree = ast.parse(Path(__file__).read_text(encoding="utf-8"))
        definition_counts = Counter(node.name for node in ast.walk(tree) if isinstance(node, ast.FunctionDef))
        # V13 intentionally wraps these two scanners once to normalize structured OHLC
        # inputs and append timestamp/declared-volume events while preserving the V11 core.
        public_pipeline = ("analyze_candles", "diagnostics", "_v10_requested_context_patterns")
        unique_public_pipeline = (
            all(definition_counts[name] == 1 for name in public_pipeline)
            and definition_counts["_v10_catalog_runtime_report"] == 2
            and definition_counts["_supplemental_candle_and_smc_patterns"] == 2
            and definition_counts["_detect_classical_chart_patterns"] == 2
            and definition_counts["_extended_candle_patterns"] == 2
            and "_V13_PREVIOUS_SUPPLEMENTAL_PATTERNS" in Path(__file__).read_text(encoding="utf-8") 
        )
        detector_functions = {"_extended_candle_patterns", "_core_supplemental_candle_and_smc_patterns",
            "_supplemental_candle_and_smc_patterns", "_core_detect_classical_chart_patterns",
            "_detect_classical_chart_patterns", "_core_requested_context_patterns",
            "_v10_requested_context_patterns", "_v10_2_missing_candle_events",
            "_apply_pattern_context", "_weighted_recent_pattern_bias",
            "_enhanced_price_action_context", "_structural_candle_context"}
        detector_literals = {node.value for fn in ast.walk(tree) if isinstance(fn, ast.FunctionDef) and fn.name in detector_functions
            for node in ast.walk(fn) if isinstance(node, ast.Constant) and isinstance(node.value, str)
            and re.fullmatch(r"[A-Z][A-Z0-9_]{2,}", node.value)}
        data_or_method_statuses = {"METHODOLOGY_APPLIED_TO_FEATURES", "CONDITIONAL_TIMESTAMPED_DATA",
            "CONDITIONAL_MULTITIMEFRAME_DATA", "CONDITIONAL_VERIFIED_VOLUME", "HEURISTIC_SEQUENCE_PROXY"}
        unmapped_price_features = [row["name"] for row in _V10_REQUESTED_ANALYSIS_CATALOG
            if row["implementation_status"] not in data_or_method_statuses
            and not any(alias in detector_literals for alias in row.get("match_aliases", []))]
        feature_detector_coverage = not unmapped_price_features
    except Exception:
        unique_public_pipeline = False
        feature_detector_coverage = False
    check("V13.0 keeps one primary pipeline entry point and only the documented scanner wrappers", unique_public_pipeline)
    check("V11.0 connects every price-data-driven catalog item to an actual detector rule", feature_detector_coverage)

    # Rising pivot sequence to exercise HH/HL labels without adding directional votes.
    closes = [100, 102, 105, 103, 102, 105, 108, 106, 105, 108, 111, 109,
              108, 111, 114, 112, 111, 114, 117, 115, 114, 117, 120, 118]
    candles: List[Dict[str, Any]] = []
    previous = closes[0] - 0.5
    for i, close in enumerate(closes, start=1):
        open_ = previous
        high = max(open_, close) + 0.45
        low = min(open_, close) - 0.45
        candles.append({"index": i, "estimated_open_price": open_, "estimated_high_price": high,
            "estimated_low_price": low, "estimated_close_price": close,
            "estimated_open_pixel": -open_, "estimated_close_pixel": -close,
            "wick_top_pixel": -high, "wick_bottom_pixel": -low,
            "body_top_pixel": -max(open_, close), "body_bottom_pixel": -min(open_, close),
            "body_height_pixels": max(1.0, abs(close-open_)), "upper_wick_pixels": 0.45,
            "lower_wick_pixels": 0.45, "width": 5, "height": max(2, int(high-low)),
            "x": i*8, "y": int(-high), "color": "GREEN" if close >= open_ else "RED",
            "sequence_break_before": False})
        previous = close
    structure_names = {row.get("name") for row in _v10_requested_context_patterns(candles)}
    check("V11.0 emits a neutral MARKET_STRUCTURE context feature", "MARKET_STRUCTURE" in structure_names)
    check("V11.0 swing comparison emits HH/HL labels when the confirmed pivots rise",
          bool({"HIGHER_HIGH", "HIGHER_LOW", "UPTREND"} & structure_names))
    check("V11.0 structure labels are context-only and cannot create direction votes by themselves",
          all(float(row.get("bias") or 0.0) == 0.0 for row in _v10_requested_context_patterns(candles)
              if row.get("name") in {"MARKET_STRUCTURE", "HIGHER_HIGH", "HIGHER_LOW", "LOWER_HIGH", "LOWER_LOW", "UPTREND", "DOWNTREND"}))

    # Expanding, gently rising candle envelopes exercise the missing broadening-wedge detector.
    broadening: List[Dict[str, Any]] = []
    for i in range(24):
        mid = 100.0 + 0.50*i
        spread = 1.0 + 0.10*i
        op = mid - 0.08
        cl = mid + 0.08
        hi = mid + spread
        lo = mid - spread
        broadening.append({"index": i+1, "estimated_open_price": op, "estimated_high_price": hi,
            "estimated_low_price": lo, "estimated_close_price": cl,
            "estimated_open_pixel": -op, "estimated_close_pixel": -cl,
            "wick_top_pixel": -hi, "wick_bottom_pixel": -lo,
            "body_top_pixel": -max(op, cl), "body_bottom_pixel": -min(op, cl),
            "body_height_pixels": abs(cl-op), "upper_wick_pixels": hi-max(op,cl),
            "lower_wick_pixels": min(op,cl)-lo, "width": 5, "height": int(hi-lo),
            "x": i*8, "y": int(-hi), "color": "GREEN", "sequence_break_before": False})
    broad_ctx_names = {row.get("name") for row in _v10_requested_context_patterns(broadening)}
    broad_classic = _detect_classical_chart_patterns(broadening)
    broad_classic_names = {row.get("name") for row in broad_classic.get("patterns", [])}
    check("V11.0 recognizes expanding broadening formation / ascending broadening wedge candidates",
          bool({"BROADENING_FORMATION", "ASCENDING_BROADENING_WEDGE"} & (broad_ctx_names | broad_classic_names)))

    # A body with tiny shadows should create a direction-specific marubozu event in the scanner.
    maru = list(candles)
    op, cl = float(closes[-1]), float(closes[-1]) + 5.0
    maru.append({"index": len(maru)+1, "estimated_open_price": op, "estimated_high_price": cl+0.04,
        "estimated_low_price": op-0.04, "estimated_close_price": cl,
        "estimated_open_pixel": -op, "estimated_close_pixel": -cl,
        "wick_top_pixel": -(cl+0.04), "wick_bottom_pixel": -(op-0.04),
        "body_top_pixel": -cl, "body_bottom_pixel": -op, "body_height_pixels": cl-op,
        "upper_wick_pixels": 0.04, "lower_wick_pixels": 0.04, "width": 5,
        "height": int(cl-op+0.08), "x": (len(maru)+1)*8, "y": int(-(cl+0.04)),
        "color": "GREEN", "sequence_break_before": False})
    maru_names = {row.get("name") for row in _supplemental_candle_and_smc_patterns(maru)}
    check("V11.0 direction-specific marubozu detection is connected to the supplemental scan",
          "BULLISH_MARUBOZU" in maru_names)

    runtime = _v10_catalog_runtime_report({"candle_count": len(candles), "candles": candles,
        "patterns": _supplemental_candle_and_smc_patterns(candles),
        "trend": "UP", "structural_context": {"available": True},
        "price_action_context": {"trend": "UP", "components": {}}})
    check("V13.0 runtime coverage reports its model wiring and preserves the 169-item registry",
          runtime.get("catalog_version") == "13.0-one-callable-per-requested-feature"
          and runtime.get("requested_item_count") == 169
          and len(runtime.get("all_requested_features") or []) == 169
          and bool(runtime.get("detector_wiring")))
    check("V13.0 does not claim a named ICT session or real volume without source data",
          all(row.get("evaluated_for_this_chart") is False for row in runtime.get("all_requested_features", [])
              if row.get("name") in {"Judas Swing", "Silver Bullet Setup", "ICT Kill Zones", "Volume"}))

    for label, ok in checks:
        print(("PASS" if ok else "FAIL") + " | " + label, flush=True)
    passed = sum(ok for _, ok in checks)
    print(f"BOT 11.0 CONSOLIDATED-ENGINE REGRESSION: {passed}/{len(checks)} passed", flush=True)
    return 0 if passed == len(checks) else 1

def main() -> int:
    """Run the GUI and live selected-chart pipeline; no online research worker is started."""
    _enable_windows_dpi_awareness()
    STOP_EVENT.clear()
    CYCLE_WAKE.clear()
    try:
        app = PutraDashboard()
    except Exception as exc:
        print(f"PUTRA TRADING BOT 18.0 startup error: {type(exc).__name__}: {exc}", flush=True)
        return 1
    app_log("Started — selected broker chart only; 1-minute candles feed one unified five-minute pattern-led score; external context disabled")
    app_log("START READING samples live screen frames; 65%+ is a directional evidence score, not a calibrated win probability; orders remain manual")
    app.run()
    STOP_EVENT.set()
    return 0




# ====================== PUTRA TRADING BOT 14.0 EXTENSION ======================
# This layer preserves the established capture, scoring, confirmation, alert and
# persistence flow. It reuses the original scanners instead of duplicating them,
# exposes one callable detector per requested catalog feature, and adds source-aware
# ICT/time and declared-volume events that were previously listed but not activated.
VERSION = "PUTRA TRADING BOT 18.0 — live candle-only five-minute pattern analysis"
V13_MODEL_VERSION = "putra_trading_bot_13_0_feature_function_registry"
# Keep outcome history for this detector build separate from prior model versions.
CANDLE_ANALYSIS_MODEL_VERSION = V13_MODEL_VERSION
V10_MODEL_VERSION = V13_MODEL_VERSION
V11_MODEL_VERSION = V13_MODEL_VERSION

# The standard windows below are a configurable working convention, not a claim that
# all ICT educators use identical session boundaries. All are expressed in New York time
# so daylight-saving changes are applied by zoneinfo rather than fixed UTC offsets.
V13_ICT_TIMEZONE = os.environ.get("PUTRA_ICT_TIMEZONE", "America/New_York")
V13_ICT_KILLZONE_WINDOWS = {
    "ASIA": ("20:00", "00:00"),
    "LONDON": ("02:00", "05:00"),
    "NEW_YORK_AM": ("08:30", "11:00"),
    "NEW_YORK_PM": ("13:30", "16:00"),
}
V13_ICT_SILVER_BULLET_WINDOWS = {
    "LONDON": ("03:00", "04:00"),
    "NEW_YORK_AM": ("10:00", "11:00"),
    "NEW_YORK_PM": ("14:00", "15:00"),
}
V13_ICT_JUDAS_WINDOWS = {
    "LONDON_OPEN": ("02:00", "03:00"),
    "NEW_YORK_AM_OPEN": ("08:30", "09:30"),
}


def _v13_normalize_candle_rows(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Adapt timestamped OHLC rows to the existing candle schema without changing image rows."""
    normalized: List[Dict[str, Any]] = []
    for i, original in enumerate(candles or []):
        if not isinstance(original, dict):
            continue
        row = dict(original)
        direct = [parse_float(row.get(key), None) for key in ("open", "high", "low", "close")]
        has_direct_ohlc = all(value is not None and value > 0 for value in direct)
        if has_direct_ohlc:
            o, h, l, c = (float(v) for v in direct)
            if h >= max(o, c) and l <= min(o, c) and h >= l:
                # These estimates are exact input OHLC, not pixels; the source remains in metadata.
                row.setdefault("estimated_open_price", o)
                row.setdefault("estimated_high_price", h)
                row.setdefault("estimated_low_price", l)
                row.setdefault("estimated_close_price", c)
                row.setdefault("color", "GREEN" if c >= o else "RED")
                row.setdefault("index", i + 1)
                row.setdefault("sequence_break_before", False)
                row.setdefault("ohlc_status", "STRUCTURED_OHLC_INPUT; source provenance must be verified separately")
        normalized.append(row)
    return normalized


def _v13_timestamp_epoch(row: Dict[str, Any]) -> Optional[float]:
    """Return a usable epoch only for explicit candle-time fields; never infer time from pixels."""
    for key in ("timestamp", "timestamp_epoch", "open_time", "time_epoch", "timestamp_utc", "datetime", "time", "date"):
        raw = row.get(key)
        if raw is None or str(raw).strip() == "":
            continue
        numeric = parse_float(raw, None)
        if numeric is not None:
            # Unix milliseconds are common in exchange APIs; normalize them to seconds.
            if numeric > 100_000_000_000:
                numeric /= 1000.0
            if numeric > 100_000_000:
                return float(numeric)
        parsed = parse_epoch(raw)
        if parsed is not None and parsed > 100_000_000:
            return float(parsed)
    return None


def _v13_explicit_ohlc(row: Dict[str, Any]) -> Optional[Tuple[float, float, float, float]]:
    """Read structured OHLC only; visual pixel proxies are not accepted as timestamp evidence."""
    vals = [parse_float(row.get(key), None) for key in ("open", "high", "low", "close")]
    if any(v is None or v <= 0 for v in vals):
        return None
    o, h, l, c = (float(v) for v in vals)
    if h < max(o, c) or l > min(o, c) or h < l:
        return None
    return o, h, l, c


def _v13_has_timestamped_ohlc(candles: List[Dict[str, Any]], minimum: int = 5) -> bool:
    """Require real timestamp fields and valid structured OHLC, with no duplicate time values."""
    rows = list(candles or [])
    valid = [(_v13_timestamp_epoch(row), _v13_explicit_ohlc(row)) for row in rows]
    valid = [(stamp, ohlc) for stamp, ohlc in valid if stamp is not None and ohlc is not None]
    if len(valid) < minimum:
        return False
    recent = valid[-minimum:]
    stamps = [float(item[0]) for item in recent]
    return len(set(stamps)) == len(stamps) and all(0 < b - a <= 180 for a, b in zip(stamps, stamps[1:]))


def _v13_has_declared_volume(candles: List[Dict[str, Any]], minimum: int = 5) -> bool:
    """Volume is usable only when OHLCV carries an allowed, declared volume semantic."""
    rows = list(candles or [])
    valid = []
    for row in rows:
        ohlc = _v13_explicit_ohlc(row)
        volume = parse_float(row.get("volume"), None)
        volume_type = str(row.get("volume_type") or "").strip().lower()
        if ohlc is not None and volume is not None and volume >= 0 and volume_type in VOLUME_TYPES_ALLOWED:
            valid.append((row, ohlc, float(volume), volume_type))
    return len(valid) >= minimum


def _v13_clock_minutes(value: str) -> int:
    hour, minute = value.split(":", 1)
    return int(hour) * 60 + int(minute)


def _v13_in_time_window(local_dt: datetime, window: Tuple[str, str]) -> bool:
    current = local_dt.hour * 60 + local_dt.minute
    start, end = (_v13_clock_minutes(value) for value in window)
    return start <= current < end if start < end else current >= start or current < end


def _v13_pattern_event(name: str, bias: float, indices: List[int], strength: float,
                       context: str, confirmed: bool, family: str,
                       **extra: Any) -> Dict[str, Any]:
    """Build a detector event in the schema consumed by the existing scoring pipeline."""
    row = {
        "name": str(name), "bias": float(clamp(bias, -1.0, 1.0)),
        "confirmed": bool(confirmed), "candle_indices": [int(v) for v in indices],
        "strength": round(float(clamp(strength, 0.05, 0.95)), 3),
        "raw_strength": round(float(clamp(strength, 0.05, 0.95)), 3),
        "context": str(context), "pattern_family": str(family),
        "measurement_basis": "structured timestamped OHLC; no screenshot-derived session time",
        "not_a_calibrated_probability": True,
        "feature_engine_version": V13_MODEL_VERSION,
    }
    row.update(extra)
    return row


def _v13_timestamped_ict_patterns(candles: List[Dict[str, Any]],
                                   existing_patterns: Optional[List[Dict[str, Any]]] = None) -> List[Dict[str, Any]]:
    """Detect configured ICT session labels and require measured sweep→FVG evidence for setups."""
    rows = list(candles or [])
    if not _v13_has_timestamped_ohlc(rows, minimum=5):
        return []
    try:
        from zoneinfo import ZoneInfo
        session_tz = ZoneInfo(V13_ICT_TIMEZONE)
    except Exception:
        return []
    stamps = [_v13_timestamp_epoch(row) for row in rows]
    ohlc = [_v13_explicit_ohlc(row) for row in rows]
    valid_pairs = [(i, stamp, bar) for i, (stamp, bar) in enumerate(zip(stamps, ohlc))
                   if stamp is not None and bar is not None]
    if len(valid_pairs) < 5:
        return []
    latest_i, latest_stamp, latest_bar = valid_pairs[-1]
    local_dt = datetime.fromtimestamp(float(latest_stamp), timezone.utc).astimezone(session_tz)
    latest_index = latest_i + 1
    events: List[Dict[str, Any]] = []
    active_killzones = [name for name, window in V13_ICT_KILLZONE_WINDOWS.items()
                        if _v13_in_time_window(local_dt, window)]
    for session_name in active_killzones:
        events.append(_v13_pattern_event(
            "ICT_KILL_ZONES", 0.0, [latest_index], 0.18,
            f"Latest timestamp falls in configured {session_name} killzone ({V13_ICT_TIMEZONE}); session label is context-only.",
            True, "ict_session_context", session_name=session_name,
            timezone=V13_ICT_TIMEZONE, local_timestamp=local_dt.isoformat()))

    patterns = list(existing_patterns or [])
    def recent_event(predicate, lookback: int = 12) -> List[Dict[str, Any]]:
        found = []
        earliest = max(1, len(rows) - lookback + 1)
        for item in patterns:
            if not isinstance(item, dict) or not predicate(str(item.get("name") or "")):
                continue
            idx = item.get("candle_indices") or []
            numeric = [int(x) for x in idx if parse_float(x, None) is not None]
            if numeric and max(numeric) >= earliest:
                found.append(item)
        return found

    silver_windows = [name for name, window in V13_ICT_SILVER_BULLET_WINDOWS.items()
                      if _v13_in_time_window(local_dt, window)]
    if silver_windows:
        bullish_fvgs = recent_event(lambda name: name in {"BULLISH_FVG", "BULLISH_FVG_IMBALANCE_LIQUIDITY_VOID"}
                                    or name.startswith("BULLISH_FVG"))
        bearish_fvgs = recent_event(lambda name: name in {"BEARISH_FVG", "BEARISH_FVG_IMBALANCE_LIQUIDITY_VOID"}
                                    or name.startswith("BEARISH_FVG"))
        ssl_sweeps = recent_event(lambda name: name == "SELL_SIDE_LIQUIDITY_SWEEP_BUY_SIGNAL")
        bsl_sweeps = recent_event(lambda name: name == "BUY_SIDE_LIQUIDITY_SWEEP_SELL_SIGNAL")
        candidates = []
        for fvg, sweeps, side in ((bullish_fvgs, ssl_sweeps, 1), (bearish_fvgs, bsl_sweeps, -1)):
            for gap in fvg:
                gap_indices = [int(x) for x in (gap.get("candle_indices") or []) if parse_float(x, None) is not None]
                if not gap_indices:
                    continue
                gap_start, gap_end = min(gap_indices), max(gap_indices)
                prior_sweeps = []
                for sweep in sweeps:
                    sweep_indices = [int(x) for x in (sweep.get("candle_indices") or []) if parse_float(x, None) is not None]
                    if sweep_indices and max(sweep_indices) < gap_start and max(sweep_indices) >= max(1, gap_start - 10):
                        prior_sweeps.append(sweep)
                if prior_sweeps and gap_end >= max(1, latest_index - 8):
                    candidates.append((side, gap_start, gap_end, gap, prior_sweeps[-1]))
        if candidates:
            side, gap_start, gap_end, gap, sweep = candidates[-1]
            open_, high, low, close = latest_bar
            directional_close = close > open_ if side > 0 else close < open_
            session = silver_windows[-1]
            events.append(_v13_pattern_event(
                "SILVER_BULLET_SETUP", side * 0.46, [min(gap_start, gap_end), latest_index], 0.43,
                f"Measured liquidity sweep followed by a same-direction FVG during the configured {session} Silver Bullet hour; requires risk/invalidation checks.",
                directional_close, "ict_time_liquidity_fvg", session_name=session,
                sweep_name=str(sweep.get("name") or ""), fvg_name=str(gap.get("name") or ""),
                timezone=V13_ICT_TIMEZONE, local_timestamp=local_dt.isoformat()))

    judas_windows = [name for name, window in V13_ICT_JUDAS_WINDOWS.items()
                     if _v13_in_time_window(local_dt, window)]
    if judas_windows:
        bearish_sweeps = recent_event(lambda name: name == "BUY_SIDE_LIQUIDITY_SWEEP_SELL_SIGNAL", lookback=8)
        bullish_sweeps = recent_event(lambda name: name == "SELL_SIDE_LIQUIDITY_SWEEP_BUY_SIGNAL", lookback=8)
        open_, high, low, close = latest_bar
        prior = valid_pairs[max(0, len(valid_pairs) - 11):-1]
        prior_high = max((float(bar[2][1]) for bar in prior), default=high)
        prior_low = min((float(bar[2][2]) for bar in prior), default=low)
        choice = None
        if bearish_sweeps and close < prior_high:
            choice = (-1, bearish_sweeps[-1])
        elif bullish_sweeps and close > prior_low:
            choice = (1, bullish_sweeps[-1])
        if choice:
            side, sweep = choice
            window_name = judas_windows[-1]
            events.append(_v13_pattern_event(
                "JUDAS_SWING", side * 0.38, [max(1, latest_index - 2), latest_index], 0.34,
                f"An earlier measured liquidity sweep is followed by a close back inside the recent range during configured {window_name}; heuristic ICT sequence, not institutional-flow proof.",
                (close > open_) if side > 0 else (close < open_), "ict_sweep_reversal",
                session_name=window_name, sweep_name=str(sweep.get("name") or ""),
                timezone=V13_ICT_TIMEZONE, local_timestamp=local_dt.isoformat()))
    return events


def _v13_declared_volume_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Add a small, non-standalone volume modifier only for declared OHLCV data."""
    rows = list(candles or [])
    if not _v13_has_declared_volume(rows, minimum=5):
        return []
    parsed = []
    for i, row in enumerate(rows):
        bar = _v13_explicit_ohlc(row)
        volume = parse_float(row.get("volume"), None)
        kind = str(row.get("volume_type") or "").strip().lower()
        if bar is not None and volume is not None and volume >= 0 and kind in VOLUME_TYPES_ALLOWED:
            parsed.append((i, row, bar, float(volume), kind))
    if len(parsed) < 5:
        return []
    idx, row, bar, current_volume, volume_kind = parsed[-1]
    prior_volumes = [item[3] for item in parsed[:-1][-20:] if item[3] > 0]
    if len(prior_volumes) < 4:
        return []
    baseline = float(np.median(np.asarray(prior_volumes, dtype=float)))
    if baseline <= 0 or current_volume < 1.40 * baseline:
        return []
    o, h, l, c = bar
    candle_range = max(1e-12, h - l)
    body_ratio = abs(c - o) / candle_range
    close_location = (c - l) / candle_range
    if body_ratio < 0.55:
        return []
    if c > o and close_location >= 0.78:
        side, interpretation = 1, "elevated declared volume accompanied a bullish body closing near its high"
    elif c < o and close_location <= 0.22:
        side, interpretation = -1, "elevated declared volume accompanied a bearish body closing near its low"
    else:
        return []
    closed = bool(row.get("is_closed") or row.get("completed") or row.get("bar_closed"))
    return [_v13_pattern_event(
        "VOLUME", side * 0.14, [idx + 1], 0.22,
        f"{interpretation}; relative volume={current_volume / baseline:.2f}× median of prior valid bars. Volume confirms participation, not direction on its own.",
        closed, "volume_confirmation", volume_type=volume_kind,
        relative_volume=round(current_volume / baseline, 3), baseline_volume=round(baseline, 6),
        source=str(row.get("volume_source") or row.get("source") or "declared OHLCV input"))]


# Keep the original, already-tested scanners as the source of all existing pattern rules.
_V13_PREVIOUS_EXTENDED_CANDLE_PATTERNS = _extended_candle_patterns
_V13_PREVIOUS_SUPPLEMENTAL_PATTERNS = _supplemental_candle_and_smc_patterns
_V13_PREVIOUS_CLASSICAL_PATTERN_DETECTOR = _detect_classical_chart_patterns


def _extended_candle_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """V15 wrapper: preserve old rules and add independently callable named candle patterns."""
    rows = _v13_normalize_candle_rows(candles)
    existing = list(_V13_PREVIOUS_EXTENDED_CANDLE_PATTERNS(rows) or [])
    existing.extend(_v15_scan_extra_patterns(rows))
    unique: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for item in existing:
        key = (str(item.get("name") or ""), tuple(item.get("candle_indices") or []))
        previous = unique.get(key)
        if previous is None or (bool(item.get("confirmed")) and not bool(previous.get("confirmed"))) or float(item.get("strength") or 0) > float(previous.get("strength") or 0):
            unique[key] = item
    return list(unique.values())


def _detect_classical_chart_patterns(candles: List[Dict[str, Any]]) -> Dict[str, Any]:
    """V13 adapter: retain the existing chart-formation engine and normalize structured OHLC input."""
    return _V13_PREVIOUS_CLASSICAL_PATTERN_DETECTOR(_v13_normalize_candle_rows(candles))


def _supplemental_candle_and_smc_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """V13 shared integration point for old pattern rules plus timestamp/volume-aware events."""
    rows = _v13_normalize_candle_rows(candles)
    existing = list(_V13_PREVIOUS_SUPPLEMENTAL_PATTERNS(rows) or [])
    extra = _v13_timestamped_ict_patterns(rows, existing)
    extra.extend(_v13_declared_volume_patterns(rows))
    unique: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for event in existing + extra:
        key = (str(event.get("name") or ""), tuple(event.get("candle_indices") or []))
        old = unique.get(key)
        if old is None or (bool(event.get("confirmed")) and not bool(old.get("confirmed"))) or (
                bool(event.get("confirmed")) == bool(old.get("confirmed"))
                and float(parse_float(event.get("strength"), 0.0) or 0.0) > float(parse_float(old.get("strength"), 0.0) or 0.0)):
            unique[key] = event
    return list(unique.values())


def _v13_make_scan_context(candles: List[Dict[str, Any]], analysis: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Build one shared detector result set so feature wrappers do not rerun every scanner."""
    rows = _v13_normalize_candle_rows(candles)
    source = analysis or {}
    has_analysis_patterns = isinstance(source.get("patterns"), list)
    if has_analysis_patterns:
        candle_events = [row for row in source.get("patterns", []) if isinstance(row, dict)]
    else:
        candle_events = list(_extended_candle_patterns(rows)) + list(_supplemental_candle_and_smc_patterns(rows))
        try:
            candle_events.extend(_visual_divergence_patterns(rows).get("patterns") or [])
        except Exception:
            pass
    classical_info = source.get("classical_chart_patterns") or {}
    if not classical_info:
        price_context = source.get("price_action_context") or {}
        classical_info = price_context.get("classical_chart_patterns") or {}
    if classical_info and isinstance(classical_info, dict):
        chart_events = [row for row in classical_info.get("patterns", []) if isinstance(row, dict)]
    else:
        chart_events = list((_detect_classical_chart_patterns(rows).get("patterns") or []))
    all_events = candle_events + chart_events
    return {"candles": rows, "analysis": source, "candle_events": candle_events,
            "chart_events": chart_events, "all_events": all_events}


def _v13_evaluate_feature(spec: Dict[str, Any], context: Dict[str, Any],
                          base_row: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Run one catalog feature's dedicated callable against the shared detector evidence."""
    name = str(spec.get("name") or "")
    aliases = list(spec.get("match_aliases") or [_v10_feature_key(name)])
    alias_keys = {_v10_feature_key(alias) for alias in aliases}
    source = context.get("analysis") or {}
    rows = list(context.get("candles") or [])
    events = list(context.get("all_events") or [])
    matched_events = []
    for event in events:
        event_name = str(event.get("name") or "")
        event_key = _v10_feature_key(event_name)
        if any(event_key == key or (len(key) >= 8 and key in event_key) for key in alias_keys):
            matched_events.append(event)

    status = str(spec.get("implementation_status") or "")
    candle_count = len(rows)
    volume_available = _v13_has_declared_volume(rows)
    timestamped_available = _v13_has_timestamped_ohlc(rows)
    mtf_available = bool((source.get("multi_timeframe_confirmation") or {}).get("available"))
    method_name = name in _V10_METHODOLOGY_NAMES
    if name in _V10_MTF_NAMES:
        evaluated = mtf_available
        matched = mtf_available
        detail = source.get("multi_timeframe_confirmation") or {}
        if mtf_available and not matched_events:
            matched_events = [{"name": "MULTI_TIMEFRAME_CONFIRMATION", "bias": parse_float(detail.get("bias"), 0.0) or 0.0,
                              "confirmed": bool(detail.get("confirmed")), "context": "Completed higher-timeframe context, when provided."}]
    elif name in _V10_VOLUME_NAMES:
        evaluated = volume_available or bool((source.get("volume_profile") or {}).get("available"))
        matched = bool(matched_events)
    elif name in _V10_TIME_DEPENDENT_NAMES:
        evaluated = timestamped_available
        matched = bool(matched_events)
    elif method_name:
        evaluated = candle_count > 0
        # Methodology labels mean the components are in use; they do not become fake trade signals.
        matched = bool(evaluated and (source.get("price_action_context") or source.get("structural_context") or events))
    else:
        evaluated = bool(base_row.get("evaluated_for_this_chart")) if base_row else candle_count > 0
        matched = bool(matched_events or (base_row and base_row.get("matched_this_chart")))

    if matched_events:
        weighted_biases = []
        for event in matched_events:
            bias = parse_float(event.get("bias"), 0.0) or 0.0
            if abs(bias) <= 1e-10:
                continue
            weight = max(0.05, parse_float(event.get("strength"), 0.25) or 0.25)
            if event.get("confirmed"):
                weight *= 1.25
            weighted_biases.append((bias, weight))
        directional_bias = (sum(b * w for b, w in weighted_biases) / sum(w for _, w in weighted_biases)) if weighted_biases else 0.0
    else:
        directional_bias = 0.0
    if method_name:
        score_role = "applied_methodology_context; component evidence is scored, methodology label is not a standalone vote"
    elif name in _V10_MTF_NAMES:
        score_role = "separate higher-timeframe confirmation/risk group in the combined five-minute score"
    elif name in _V10_VOLUME_NAMES:
        score_role = "declared-volume confirmation modifier; unavailable volume is omitted, never synthesized"
    elif name in _V10_TIME_DEPENDENT_NAMES:
        score_role = "timestamp/session setup enters the shared recency/confirmation pattern pipeline only when measured"
    elif matched_events and abs(directional_bias) <= 1e-10:
        score_role = "neutral context only; no directional vote from a name/location label alone"
    else:
        score_role = "pattern event enters the existing recency-, confirmation-, context- and family-weighted score; aliases are not independent votes"
    return {
        "name": name, "key": spec.get("key"),
        "detector_function": str(spec.get("detector_function") or ""),
        "function_implemented": True, "implementation_status": status,
        "evaluated_for_this_chart": bool(evaluated), "available": bool(evaluated),
        "matched_this_chart": bool(matched),
        "matched_detector_aliases": sorted({str(row.get("name") or "") for row in matched_events}),
        "matched_events": [{"name": str(row.get("name") or ""),
                            "bias": round(float(parse_float(row.get("bias"), 0.0) or 0.0), 4),
                            "confirmed": bool(row.get("confirmed")),
                            "candle_indices": list(row.get("candle_indices") or []),
                            "strength": round(float(parse_float(row.get("strength"), 0.0) or 0.0), 3),
                            "context": str(row.get("context") or "")[:280]}
                           for row in matched_events[:12]],
        "uses": str(spec.get("algorithm") or ""),
        "data_requirement": str(spec.get("data_requirement") or ""),
        "estimated_directional_bias": round(float(clamp(directional_bias, -1.0, 1.0)), 4),
        "bias_is_individual_diagnostic_not_additive_vote": True,
        "score_role": score_role,
        "score_link": "Shared five-minute scoring pipeline; confirmed directional events are grouped/recency-weighted, neutral context is not independently counted.",
    }


# Every requested item receives a unique callable backed by its mapped detector aliases and
# the shared result set. The callable is introspectable and usable independently by tests/tools.
_V13_REQUESTED_FEATURE_SPECS: List[Dict[str, Any]] = []
_V13_FEATURE_DETECTORS: Dict[str, Any] = {}
for _v13_original_spec in _V10_REQUESTED_ANALYSIS_CATALOG:
    _v13_spec = dict(_v13_original_spec)
    _v13_slug = re.sub(r"[^a-z0-9]+", "_", str(_v13_spec["name"]).lower()).strip("_")
    if _v13_spec.get("group") == "candlestick_pattern":
        _v13_spec["detector_function"] = "_extended_candle_patterns + _supplemental_candle_and_smc_patterns"
    elif _v13_spec.get("group") == "classical_chart_pattern":
        _v13_spec["detector_function"] = "_detect_classical_chart_patterns"
    elif _v13_spec.get("name") in _V10_MTF_NAMES:
        _v13_spec["detector_function"] = "_visual_multitimeframe_confirmation / broker OHLC confirmation"
    elif _v13_spec.get("name") in _V10_VOLUME_NAMES:
        _v13_spec["detector_function"] = "_v13_declared_volume_patterns / _visible_volume_profile"
    elif _v13_spec.get("name") in _V10_TIME_DEPENDENT_NAMES:
        _v13_spec["detector_function"] = "_v13_timestamped_ict_patterns"
    elif _v13_spec.get("name") in _V10_METHODOLOGY_NAMES:
        _v13_spec["detector_function"] = "_v13_evaluate_feature (measurable component aggregation)"
    else:
        _v13_spec["detector_function"] = "_v10_requested_context_patterns + _supplemental_candle_and_smc_patterns"

    def _make_v13_feature_detector(spec: Dict[str, Any]):
        def _detector(candles: List[Dict[str, Any]], analysis: Optional[Dict[str, Any]] = None,
                      scan_context: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
            context = scan_context or _v13_make_scan_context(candles, analysis)
            return _v13_evaluate_feature(spec, context)
        _detector.__name__ = "detect_requested_feature_" + re.sub(r"[^a-z0-9]+", "_", str(spec["name"]).lower()).strip("_")
        _detector.__qualname__ = _detector.__name__
        _detector.__doc__ = ("Dedicated callable for " + str(spec["name"]) + ". Uses the catalog rule, required evidence, mapped aliases, "
                             "and the shared detector output; directional evidence is routed through the existing score pipeline.")
        return _detector

    _v13_detector = _make_v13_feature_detector(_v13_spec)
    _v13_spec["callable_name"] = _v13_detector.__name__
    _V13_FEATURE_DETECTORS[_v13_spec["name"]] = _v13_detector
    _V13_REQUESTED_FEATURE_SPECS.append(_v13_spec)


def requested_feature_detector(feature_name: str):
    """Return the unique detector callable for a catalog item, or raise KeyError for unknown names."""
    key = str(feature_name or "").strip()
    if key not in _V13_FEATURE_DETECTORS:
        raise KeyError(f"Unknown requested analysis feature: {key}")
    return _V13_FEATURE_DETECTORS[key]


def requested_feature_function_inventory() -> List[Dict[str, Any]]:
    """Expose the complete per-item function, uses, aliases, and source requirements."""
    return [{"name": row["name"], "callable_name": row["callable_name"],
             "detector_function": row["detector_function"], "group": row["group"],
             "implementation_status": row["implementation_status"],
             "uses": row["algorithm"], "data_requirement": row["data_requirement"],
             "match_aliases": list(row["match_aliases"]),
             "score_connection": "shared five-minute score; correlated aliases grouped; context-only labels remain neutral"}
            for row in _V13_REQUESTED_FEATURE_SPECS]


_V13_PREVIOUS_CATALOG_RUNTIME_REPORT = _v10_catalog_runtime_report


def _v10_catalog_runtime_report(analysis: Dict[str, Any]) -> Dict[str, Any]:
    """V13 per-feature audit: attach real callables and evidence without changing score weights."""
    report = _V13_PREVIOUS_CATALOG_RUNTIME_REPORT(analysis)
    rows = _v13_normalize_candle_rows(list(analysis.get("candles") or []))
    context = _v13_make_scan_context(rows, analysis)
    spec_by_name = {row["name"]: row for row in _V13_REQUESTED_FEATURE_SPECS}
    base_by_name = {row.get("name"): row for row in report.get("all_requested_features") or []}
    enriched_rows = []
    unavailable = set(report.get("conditional_data_items_unavailable") or [])
    for feature_row in report.get("all_requested_features") or []:
        name = str(feature_row.get("name") or "")
        spec = spec_by_name.get(name)
        if not spec:
            enriched_rows.append(feature_row)
            continue
        detail = _v13_evaluate_feature(spec, context, base_by_name.get(name))
        feature_row.update({
            "detector_function": detail["detector_function"],
            "callable_name": spec["callable_name"],
            "function_implemented": True,
            "uses": detail["uses"],
            "matched_events": detail["matched_detector_aliases"],
            "estimated_directional_bias": detail["estimated_directional_bias"],
            "score_role": detail["score_role"],
            "score_link": detail["score_link"],
        })
        feature_row["evaluated_for_this_chart"] = bool(detail["evaluated_for_this_chart"])
        feature_row["matched_this_chart"] = bool(detail["matched_this_chart"])
        feature_row["matched_detector_aliases"] = detail["matched_detector_aliases"] or feature_row.get("matched_detector_aliases", [])
        if name in _V10_TIME_DEPENDENT_NAMES:
            if detail["evaluated_for_this_chart"]:
                unavailable.discard(name)
            else:
                unavailable.add(name)
        elif name in _V10_VOLUME_NAMES:
            if detail["evaluated_for_this_chart"]:
                unavailable.discard(name)
            else:
                unavailable.add(name)
        elif name in _V10_MTF_NAMES:
            if detail["evaluated_for_this_chart"]:
                unavailable.discard(name)
            else:
                unavailable.add(name)
        enriched_rows.append(feature_row)
    report["all_requested_features"] = enriched_rows
    report["requested_item_count"] = len(_V13_REQUESTED_FEATURE_SPECS)
    report["functional_detector_count"] = len(_V13_FEATURE_DETECTORS)
    report["evaluated_items"] = sum(bool(row.get("evaluated_for_this_chart")) for row in enriched_rows)
    report["matched_items_on_this_chart"] = sum(bool(row.get("matched_this_chart")) for row in enriched_rows)
    report["conditional_data_items_unavailable"] = sorted(unavailable)
    report["catalog_version"] = "13.0-one-callable-per-requested-feature"
    report["score_integration"] = (
        "All requested items have callable detectors backed by shared, non-duplicated rule engines. "
        "Actual directional candle, chart, structure, liquidity/SMC, and eligible timestamped ICT events "
        "flow into the existing five-minute recency/confirmation/context-weighted analysis; declared volume "
        "and higher-timeframe confirmation are evidence modifiers; methodology and location labels never "
        "create standalone votes."
    )
    report["detector_wiring"] = {
        "callable_registry": "requested_feature_detector(name) -> unique per-feature callable -> shared scan context -> mapped event(s) and use/data metadata",
        "candlestick_events": "_extended_candle_patterns + _supplemental_candle_and_smc_patterns -> _confirm_candle_patterns -> _apply_pattern_context -> _weighted_recent_pattern_bias -> five-minute score",
        "chart_formations": "_detect_classical_chart_patterns -> classical pattern/line output and price_action_context bias -> five-minute score",
        "market_structure_smc": "_v10_requested_context_patterns + existing SMC scanner -> event grouping, structure/location context, liquidity/OB/FVG proxies -> score",
        "time_and_volume": "timestamped ICT events and declared OHLCV volume modifiers are only emitted when their source data validates, and then join the same shared score pipeline",
        "anti_duplication": "old scanner logic reused; events de-duplicated by (name, candle span); aliases do not stack as independent votes",
    }
    report["source_data_policy"] = {
        "timestamped_ict": f"Requires at least five valid timestamped structured OHLC bars; timezone={V13_ICT_TIMEZONE}; sessions are configurable conventions.",
        "volume": "Requires at least five structured OHLCV records with declared tick_volume or real_volume; screenshot color is never treated as volume.",
        "multi_timeframe": "Uses existing completed higher-timeframe context only when it reports available.",
        "prediction": "The five-minute output remains a heuristic directional model score, not an assured outcome or calibrated win probability.",
    }
    return report


_V13_PREVIOUS_ATTACH_COVERAGE = _attach_requested_analysis_coverage


def _attach_requested_analysis_coverage(result: Dict[str, Any]) -> Dict[str, Any]:
    """Attach full per-feature callable audit while preserving the original compact status block."""
    result = _V13_PREVIOUS_ATTACH_COVERAGE(result)
    try:
        report = _v10_catalog_runtime_report(result)
        result["requested_feature_analysis"] = report.get("all_requested_features", [])
        result["requested_feature_function_count"] = len(_V13_FEATURE_DETECTORS)
        result["requested_analysis_coverage"] = {key: value for key, value in report.items()
                                                 if key != "all_requested_features"}
        audit = result.setdefault("connected_feature_audit", {})
        audit["requested_feature_functions"] = {
            "function_count": len(_V13_FEATURE_DETECTORS),
            "evaluated_for_current_chart": report.get("evaluated_items", 0),
            "matched_for_current_chart": report.get("matched_items_on_this_chart", 0),
            "score_link": report.get("score_integration"),
        }
    except Exception as exc:
        # Audit enrichment is deliberately non-fatal to the scoring/alert loop.
        result.setdefault("requested_feature_analysis", [])
        result.setdefault("requested_feature_function_audit_error", type(exc).__name__)
    return result


def _v13_regression_tests() -> int:
    """Verify one-to-one callable coverage and source-aware feature-to-score integration."""
    checks: List[Tuple[str, bool]] = []
    def check(label: str, condition: Any) -> None:
        checks.append((label, bool(condition)))

    check("V13.0 preserves the exact 169 unique requested feature names",
          len(_V10_CATALOG_NAMES) == 169 and len(set(_V10_CATALOG_NAMES)) == 169
          and len(_V13_FEATURE_DETECTORS) == 169 and len(_V13_REQUESTED_FEATURE_SPECS) == 169)
    check("V13.0 gives every catalog entry a unique callable with rule, aliases and source requirements",
          len({fn.__name__ for fn in _V13_FEATURE_DETECTORS.values()}) == 169
          and all(callable(fn) for fn in _V13_FEATURE_DETECTORS.values())
          and all(row.get("algorithm") and row.get("data_requirement") and row.get("match_aliases")
                  and row.get("callable_name") for row in _V13_REQUESTED_FEATURE_SPECS))
    check("V13.0 public detector lookup rejects unknown names and returns a callable for known names",
          callable(requested_feature_detector("Hammer")) and callable(requested_feature_detector("Volume")))

    # Twelve actual structured bars with timestamps during the NY AM Silver Bullet window.
    try:
        from zoneinfo import ZoneInfo
        ny = ZoneInfo("America/New_York")
        base_dt = datetime(2026, 10, 22, 10, 4, tzinfo=ny)
        structured = []
        for i in range(12):
            op = 100.0 + i * 0.05
            cl = op + (0.04 if i % 3 else -0.02)
            structured.append({"timestamp": (base_dt + __import__("datetime").timedelta(minutes=i)).timestamp(),
                               "open": op, "high": max(op, cl) + 0.03, "low": min(op, cl) - 0.03,
                               "close": cl, "volume": 100.0, "volume_type": "tick_volume",
                               "source": "synthetic test only", "index": i + 1})
        session_events = _v13_timestamped_ict_patterns(structured, [])
        check("V13.0 recognizes configured ICT killzone from real timestamp fields and DST-aware New York time",
              any(row.get("name") == "ICT_KILL_ZONES" for row in session_events))
        fake_sweep = {"name": "SELL_SIDE_LIQUIDITY_SWEEP_BUY_SIGNAL", "bias": 0.3,
                      "confirmed": True, "candle_indices": [6], "strength": 0.4}
        fake_fvg = {"name": "BULLISH_FVG", "bias": 0.3,
                    "confirmed": True, "candle_indices": [8, 9, 10], "strength": 0.4}
        sb_events = _v13_timestamped_ict_patterns(structured, [fake_sweep, fake_fvg])
        check("V13.0 requires a measured prior liquidity sweep plus FVG before labeling Silver Bullet",
              any(row.get("name") == "SILVER_BULLET_SETUP" and row.get("bias", 0) > 0 for row in sb_events))
    except Exception as exc:
        check(f"V13.0 timestamped ICT detector executes without error ({type(exc).__name__})", False)

    # Declared OHLCV only: latest bar has elevated volume and a strong bullish close.
    volume_bars = []
    for i in range(10):
        op = 100.0 + i * 0.10
        cl = op + 0.08
        volume_bars.append({"timestamp": 1792660000 + i * 60, "open": op,
                            "high": cl + 0.01, "low": op - 0.01, "close": cl,
                            "volume": 300.0 if i == 9 else 100.0,
                            "volume_type": "tick_volume", "is_closed": True, "index": i + 1})
    vol_events = _v13_declared_volume_patterns(volume_bars)
    check("V13.0 activates the volume modifier only with declared OHLCV and an elevated directional bar",
          len(vol_events) == 1 and vol_events[0].get("name") == "VOLUME" and vol_events[0].get("bias", 0) > 0)
    check("V13.0 refuses to invent volume for screenshot-only pixel candles",
          _v13_declared_volume_patterns([{"color": "GREEN", "estimated_open_pixel": 30,
                                         "estimated_close_pixel": 20, "wick_top_pixel": 18,
                                         "wick_bottom_pixel": 34, "height": 16}] * 8) == [])

    fixture = []
    for i in range(24):
        op = 100.0 + 0.15 * i
        cl = op + (0.3 if i % 4 else -0.1)
        hi, lo = max(op, cl) + 0.12, min(op, cl) - 0.12
        fixture.append({"index": i + 1, "estimated_open_price": op, "estimated_high_price": hi,
                        "estimated_low_price": lo, "estimated_close_price": cl,
                        "estimated_open_pixel": -op, "estimated_close_pixel": -cl,
                        "wick_top_pixel": -hi, "wick_bottom_pixel": -lo,
                        "body_top_pixel": -max(op, cl), "body_bottom_pixel": -min(op, cl),
                        "body_height_pixels": abs(cl-op), "upper_wick_pixels": hi-max(op,cl),
                        "lower_wick_pixels": min(op,cl)-lo, "width": 5, "height": int(hi-lo),
                        "x": i * 8, "y": int(-hi), "color": "GREEN" if cl >= op else "RED",
                        "sequence_break_before": False})
    scan = _v13_make_scan_context(fixture)
    reports = [fn(fixture, scan_context=scan) for fn in _V13_FEATURE_DETECTORS.values()]
    check("V13.0 every per-feature callable executes on a shared scan context without duplicating scanners",
          len(reports) == 169 and all(row.get("function_implemented") for row in reports))
    analysis = {"candles": fixture, "candle_count": len(fixture), "patterns": scan["candle_events"],
                "classical_chart_patterns": {"patterns": scan["chart_events"]},
                "trend": "UP", "structural_context": {"available": True},
                "price_action_context": {"available": True, "trend": "UP", "components": {}}}
    runtime = _v10_catalog_runtime_report(analysis)
    check("V14.0 runtime report exposes all 169 functions, uses, data requirements and scoring roles",
          runtime.get("functional_detector_count") == 169
          and len(runtime.get("all_requested_features") or []) == 169
          and all(row.get("function_implemented") and row.get("callable_name")
                  and row.get("uses") and row.get("score_link") for row in runtime.get("all_requested_features") or []))
    check("V14.0 retains one five-minute score integration path and explicit non-probability semantics",
          FIXED_EXPIRY_MINUTES == 5 and TIMEFRAME_LABEL == "M1" and FORECAST_HORIZON_BARS == 5
          and "shared" in runtime.get("score_integration", "").lower()
          and "calibrated" in runtime.get("measurement_limit", "").lower())
    for label, ok in checks:
        print(("PASS" if ok else "FAIL") + " | " + label, flush=True)
    passed = sum(ok for _, ok in checks)
    print(f"BOT 14.0 FEATURE-FUNCTION REGRESSION: {passed}/{len(checks)} passed", flush=True)
    return 0 if passed == len(checks) else 1

