V15_MAX_PATTERN_LABELS_ON_LIVE_CHART = 9
V15_PATTERN_LOOKBACK = 120

_V15_SUPPLEMENTAL_PATTERN_SPECS: List[Dict[str, Any]] = [
    {"name":"Homing Pigeon", "min_bars":2, "uses":"Bullish reversal candidate after a downtrend: two black bodies, the second smaller and contained inside the first body.", "data_requirement":"Two consecutive OHLC candles plus a measurable prior trend; gaps in the visible sequence invalidate the match."},
    {"name":"In Neck", "min_bars":2, "uses":"Bearish-continuation context: a long black candle followed by a white candle opening below the prior low and closing just above that low.", "data_requirement":"Two consecutive OHLC candles; tolerances are normalized to the local median range."},
    {"name":"On Neck", "min_bars":2, "uses":"Bearish-continuation context: a long black candle followed by a white candle that opens below and closes near the prior low.", "data_requirement":"Two consecutive OHLC candles; the assumed prior downtrend is checked when enough bars exist."},
    {"name":"Thrusting Line", "min_bars":2, "uses":"Weak bearish-continuation pattern: a white candle rebounds into, but not above the midpoint of, the prior long black body.", "data_requirement":"Two consecutive OHLC candles and a local body-size baseline."},
    {"name":"Bullish Doji Star", "min_bars":2, "uses":"Potential bullish reversal warning after a down move: a long black candle followed by a genuinely separated doji; requires bullish follow-through.", "data_requirement":"Two consecutive OHLC candles and a measurable body gap; ordinary adjacent bars are not treated as gapped."},
    {"name":"Bearish Doji Star", "min_bars":2, "uses":"Potential bearish reversal warning after an up move: a long white candle followed by a separated doji; requires bearish follow-through.", "data_requirement":"Two consecutive OHLC candles and a measurable body gap."},
    {"name":"Morning Doji Star", "min_bars":3, "uses":"Bullish reversal candidate: long black candle, gapped/isolated doji, then a white candle recovering beyond the first candle's body midpoint.", "data_requirement":"Three contiguous OHLC candles; star/body-gap thresholds scale with local range."},
    {"name":"Evening Doji Star", "min_bars":3, "uses":"Bearish reversal candidate: long white candle, gapped/isolated doji, then a black candle closing below the first body's midpoint.", "data_requirement":"Three contiguous OHLC candles; star/body-gap thresholds scale with local range."},
    {"name":"Matching Low", "min_bars":2, "uses":"Possible bullish support/reversal cue when consecutive black candles close at nearly the same level after a decline.", "data_requirement":"Two consecutive OHLC candles; close equality is range-normalized."},
    {"name":"Matching High", "min_bars":2, "uses":"Possible bearish resistance/reversal cue when consecutive white candles close at nearly the same level after a rise.", "data_requirement":"Two consecutive OHLC candles; close equality is range-normalized."},
    {"name":"Rising Window", "min_bars":2, "uses":"Bullish continuation/location cue for a real high-to-low gap between consecutive bars; a later hold strengthens it.", "data_requirement":"Two consecutive OHLC candles with low[current] above high[previous]; no gap is invented for continuous trading."},
    {"name":"Falling Window", "min_bars":2, "uses":"Bearish continuation/location cue for a real downward high-to-low gap; a later failure to reclaim it strengthens it.", "data_requirement":"Two consecutive OHLC candles with high[current] below low[previous]."},
    {"name":"Upside Gap Three Methods", "min_bars":3, "uses":"Bullish continuation candidate: an upside gap, then a pullback candle partially filling but not fully erasing the gap.", "data_requirement":"Three contiguous OHLC candles and a genuine gap between the first two bars."},
    {"name":"Downside Gap Three Methods", "min_bars":3, "uses":"Bearish continuation candidate: a downside gap, then a rebound candle partially filling but not fully erasing the gap.", "data_requirement":"Three contiguous OHLC candles and a genuine gap between the first two bars."},
    {"name":"Bullish Three-Line Strike", "min_bars":4, "uses":"Bullish reversal candidate: three declining black candles followed by a strong white candle that engulfs the preceding decline body sequence.", "data_requirement":"Four contiguous OHLC candles with sequential body/close checks."},
    {"name":"Bearish Three-Line Strike", "min_bars":4, "uses":"Bearish reversal candidate: three advancing white candles followed by a strong black candle engulfing the preceding rise body sequence.", "data_requirement":"Four contiguous OHLC candles with sequential body/close checks."},
    {"name":"Concealing Baby Swallow", "min_bars":4, "uses":"Rare bullish reversal candidate after a downtrend: four black candles with a specific marubozu/overlapping-shadow sequence.", "data_requirement":"Four contiguous OHLC candles; the heuristic is intentionally strict and low-weight."},
    {"name":"Unique Three-River Bottom", "min_bars":3, "uses":"Bullish bottom candidate: a long black candle, a lower-low hammer-like black candle, then a small white recovery.", "data_requirement":"Three contiguous OHLC candles and a measurable prior decline."},
    {"name":"Ladder Bottom", "min_bars":5, "uses":"Bullish reversal candidate: four declining black candles followed by a strong white recovery that breaks the prior candle high.", "data_requirement":"Five contiguous OHLC candles with a directional sequence."},
    {"name":"Ladder Top", "min_bars":5, "uses":"Custom bearish exhaustion analogue: a rising sequence loses momentum and a final black candle closes through the prior candle low.", "data_requirement":"Five contiguous OHLC candles; explicitly marked heuristic because the label is not standardized across libraries."},
    {"name":"Bullish Side-by-Side White Lines", "min_bars":3, "uses":"Potential bullish continuation: two similarly sized white candles hold side by side after an upside gap.", "data_requirement":"Three consecutive OHLC candles; a real upside gap is required."},
    {"name":"Bearish Side-by-Side White Lines", "min_bars":3, "uses":"Potential bearish continuation despite two white candles: same-sized white bars remain below a real downside gap.", "data_requirement":"Three consecutive OHLC candles; a real downside gap is required."},
    {"name":"Identical Three Crows", "min_bars":3, "uses":"Bearish continuation/reversal evidence from three black candles with progressively lower closes and closely aligned bodies/closes.", "data_requirement":"Three contiguous OHLC candles; equal-close tolerance is range-normalized."},
    {"name":"Bullish Tasuki Line", "min_bars":3, "uses":"Bullish continuation: after a genuine upward gap and advancing candles, a black pullback partially enters the gap but does not close it.", "data_requirement":"Three contiguous OHLC candles and a genuine gap; continuous BTC charts may rarely qualify."},
    {"name":"Bearish Tasuki Line", "min_bars":3, "uses":"Bearish continuation: after a genuine downward gap, a white pullback partially enters the gap but does not close it.", "data_requirement":"Three contiguous OHLC candles and a genuine gap."},
    {"name":"Takuri Line", "min_bars":1, "uses":"Lower-wick rejection candidate: tiny real body, very long lower shadow, tiny upper shadow, ideally after a decline.", "data_requirement":"One OHLC candle plus prior trend context; needs a later close for confirmation."},
    {"name":"Descending Hawk", "min_bars":2, "uses":"Bearish reversal candidate after an uptrend: a long white candle followed by a smaller white body inside the first body.", "data_requirement":"Two consecutive OHLC candles plus prior uptrend context."},
    {"name":"Two Black Gapping Candles", "min_bars":3, "uses":"Bearish continuation candidate: two black candles after a real downside gap from the prior bar/body.", "data_requirement":"Three contiguous OHLC candles and a genuine downside gap."},
    {"name":"Last Engulfing Bottom", "min_bars":2, "uses":"Context-sensitive potential turning-point pattern in a downtrend: a white candle followed by a black body engulfing it; direction is not assumed from color alone.", "data_requirement":"Two consecutive OHLC candles, prior downtrend, and subsequent confirmation if available."},
    {"name":"Last Engulfing Top", "min_bars":2, "uses":"Context-sensitive potential turning-point pattern in an uptrend: a black candle followed by a white body engulfing it; direction is not assumed from color alone.", "data_requirement":"Two consecutive OHLC candles, prior uptrend, and subsequent confirmation if available."},
    {"name":"Turn Up", "min_bars":2, "uses":"Bullish structure confirmation: a white candle closes above a recent prior candle high following downside pressure.", "data_requirement":"At least two contiguous candles; break level is based on visible prior highs."},
    {"name":"Turn Down", "min_bars":2, "uses":"Bearish structure confirmation: a black candle closes below a recent prior candle low following upside pressure.", "data_requirement":"At least two contiguous candles; break level is based on visible prior lows."},
    {"name":"Northern Doji", "min_bars":1, "uses":"Neutral-to-bearish indecision marker: a doji occurring near the top of the recent range after an uptrend.", "data_requirement":"A doji-shaped candle and sufficient preceding candles to estimate location/trend."},
    {"name":"Southern Doji", "min_bars":1, "uses":"Neutral-to-bullish indecision marker: a doji occurring near the bottom of the recent range after a downtrend.", "data_requirement":"A doji-shaped candle and sufficient preceding candles to estimate location/trend."},
    {"name":"Gapping Up Doji", "min_bars":2, "uses":"Neutral indecision marker when a doji's body is genuinely separated upward from the prior body; direction requires later confirmation.", "data_requirement":"Two contiguous OHLC candles and a real body gap."},
    {"name":"Gapping Down Doji", "min_bars":2, "uses":"Neutral indecision marker when a doji's body is genuinely separated downward from the prior body; direction requires later confirmation.", "data_requirement":"Two contiguous OHLC candles and a real body gap."},
    {"name":"Collapsing Doji Star", "min_bars":3, "uses":"Bearish reversal candidate: an advancing white candle, isolated doji, then a black candle collapsing beneath the first body's midpoint.", "data_requirement":"Three contiguous OHLC candles with real body-gap and midpoint checks."},
    {"name":"Stalled Pattern", "min_bars":3, "uses":"Bearish exhaustion warning after an uptrend: three white candles advance but the third body stalls/shrinks with a rejection wick.", "data_requirement":"Three contiguous OHLC candles and body-size comparison."},
    {"name":"Hikkake", "min_bars":4, "uses":"False-breakout setup: an inside bar is broken one way, then price closes back through the inside-bar boundary in the opposite direction.", "data_requirement":"Four contiguous OHLC bars with a measured inside bar and later failed-break/reclaim sequence."},
    {"name":"Modified Hikkake", "min_bars":4, "uses":"Stricter Hikkake variant requiring a particularly compressed inside bar before the false-break/reclaim.", "data_requirement":"Four contiguous OHLC bars; the inside bar must be small relative to its mother candle."},
    {"name":"Kicking by Length", "min_bars":2, "uses":"Opposite-color marubozu gap reversal; the longer second real body sets the candidate direction.", "data_requirement":"Two consecutive OHLC candles, opposite near-marubozu bodies, and a genuine directional gap."},
    {"name":"Black Candle", "min_bars":1, "uses":"Descriptive bearish candle-color tag only; deliberately neutral in scoring to avoid voting twice for color.", "data_requirement":"One OHLC candle with close below open."},
    {"name":"White Candle", "min_bars":1, "uses":"Descriptive bullish candle-color tag only; deliberately neutral in scoring to avoid voting twice for color.", "data_requirement":"One OHLC candle with close above open."},
    {"name":"Short Black Candle", "min_bars":1, "uses":"Descriptive small bearish real-body tag; neutral by itself, useful for harami/sequence context.", "data_requirement":"One OHLC candle and recent real-body baseline."},
    {"name":"Short White Candle", "min_bars":1, "uses":"Descriptive small bullish real-body tag; neutral by itself, useful for harami/sequence context.", "data_requirement":"One OHLC candle and recent real-body baseline."},
    {"name":"Black Spinning Top", "min_bars":1, "uses":"Neutral indecision tag for a black candle with a small body and meaningful upper/lower shadows.", "data_requirement":"One OHLC candle with measurable shadows."},
    {"name":"White Spinning Top", "min_bars":1, "uses":"Neutral indecision tag for a white candle with a small body and meaningful upper/lower shadows.", "data_requirement":"One OHLC candle with measurable shadows."},
    {"name":"Black Marubozu", "min_bars":1, "uses":"Bearish momentum tag for a black candle with minimal combined shadows; grouped with existing marubozu aliases.", "data_requirement":"One OHLC candle with body-to-range and shadow ratios."},
    {"name":"White Marubozu", "min_bars":1, "uses":"Bullish momentum tag for a white candle with minimal combined shadows; grouped with existing marubozu aliases.", "data_requirement":"One OHLC candle with body-to-range and shadow ratios."},
    {"name":"Opening Black Marubozu", "min_bars":1, "uses":"Bearish momentum variant opening near its high; lower shadow may remain.", "data_requirement":"One OHLC candle; upper-shadow ratio near zero."},
    {"name":"Opening White Marubozu", "min_bars":1, "uses":"Bullish momentum variant opening near its low; upper shadow may remain.", "data_requirement":"One OHLC candle; lower-shadow ratio near zero."},
    {"name":"Closing Black Marubozu", "min_bars":1, "uses":"Bearish momentum variant closing near its low; upper shadow may remain.", "data_requirement":"One OHLC candle; lower-shadow ratio near zero."},
    {"name":"Closing White Marubozu", "min_bars":1, "uses":"Bullish momentum variant closing near its high; lower shadow may remain.", "data_requirement":"One OHLC candle; upper-shadow ratio near zero."},
    {"name":"Above the Stomach", "min_bars":2, "uses":"Bullish reversal candidate after a downtrend: white candle opens and closes at/above the prior black body's midpoint.", "data_requirement":"Two consecutive OHLC candles; prior downtrend and body midpoint must be measurable."},
]


def _v15_pattern_slug(name: str) -> str:
    return re.sub(r"[^A-Z0-9]+", "_", str(name).upper()).strip("_")


def _v15_pattern_trend(ohlc: List[Tuple[float, float, float, float]], index: int,
                       ranges: List[float], lookback: int = 6) -> str:
    start = max(0, index - lookback)
    if index - start < 3:
        return "UNKNOWN"
    close_values = np.asarray([ohlc[k][3] for k in range(start, index)], dtype=float)
    if len(close_values) < 3:
        return "UNKNOWN"
    slope = float(np.polyfit(np.arange(len(close_values), dtype=float), close_values, 1)[0])
    delta = float(close_values[-1] - close_values[0])
    scale = max(1e-9, float(np.median(ranges[start:index])))
    if slope > 0 and delta > 0.25 * scale:
        return "UP"
    if slope < 0 and delta < -0.25 * scale:
        return "DOWN"
    return "SIDEWAYS"


def _v15_detect_named_pattern(name: str, candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Transparent OHLC rule for one extra named pattern; gaps remain true measured gaps."""
    rows = list(candles or [])
    spec = next((item for item in _V15_SUPPLEMENTAL_PATTERN_SPECS if item["name"] == name), None)
    if not spec or len(rows) < int(spec["min_bars"]):
        return []
    ohlc = [_candle_proxy_ohlc(row) for row in rows]
    opens = [float(item[0]) for item in ohlc]
    highs = [float(item[1]) for item in ohlc]
    lows = [float(item[2]) for item in ohlc]
    closes = [float(item[3]) for item in ohlc]
    ranges = [max(1e-9, highs[i] - lows[i]) for i in range(len(rows))]
    bodies = [abs(closes[i] - opens[i]) for i in range(len(rows))]
    uppers = [max(0.0, highs[i] - max(opens[i], closes[i])) for i in range(len(rows))]
    lowers = [max(0.0, min(opens[i], closes[i]) - lows[i]) for i in range(len(rows))]
    n = len(rows)
    events: List[Dict[str, Any]] = []
    begin = max(0, n - V15_PATTERN_LOOKBACK)
    med_range = max(1e-9, float(np.median(ranges[max(0, n-30):n])))
    med_body = max(1e-9, float(np.median(bodies[max(0, n-30):n])))
    tol = max(1e-9, med_range * 0.08)

    def contiguous(start: int, end: int) -> bool:
        return 0 <= start <= end < n and all(not bool(rows[pos].get("sequence_break_before")) for pos in range(start+1, end+1))

    def trend(start: int) -> str:
        return _v15_pattern_trend(ohlc, start, ranges)

    def bull(i: int) -> bool:
        return closes[i] > opens[i]

    def bear(i: int) -> bool:
        return closes[i] < opens[i]

    def doji(i: int) -> bool:
        return bodies[i] / ranges[i] <= 0.12

    def long_body(i: int) -> bool:
        local = max(1e-9, float(np.median(bodies[max(0, i-10):i] or bodies[max(0, n-30):n])))
        return bodies[i] >= 1.15 * local and bodies[i] / ranges[i] >= 0.52

    def body_gap_up(a: int, b: int) -> bool:
        return min(opens[b], closes[b]) > max(opens[a], closes[a]) + tol

    def body_gap_down(a: int, b: int) -> bool:
        return max(opens[b], closes[b]) < min(opens[a], closes[a]) - tol

    def gap_up(a: int, b: int) -> bool:
        return lows[b] > highs[a] + tol

    def gap_down(a: int, b: int) -> bool:
        return highs[b] < lows[a] - tol

    def emit(start: int, end: int, bias: float, strength: float, why: str,
             confirmed: bool = False, family: str = "supplemental_candlestick") -> None:
        code = _v15_pattern_slug(name)
        events.append({
            "name": code, "display_name": name, "bias": float(bias),
            "confirmed": bool(confirmed), "candle_indices": [int(start+1), int(end+1)],
            "strength": round(float(strength), 3), "raw_strength": round(float(strength), 3),
            "contextual_strength": round(float(strength), 3), "pattern_family": family,
            "context": str(why), "uses": str(spec["uses"]),
            "data_requirement": str(spec["data_requirement"]),
            "confirmation_status": "CONFIRMED_BY_LATER_VISIBLE_CLOSE" if confirmed else "FORMING_OR_REQUIRES_FOLLOW_THROUGH",
            "measurement_basis": "visible OHLC geometry; screen-pixel proxy where price-axis scale is unavailable",
            "not_a_calibrated_probability": True,
        })

    # Context-only primitive tags are evaluated on the newest candle only. They do not
    # compete with the existing color/momentum component in the directional score.
    if name in {"Black Candle", "White Candle", "Short Black Candle", "Short White Candle",
                "Black Spinning Top", "White Spinning Top", "Black Marubozu", "White Marubozu",
                "Opening Black Marubozu", "Opening White Marubozu", "Closing Black Marubozu", "Closing White Marubozu",
                "Takuri Line", "Northern Doji", "Southern Doji"}:
        candidates = [n-1]
    else:
        candidates = range(max(begin, int(spec["min_bars"])-1), n)

    for end in candidates:
        end = int(end)
        m = int(spec["min_bars"])
        start = end - m + 1
        if start < begin or start < 0 or not contiguous(start, end):
            continue
        o, h, l, c = ohlc[end]
        r, body, uw, lw = ranges[end], bodies[end], uppers[end], lowers[end]
        b = lambda i: bull(i)
        s = lambda i: bear(i)
        direction_bias: Optional[float] = None
        strength = 0.22
        why = "Measured geometry matched; context and follow-through remain necessary."
        confirmed = False

        if name == "Homing Pigeon":
            if s(start) and s(end) and long_body(start) and bodies[end] <= 0.72*bodies[start] and min(opens[end],closes[end]) >= min(opens[start],closes[start])-tol and max(opens[end],closes[end]) <= max(opens[start],closes[start])+tol and trend(start)=="DOWN":
                direction_bias, strength, why = 0.34, 0.36, "Two black bodies; the second is smaller and contained within the first body after a measured downtrend. Confirm with a later close above the pattern high."
                confirmed = end+1 < n and contiguous(start,end+1) and closes[end+1] > highs[end]
        elif name == "In Neck":
            if s(start) and b(end) and long_body(start) and opens[end] < lows[start]+tol and closes[end] > lows[start]-tol and closes[end] < closes[start]+0.25*ranges[start]:
                direction_bias, strength, why = -0.22, 0.25, "White rebound opens under the prior low but only recovers to the neck area; conventionally a weak bearish-continuation cue."
        elif name == "On Neck":
            if s(start) and b(end) and long_body(start) and opens[end] < lows[start]+tol and abs(closes[end]-lows[start]) <= tol:
                direction_bias, strength, why = -0.24, 0.26, "White candle opens below the prior low and closes almost on that low; bearish continuation is only a hypothesis."
        elif name == "Thrusting Line":
            midpoint = (opens[start]+closes[start])/2.0
            if s(start) and b(end) and long_body(start) and opens[end] < lows[start]+tol and closes[end] > closes[start] and closes[end] < midpoint:
                direction_bias, strength, why = -0.25, 0.27, "White candle thrusts into the lower half of a prior long black body but fails to regain its midpoint."
        elif name == "Bullish Doji Star":
            if s(start) and long_body(start) and doji(end) and body_gap_down(start,end) and trend(start)=="DOWN":
                direction_bias, strength, why = 0.14, 0.19, "Doji body is separated below a long black body after a downtrend; indecision only until a bullish close confirms."
                confirmed = end+1 < n and closes[end+1] > highs[end]
        elif name == "Bearish Doji Star":
            if b(start) and long_body(start) and doji(end) and body_gap_up(start,end) and trend(start)=="UP":
                direction_bias, strength, why = -0.14, 0.19, "Doji body is separated above a long white body after an uptrend; bearish direction requires later downside confirmation."
                confirmed = end+1 < n and closes[end+1] < lows[end]
        elif name == "Morning Doji Star":
            a, d, z = end-2, end-1, end
            if s(a) and long_body(a) and doji(d) and body_gap_down(a,d) and b(z) and closes[z] >= (opens[a]+closes[a])/2.0:
                direction_bias, strength, why, confirmed = 0.48, 0.48, "Three-bar morning doji star: black impulse, isolated doji, and white recovery through the first body's midpoint.", True
        elif name == "Evening Doji Star":
            a, d, z = end-2, end-1, end
            if b(a) and long_body(a) and doji(d) and body_gap_up(a,d) and s(z) and closes[z] <= (opens[a]+closes[a])/2.0:
                direction_bias, strength, why, confirmed = -0.48, 0.48, "Three-bar evening doji star: white impulse, isolated doji, and black decline through the first body's midpoint.", True
        elif name == "Matching Low":
            if s(start) and s(end) and abs(closes[start]-closes[end]) <= tol and trend(start)=="DOWN":
                direction_bias, strength, why = 0.23, 0.25, "Two black candles share nearly equal closes following a downtrend; the repeated close is a support candidate, not a guaranteed reversal."
                confirmed = end+1 < n and closes[end+1] > highs[end]
        elif name == "Matching High":
            if b(start) and b(end) and abs(closes[start]-closes[end]) <= tol and trend(start)=="UP":
                direction_bias, strength, why = -0.23, 0.25, "Two white candles share nearly equal closes following an uptrend; the repeated close is a resistance candidate."
                confirmed = end+1 < n and closes[end+1] < lows[end]
        elif name == "Rising Window":
            if gap_up(start,end):
                direction_bias, strength, why = 0.30, 0.31, "A real gap separates the prior high and current low; on continuous OTC/crypto charts this may be rare and must not be inferred from color alone."
                confirmed = end+1 < n and lows[end+1] >= highs[start]-tol
        elif name == "Falling Window":
            if gap_down(start,end):
                direction_bias, strength, why = -0.30, 0.31, "A real downward gap separates current high from the prior low; direction is weakened if price quickly reclaims the window."
                confirmed = end+1 < n and highs[end+1] <= lows[start]+tol
        elif name == "Upside Gap Three Methods":
            a, gap, pull = end-2, end-1, end
            if b(a) and b(gap) and gap_up(a,gap) and s(pull) and closes[pull] < opens[gap] and closes[pull] > highs[a]-tol:
                direction_bias, strength, why = 0.30, 0.32, "A black pullback partially enters an upside window without closing back beneath the first candle's high."
        elif name == "Downside Gap Three Methods":
            a, gap, pull = end-2, end-1, end
            if s(a) and s(gap) and gap_down(a,gap) and b(pull) and closes[pull] > opens[gap] and closes[pull] < lows[a]+tol:
                direction_bias, strength, why = -0.30, 0.32, "A white pullback partially enters a downside window without reclaiming the first candle's low."
        elif name == "Bullish Three-Line Strike":
            a,b1,c1,d=end-3,end-2,end-1,end
            if all(s(i) for i in (a,b1,c1)) and closes[b1] < closes[a] and closes[c1] < closes[b1] and b(d) and opens[d] <= closes[c1]+tol and closes[d] > opens[a] and bodies[d] >= 0.65*max(bodies[a],bodies[b1],bodies[c1]):
                direction_bias, strength, why, confirmed = 0.43, 0.46, "Three declining black bodies are reversed by a strong white strike closing above the first candle's open."
                confirmed = end+1 < n and closes[end+1] > highs[d]
        elif name == "Bearish Three-Line Strike":
            a,b1,c1,d=end-3,end-2,end-1,end
            if all(b(i) for i in (a,b1,c1)) and closes[b1] > closes[a] and closes[c1] > closes[b1] and s(d) and opens[d] >= closes[c1]-tol and closes[d] < opens[a] and bodies[d] >= 0.65*max(bodies[a],bodies[b1],bodies[c1]):
                direction_bias, strength, why = -0.43, 0.46, "Three advancing white bodies are reversed by a strong black strike closing below the first candle's open."
                confirmed = end+1 < n and closes[end+1] < lows[d]
        elif name == "Concealing Baby Swallow":
            a,b1,c1,d=end-3,end-2,end-1,end
            maru1 = bodies[a]/ranges[a] >= 0.78 and (uppers[a]+lowers[a])/ranges[a] <= 0.22
            maru2 = bodies[b1]/ranges[b1] >= 0.78 and (uppers[b1]+lowers[b1])/ranges[b1] <= 0.22
            if all(s(i) for i in (a,b1,c1,d)) and maru1 and maru2 and lows[b1] <= lows[a]+tol and uppers[c1] > 0.20*ranges[c1] and highs[d] > closes[c1] and closes[d] <= min(closes[a],closes[b1]):
                direction_bias, strength, why = 0.20, 0.23, "Four black candles match a strict concealing-baby-swallow geometry; very rare pattern and requires a later bullish break."
                confirmed = end+1 < n and closes[end+1] > highs[d]
        elif name == "Unique Three-River Bottom":
            a,b1,d=end-2,end-1,end
            hammer2 = s(b1) and lowers[b1] >= 1.25*max(bodies[b1],tol) and highs[b1] <= highs[a]+tol and lows[b1] < lows[a]
            small_white = b(d) and bodies[d] <= 0.65*bodies[b1] and closes[d] > closes[b1]
            if s(a) and long_body(a) and hammer2 and small_white and trend(a)=="DOWN":
                direction_bias, strength, why = 0.30, 0.32, "Three-bar bottom candidate with a long black candle, a lower-low hammer-like bar, and a small white recovery."
                confirmed = end+1 < n and closes[end+1] > highs[d]
        elif name == "Ladder Bottom":
            seq = list(range(end-4,end+1))
            if all(s(i) for i in seq[:4]) and all(closes[seq[k]] < closes[seq[k-1]] for k in range(1,4)) and b(seq[4]) and closes[seq[4]] > highs[seq[3]] and trend(seq[0])=="DOWN":
                direction_bias, strength, why, confirmed = 0.42, 0.45, "Four declining black candles are followed by a white candle that breaks above the fourth bar's high."
                confirmed = end+1 < n and closes[end+1] > highs[end]
        elif name == "Ladder Top":
            seq = list(range(end-4,end+1))
            if all(b(i) for i in seq[:4]) and all(closes[seq[k]] > closes[seq[k-1]] for k in range(1,4)) and s(seq[4]) and closes[seq[4]] < lows[seq[3]] and trend(seq[0])=="UP":
                direction_bias, strength, why = -0.36, 0.40, "Custom ladder-top exhaustion analogue: four advancing white candles are followed by a black close through the prior low."
        elif name == "Bullish Side-by-Side White Lines":
            a,b1,d=end-2,end-1,end
            similar = abs(bodies[b1]-bodies[d]) <= 0.35*max(bodies[b1],bodies[d],tol) and abs(opens[b1]-opens[d]) <= 0.35*med_range
            if gap_up(a,b1) and b(b1) and b(d) and similar and lows[b1] > highs[a] and lows[d] > highs[a]:
                direction_bias, strength, why = 0.26, 0.28, "Two similarly sized white candles remain side by side above a real upward gap; gap continuation requires later hold."
        elif name == "Bearish Side-by-Side White Lines":
            a,b1,d=end-2,end-1,end
            similar = abs(bodies[b1]-bodies[d]) <= 0.35*max(bodies[b1],bodies[d],tol) and abs(opens[b1]-opens[d]) <= 0.35*med_range
            if gap_down(a,b1) and b(b1) and b(d) and similar and highs[b1] < lows[a] and highs[d] < lows[a]:
                direction_bias, strength, why = -0.24, 0.26, "Two similar white candles remain below a real downside gap; white bar color does not erase bearish gap context."
        elif name == "Identical Three Crows":
            a,b1,d=end-2,end-1,end
            aligned = max(closes[a],closes[b1],closes[d])-min(closes[a],closes[b1],closes[d]) <= 0.22*med_range
            if all(s(i) for i in (a,b1,d)) and closes[b1] < closes[a] and closes[d] < closes[b1] and aligned and opens[b1] <= opens[a]+0.35*med_range and opens[d] <= opens[b1]+0.35*med_range:
                direction_bias, strength, why = -0.36, 0.38, "Three black candles descend with closely aligned body/close geometry; a fresh lower close supports bearish continuation."
        elif name == "Bullish Tasuki Line":
            a,gap,pull=end-2,end-1,end
            if b(a) and b(gap) and gap_up(a,gap) and s(pull) and closes[pull] < opens[gap] and closes[pull] > highs[a]+tol:
                direction_bias, strength, why = 0.30, 0.31, "Black pullback enters but does not close an upside window formed by the two bullish bars."
        elif name == "Bearish Tasuki Line":
            a,gap,pull=end-2,end-1,end
            if s(a) and s(gap) and gap_down(a,gap) and b(pull) and closes[pull] > opens[gap] and closes[pull] < lows[a]-tol:
                direction_bias, strength, why = -0.30, 0.31, "White pullback enters but does not close a downside window formed by the two bearish bars."
        elif name == "Takuri Line":
            if body/r <= 0.18 and lw >= 2.8*max(body,tol) and uw/r <= 0.12 and (trend(end)=="DOWN" or trend(end)=="UNKNOWN"):
                direction_bias, strength, why = 0.30, 0.32, "Tiny body with an exceptionally long lower shadow and tiny upper shadow; bullish only as rejection evidence after a decline."
        elif name == "Descending Hawk":
            if b(start) and b(end) and bodies[start] >= 1.15*med_body and bodies[end] < bodies[start] and min(opens[end],closes[end]) >= min(opens[start],closes[start])-tol and max(opens[end],closes[end]) <= max(opens[start],closes[start])+tol and trend(start)=="UP":
                direction_bias, strength, why = -0.25, 0.27, "Two white bodies after an uptrend; second body sits inside the first and warns of weakening upside momentum."
        elif name == "Two Black Gapping Candles":
            a,b1,d=end-2,end-1,end
            if b(a) and s(b1) and s(d) and body_gap_down(a,b1) and closes[d] < closes[b1] and bodies[b1]/ranges[b1] >= 0.45 and bodies[d]/ranges[d] >= 0.45:
                direction_bias, strength, why = -0.30, 0.32, "Two sizeable black bars follow a real downside body gap; continuation risk remains bearish unless price reclaims the gap."
        elif name == "Last Engulfing Bottom":
            if trend(start)=="DOWN" and b(start) and s(end) and min(opens[end],closes[end]) <= min(opens[start],closes[start])+tol and max(opens[end],closes[end]) >= max(opens[start],closes[start])-tol:
                direction_bias, strength, why = 0.12, 0.18, "Black body engulfs a white candle during a downtrend; this is context-sensitive and can continue lower, so bullish confirmation above the engulfing body is required."
                confirmed = end+1 < n and closes[end+1] > max(opens[end],closes[end])
        elif name == "Last Engulfing Top":
            if trend(start)=="UP" and s(start) and b(end) and min(opens[end],closes[end]) <= min(opens[start],closes[start])+tol and max(opens[end],closes[end]) >= max(opens[start],closes[start])-tol:
                direction_bias, strength, why = -0.12, 0.18, "White body engulfs a black candle during an uptrend; this is context-sensitive and requires later bearish confirmation."
                confirmed = end+1 < n and closes[end+1] < min(opens[end],closes[end])
        elif name == "Turn Up":
            prior_start = max(0, end-4)
            if b(end) and end > 0 and closes[end] > max(highs[prior_start:end]) + tol and trend(end)=="DOWN":
                direction_bias, strength, why, confirmed = 0.36, 0.38, "White close broke above the recent visible high after downside pressure; price confirmation has occurred, but follow-through is still needed.", True
        elif name == "Turn Down":
            prior_start = max(0, end-4)
            if s(end) and end > 0 and closes[end] < min(lows[prior_start:end]) - tol and trend(end)=="UP":
                direction_bias, strength, why, confirmed = -0.36, 0.38, "Black close broke below the recent visible low after upside pressure; price confirmation has occurred, but follow-through is still needed.", True
        elif name == "Northern Doji":
            look = max(0,end-8)
            local_high, local_low = max(highs[look:end+1]), min(lows[look:end+1])
            if doji(end) and trend(end)=="UP" and closes[end] >= local_low+0.70*(local_high-local_low):
                direction_bias, strength, why = -0.08, 0.12, "Doji near the upper part of the recent range after an uptrend; neutral indecision with slight exhaustion risk, not a sell trigger."
        elif name == "Southern Doji":
            look = max(0,end-8)
            local_high, local_low = max(highs[look:end+1]), min(lows[look:end+1])
            if doji(end) and trend(end)=="DOWN" and closes[end] <= local_low+0.30*(local_high-local_low):
                direction_bias, strength, why = 0.08, 0.12, "Doji near the lower part of the recent range after a downtrend; neutral indecision with slight rebound context, not a buy trigger."
        elif name == "Gapping Up Doji":
            if end > 0 and doji(end) and body_gap_up(end-1,end):
                direction_bias, strength, why = 0.0, 0.16, "A doji body is genuinely separated upward from the previous body; neutral until a breakout direction is confirmed."
        elif name == "Gapping Down Doji":
            if end > 0 and doji(end) and body_gap_down(end-1,end):
                direction_bias, strength, why = 0.0, 0.16, "A doji body is genuinely separated downward from the previous body; neutral until a breakout direction is confirmed."
        elif name == "Collapsing Doji Star":
            a,d,z=end-2,end-1,end
            if b(a) and long_body(a) and doji(d) and body_gap_up(a,d) and s(z) and closes[z] < (opens[a]+closes[a])/2.0:
                direction_bias, strength, why, confirmed = -0.38, 0.39, "A separated doji following a white impulse is followed by a black close below the first body's midpoint."
                confirmed = end+1 < n and closes[end+1] < lows[z]
        elif name == "Stalled Pattern":
            a,b1,z=end-2,end-1,end
            if all(b(i) for i in (a,b1,z)) and closes[b1] > closes[a] and closes[z] >= closes[b1]-0.15*r and bodies[z] <= 0.65*min(bodies[a],bodies[b1]) and (uppers[z] >= 0.25*r or closes[z] <= closes[b1]):
                direction_bias, strength, why = -0.20, 0.23, "Three white candles advance but the final real body shrinks/stalls; treat as exhaustion risk pending a bearish break."
                confirmed = end+1 < n and closes[end+1] < lows[z]
        elif name in {"Hikkake", "Modified Hikkake"}:
            a, inside, failed, reclaim = end-3,end-2,end-1,end
            inside_ok = highs[inside] < highs[a] and lows[inside] > lows[a]
            compressed_ok = ranges[inside] <= 0.55*ranges[a]
            if inside_ok and (name != "Modified Hikkake" or compressed_ok):
                if lows[failed] < lows[a]-tol and closes[reclaim] > highs[inside]+tol:
                    direction_bias, strength, why, confirmed = 0.35, 0.38, "Inside bar broke below its mother range, then a later close reclaimed above the inside-bar high: bullish failed-break/reversal sequence.", True
                elif highs[failed] > highs[a]+tol and closes[reclaim] < lows[inside]-tol:
                    direction_bias, strength, why, confirmed = -0.35, 0.38, "Inside bar broke above its mother range, then a later close fell below the inside-bar low: bearish failed-break/reversal sequence.", True
        elif name == "Kicking by Length":
            if end > 0 and ((b(end) and s(end-1)) or (s(end) and b(end-1))):
                maru_prev = bodies[end-1]/ranges[end-1] >= 0.78 and (uppers[end-1]+lowers[end-1])/ranges[end-1] <= 0.22
                maru_curr = bodies[end]/ranges[end] >= 0.78 and (uw+lw)/r <= 0.22
                separated = gap_up(end-1,end) if b(end) else gap_down(end-1,end)
                if maru_prev and maru_curr and separated:
                    side = 1 if b(end) else -1
                    direction_bias, strength, why = side*0.35, 0.37, "Opposite-color near-marubozu candles are separated by a measured gap; the second candle is the longer directional body only if its body exceeds the first."
                    if bodies[end] <= bodies[end-1]:
                        direction_bias *= 0.65
        elif name == "Black Candle":
            if bear(end): direction_bias, strength, why = 0.0, 0.10, "Latest candle closes below open; descriptive color only, no independent directional score vote."
        elif name == "White Candle":
            if bull(end): direction_bias, strength, why = 0.0, 0.10, "Latest candle closes above open; descriptive color only, no independent directional score vote."
        elif name == "Short Black Candle":
            if bear(end) and body <= 0.55*med_body and body/r <= 0.48:
                direction_bias, strength, why = 0.0, 0.12, "Small black real body relative to recent candles; contextual tag only."
        elif name == "Short White Candle":
            if bull(end) and body <= 0.55*med_body and body/r <= 0.48:
                direction_bias, strength, why = 0.0, 0.12, "Small white real body relative to recent candles; contextual tag only."
        elif name == "Black Spinning Top":
            if bear(end) and body/r <= 0.30 and uw/r >= 0.15 and lw/r >= 0.15:
                direction_bias, strength, why = 0.0, 0.15, "Black spinning top has a small body and two-sided shadows; neutral indecision tag."
        elif name == "White Spinning Top":
            if bull(end) and body/r <= 0.30 and uw/r >= 0.15 and lw/r >= 0.15:
                direction_bias, strength, why = 0.0, 0.15, "White spinning top has a small body and two-sided shadows; neutral indecision tag."
        elif name == "Black Marubozu":
            if bear(end) and body/r >= 0.80 and (uw+lw)/r <= 0.20:
                direction_bias, strength, why = -0.28, 0.29, "Black marubozu has a dominant real body and tiny combined shadows; grouped with existing marubozu evidence."
        elif name == "White Marubozu":
            if bull(end) and body/r >= 0.80 and (uw+lw)/r <= 0.20:
                direction_bias, strength, why = 0.28, 0.29, "White marubozu has a dominant real body and tiny combined shadows; grouped with existing marubozu evidence."
        elif name == "Opening Black Marubozu":
            if bear(end) and body/r >= 0.65 and uw/r <= 0.08 and lw/r <= 0.28:
                direction_bias, strength, why = -0.24, 0.26, "Black candle opens near its high; lower shadow may remain, so this is the opening-marubozu variant."
        elif name == "Opening White Marubozu":
            if bull(end) and body/r >= 0.65 and lw/r <= 0.08 and uw/r <= 0.28:
                direction_bias, strength, why = 0.24, 0.26, "White candle opens near its low; upper shadow may remain, so this is the opening-marubozu variant."
        elif name == "Closing Black Marubozu":
            if bear(end) and body/r >= 0.65 and lw/r <= 0.08 and uw/r <= 0.28:
                direction_bias, strength, why = -0.24, 0.26, "Black candle closes near its low; upper shadow may remain, so this is the closing-marubozu variant."
        elif name == "Closing White Marubozu":
            if bull(end) and body/r >= 0.65 and uw/r <= 0.08 and lw/r <= 0.28:
                direction_bias, strength, why = 0.24, 0.26, "White candle closes near its high; lower shadow may remain, so this is the closing-marubozu variant."
        elif name == "Above the Stomach":
            midpoint = (opens[start]+closes[start])/2.0
            if s(start) and b(end) and trend(start)=="DOWN" and opens[end] >= midpoint-tol and closes[end] >= midpoint-tol and closes[end] < opens[start]+tol:
                direction_bias, strength, why = 0.24, 0.27, "Following a downtrend, the white candle opens and closes at/above the prior black body's midpoint; stronger if a later high is broken."
                confirmed = end+1 < n and closes[end+1] > highs[end]

        if direction_bias is not None:
            emit(start, end, direction_bias, strength, why, confirmed)

    # Dedupe this named rule's identical span; keep the strongest/confirmed occurrence.
    unique: Dict[Tuple[str, Tuple[int, ...]], Dict[str, Any]] = {}
    for row in events:
        key = (str(row.get("name") or ""), tuple(row.get("candle_indices") or []))
        prior = unique.get(key)
        if prior is None or (bool(row.get("confirmed")) and not bool(prior.get("confirmed"))) or float(row.get("strength") or 0) > float(prior.get("strength") or 0):
            unique[key] = row
    return list(unique.values())


def _v15_make_pattern_detector(name: str):
    """Create a unique public callable for each pattern while sharing validated OHLC primitives."""
    def detector(candles: List[Dict[str, Any]], scan_context: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
        return _v15_detect_named_pattern(name, candles)
    detector.__name__ = "_v15_detect_" + _v15_pattern_slug(name).lower()
    detector.__qualname__ = detector.__name__
    detector.__doc__ = next((row["uses"] for row in _V15_SUPPLEMENTAL_PATTERN_SPECS if row["name"] == name), "Supplemental candlestick detector")
    return detector


_V15_EXTRA_PATTERN_DETECTORS = {row["name"]: _v15_make_pattern_detector(row["name"]) for row in _V15_SUPPLEMENTAL_PATTERN_SPECS}
_V15_EXTRA_PATTERN_SPEC_BY_NAME = {row["name"]: row for row in _V15_SUPPLEMENTAL_PATTERN_SPECS}


def _v15_scan_extra_patterns(candles: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Run every additional named rule and merge events into the existing shared pattern score route."""
    rows = list(candles or [])
    if not rows:
        return []
    events: List[Dict[str, Any]] = []
    for name, detector in _V15_EXTRA_PATTERN_DETECTORS.items():
        try:
            events.extend(detector(rows))
        except (TypeError, ValueError, IndexError, OverflowError, FloatingPointError):
            # One malformed visual row must not crash every other pattern rule or the live screen loop.
            continue
    return events


def _v15_supplemental_pattern_report(analysis: Dict[str, Any]) -> Dict[str, Any]:
    rows = list(analysis.get("candles") or [])
    names_seen = {str(row.get("name") or "").upper() for row in (analysis.get("patterns") or []) if isinstance(row, dict)}
    detail = []
    for spec in _V15_SUPPLEMENTAL_PATTERN_SPECS:
        slug = _v15_pattern_slug(spec["name"])
        matched = [row for row in (analysis.get("patterns") or []) if isinstance(row, dict) and str(row.get("name") or "").upper() == slug]
        detail.append({
            "name": spec["name"], "callable_name": _V15_EXTRA_PATTERN_DETECTORS[spec["name"]].__name__,
            "function_implemented": callable(_V15_EXTRA_PATTERN_DETECTORS[spec["name"]]),
            "uses": spec["uses"], "data_requirement": spec["data_requirement"],
            "evaluated_for_this_chart": len(rows) >= int(spec["min_bars"]),
            "matched_this_chart": bool(matched), "match_count": len(matched),
            "event_names": [row.get("name") for row in matched[:10]],
            "score_role": "Direction-bearing events join existing recency/trend/location/context weighting; neutral tags do not vote; aliases cluster by candle endpoint.",
            "score_connection": "_extended_candle_patterns -> _apply_pattern_context -> _weighted_recent_pattern_bias -> fixed five-minute score",
            "not_a_calibrated_probability": True,
        })
    return {
        "version": "15.0-supplemental-technical-candlestick-rules",
        "feature_count": len(detail), "unique_callable_count": len({row["callable_name"] for row in detail}),
        "evaluated_count": sum(bool(row["evaluated_for_this_chart"]) for row in detail),
        "matched_count": sum(bool(row["matched_this_chart"]) for row in detail),
        "score_connection": "All measured directional outputs enter the existing five-minute context-aware pattern weighting. Primitive candle-color tags and doji/gap-neutral events have zero bias and cannot independently force BUY/SELL.",
        "source_limit": "The rules use visible OHLC geometry. When the chart is only pixel-estimated, price levels are proxies; gaps require measured separation and are not fabricated. Actual OTC results require broker-aligned outcome data.",
        "all_features": detail,
    }


# Keep the exact 169-item legacy feature catalog stable; attach the added candle patterns as a
# separate, explicit extension audit so the old one-to-one coverage tests and public API remain intact.
_V15_PREVIOUS_ATTACH_COVERAGE = _attach_requested_analysis_coverage

def _attach_requested_analysis_coverage(result: Dict[str, Any]) -> Dict[str, Any]:
    result = _V15_PREVIOUS_ATTACH_COVERAGE(result)
    try:
        audit = _v15_supplemental_pattern_report(result)
        result["v15_supplemental_pattern_analysis"] = audit.get("all_features", [])
        result["v15_supplemental_pattern_count"] = audit["feature_count"]
        result["v15_supplemental_pattern_coverage"] = {key: value for key, value in audit.items() if key != "all_features"}
        result.setdefault("connected_feature_audit", {})["v15_supplemental_patterns"] = {
            "feature_count": audit["feature_count"], "unique_callable_count": audit["unique_callable_count"],
            "matched_count": audit["matched_count"], "score_connection": audit["score_connection"],
        }
    except Exception as exc:
        result.setdefault("v15_supplemental_pattern_coverage", {"available": False, "error_type": type(exc).__name__})
    return result


def _v15_draw_line_only_projection(image: np.ndarray, candles: List[Dict[str, Any]],
                                   forecast_display: Dict[str, Any], score_hidden: bool = False) -> np.ndarray:
    """Draw a five-step scenario path and expanding uncertainty guides inside the real chart image."""
    if not isinstance(image, np.ndarray) or image.size == 0 or not candles:
        return image
    canvas = image.copy()
    h, w = canvas.shape[:2]
    if w < 40 or h < 40:
        return canvas
    last = candles[-1]
    last_x = int(round(float(last.get("slot_center_x", float(last.get("x", 0)) + float(last.get("width", 1))/2))))
    last_y = int(round(float(last.get("estimated_close_pixel", last.get("body_top_pixel", h/2)))))
    last_x = int(clamp(last_x, 1, w-2)); last_y = int(clamp(last_y, 1, h-2))
    right_x = w - 6
    # Use existing unused chart space to the right of the latest candle; do not extend the preview.
    if right_x - last_x < 18:
        path_start_x = max(3, int(round(w*0.70)))
        path_start_x = min(path_start_x, right_x-10)
    else:
        path_start_x = min(right_x-12, last_x+3)
    direction = str(forecast_display.get("direction") or "").upper()
    bias = parse_float(forecast_display.get("bias"), 0.0) or 0.0
    if direction not in ("BUY", "SELL"):
        direction = "NEUTRAL"
    if direction == "BUY": bias = abs(bias) if abs(bias) > 0 else 0.12
    elif direction == "SELL": bias = -abs(bias) if abs(bias) > 0 else -0.12
    local_ranges = [float(row.get("height", 0) or 0) for row in candles[-min(30,len(candles)):]]
    local_ranges = [v for v in local_ranges if v > 0]
    typical = max(3.0, float(np.median(local_ranges)) if local_ranges else h*0.025)
    distance = min(h*0.18, max(4.0, typical*(0.45+2.6*abs(bias))))
    if direction == "BUY": target_y = int(clamp(last_y-distance, 5, h-6)); color = "#00e28b"
    elif direction == "SELL": target_y = int(clamp(last_y+distance, 5, h-6)); color = "#ff5364"
    else: target_y = last_y; color = "#cbd5e1"
    if right_x <= path_start_x:
        path_start_x = max(2, right_x-8)
    step = max(1.0, (right_x-path_start_x)/5.0)
    points = [(path_start_x,last_y)]
    for i in range(1,6):
        x = int(round(path_start_x+step*i))
        linear = last_y+(target_y-last_y)*(i/5.0)
        wiggle = (0.0 if i==5 else min(typical*0.20,h*0.025)*(1 if i%2 else -1))
        y = int(clamp(round(linear+wiggle),5,h-6))
        points.append((x,y))
    # Price-direction channel is visual uncertainty only; it is not a calibrated probability interval.
    upper_points=[]; lower_points=[]
    for i,(x,y) in enumerate(points):
        half = min(h*0.09, max(3.0,typical*(0.25+0.16*i)))
        upper_points.append((x,int(clamp(y-half,4,h-5))))
        lower_points.append((x,int(clamp(y+half,4,h-5))))
    if len(upper_points)>1:
        cv2.polylines(canvas,[np.asarray(upper_points,dtype=np.int32)],False,(150,150,150),1,cv2.LINE_AA)
        cv2.polylines(canvas,[np.asarray(lower_points,dtype=np.int32)],False,(150,150,150),1,cv2.LINE_AA)
        for line_points in (upper_points,lower_points):
            for p1,p2 in zip(line_points,line_points[1:]):
                if max(p1[0],p2[0])-min(p1[0],p2[0])>0:
                    cv2.line(canvas,p1,p2,(150,150,150),1,cv2.LINE_AA)
    cv2.polylines(canvas,[np.asarray(points,dtype=np.int32)],False,
                  (0,226,139) if direction=="BUY" else (80,95,255) if direction=="SELL" else (190,190,190),2,cv2.LINE_AA)
    if len(points)>=2:
        cv2.arrowedLine(canvas,points[-2],points[-1],(0,226,139) if direction=="BUY" else (80,95,255) if direction=="SELL" else (190,190,190),2,cv2.LINE_AA,tipLength=0.35)
    # The caption names a scenario and deliberately calls the percentage a model score.
    score = parse_float(forecast_display.get("confidence"),None)
    caption = "5M SCENARIO: " + direction
    if not score_hidden and score is not None:
        caption += f" | MODEL SCORE {score:.0f}%"
    caption += " | NOT A WIN-RATE"
    max_caption_width = min(w-8,760)
    cv2.rectangle(canvas,(5,5),(max(6,max_caption_width),26),(7,18,38),-1)
    cv2.putText(canvas,caption[:100],(10,19),cv2.FONT_HERSHEY_SIMPLEX,0.34,(220,235,255),1,cv2.LINE_AA)
    return canvas


def _append_five_minute_projection_panel(image: np.ndarray, candles: List[Dict[str, Any]],
                                         forecast_display: Dict[str, Any], candle_analysis: Dict[str, Any],
                                         score_hidden: bool = False) -> np.ndarray:
    """V15 compatibility name: no side panel or synthetic future candle drawings; line-only chart path."""
    return _v15_draw_line_only_projection(image, candles, forecast_display, score_hidden)


class LiveChartOverlay:
    """Transparent Windows overlay aligned to the selected chart plot; clicks pass through."""
    def __init__(self, root: tk.Tk) -> None:
        self.root = root
        self.window = tk.Toplevel(root)
        self.window.title("PUTRA_V15_CLICK_THROUGH_CHART_OVERLAY")
        self.window.overrideredirect(True)
        self.window.attributes("-topmost", True)
        self.window.configure(bg=V15_OVERLAY_TRANSPARENT_KEY)
        self.canvas = tk.Canvas(self.window, bg=V15_OVERLAY_TRANSPARENT_KEY, highlightthickness=0, bd=0)
        self.canvas.pack(fill="both", expand=True)
        self.active = False
        self.enabled = False
        self.hwnd = None
        self._transparent_supported = False
        self.window.geometry("1x1+0+0")
        self.window.withdraw()
        try:
            if os.name == "nt":
                self.window.attributes("-transparentcolor", V15_OVERLAY_TRANSPARENT_KEY)
                self._transparent_supported = True
                self.window.update_idletasks()
                self.hwnd = self._root_hwnd()
                self.enabled = self._apply_clickthrough_styles()
        except Exception:
            self.enabled = False
        if not self.enabled:
            try: self.window.withdraw()
            except Exception: pass

    def _root_hwnd(self):
        if os.name != "nt": return None
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        hwnd = int(self.window.winfo_id())
        try:
            root_hwnd = user32.GetAncestor(wintypes.HWND(hwnd), 2)
            if root_hwnd: hwnd = int(root_hwnd)
        except Exception:
            pass
        return hwnd

    def _apply_clickthrough_styles(self) -> bool:
        if os.name != "nt" or not self._transparent_supported or not self.hwnd:
            return False
        try:
            import ctypes
            from ctypes import wintypes
            user32 = ctypes.windll.user32
            GWL_EXSTYLE = -20
            WS_EX_LAYERED = 0x00080000
            WS_EX_TRANSPARENT = 0x00000020
            WS_EX_TOOLWINDOW = 0x00000080
            WS_EX_NOACTIVATE = 0x08000000
            if ctypes.sizeof(ctypes.c_void_p) == 8:
                get_long = user32.GetWindowLongPtrW
                set_long = user32.SetWindowLongPtrW
                get_long.restype = ctypes.c_ssize_t
                set_long.restype = ctypes.c_ssize_t
            else:
                get_long = user32.GetWindowLongW
                set_long = user32.SetWindowLongW
                get_long.restype = ctypes.c_long
                set_long.restype = ctypes.c_long
            get_long.argtypes = [wintypes.HWND, ctypes.c_int]
            set_long.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_ssize_t if ctypes.sizeof(ctypes.c_void_p)==8 else ctypes.c_long]
            exstyle = int(get_long(wintypes.HWND(self.hwnd), GWL_EXSTYLE))
            exstyle |= WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE
            set_long(wintypes.HWND(self.hwnd), GWL_EXSTYLE, exstyle)
            user32.SetWindowPos(wintypes.HWND(self.hwnd), wintypes.HWND(-1), 0,0,0,0, 0x0001|0x0002|0x0010|0x0020)
            return True
        except Exception:
            return False

    def hide_native(self) -> None:
        """Capture-thread-safe native hide before grabbing the live chart, preventing overlay feedback."""
        if not self.enabled or not self.active or not self.hwnd or os.name != "nt": return
        try:
            import ctypes
            ctypes.windll.user32.ShowWindow(int(self.hwnd), 0)  # SW_HIDE
        except Exception:
            pass

    def show_native(self) -> None:
        """Capture-thread-safe show without activation after the screenshot is already grabbed."""
        if not self.enabled or not self.active or not self.hwnd or os.name != "nt": return
        try:
            import ctypes
            ctypes.windll.user32.ShowWindow(int(self.hwnd), 4)  # SW_SHOWNOACTIVATE
        except Exception:
            pass

    @staticmethod
    def _canvas_color(bias: float) -> str:
        return "#00e28b" if bias > 0 else "#ff5364" if bias < 0 else "#d1d5db"

    def render_result(self, result: Dict[str, Any], region: Optional[Dict[str, int]], hide_score: bool = False) -> None:
        if not self.enabled or not region or not isinstance(result,dict):
            self.hide()
            return
        candle_result = result.get("candle_result") or {}
        candle_analysis = result.get("candle_analysis") or {}
        candles = list(candle_result.get("candles") or [])
        if not candles:
            self.hide(); return
        shape = result.get("chart_crop_shape") or (0,0)
        height = int(shape[0]) if len(shape)>0 else 0
        width = int(shape[1]) if len(shape)>1 else 0
        roi = candle_result.get("chart_region") or {}
        roi_x = int(roi.get("x",0) or 0); roi_y = int(roi.get("y",0) or 0)
        width = max(1,min(width,int(roi.get("width",width) or width)))
        height = max(1,min(height,int(roi.get("height",height) or height)))
        left = int(region.get("left",0))+roi_x
        top = int(region.get("top",0))+roi_y
        self.window.geometry(f"{width}x{height}+{left}+{top}")
        self.canvas.configure(width=width,height=height)
        self.canvas.delete("all")
        self.canvas.configure(bg=V15_OVERLAY_TRANSPARENT_KEY)
        self.window.configure(bg=V15_OVERLAY_TRANSPARENT_KEY)
        # Mark recent candle formations with bounded boxes and their canonical names.
        patterns = list(candle_analysis.get("patterns") or [])
        indexed = []
        for item in patterns:
            if not isinstance(item,dict): continue
            idxs = item.get("candle_indices") or []
            parsed = [int(v)-1 for v in idxs if parse_float(v,None) is not None and 1<=int(v)<=len(candles)]
            if not parsed or max(parsed) < len(candles)-15: continue
            indexed.append((item,parsed))
        indexed.sort(key=lambda pair:(max(pair[1]),bool(pair[0].get("confirmed")),float(parse_float(pair[0].get("strength"),0.0) or 0.0)),reverse=True)
        seen=set(); label_rows=[]
        for item,idxs in indexed:
            name = str(item.get("display_name") or item.get("name") or "PATTERN").replace("_"," ").strip()
            if not name or name in seen: continue
            seen.add(name); label_rows.append((item,idxs,name))
            if len(label_rows)>=V15_MAX_PATTERN_LABELS_ON_LIVE_CHART: break
        for row_no,(item,idxs,name) in enumerate(label_rows):
            x_left=min(float(candles[i].get("x",0)) for i in idxs)-2
            x_right=max(float(candles[i].get("x",0))+float(candles[i].get("width",1)) for i in idxs)+2
            y_top=min(float(candles[i].get("wick_top_pixel",candles[i].get("y",0))) for i in idxs)-2
            y_bottom=max(float(candles[i].get("wick_bottom_pixel", float(candles[i].get("y", 0)) + float(candles[i].get("height", 1)))) for i in idxs)+2
            x_left=int(clamp(x_left,1,width-2)); x_right=int(clamp(x_right,x_left+1,width-1))
            y_top=int(clamp(y_top,1,height-2)); y_bottom=int(clamp(y_bottom,y_top+1,height-1))
            bias=float(parse_float(item.get("bias"),0.0) or 0.0); color=self._canvas_color(bias)
            self.canvas.create_rectangle(x_left,y_top,x_right,y_bottom,outline=color,width=1)
            conf=" CONF" if item.get("confirmed") else " FORMING"
            label=(name+conf)[:44]
            label_w=min(width-4,max(64,8+len(label)*6))
            label_x=int(clamp(x_left,2,max(2,width-label_w-2)))
            label_y=y_top-17 if y_top>=20 else min(height-17,y_bottom+2+row_no*2)
            self.canvas.create_rectangle(label_x,label_y,label_x+label_w,label_y+15,fill="#071526",outline=color,width=1)
            self.canvas.create_text(label_x+4,label_y+7,anchor="w",text=label,fill=color,font=("Segoe UI",8,"bold"))

        # Draw confirmed HH/HL/LH/LL pivots plus BOS/CHoCH/retest guides using the same scanner output.
        structure = candle_analysis.get("structure_drawings") or result.get("structure_drawings") or {}
        for swing in (structure.get("swing_labels") or [])[-8:]:
            x=int(clamp(parse_float(swing.get("x"),0) or 0,2,width-2)); y=int(clamp(parse_float(swing.get("y"),0) or 0,2,height-2))
            col="#63c5ff" if str(swing.get("kind"))=="HIGH" else "#ffc857"
            self.canvas.create_text(x,y-8,text=str(swing.get("label") or ""),fill=col,font=("Segoe UI",8,"bold"))
        for key,label,color in (("break_y",str(structure.get("event") or "BOS/CHOCH"),"#00e28b" if "BULLISH" in str(structure.get("event")) else "#ff5364"),
                                ("invalidation_y","INVALIDATION","#e5e7eb")):
            y = parse_float(structure.get(key),None)
            if y is None or not 1<=y<height: continue
            yy=int(round(y)); self.canvas.create_line(3,yy,width-4,yy,fill=color,dash=(5,4),width=1)
            self.canvas.create_text(max(5,width-5),max(8,yy-8),anchor="e",text=label[:32],fill=color,font=("Segoe UI",8,"bold"))

        # Draw support/resistance zones from the same analysis values used by scoring.
        for zone,label,color in [*((z,"RESISTANCE","#ff6470") for z in (candle_analysis.get("resistance_pixel_zones") or [])[:2]),
                                 *((z,"SUPPORT","#42e8a0") for z in (candle_analysis.get("support_pixel_zones") or [])[:2])]:
            y=parse_float(zone.get("pixel_y"),None)
            if y is None or not 1<=y<height: continue
            yy=int(round(y)); self.canvas.create_line(1,yy,width-2,yy,fill=color,dash=(3,4),width=1)
            self.canvas.create_text(4,max(8,yy-8),anchor="w",text=label,fill=color,font=("Segoe UI",7,"bold"))

        # Forecast is a five-minute line-and-channel scenario; no synthetic future candle bars are drawn.
        latest = candles[-1]
        latest_x=int(round(float(latest.get("slot_center_x",float(latest.get("x",0))+float(latest.get("width",1))/2))))
        latest_y=int(round(float(latest.get("estimated_close_pixel",latest.get("body_top_pixel",height/2)))))
        forecast = candle_analysis.get("five_minute_forecast_display") or {}
        direction=str(forecast.get("direction") or result.get("direction") or "NEUTRAL").upper()
        if direction not in ("BUY","SELL"): direction="NEUTRAL"
        bias=float(parse_float(forecast.get("bias"),result.get("bias",0.0)) or 0.0)
        sign=-1 if direction=="BUY" else 1 if direction=="SELL" else 0
        recent_ranges=[float(row.get("height",0) or 0) for row in candles[-min(30,len(candles)):]]
        recent_ranges=[v for v in recent_ranges if v>0]
        typical=max(3.0,float(np.median(recent_ranges)) if recent_ranges else height*.025)
        endpoint_distance=min(height*.18,max(4.0,typical*(.45+2.6*abs(bias))))
        target_y=int(clamp(latest_y+sign*endpoint_distance,5,height-6))
        right_x=width-5
        path_start_x=min(max(3,latest_x+3),max(3,right_x-12))
        if right_x-path_start_x<12: path_start_x=max(3,int(width*.70))
        step=max(1.0,(right_x-path_start_x)/5.0)
        points=[(path_start_x,int(clamp(latest_y,3,height-4)))]
        for i in range(1,6):
            x=int(round(path_start_x+step*i))
            wiggle=0 if i==5 else min(typical*.20,height*.025)*(1 if i%2 else -1)
            y=int(clamp(round(latest_y+(target_y-latest_y)*i/5+wiggle),4,height-5))
            points.append((x,y))
        line_color="#00e28b" if direction=="BUY" else "#ff5364" if direction=="SELL" else "#d1d5db"
        upper=[]; lower=[]
        for i,(x,y) in enumerate(points):
            half=min(height*.08,max(3.0,typical*(.25+i*.15)))
            upper.append((x,int(clamp(y-half,3,height-4)))); lower.append((x,int(clamp(y+half,3,height-4))))
        self.canvas.create_line(*[v for p in upper for v in p],fill="#cbd5e1",dash=(5,4),width=1,smooth=True)
        self.canvas.create_line(*[v for p in lower for v in p],fill="#cbd5e1",dash=(5,4),width=1,smooth=True)
        self.canvas.create_line(*[v for p in points for v in p],fill=line_color,width=2,smooth=True,arrow=tk.LAST)
        score=parse_float(forecast.get("confidence"),None)
        caption=f"5M SCENARIO {direction}"
        if not hide_score and score is not None: caption+=f" | MODEL SCORE {score:.0f}%"
        caption+=" | NOT WIN-RATE"
        x_label=max(4,min(width-4,max(4,path_start_x-15)))
        self.canvas.create_rectangle(4,3,min(width-4,max(120,4+len(caption)*6)),20,fill="#071526",outline=line_color,width=1)
        self.canvas.create_text(8,11,anchor="w",text=caption[:72],fill=line_color,font=("Segoe UI",8,"bold"))
        self.active = True
        self.window.deiconify()
        self.window.lift()
        self._apply_clickthrough_styles()
        self.show_native()

    def hide(self) -> None:
        self.active = False
        try: self.window.withdraw()
        except Exception: pass

    def close(self) -> None:
        self.active = False
        try: self.window.destroy()
        except Exception: pass


def _v15_regression_tests() -> int:
    checks: List[Tuple[str,bool]]=[]
    def check(label: str, condition: Any) -> None: checks.append((label,bool(condition)))
    names=[row["name"] for row in _V15_SUPPLEMENTAL_PATTERN_SPECS]
    detector_names=[fn.__name__ for fn in _V15_EXTRA_PATTERN_DETECTORS.values()]
    check("V15 includes every requested supplemental pattern with its own unique callable/use/data requirement",
          len(names)==len(set(names)) and len(_V15_EXTRA_PATTERN_DETECTORS)==len(names)
          and len(set(detector_names))==len(names)
          and all(callable(fn) for fn in _V15_EXTRA_PATTERN_DETECTORS.values())
          and all(row.get("uses") and row.get("data_requirement") for row in _V15_SUPPLEMENTAL_PATTERN_SPECS))
    fixture=[]
    # Synthetic only: a downtrend with a Homing Pigeon body sequence; these values are not market data.
    vals=[(110,112,107,108),(108,109,103,104),(104,105,100,101),(101,102,97,98),(98,99,93,94),
          (94,95,90,91),(91,92,88,89),(89,90,87,88),(89,90,87.5,88.2)]
    for i,(o,h,l,c) in enumerate(vals):
        fixture.append({"index":i+1,"estimated_open_price":o,"estimated_high_price":h,"estimated_low_price":l,"estimated_close_price":c,
                       "estimated_open_pixel":-o,"estimated_close_pixel":-c,"wick_top_pixel":-h,"wick_bottom_pixel":-l,
                       "body_top_pixel":-max(o,c),"body_bottom_pixel":-min(o,c),"body_height_pixels":abs(c-o),
                       "upper_wick_pixels":h-max(o,c),"lower_wick_pixels":min(o,c)-l,"width":5,"height":int(h-l),
                       "x":i*8,"slot_center_x":i*8+2,"y":int(-h),"color":"GREEN" if c>o else "RED","sequence_break_before":False})
    all_events=_v15_scan_extra_patterns(fixture)
    check("V15 all supplemental detector callables execute safely on structured OHLC candles",
          all(isinstance(_V15_EXTRA_PATTERN_DETECTORS[name](fixture),list) for name in names))
    check("V15 event stream preserves named uses, measured candle spans and non-probability metadata",
          all(row.get("name") and row.get("candle_indices") and row.get("uses") and row.get("not_a_calibrated_probability") is True for row in all_events))
    check("V15 keeps forecast output size unchanged and draws no synthetic future candle panel",
          _append_five_minute_projection_panel(np.zeros((240,420,3),dtype=np.uint8),fixture,{"direction":"BUY","bias":0.3,"confidence":70}, {}) .shape==(240,420,3))
    check("V15 retains the original 169-feature registry and wires extra pattern events into extended scanner",
          len(_V10_CATALOG_NAMES)==169 and len(_V13_FEATURE_DETECTORS)==169
          and len(_extended_candle_patterns(fixture)) >= len(_V13_PREVIOUS_EXTENDED_CANDLE_PATTERNS(fixture)))
    passed=sum(ok for _,ok in checks)
    for label,ok in checks: print(("PASS" if ok else "FAIL")+" | "+label,flush=True)
    print(f"BOT 15.0 SUPPLEMENTAL PATTERN / LINE-ONLY PROJECTION TEST: {passed}/{len(checks)} passed",flush=True)
    return 0 if passed==len(checks) else 1

# ======================== END PUTRA TRADING BOT 17.0 ==========================


# ======================== PUTRA TRADING BOT 17.0 ==============================
# V17 changes the final scoring/score-synchronization layer only. All existing candle
# detection, live capture, chart drawing, panel layout, alerts, and broker/manual-order
# flow remain intact. It consumes the existing pattern event stream instead of rewriting
# or replacing individual pattern rules.
V17_MODEL_VERSION = "putra_trading_bot_17_0_unified_five_minute_pattern_confluence"
V17_PATTERN_RECENCY_CANDLES = 20
V17_PATTERN_RECENCY_DECAY = 5.5


def _v17_pattern_events(candle: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Collect/deduplicate current pattern events, including standalone chart formations."""
    if not isinstance(candle, dict):
        return []
    context = candle.get("price_action_context") or {}
    sources: List[Tuple[str, Any]] = [
        ("candlestick_and_smc", candle.get("patterns")),
        ("classical_chart", candle.get("classical_chart_patterns")),
        ("classical_chart", context.get("classical_chart_patterns")),
        ("divergence", candle.get("visual_momentum_divergence")),
        ("smc_ict", candle.get("smart_money_patterns")),
        ("smc_ict", candle.get("ict_patterns")),
        ("volume", candle.get("volume_patterns")),
    ]
    raw_events: List[Tuple[str, Dict[str, Any]]] = []
    for source_name, source_value in sources:
        if isinstance(source_value, list):
            collection = source_value
        elif isinstance(source_value, dict):
            collection = source_value.get("patterns") or source_value.get("events") or []
        else:
            collection = []
        for event in collection:
            if isinstance(event, dict):
                raw_events.append((source_name, event))

    try:
        candle_count = int(parse_float(candle.get("candle_count"), 0) or 0)
    except Exception:
        candle_count = 0
    visible_rows = candle.get("candles")
    if candle_count <= 0 and isinstance(visible_rows, list):
        candle_count = len(visible_rows)
    if candle_count <= 0:
        candle_count = max((
            max([int(parse_float(v, 0) or 0) for v in (e.get("candle_indices") or [])] or [0])
            for _, e in raw_events
        ), default=0)

    # Same named event/span produced by two scanners is one event, not two votes.
    unique: Dict[Tuple[str, Tuple[int, ...]], Tuple[str, Dict[str, Any]]] = {}
    for source_name, event in raw_events:
        name = str(event.get("name") or event.get("display_name") or "").strip().upper()
        if not name:
            continue
        raw_indices = event.get("candle_indices") if isinstance(event.get("candle_indices"), list) else event.get("indices")
        indices: List[int] = []
        if isinstance(raw_indices, (list, tuple)):
            for value in raw_indices:
                number = parse_float(value, None)
                if number is not None and int(number) > 0:
                    indices.append(int(number))
        indices_tuple = tuple(sorted(set(indices)))
        identity = (re.sub(r"[^A-Z0-9]+", "_", name).strip("_"), indices_tuple)
        previous = unique.get(identity)
        if previous is None:
            unique[identity] = (source_name, event)
        else:
            old_event = previous[1]
            old_confirmed = bool(old_event.get("confirmed")) or str(old_event.get("confirmation_status") or "").upper().startswith("CONFIRMED")
            new_confirmed = bool(event.get("confirmed")) or str(event.get("confirmation_status") or "").upper().startswith("CONFIRMED")
            old_strength = parse_float(old_event.get("contextual_strength"), None)
            if old_strength is None:
                old_strength = parse_float(old_event.get("strength"), 0.0) or 0.0
            new_strength = parse_float(event.get("contextual_strength"), None)
            if new_strength is None:
                new_strength = parse_float(event.get("strength"), 0.0) or 0.0
            if (new_confirmed and not old_confirmed) or (new_confirmed == old_confirmed and new_strength > old_strength):
                unique[identity] = (source_name, event)

    result: List[Dict[str, Any]] = []
    min_endpoint = max(1, candle_count - V17_PATTERN_RECENCY_CANDLES + 1)
    for (name_key, indices), (source_name, event) in unique.items():
        bias = parse_float(event.get("bias"), 0.0)
        if bias is None or abs(bias) < 1e-9:
            continue  # Neutral doji/indecision/descriptive tags do not fabricate a direction.
        end_index = max(indices) if indices else max(1, candle_count)
        if candle_count and end_index < min_endpoint:
            continue  # Distant events are stale for the next-five-minute decision.
        age = max(0, candle_count - end_index) if candle_count else 0
        recency = math.exp(-float(age) / V17_PATTERN_RECENCY_DECAY)
        strength = parse_float(event.get("contextual_strength"), None)
        if strength is None:
            strength = parse_float(event.get("strength"), None)
        if strength is None:
            strength = parse_float(event.get("raw_strength"), 0.25)
        strength = float(clamp(float(strength or 0.0), 0.05, 1.0))
        confirmation_status = str(event.get("confirmation_status") or "").upper()
        confirmed = bool(event.get("confirmed")) or confirmation_status.startswith("CONFIRMED")
        confirmation_factor = 1.0 if confirmed else 0.36
        family = str(event.get("pattern_family") or event.get("family") or source_name).strip().lower()
        if not family:
            family = source_name
        weight = max(1e-5, strength * recency * confirmation_factor)
        result.append({
            "name": name_key, "bias": float(clamp(float(bias), -1.0, 1.0)),
            "end_index": int(end_index), "age_candles": int(age), "family": family,
            "confirmed": bool(confirmed), "strength": strength, "recency_weight": recency,
            "weight": weight, "source": source_name,
        })
    return result


def _v17_aggregate_pattern_evidence(candle: Dict[str, Any]) -> Dict[str, Any]:
    """One direction-bearing vote per endpoint/family prevents overlapping aliases from inflating score."""
    events = _v17_pattern_events(candle)
    grouped: Dict[Tuple[int, str], List[Dict[str, Any]]] = defaultdict(list)
    for event in events:
        grouped[(int(event["end_index"]), str(event["family"]))].append(event)

    buckets: List[Dict[str, Any]] = []
    for (end_index, family), rows in grouped.items():
        total_weight = sum(float(row["weight"]) for row in rows)
        if total_weight <= 0:
            continue
        vote = sum(float(row["bias"]) * float(row["weight"]) for row in rows) / total_weight
        # The average individual weight, rather than the sum, stops a pile of overlapping
        # names on one candle from pretending to be independent corroboration.
        bucket_weight = total_weight / max(1, len(rows))
        age = min(int(row["age_candles"]) for row in rows)
        buckets.append({
            "end_index": end_index, "family": family,
            "bias": float(clamp(vote, -1.0, 1.0)), "weight": float(bucket_weight),
            "event_count": len(rows), "confirmed_event_count": sum(bool(row["confirmed"]) for row in rows),
            "age_candles": age,
        })
    weight_sum = sum(float(row["weight"]) for row in buckets)
    if weight_sum > 0:
        bias = sum(float(row["bias"]) * float(row["weight"]) for row in buckets) / weight_sum
        positive_weight = sum(float(row["weight"]) for row in buckets if float(row["bias"]) > 0)
        negative_weight = sum(float(row["weight"]) for row in buckets if float(row["bias"]) < 0)
        total_directional = positive_weight + negative_weight
        buy_vote_share = positive_weight / total_directional if total_directional else 0.5
        sell_vote_share = negative_weight / total_directional if total_directional else 0.5
    else:
        bias, buy_vote_share, sell_vote_share = 0.0, 0.5, 0.5
    confirmed_bull = sum(1 for row in events if row["confirmed"] and row["bias"] > 0)
    confirmed_bear = sum(1 for row in events if row["confirmed"] and row["bias"] < 0)
    family_count = len({str(row["family"]) for row in buckets})
    endpoint_count = len({int(row["end_index"]) for row in buckets})
    return {
        "bias": float(clamp(bias, -1.0, 1.0)),
        "confirmed_bullish_count": int(confirmed_bull),
        "confirmed_bearish_count": int(confirmed_bear),
        "event_count": len(events), "independent_endpoint_family_groups": len(buckets),
        "active_pattern_family_count": family_count, "active_endpoint_count": endpoint_count,
        "buy_vote_share_percent": round(100.0 * buy_vote_share, 1),
        "sell_vote_share_percent": round(100.0 * sell_vote_share, 1),
        "buckets": buckets,
        "events": events,
        "method": "recent confirmed/unfinished pattern events, normalized per endpoint and family; stale events decay; neutral tags do not cast a directional vote",
    }


def _v10_recent_pattern_bias(candle: Dict[str, Any]) -> Tuple[float, int, int]:
    """V17 unified recency-weighted bias across candlestick, chart, divergence, SMC/ICT and measured volume patterns."""
    detail = _v17_aggregate_pattern_evidence(candle)
    return (float(detail["bias"]), int(detail["confirmed_bullish_count"]), int(detail["confirmed_bearish_count"]))


_V17_PREVIOUS_APPLY_SCORE = _v10_apply_five_minute_score

def _v17_resync_score(result: Dict[str, Any], note: Optional[str] = None) -> Dict[str, Any]:
    """Make every final score field agree with one selected five-minute model score."""
    if not isinstance(result, dict):
        return result
    direction = str(result.get("direction") or "").upper()
    if direction not in ("BUY", "SELL"):
        bias = parse_float(result.get("combined_bias"), 0.0) or 0.0
        direction = "BUY" if bias >= 0 else "SELL"
    score_value = parse_float(result.get("selected_direction_score_percent"), None)
    if score_value is None:
        score_value = parse_float(result.get("confidence"), 50.0) or 50.0
    score = float(clamp(float(score_value), 50.0, 95.0))
    buy_score = score if direction == "BUY" else 100.0 - score
    sell_score = score if direction == "SELL" else 100.0 - score
    result.update({
        "direction": direction,
        "selected_direction_score_percent": round(score, 1),
        "final_five_minute_score_percent": round(score, 1),
        "unified_five_minute_score_percent": round(score, 1),
        "final_five_minute_direction": direction,
        "buy_direction_score_percent": round(buy_score, 1),
        "sell_direction_score_percent": round(sell_score, 1),
        # Legacy keys retained for UI/API compatibility but now mirror the same model score,
        # not the older, independently-derived 50 + 49*|bias| estimate.
        "buy_outcome_probability_percent": round(buy_score, 1),
        "sell_outcome_probability_percent": round(sell_score, 1),
        "buy_five_minute_direction_estimate_percent": round(buy_score, 1),
        "sell_five_minute_direction_estimate_percent": round(sell_score, 1),
        "confidence": round(score, 1),
        "confidence_is_calibrated_probability": False,
        "forecast_probability_estimate_is_empirically_calibrated": False,
        "forecast_probability_estimate_is_five_minute_direction_probability_estimate": False,
        "forecast_probability_estimate_is_five_minute_success_estimate": False,
        "score_semantics": "V17 unified five-minute directional evidence/confluence score (50–95). BUY and SELL side values are complementary views of this one score, not separately calculated probabilities. It is not a calibrated win probability or empirically calibrated win rate; calibration requires enough broker-aligned five-M1-bar outcomes and out-of-sample validation.",
        "analysis_model": V17_MODEL_VERSION,
        "bot_version": VERSION,
    })
    if result.get("v10_signal_eligible") is not None:
        result["signal_ready"] = bool(result.get("v10_signal_eligible") and score >= ALERT_SIGNAL_THRESHOLD_PERCENT)
    if note:
        notes = list(result.get("analysis_risk_notes") or [])
        notes.append(note)
        result["analysis_risk_notes"] = sorted(set(str(value) for value in notes if value))
    selected = result.get("fixed_expiry_forecast")
    if isinstance(selected, dict):
        selected.update({
            "direction": direction, "score_percent": round(score, 1),
            "selected_direction_score_percent": round(score, 1),
            "bias": round(float(parse_float(result.get("combined_bias"), selected.get("bias", 0.0)) or 0.0), 5),
            "horizon_minutes": FIXED_EXPIRY_MINUTES, "target_minutes": FIXED_EXPIRY_MINUTES,
            "signal_ready": bool(result.get("signal_ready", False)),
            "score_semantics": result["score_semantics"],
        })
    return result


def _v10_resync_score(result: Dict[str, Any], note: Optional[str] = None) -> Dict[str, Any]:
    return _v17_resync_score(result, note)


def _v10_apply_five_minute_score(candle: Dict[str, Any], online: Dict[str, Any],
                                  vision: Optional[Dict[str, Any]],
                                  visual_indicators: Dict[str, Any],
                                  result: Dict[str, Any]) -> Dict[str, Any]:
    """Pattern-led final pass: all live evidence comes from the selected chart only."""
    offline_context = {"available": False, "bias": 0.0, "direction": "UNAVAILABLE",
                       "mode": "LIVE_SELECTED_CHART_CANDLES_ONLY"}
    scored = _V17_PREVIOUS_APPLY_SCORE(candle, offline_context, None, visual_indicators, result)
    detail = _v17_aggregate_pattern_evidence(candle)
    pattern_bias = float(parse_float(detail.get("bias"), 0.0) or 0.0)
    base_bias = float(parse_float(scored.get("combined_bias"), parse_float(candle.get("bias"), 0.0)) or 0.0)
    events = list(detail.get("events") or [])
    event_count = len(events)
    confirmed_count = sum(1 for row in events if row.get("confirmed"))
    confirmed_ratio = confirmed_count / max(1, event_count)
    pattern_strength = abs(pattern_bias) * (0.60 + 0.40 * confirmed_ratio)
    ctx = candle.get("price_action_context") or {}
    exhaustion = ctx.get("trend_exhaustion_5m") or {}
    position = ctx.get("position_context") or {}
    bullish_reversal_confirmed = bool(
        exhaustion.get("confirmed_bullish_reversal")
        or (position.get("support_rejection_detected") and
            (exhaustion.get("bullish_reclaim_of_prior_close") or exhaustion.get("bullish_exhaustion_reclaim")))
    )
    bearish_reversal_confirmed = bool(
        exhaustion.get("confirmed_bearish_reversal")
        or (position.get("resistance_rejection_detected") and
            (exhaustion.get("bearish_reclaim_of_prior_close") or exhaustion.get("bearish_exhaustion_reclaim")))
    )
    bullish_continuation_confirmed = bool(exhaustion.get("bullish_continuation_confirmed"))
    bearish_continuation_confirmed = bool(exhaustion.get("bearish_continuation_confirmed"))

    if event_count and abs(pattern_bias) >= 0.05:
        # Pattern direction has the largest single weight; candle structure/exhaustion can
        # temper it or confirm a counter-trend reversal. Raw red/green streak counts do not vote.
        reversal_context = ((pattern_bias > 0 and bullish_reversal_confirmed)
                            or (pattern_bias < 0 and bearish_reversal_confirmed))
        pattern_weight = 0.52 if reversal_context else 0.60
        final_bias = float(clamp(pattern_weight * pattern_bias + (1.0 - pattern_weight) * base_bias, -1.0, 1.0))
        direction = "BUY" if final_bias > 0 else "SELL" if final_bias < 0 else str(scored.get("direction") or "BUY")
        aligned = (pattern_bias * base_bias) > 0
        direction_confluence = 1.0 if aligned else 0.62 if reversal_context else 0.0
        base_agreement = float(clamp(parse_float(scored.get("v10_confirmation_agreement_ratio"), 0.0) or 0.0, 0.0, 1.0))
        # Pattern magnitude and confirmation carry most of this one evidence score.
        evidence = float(clamp(
            0.38 * abs(final_bias) + 0.37 * pattern_strength
            + 0.15 * base_agreement + 0.10 * direction_confluence,
            0.0, 1.0))
        pattern_model_score = 50.0 + 45.0 * evidence
        prior_score = float(parse_float(scored.get("selected_direction_score_percent"), 50.0) or 50.0)
        score = 0.70 * pattern_model_score + 0.30 * prior_score
        if not aligned and not reversal_context:
            # A pattern/structure disagreement is uncertainty, not a reason to force BUY or SELL strength.
            score = min(score, 64.9)
            scored.setdefault("analysis_risk_notes", []).append(
                "recent directional pattern events conflict with the broader candle structure; alert strength reduced")
        mature_down = bool(exhaustion.get("mature_downtrend") or exhaustion.get("prolonged_down_streak"))
        mature_up = bool(exhaustion.get("mature_uptrend") or exhaustion.get("prolonged_up_streak"))
        if direction == "SELL" and mature_down and not bearish_continuation_confirmed:
            score = min(score, 70.0)
            scored.setdefault("analysis_risk_notes", []).append(
                "long decline alone is not continuation confirmation; SELL score capped until pattern follow-through appears")
        if direction == "BUY" and mature_up and not bullish_continuation_confirmed:
            score = min(score, 70.0)
            scored.setdefault("analysis_risk_notes", []).append(
                "long rise alone is not continuation confirmation; BUY score capped until pattern follow-through appears")
        scored.update({
            "combined_bias": round(final_bias, 5),
            "direction": direction,
            "selected_direction_score_percent": round(float(clamp(score, 50.0, 95.0)), 1),
            "v18_pattern_led_evidence_strength": round(evidence, 4),
            "v18_pattern_weight_percent": round(pattern_weight * 100.0, 1),
            "v18_pattern_confirmation_ratio_percent": round(confirmed_ratio * 100.0, 1),
            "v18_pattern_structure_aligned": bool(aligned),
            "v18_pattern_reversal_context_confirmed": bool(reversal_context),
            "v18_pattern_score_method": "60% recent normalized pattern bias (52% for a context-confirmed counter-trend reversal), with chart structure/exhaustion, grouped indicator agreement, and confirmation quality; disagreement is capped below alert threshold",
        })
    else:
        # If no directional pattern is actually measured, the old structure model may select
        # a tentative direction, but cannot manufacture a >=65% pattern-led alert score.
        old_score = float(parse_float(scored.get("selected_direction_score_percent"), 50.0) or 50.0)
        scored["selected_direction_score_percent"] = round(min(old_score, 64.9), 1)
        scored["v18_pattern_led_evidence_strength"] = 0.0
        scored["v18_pattern_weight_percent"] = 0.0
        scored["v18_pattern_confirmation_ratio_percent"] = 0.0
        scored["v18_pattern_structure_aligned"] = False
        scored["v18_pattern_reversal_context_confirmed"] = False
        scored["v18_pattern_score_method"] = "No active directional pattern: conservative candidate score capped below the 65% alert threshold"

    scored.update({
        "v17_pattern_bias": round(pattern_bias, 5),
        "v17_pattern_event_count": int(detail["event_count"]),
        "v17_pattern_endpoint_family_group_count": int(detail["independent_endpoint_family_groups"]),
        "v17_pattern_family_count": int(detail["active_pattern_family_count"]),
        "v17_pattern_endpoint_count": int(detail["active_endpoint_count"]),
        "v17_pattern_confirmed_bullish_count": int(detail["confirmed_bullish_count"]),
        "v17_pattern_confirmed_bearish_count": int(detail["confirmed_bearish_count"]),
        "v17_pattern_buy_vote_share_percent": detail["buy_vote_share_percent"],
        "v17_pattern_sell_vote_share_percent": detail["sell_vote_share_percent"],
        "v17_pattern_aggregation_method": detail["method"],
        "v17_pattern_event_groups": detail["buckets"],
        "v17_pattern_score_connection": "All recent directional pattern families are endpoint/family-deduplicated, confirmation-weighted, and feed the same unified five-minute score.",
        "v17_score_is_single_unified_five_minute_score": True,
        "online_context_used_for_score": False,
        "score_source": "live selected-chart candle patterns and chart-derived structure only",
    })
    # Keep exactly one displayed model score and synchronize BUY/SELL complementary values.
    return _v17_resync_score(scored)


def _v18_regression_tests() -> int:
    """Regression checks for live-chart-only, pattern-led five-minute scoring."""
    checks: List[Tuple[str, bool]] = []
    def check(label: str, ok: Any) -> None:
        checks.append((label, bool(ok)))

    offline = {"available": False, "bias": 0.0, "direction": "UNAVAILABLE"}
    base = {
        "candle_count": 30, "candles": [{} for _ in range(30)], "bias": 0.20,
        "direction": "BUY", "selected_direction_score_percent": 66.0,
        "reading_confidence_percent": 95.0,
        "geometry_validation": {"geometry_valid_percent": 95.0},
        "image_quality": {"score": 95},
        "fixed_expiry_forecast": {"bias": 0.20, "direction": "BUY", "horizon_minutes": 5},
        "price_action_context": {"bias": 0.20,
            "components": {"trend": 0.25, "momentum": 0.18, "swing_structure": 0.2,
                           "support_resistance_reaction": 0.15, "context_confirmed_patterns": 0.1},
            "position_context": {}, "trend_exhaustion_5m": {}},
        "structural_context": {"bias": 0.20}, "patterns": [],
    }
    bullish = dict(base)
    bullish["patterns"] = [
        {"name": "BULLISH_ENGULFING", "bias": 0.85, "strength": 0.90,
         "contextual_strength": 0.90, "confirmed": True,
         "candle_indices": [29, 30], "pattern_family": "candlestick"},
        {"name": "MORNING_STAR", "bias": 0.80, "strength": 0.82,
         "contextual_strength": 0.82, "confirmed": True,
         "candle_indices": [28, 29, 30], "pattern_family": "star_reversal"},
    ]
    scored_bull = combine_assessments(bullish, offline, None, visual_indicators={"sample_count": 30, "directional_bias": 0.2})
    check("confirmed bullish patterns are the primary directional input", scored_bull.get("direction") == "BUY"
          and float(scored_bull.get("v18_pattern_weight_percent", 0.0)) >= 50.0
          and float(scored_bull.get("selected_direction_score_percent", 0.0)) >= ALERT_SIGNAL_THRESHOLD_PERCENT)
    check("single unified score is synchronized across forecast and complementary sides",
          scored_bull.get("selected_direction_score_percent") == scored_bull.get("confidence")
          and scored_bull.get("selected_direction_score_percent") == (scored_bull.get("fixed_expiry_forecast") or {}).get("score_percent")
          and round(float(scored_bull.get("buy_outcome_probability_percent", 0.0)) + float(scored_bull.get("sell_outcome_probability_percent", 0.0)), 1) == 100.0)
    check("live score explicitly records that online context did not contribute", scored_bull.get("online_context_used_for_score") is False
          and "live selected-chart" in str(scored_bull.get("score_source", "")))

    no_pattern = dict(base)
    no_pattern.update({"bias": -0.92, "direction": "SELL", "selected_direction_score_percent": 90.0,
        "price_action_context": {"bias": -0.92, "components": {"trend": -0.9}, "position_context": {},
            "trend_exhaustion_5m": {"mature_downtrend": True, "prolonged_down_streak": True}}})
    scored_no_pattern = combine_assessments(no_pattern, offline, None, visual_indicators={"sample_count": 30, "directional_bias": -0.8})
    check("a long red/down streak without a directional named pattern cannot create a 65+ alert score",
          float(scored_no_pattern.get("selected_direction_score_percent", 100.0)) < ALERT_SIGNAL_THRESHOLD_PERCENT
          and scored_no_pattern.get("signal_ready") is False)

    conflict = dict(bullish)
    conflict.update({"bias": -0.75, "direction": "SELL", "selected_direction_score_percent": 76.0,
        "price_action_context": {"bias": -0.75, "components": {"trend": -0.7, "momentum": -0.6},
            "position_context": {}, "trend_exhaustion_5m": {}}})
    conflict_scored = combine_assessments(conflict, offline, None, visual_indicators={"sample_count": 30, "directional_bias": -0.7})
    check("pattern/structure conflict is treated as uncertainty, not inflated into a strong alert",
          float(conflict_scored.get("selected_direction_score_percent", 100.0)) < ALERT_SIGNAL_THRESHOLD_PERCENT
          and conflict_scored.get("signal_ready") is False)

    check("remote data endpoint configuration is empty and fetch helper is blocked",
          not NEWS_FEEDS and not OFFICIAL_CALENDAR_SOURCES and not YAHOO_CHART_URL
          and "disabled" in (http_get.__doc__ or "").lower())
    for label, ok in checks:
        print(("PASS" if ok else "FAIL") + " | " + label, flush=True)
    passed = sum(ok for _, ok in checks)
    print(f"BOT 18.0 CHART-ONLY PATTERN SCORE TEST: {passed}/{len(checks)} passed", flush=True)
    return 0 if passed == len(checks) else 1

def _v17_regression_tests() -> int:
    checks: List[Tuple[str, bool]] = []
    def check(label: str, condition: Any) -> None:
        checks.append((label, bool(condition)))
    try:
        test_candle = {
            "candle_count": 30,
            "candles": [{} for _ in range(30)],
            "patterns": [
                {"name": "BULLISH_ENGULFING", "bias": 0.6, "strength": 0.8, "confirmed": True,
                 "candle_indices": [29, 30], "pattern_family": "candlestick"},
                {"name": "MORNING_STAR", "bias": 0.5, "strength": 0.7, "confirmed": False,
                 "candle_indices": [28, 29, 30], "pattern_family": "candlestick"},
                {"name": "DOJI", "bias": 0.0, "strength": 0.9, "confirmed": True,
                 "candle_indices": [30], "pattern_family": "candlestick"},
            ],
            "classical_chart_patterns": {"patterns": [
                {"name": "ASCENDING_TRIANGLE", "bias": 0.45, "strength": 0.75, "confirmed": True,
                 "candle_indices": [23, 26, 30], "pattern_family": "classical_chart"},
                {"name": "BULLISH_ENGULFING", "bias": 0.6, "strength": 0.1, "confirmed": False,
                 "candle_indices": [29, 30], "pattern_family": "candlestick"},
            ]},
            "price_action_context": {"classical_chart_patterns": {"patterns": [
                {"name": "BEARISH_DOUBLE_TOP", "bias": -0.35, "strength": 0.6, "confirmed": True,
                 "candle_indices": [25, 28, 30], "pattern_family": "classical_chart"},
            ]}},
        }
        aggregated = _v17_aggregate_pattern_evidence(test_candle)
        check("unified pattern aggregation consumes candle and classical chart-formation events", aggregated["event_count"] >= 4 and aggregated["active_pattern_family_count"] >= 2)
        check("neutral doji/indecision tags do not add directional bias", abs(aggregated["bias"]) > 0 and all(e["name"] != "DOJI" for e in aggregated["events"]))
        check("same named event/span from multiple scanners is deduplicated", sum(1 for e in aggregated["events"] if e["name"] == "BULLISH_ENGULFING" and e["end_index"] == 30) == 1)

        sample = {
            "direction": "BUY", "selected_direction_score_percent": 73.2,
            "combined_bias": 0.32, "v10_signal_eligible": True,
            "fixed_expiry_forecast": {"direction": "BUY", "score_percent": 69.0, "horizon_minutes": 5},
        }
        synchronized = _v17_resync_score(sample)
        check("one selected BUY score is synchronized across every legacy and unified field",
              synchronized["selected_direction_score_percent"] == synchronized["confidence"] == synchronized["final_five_minute_score_percent"] == synchronized["unified_five_minute_score_percent"] == synchronized["buy_outcome_probability_percent"] == synchronized["buy_direction_score_percent"] == 73.2
              and synchronized["sell_outcome_probability_percent"] == synchronized["sell_direction_score_percent"] == 26.8
              and synchronized["fixed_expiry_forecast"]["score_percent"] == 73.2)
        sample_sell = _v17_resync_score({"direction": "SELL", "selected_direction_score_percent": 68.4, "v10_signal_eligible": True})
        check("SELL score is primary and BUY value is its exact complement",
              sample_sell["sell_direction_score_percent"] == 68.4 and sample_sell["buy_direction_score_percent"] == 31.6 and sample_sell["final_five_minute_direction"] == "SELL")
        check("65-percent alert threshold is respected after score synchronization",
              _v17_resync_score({"direction": "BUY", "selected_direction_score_percent": 64.9, "v10_signal_eligible": True}).get("signal_ready") is False)
        check("score is clearly labeled as not empirically calibrated probability",
              synchronized.get("confidence_is_calibrated_probability") is False and "not a calibrated win probability" in synchronized.get("score_semantics", ""))
    except Exception as exc:
        checks.append((f"V17 unified scoring regression raised {type(exc).__name__}: {exc}", False))
    for label, passed in checks:
        print(("PASS" if passed else "FAIL") + " | " + label, flush=True)
    passed_count = sum(passed for _, passed in checks)
    print(f"BOT 17.0 UNIFIED FIVE-MINUTE SCORE TEST: {passed_count}/{len(checks)} passed", flush=True)
    return 0 if passed_count == len(checks) else 1

